ClinicalChunks.register("data/orders-004.js",[{"id":"orders-a00b73ec116d25267015","key":"v1-c9ccc21dfe2a3058|orders-a00b73ec116d25267015","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"钩端螺旋体病","category":"内科-感染","raw":{"name":"钩端螺旋体病","category":"内科-感染","summary":"由致病性钩端螺旋体引起的动物源性传染病，鼠类和猪是主要传染源，临床特点为起病急骤、高热、全身酸痛、腓肠肌压痛、眼结膜充血、浅表淋巴结肿大，重者可并发肺出血、黄疸、肾衰竭、脑膜脑炎。","symptoms":["早期（钩体血症期）：急起高热、畏寒寒战、全身肌肉酸痛（腓肠肌压痛明显）、乏力、眼结膜充血（无分泌物）、浅表淋巴结肿大（腹股沟、腋下）、皮疹、肝脾肿大","中期（器官损伤期）：肺出血型（咳嗽、咯血、呼吸困难、发绀，肺弥漫性出血是常见死因）、黄疸出血型（进行性黄疸、出血倾向、肝肾功能损害）、肾衰竭型（少尿、无尿、氮质血症）、脑膜脑炎型（头痛、呕吐、意识障碍、脑膜刺激征、瘫痪）、流感伤寒型（类似流感，无明显器官损害）","后期（恢复期或后发症期）：后发热、眼后发症（葡萄膜炎、虹膜睫状体炎）、神经系统后发症（闭塞性脑动脉炎、蛛网膜下腔出血、周围神经炎）","全身症状：恶心、呕吐、腹泻、腹痛、鼻出血、牙龈出血","严重并发症：肺弥漫性出血、急性肝衰竭、急性肾衰竭、呼吸衰竭、休克、DIC"],"diagnosis":["流行病学史：夏秋季节，疫区，有疫水接触史（稻田、池塘、洪水），鼠类或猪接触史","典型临床表现：急起高热、腓肠肌压痛、眼结膜充血、淋巴结肿大，多器官损害","血常规：白细胞总数及中性粒细胞轻度升高，血小板可减少","尿常规：蛋白尿、红细胞、白细胞、管型","肝功能：转氨酶升高、胆红素升高（黄疸出血型）","肾功能：血肌酐、尿素氮升高（肾衰竭型）","脑脊液：脑膜脑炎型压力升高、白细胞升高（淋巴细胞为主）、蛋白升高、糖正常","病原学检查：血培养（发病1周内）、尿培养（发病2周后）、暗视野显微镜检查（直接找钩体）","血清学检查：显微镜凝集试验（MAT，抗体滴度≥1:400或恢复期较急性期升高4倍以上）、ELISA检测IgM抗体","分子生物学：PCR检测钩体DNA","鉴别诊断：流感、伤寒、病毒性肝炎、流行性出血热、急性肾小球肾炎、脑膜炎、败血症"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（病原治疗；首选青霉素）：","  用法：0.9%NS 100ml + 青霉素G 400万U ivgtt q6h（首剂小剂量40万U，预防赫氏反应，疗程7天）；青霉素过敏用0.9%NS 250ml + 多西环素0.1g ivgtt q12h 或 0.9%NS 250ml + 庆大霉素8万U ivgtt q8h 或 0.9%NS 250ml + 头孢曲松2g ivgtt qd","","方案2（赫氏反应处理）：","  用法：0.9%NS 20ml + 氢化可的松200mg iv + 物理降温、抗休克〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","","方案3（肺出血）：","  用法：0.9%NS 20ml + 氢化可的松200-300mg iv（大剂量激素）+ 止血药（氨甲环酸、酚磺乙胺）+ 镇静（哌替啶）+ 吸氧，必要时机械通气〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","","方案4（黄疸出血型）：","  用法：0.9%NS 100ml + 青霉素G 400万U 静滴 q6h（皮试阴性后）；0.9%NS 100ml + 还原型谷胱甘肽 1.2g 静滴 qd；0.9%NS 100ml + 维生素K1 10mg 静滴 qd；出血明显时：0.9%NS 100ml + 氨甲环酸 0.5g 静滴 q8h；肝衰竭者行血浆置换/人工肝支持","","方案5（肾衰竭）：","  用法：利尿（呋塞米）、纠正水电解质紊乱，必要时血液透析〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","","方案6（脑膜脑炎型）：","  用法：20%甘露醇 125ml 静滴 q6h（快速滴入，30min内）；地塞米松 10mg 静推 qd；0.9%NS 100ml + 青霉素G 400万U 静滴 q6h（皮试阴性后）","","方案7（休克）：","  用法：0.9%NS 500ml 静滴快速补液（首剂 30min 内 500ml）；0.9%NS 250ml + 多巴胺 100mg 静滴，5~10μg/kg/min 泵入；维持收缩压>90mmHg、尿量>30ml/h（多巴胺、去甲肾上腺素）","","方案8（DIC）：","  用法：0.9%NS 50ml + 肝素钠 5000U 静滴，持续泵入（APTT 维持正常 1.5~2 倍）；新鲜冰冻血浆 200ml 静滴；冷沉淀 10U 静滴；血小板<50×10⁹/L 时输注血小板 1 治疗量","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（轻症口服）：","用法：多西环素0.1g bid（7天）或 阿莫西林0.5g qid（7天）〔调 CrCl<30 减量；青霉素过敏禁用〕","药物2（退热）：","用法：对乙酰氨基酚0.5g prn 或 布洛芬0.3g prn〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物3（保肝）：","用法：水飞蓟宾70mg tid 或 多烯磷脂酰胆碱456mg tid","药物4（止血）：","用法：氨甲环酸0.5g tid 或 酚磺乙胺0.5g tid〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","药物5（预防）：","用法：多西环素0.2g每周一次（进入疫区前2天开始，离开后继续2-3周）〔调 ★ 8岁以下及妊娠期禁用；食管刺激（需直立饮水送服）〕","药物6（对症）：","用法：补液、维持水电解质平衡","药物7：","用法：中医中药治疗","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["一般治疗：早期卧床休息，就地治疗（避免搬动诱发肺出血），清淡饮食，营养支持，维持水电解质平衡","病原治疗：早期使用抗生素（发病1周内效果好），青霉素首选（40万U 肌注 q6-8h，疗程7天），首剂小剂量预防赫氏反应，青霉素过敏改用多西环素 100mg 口服 bid 或庆大霉素 8万U 肌注 q8h","对症治疗：退热（对乙酰氨基酚 0.5g 口服 q6h）、镇静（地西泮 5-10mg 口服/静推）、止血（维生素K1 10mg 肌注 qd）、保肝、护肾、降颅压（甘露醇 0.25-0.5g/kg 静滴 q6-8h）","并发症治疗：肺出血（氢化可的松 200-300mg 静滴 qd + 止血 + 镇静 + 机械通气）、急性肝衰竭（人工肝）、急性肾衰竭（血液透析）、脑膜脑炎（甘露醇降颅压 + 地塞米松 10mg 静推 q6h）、休克（补液 + 多巴胺 5-20μg/kg·min 静滴）、DIC（肝素 50-100mg 静滴 qd + 凝血因子）","赫氏反应处理：立即氢化可的松 200-300mg 静推 + 物理降温 + 抗休克","后发症治疗：眼葡萄膜炎（阿托品散瞳 + 泼尼松 30-40mg 口服 qd）、闭塞性脑动脉炎（激素、血管扩张药）","预防：管理传染源（灭鼠、猪圈养）、切断传播途径（避免疫水接触、防护）、保护易感人群（钩体疫苗接种、口服多西环素 200mg 每周 1 次）","定期随访：监测肝肾功能、神经系统症状、眼部情况（出院后每月 1 次，共 3-6 个月）"],"management":["急性期绝对卧床休息，避免搬动（诱发肺出血）","就地治疗，避免长途转送","密切监测生命体征、意识、出血情况、尿量、肝肾功能","肺出血患者保持呼吸道通畅，吸氧，必要时气管插管机械通气","记录出入量，维持水电解质平衡","清淡易消化饮食，保证营养","避免使用肾毒性药物","疫区工作者做好防护（穿长筒靴、戴手套），避免接触疫水","灭鼠、防鼠，猪圈养，管理牲畜粪便","疫苗接种（流行区人群）","进入疫区前2天开始口服多西环素预防，离开后继续2-3周","定期随访，注意后发症（眼葡萄膜炎、神经系统症状）","保持乐观心态，避免焦虑"],"notes":["又称钩体病，是自然疫源性疾病，鼠类和猪是主要传染源","传播途径：接触疫水（皮肤黏膜破损处侵入），夏秋季节高发","典型表现：寒热酸痛一身乏，眼红腿痛淋巴大（三症状三体征）","腓肠肌压痛是特征性表现","肺弥漫性出血是常见死因，早期表现为咯血、呼吸困难，进展迅速","赫氏反应：首剂青霉素后半小时至4小时发生，表现为突然寒战、高热、头痛、全身痛、心率呼吸加快，严重者休克，是大量钩体死亡释放毒素所致","首剂青霉素用小剂量（40万U）可预防赫氏反应","治疗原则：三早一就（早发现、早诊断、早治疗、就地治疗）","青霉素是首选药物，过敏者用多西环素、庆大霉素、头孢曲松","后发症：眼葡萄膜炎、闭塞性脑动脉炎，与免疫反应有关","预防关键是灭鼠和避免疫水接触","疫苗接种可降低发病率","预后：轻症预后好，重症（肺出血型、黄疸出血型）病死率高"],"emergency":["出现咯血、呼吸困难、发绀（肺出血）、意识障碍、抽搐（脑膜脑炎）、少尿无尿（肾衰竭）、黄疸加重、出血倾向立即就医，就地治疗避免搬动"],"pinyin":"gouduanluoxuantibing","icd10":"A27.9","physical_exam":["生命体征：体温（热型：稽留热/弛张热/间歇热/不规则热）、脉搏（相对缓脉提示伤寒）、呼吸、血压（感染性休克低血压）、血氧","一般情况：神志（感染中毒性脑病/嗜睡/谵妄）、精神状态、面容（伤寒面容/二尖瓣面容）、体位、有无寒战","皮肤黏膜：皮疹（形态/分布/出现时间：斑丘疹/出血疹/疱疹/荨麻疹）、瘀点瘀斑（脑膜炎双球菌）、黄疸、溃疡、焦痂（恙虫病）、脓肿、红肿热痛","淋巴结：全身/局部淋巴结肿大（压痛/质地/活动度）","头颈部：结膜充血/出血、咽充血、扁桃体肿大/渗出、口腔溃疡、颈强直（脑膜刺激征）","胸部：心率心律、双肺呼吸音/啰音（肺部感染）","腹部：压痛（部位）、反跳痛、肝脾肿大、腹水征、肠鸣音","神经系统：意识状态、脑膜刺激征、病理征、局灶体征","其他：感染灶寻找（皮肤/呼吸道/消化道/泌尿道/胆道）"],"lab_tests":["血常规（入院即查并动态复查）：白细胞及中性粒细胞升高、血小板进行性下降提示重型及肺出血倾向","血清学检查：钩端螺旋体显微凝集试验（MAT）双份血清（急性期及发病2周后恢复期各一次），或第5～7病日起查钩体IgM抗体","病原学检查：发病1周内取血（柯氏培养基）培养钩端螺旋体，2周后可加做尿培养，阳性可确诊","尿常规+肾功能：查蛋白尿、血尿、管型及血肌酐/尿素氮，评估肾损害程度，动态随访","肝功能+胆红素：ALT、AST、胆红素升高提示黄疸出血型，需动态监测","影像学：胸部X线/CT（见双肺弥漫性点片状影警惕肺出血型）；脑膜脑炎型加做头颅MRI、脑脊液检查"],"nursing":["隔离与报告：按乙类传染病24小时内网络直报，实行接触隔离、标准预防，患者的血、尿等排泄物及污染物品用含氯消毒剂处理，医护人员做好防护","病情观察：密切监测体温、血压、神志、尿量及出血倾向（咯血、呕血、皮肤瘀点瘀斑、鼻出血），警惕肺出血型、黄疸出血型及急性肾衰竭","发热护理：高热以物理降温为主，遵医嘱药物降温，注意补液，观察出汗后有无血压下降、尿量减少，防止虚脱","皮肤黏膜护理：保持皮肤清洁干燥，瘀点瘀斑处避免搔抓碰撞，勤翻身防压疮，注意口腔及眼部护理，防继发感染","防并发症：急性期绝对卧床休息、减少活动，协助生活护理，准确记录24小时出入量，发现无尿、血尿、咯血等立即报告医生"],"diet":["高热量、高维生素、易消化软食，少量多餐，保证能量供给，必要时予肠内或肠外营养支持","鼓励充足饮水（或口服补液盐）以增加尿量、保护肾功能；若出现少尿、肾功能不全者按医嘱限制液体及钠、钾摄入","肾损害者适当限制蛋白质，肝损害明显者予低脂、清淡饮食并护肝治疗","忌辛辣刺激、油腻、生冷及腌制食品，禁烟酒","恢复期注意营养均衡，逐步增加优质蛋白及新鲜蔬果，促进体力恢复"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":379},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"faed502faaa15272d05e9c7f3ac87528bc36f80dc33ced2864dceeed18c8a400","pinyin":"gouduanluoxuantibing","initials":"gdlxtb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","早期（钩体血症期）：急起高热、畏寒寒战、全身肌肉酸痛（腓肠肌压痛明显）、乏力、眼结膜充血（无分泌物）、浅表淋巴结肿大（腹股沟、腋下）、皮疹、肝脾肿大\\n中期（器官损伤期）：肺出血型（咳嗽、咯血、呼吸困难、发绀，肺弥漫性出血是常见死因）、黄疸出血型（进行性黄疸、出血倾向、肝肾功能损害）、肾衰竭型（少尿、无尿、氮质血症）、脑膜脑炎型（头痛、呕吐、意识障碍、脑膜刺激征、瘫痪）、流感伤寒型（类似流感，无明显器官损害）\\n后期（恢复期或后发症期）：后发热、眼后发症（葡萄膜炎、虹膜睫状体炎）、神经系统后发症（闭塞性脑动脉炎、蛛网膜下腔出血、周围神经炎）\\n全身症状：恶心、呕吐、腹泻、腹痛、鼻出血、牙龈出血\\n严重并发症：肺弥漫性出血、急性肝衰竭、急性肾衰竭、呼吸衰竭、休克、DIC",60],["摘要","由致病性钩端螺旋体引起的动物源性传染病，鼠类和猪是主要传染源，临床特点为起病急骤、高热、全身酸痛、腓肠肌压痛、眼结膜充血、浅表淋巴结肿大，重者可并发肺出血、黄疸、肾衰竭、脑膜脑炎。",30],["疾病编码","A27.9",30],["原首字母","gouduanluoxuantibing",60]]},{"id":"orders-8d25cdf2ce30b8bdd2c6","key":"v1-c9ccc21dfe2a3058|orders-8d25cdf2ce30b8bdd2c6","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"布鲁菌病","category":"内科-感染","raw":{"name":"布鲁菌病","category":"内科-感染","summary":"由布鲁菌属细菌引起的人畜共患传染病，临床特点为长期发热、多汗、关节痛、肝脾肿大、睾丸炎、脑膜炎等，易转为慢性，复发率高。","symptoms":["急性期：发热（波浪热型，体温逐日升高达高峰后缓慢下降，持续数天至数周）、多汗（夜间或凌晨退热时大汗淋漓）、关节痛（大关节游走性疼痛，膝关节、髋关节、肩关节）、乏力、食欲减退、头痛、肌痛、肝脾肿大、淋巴结肿大","泌尿生殖系统：睾丸炎、附睾炎（男性，单侧睾丸肿痛）、卵巢炎、子宫内膜炎（女性）、流产","神经系统：坐骨神经痛、腰骶神经痛、脑膜脑炎、神经根炎、脊髓炎","心血管系统：心内膜炎（严重并发症，主动脉瓣受累多见）、心肌炎、心包炎、血管炎","呼吸系统：支气管炎、肺炎、胸膜炎","慢性期：病程超过1年，表现为固定性关节痛、肌肉痛、乏力、失眠、精神抑郁、低热、肝脾肿大","其他：皮疹、皮下结节、眼葡萄膜炎、视神经炎"],"diagnosis":["流行病学史：牧区、兽医、屠宰场、奶制品加工人员，接触病畜（羊、牛、猪）或食用未消毒奶制品","典型临床表现：长期发热、多汗、关节痛、肝脾肿大、睾丸炎","血常规：白细胞总数正常或偏低，淋巴细胞相对增多，血沉增快","病原学检查：血培养（急性期阳性率高）、骨髓培养、淋巴结穿刺培养（需特殊培养基，培养时间长）","血清学检查：平板凝集试验（PAT，筛查）、试管凝集试验（SAT，滴度≥1:160阳性）、补体结合试验（CFT，慢性期）、ELISA（检测IgM/IgG）、虎红平板凝集试验（RBPT）","皮内试验：布鲁菌素皮试（慢性期阳性，流行病学调查）","分子生物学：PCR检测布鲁菌DNA","影像学：关节X线/CT/MRI（关节病变）、腹部B超（肝脾肿大、脓肿）、心脏超声（心内膜炎）","鉴别诊断：伤寒、结核、风湿热、类风湿关节炎、疟疾、黑热病、感染性心内膜炎"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：急性期联合治疗（首选多西环素+链霉素/庆大霉素）：0.9%NS 250ml + 庆大霉素8万U ivgtt q8h（或链霉素0.75g im qd）+ 多西环素0.1g po bid，疗程6周〔调 ★ 8岁以下及妊娠期禁用；食管刺激（需直立饮水送服）〕","方案2（重症或并发症）：","用法：0.9%NS 250ml + 多西环素0.1g ivgtt q12h + 0.9%NS 250ml + 利福平0.6g ivgtt qd + 0.9%NS 250ml + 庆大霉素8万U ivgtt q8h，疗程6-8周〔调 ★ 8岁以下及妊娠期禁用；食管刺激（需直立饮水送服）〕","方案3（心内膜炎）：","用法：0.9%NS 250ml + 多西环素0.1g ivgtt q12h + 0.9%NS 250ml + 利福平0.6g ivgtt qd + 0.9%NS 250ml + 庆大霉素8万U ivgtt q8h + 0.9%NS 250ml + 复方磺胺甲噁唑2片 ivgtt bid，疗程3-6个月，必要时手术换瓣","方案4（脑膜脑炎）：","用法：0.9%NS 250ml + 多西环素0.1g ivgtt q12h + 0.9%NS 250ml + 利福平0.6g ivgtt qd + 0.9%NS 250ml + 复方磺胺甲噁唑2片 ivgtt bid，疗程4-6个月，加用激素〔调 ★ 8岁以下及妊娠期禁用；食管刺激（需直立饮水送服）〕","方案5（睾丸炎）：","用法：多西环素 100mg 口服 q12h；利福平 600mg 口服 qd；泼尼松 30mg 口服 qd（睾丸炎症状明显时，疗程1~2周，逐渐减量）（泼尼松10mg tid）〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","方案6（慢性期）：","用法：抗生素+菌苗疗法（脱敏）+理疗","方案7（退热）：","用法：0.9%NS 20ml + 赖氨匹林0.9g iv（高热时）","方案8（保肝）：","用法：0.9%NS 100ml + 还原型谷胱甘肽1.2g ivgtt qd","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（急性期首选方案）：","用法：多西环素0.1g bid + 利福平0.6g qd（晨起空腹），疗程6周〔调 ★ 8岁以下及妊娠期禁用；食管刺激（需直立饮水送服）〕","药物2（替代方案）：","用法：多西环素0.1g bid + 链霉素0.75g im qd（2-3周），疗程6周〔调 ★ 8岁以下及妊娠期禁用；食管刺激（需直立饮水送服）〕","药物3（儿童）：","用法：复方磺胺甲噁唑（按体重）+ 利福平15mg/kg/d，疗程6周〔调 ★ 肝功能不全慎用；★ 强CYP450诱导剂（大量相互作用）〕","药物4（孕妇）：","用法：复方磺胺甲噁唑2片 bid（妊娠早期避免）+ 利福平0.6g qd，疗程6周〔调 ★ 肝功能不全慎用；★ 强CYP450诱导剂（大量相互作用）〕","药物5（慢性期）：","用法：多西环素0.1g bid + 利福平0.6g qd + 复方磺胺甲噁唑2片 bid，疗程3-6个月〔调 ★ 8岁以下及妊娠期禁用；食管刺激（需直立饮水送服）〕","药物6（对症）：","用法：布洛芬0.3g tid（关节痛）、泼尼松10mg tid（睾丸炎、严重毒血症，短期）、保肝药〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物7：","用法：中医中药治疗","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["一般治疗：急性期卧床休息，加强营养，补充维生素，维持水电解质平衡","病原治疗：早期、联合、足量、足疗程抗生素，多西环素+利福平首选，疗程至少6周，慢性期3-6个月，避免复发和慢性化","对症治疗：退热、止痛、保肝、营养支持","并发症治疗：心内膜炎（长疗程抗生素+手术换瓣）、脑膜脑炎（抗生素+激素+降颅压）、睾丸炎（抗生素+激素）、关节炎（抗生素+理疗）","慢性期治疗：抗生素+菌苗疗法（静脉注射死菌苗脱敏）+理疗+中医中药","手术治疗：心内膜炎瓣膜置换、关节化脓性病灶引流、脾脓肿切除","预防：管理传染源（病畜隔离、检疫、淘汰）、切断传播途径（奶制品消毒、肉类煮熟、个人防护）、保护易感人群（疫苗接种、职业防护）","定期随访：监测血常规、血沉、肝肾功能、血培养，注意复发"],"management":["急性期卧床休息，避免劳累","清淡饮食，加强营养，补充维生素B、C","多饮水，维持水电解质平衡","监测体温、关节症状、肝脾大小变化","定期复查血常规、血沉、肝肾功能、血培养","规律服药，完成疗程（至少6周），不可自行停药，预防复发和慢性化","注意药物副作用（多西环素胃肠道反应、光敏；利福平肝损伤、橘红色分泌物；链霉素耳毒性、肾毒性）","牧区、兽医、屠宰场工作人员做好个人防护（戴口罩、手套、穿防护服）","避免食用未消毒的奶制品和未煮熟的肉类","病畜隔离、检疫，淘汰病畜","疫苗接种（流行区人群和职业人群）","慢性期患者注意关节功能锻炼，配合理疗","保持乐观心态，避免焦虑抑郁","复发率较高，需长期随访"],"notes":["又称波浪热、马耳他热、地中海弛张热，是人畜共患传染病","病原体：布鲁菌属，羊布鲁菌致病力最强，其次牛、猪、犬布鲁菌","传染源：病畜（羊、牛、猪），人传人罕见","传播途径：皮肤黏膜接触（接羔、屠宰、挤奶）、消化道（未消毒奶制品、未煮熟肉类）、呼吸道（气溶胶）、虫媒","典型表现：波浪热、多汗、关节痛、肝脾肿大、睾丸炎","实验室检查：白细胞正常或偏低，淋巴细胞增多，血培养阳性（需特殊培养基），血清凝集试验阳性","治疗原则：早期、联合、足量、足疗程，多西环素+利福平首选，疗程至少6周","慢性期治疗困难，易复发，可加用菌苗疗法","心内膜炎是严重并发症，需长疗程抗生素+手术换瓣","脑膜脑炎预后较差，可遗留神经系统后遗症","预防关键是管理病畜和奶制品消毒","职业人群（兽医、屠宰工、牧民）是高危人群","疫苗接种可降低发病率"],"emergency":["出现高热不退、剧烈头痛呕吐意识障碍（脑膜脑炎）、心悸胸闷呼吸困难（心内膜炎心衰）、睾丸剧烈肿痛、关节红肿热痛（化脓性关节炎）立即就医"],"pinyin":"bulujunbing","icd10":"A23.9","physical_exam":["生命体征：体温（热型：稽留热/弛张热/间歇热/不规则热）、脉搏（相对缓脉提示伤寒）、呼吸、血压（感染性休克低血压）、血氧","一般情况：神志（感染中毒性脑病/嗜睡/谵妄）、精神状态、面容（伤寒面容/二尖瓣面容）、体位、有无寒战","皮肤黏膜：皮疹（形态/分布/出现时间：斑丘疹/出血疹/疱疹/荨麻疹）、瘀点瘀斑（脑膜炎双球菌）、黄疸、溃疡、焦痂（恙虫病）、脓肿、红肿热痛","淋巴结：全身/局部淋巴结肿大（压痛/质地/活动度）","头颈部：结膜充血/出血、咽充血、扁桃体肿大/渗出、口腔溃疡、颈强直（脑膜刺激征）","胸部：心率心律、双肺呼吸音/啰音（肺部感染）","腹部：压痛（部位）、反跳痛、肝脾肿大、腹水征、肠鸣音","神经系统：意识状态、脑膜刺激征、病理征、局灶体征","其他：感染灶寻找（皮肤/呼吸道/消化道/泌尿道/胆道）"],"lab_tests":["血常规+CRP+PCT：入院即查并动态监测，急性期白细胞多正常或偏低、淋巴细胞相对增多，CRP/PCT用于评估炎症程度及疗效","布鲁菌血培养：寒战高热期（发热前1-2小时或体温上升期）采血2-3套（含需氧瓶），须注明疑布鲁菌病并延长培养至7-14天","血清学检查：虎红平板凝集试验（RBPT）快速初筛＋试管凝集试验（SAT，滴度≥1:100有意义）动态复查，慢性或复发可疑者加查ELISA/免疫捕获法","局部标本病原学：有关节、脊柱、睾丸或神经系统受累时，采关节液、脑脊液等相应标本培养，必要时行药敏试验","影像学：发热伴关节疼痛查受累关节X线/CT/MRI（重点骶髂关节、脊柱）；伴肝脾肿大或泌尿生殖系统症状者行腹部/泌尿系B超","肝肾功能、心肌酶、心电图：入院基线评估，排查多系统受累并为抗感染用药安全提供依据"],"nursing":["隔离与疫情报告：确诊或疑似病例按传染病管理规定床边隔离，标本按生物安全要求处理，24小时内完成法定传染病网络直报","发热护理：每4小时监测体温，观察热型（波状热、弛张热），高热时以物理降温为主、遵医嘱退热药，注意多汗者及时擦干更衣、防受凉及脱水","病情观察与休息：急性期卧床休息，关节肿痛者制动并垫软枕保护，重点观察睾丸肿痛、腰痛/脊柱痛、神经系统及肝脾受累表现，警惕布鲁菌性心内膜炎等并发症","用药护理：多西环素、利福平等药物注意胃肠道反应、肝损伤及光敏反应，宜餐后服、定期复查肝功能，督促足量足疗程规律服药、严禁漏服或自行停药以防复发","健康宣教：告知经接触病畜及其排泄物、食用生乳及未熟肉制品感染，出院后避免接触疫畜及疫区生鲜制品，定期门诊随访复查血清学"],"diet":["忌口：禁食生乳及未消毒奶制品（鲜奶、奶酪、奶皮子等）、生拌牛羊肉及未熟内脏，防止重复感染或传播","推荐：高蛋白、高维生素、易消化饮食（瘦肉、鸡蛋、豆制品、新鲜蔬果），发热期给予流质或半流质，保证充足热量","补液：高热多汗者每日饮水2000-2500ml或口服补液盐，进食不足或呕吐者予静脉补液，维持水电解质平衡","营养支持：慢性期或消耗明显、贫血者加强营养，适当补充B族维生素及铁剂，必要时行肠内营养支持"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":380},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"a5c5e6cd8fe58b2907b953a343d087615a42230b772eed1f25a3e44c7d991b39","pinyin":"bulujunbing","initials":"bljb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","急性期：发热（波浪热型，体温逐日升高达高峰后缓慢下降，持续数天至数周）、多汗（夜间或凌晨退热时大汗淋漓）、关节痛（大关节游走性疼痛，膝关节、髋关节、肩关节）、乏力、食欲减退、头痛、肌痛、肝脾肿大、淋巴结肿大\\n泌尿生殖系统：睾丸炎、附睾炎（男性，单侧睾丸肿痛）、卵巢炎、子宫内膜炎（女性）、流产\\n神经系统：坐骨神经痛、腰骶神经痛、脑膜脑炎、神经根炎、脊髓炎\\n心血管系统：心内膜炎（严重并发症，主动脉瓣受累多见）、心肌炎、心包炎、血管炎\\n呼吸系统：支气管炎、肺炎、胸膜炎\\n慢性期：病程超过1年，表现为固定性关节痛、肌肉痛、乏力、失眠、精神抑郁、低热、肝脾肿大\\n其他：皮疹、皮下结节、眼葡萄膜炎、视神经炎",60],["摘要","由布鲁菌属细菌引起的人畜共患传染病，临床特点为长期发热、多汗、关节痛、肝脾肿大、睾丸炎、脑膜炎等，易转为慢性，复发率高。",30],["疾病编码","A23.9",30],["原首字母","bulujunbing",60]]},{"id":"orders-f03314994132fb79df29","key":"v1-c9ccc21dfe2a3058|orders-f03314994132fb79df29","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"炭疽","category":"内科-感染","raw":{"name":"炭疽","category":"内科-感染","summary":"由炭疽芽孢杆菌引起的人畜共患急性传染病，临床分为皮肤炭疽、肺炭疽、肠炭疽、脑膜炭疽和败血症型，皮肤炭疽最常见，肺炭疽和败血症型病死率高。","symptoms":["皮肤炭疽（最常见，约95%）：暴露部位（面、颈、手、前臂）出现无痛性丘疹，迅速变为水疱，周围组织水肿，水疱破溃形成溃疡，中心黑色焦痂（炭末样），周围水肿明显但疼痛不显著，局部淋巴结肿大，伴发热、头痛、乏力","肺炭疽（吸入性，最严重）：初期类似感冒（低热、乏力、干咳、肌痛），2-4天后突然加重，高热、寒战、咳嗽、咯血、胸痛、呼吸困难、发绀、大汗，纵隔增宽，胸腔积液，常伴休克，病死率高","肠炭疽：恶心、呕吐、腹痛、腹泻、血水样便，严重时呕血、便血、腹膜炎、休克，病死率高","脑膜炭疽（炭疽性脑膜炎）：剧烈头痛、呕吐、颈强直、抽搐、意识障碍、昏迷，脑脊液呈血性或脓性，病情凶险，病死率极高","败血症型：高热、寒战、皮肤黏膜出血、休克、DIC、多器官衰竭，常继发于肺炭疽、肠炭疽或严重皮肤炭疽","全身症状：发热、寒战、乏力、头痛、食欲减退、出汗","严重并发症：感染性休克、DIC、呼吸衰竭、心力衰竭、急性肾损伤、脑膜炎"],"diagnosis":["流行病学史：接触病畜（牛、羊、马）或其皮毛、肉类，吸入含芽孢的气溶胶，食用未煮熟病畜肉类","典型临床表现：皮肤无痛性焦痂溃疡伴周围水肿（皮肤炭疽）、严重呼吸道症状伴纵隔增宽（肺炭疽）、急性胃肠炎伴血便（肠炭疽）、血性脑膜炎（脑膜炭疽）","血常规：白细胞总数及中性粒细胞显著升高（10-20×10^9/L，可达60-80×10^9/L），血小板可减少","病原学检查：皮损分泌物、痰、呕吐物、粪便、血液、脑脊液涂片革兰染色（革兰阳性大杆菌，竹节状排列，有荚膜）、细菌培养（血琼脂平板，卷发状菌落）、动物接种","血清学检查：ELISA检测抗荚膜抗体、抗毒素抗体（恢复期较急性期升高4倍）","分子生物学：PCR检测炭疽芽孢杆菌DNA（荚膜基因、毒素基因）","影像学：胸部X线/CT（肺炭疽：纵隔增宽、胸腔积液、肺部浸润）、腹部CT（肠炭疽：肠壁增厚、腹水、肠梗阻）、头颅CT/MRI（脑膜炭疽：脑水肿、出血）","脑脊液：脑膜炭疽压力升高、血性或脓性、白细胞升高、蛋白升高、糖降低，涂片可找到炭疽杆菌","鉴别诊断：皮肤炭疽（痈、蜂窝织炎、恙虫病、兔热病）、肺炭疽（大叶性肺炎、肺鼠疫、钩体病肺出血型）、肠炭疽（急性菌痢、食物中毒、霍乱）、脑膜炎（其他细菌性脑膜炎）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（病原治疗；首选青霉素G）：","  用法：皮肤炭疽：0.9%NS 100ml + 青霉素G 240-320万U ivgtt q6h，疗程7-10天；肺炭疽、肠炭疽、败血症型、脑膜炭疽：0.9%NS 100ml + 青霉素G 400-800万U ivgtt q4-6h（每日1000-2000万U），疗程2-3周","","方案2（青霉素过敏）：","  用法：0.9%NS 250ml + 多西环素0.1g ivgtt q12h 或 0.9%NS 250ml + 环丙沙星0.4g ivgtt q12h 或 0.9%NS 250ml + 左氧氟沙星0.5g ivgtt qd 或 0.9%NS 250ml + 氯霉素1g ivgtt q6h（脑膜炭疽需透过血脑屏障）","","方案3（联合治疗；重症）：","  用法：青霉素G + 庆大霉素8万U ivgtt q8h 或 青霉素G + 环丙沙星0.4g ivgtt q12h","","方案4（抗炭疽血清）：","  用法：重症患者（肺炭疽、败血症型）在抗生素基础上加用抗炭疽血清100-300ml iv（皮试阴性后，缓慢输注）","","方案5（糖皮质激素）：","  用法：严重毒血症、纵隔水肿、脑膜脑炎：0.9%NS 100ml + 氢化可的松200-300mg ivgtt qd 或 0.9%NS 100ml + 甲泼尼龙80-160mg ivgtt qd（短期，在抗生素基础上使用）〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","","方案6（抗休克）：","  用法：补液（晶体+胶体）、升压药（多巴胺、去甲肾上腺素）、纠正酸中毒","","方案7（DIC）：","  用法：肝素、补充凝血因子、血小板","","方案8（呼吸衰竭）：","  用法：吸氧、机械通气","","方案9（脑膜脑炎）：","  用法：20%甘露醇125ml ivgtt q6-8h（降颅压）、激素、镇静止痉〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","","方案10（皮肤炭疽局部处理）：","  用法：1:2000高锰酸钾湿敷，切忌挤压和切开引流（可致败血症）","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（皮肤炭疽轻症）：","用法：阿莫西林0.5g qid 或 多西环素0.1g bid 或 左氧氟沙星0.5g qd，疗程7-10天〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物2（青霉素过敏）：","用法：多西环素0.1g bid 或 环丙沙星0.5g bid 或 左氧氟沙星0.5g qd〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物3（预防用药（暴露后））：","用法：环丙沙星0.5g bid 或 多西环素0.1g bid 或 阿莫西林0.5g qid，疗程60天（吸入性暴露）〔调 CrCl<30 减量；青霉素过敏禁用〕","药物4（对症）：","用法：对乙酰氨基酚0.5g prn（退热止痛）、补液、止吐、止泻〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物5（皮肤局部）：","用法：1:2000高锰酸钾湿敷，保持清洁，切忌挤压切开","药物6：","用法：中医中药治疗","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["一般治疗：严格隔离（皮肤炭疽接触隔离，肺炭疽呼吸道隔离），卧床休息，加强营养，维持水电解质平衡，就地治疗避免转运","病原治疗：早期足量抗生素，青霉素G首选（皮肤炭疽 160-320万U 静滴 q6h 或 青霉素V 500mg 口服 qid；重症 大剂量静脉给药 400-800万U 静滴 q6h），疗程7-10天（皮肤炭疽）或2-3周（肺炭疽、肠炭疽、败血症、脑膜炭疽），青霉素过敏用多西环素 100mg 口服 bid、环丙沙星 400mg 静滴 q12h、左氧氟沙星 500mg 口服 qd","抗毒素治疗：重症患者加用抗炭疽血清（皮试阴性后 首次 20-30ml 肌注或静滴，之后 20ml q12h）","对症治疗：退热（对乙酰氨基酚 0.5g 口服 q6h）、止痛（布桂嗪 30mg 口服 tid）、补液、抗休克（去甲肾上腺素 0.05-0.5μg/kg·min 静滴）、纠正DIC（肝素 50-100mg 静滴 qd）、呼吸支持、降颅压（甘露醇 0.25-0.5g/kg 静滴 q6-8h）","局部处理：皮肤炭疽用1:2000高锰酸钾湿敷，切忌挤压和切开引流（防止败血症）","并发症治疗：感染性休克（补液+升压+激素，氢化可的松 200-300mg 静滴 qd）、DIC（肝素+凝血因子）、呼吸衰竭（机械通气）、脑膜脑炎（降颅压+激素）、纵隔水肿（激素+利尿剂，呋塞米 20mg 静推）","手术治疗：一般不手术，皮肤炭疽切忌切开，肠炭疽并发肠梗阻、穿孔时需手术","预防：管理传染源（病畜隔离、焚烧或深埋病死畜）、切断传播途径（皮毛消毒、肉类煮熟、个人防护）、保护易感人群（炭疽疫苗接种、职业防护、暴露后预防用环丙沙星 500mg 口服 bid 或 多西环素 100mg 口服 bid，共 60 天）","疫情报告：肺炭疽按甲类传染病管理，2小时内报告；皮肤炭疽、肠炭疽按乙类管理，24小时内报告"],"management":["严格隔离：皮肤炭疽接触隔离，肺炭疽呼吸道隔离，患者分泌物、排泄物、污染物严格消毒","卧床休息，避免劳累","清淡易消化饮食，保证营养，多饮水","监测生命体征、意识、皮肤焦痂变化、呼吸、循环情况","皮肤炭疽切忌挤压和切开引流，用1:2000高锰酸钾湿敷，保持局部清洁","规律足量抗生素治疗，完成疗程，不可自行停药","注意药物副作用（青霉素过敏、赫氏反应；多西环素胃肠道反应、光敏；喹诺酮类关节痛、肌腱炎）","肺炭疽患者就地治疗，避免长途转运","接触者医学观察8天，必要时预防用药","职业人群（牧民、屠宰工、皮毛加工、兽医）做好个人防护（戴口罩、手套、穿防护服）","病死畜焚烧或深埋（2米以下，加漂白粉），严禁剥皮食用","皮毛制品严格消毒（环氧乙烷、甲醛熏蒸）","炭疽疫苗接种（职业人群，每年1次）","保持乐观心态，皮肤炭疽预后好，肺炭疽和败血症型病死率高"],"notes":["又称炭疽病，是由炭疽芽孢杆菌引起的人畜共患急性传染病","病原体：炭疽芽孢杆菌，革兰阳性大杆菌，竹节状排列，有荚膜和芽孢，芽孢抵抗力极强（土壤中可存活数十年）","传染源：病畜（牛、羊、马、猪），人传人罕见","传播途径：皮肤接触（破损皮肤接触病畜或皮毛）、呼吸道吸入（含芽孢的气溶胶，肺炭疽）、消化道摄入（未煮熟病畜肉类，肠炭疽）、虫媒叮咬","临床分型：皮肤炭疽（最常见，约95%，病死率<1%）、肺炭疽（最严重，病死率>80%）、肠炭疽（病死率25-75%）、脑膜炭疽（病死率近100%）、败血症型","皮肤炭疽特征：无痛性焦痂溃疡伴周围显著水肿（疼痛不显著是特点，与痈、蜂窝织炎鉴别）","肺炭疽特征：初期感冒样症状，2-4天后突然加重，纵隔增宽、胸腔积液、呼吸困难，病死率高","治疗：青霉素G首选，早期足量，重症大剂量静脉给药，皮肤炭疽疗程7-10天，肺炭疽等重症2-3周","抗炭疽血清用于重症患者，皮试阴性后使用","皮肤炭疽切忌挤压和切开引流（可致败血症）","肺炭疽按甲类传染病管理，2小时内报告","预防关键是管理病畜和职业防护","炭疽芽孢杆菌芽孢可用于生物恐怖主义，需警惕"],"emergency":["出现高热寒战、呼吸困难咯血发绀（肺炭疽）、剧烈腹痛呕血便血（肠炭疽）、剧烈头痛呕吐意识障碍抽搐（脑膜炭疽）、皮肤焦痂迅速扩大伴严重水肿、休克立即就医，严格隔离就地治疗"],"pinyin":"tanju","icd10":"A22.9","physical_exam":["生命体征：体温（热型：稽留热/弛张热/间歇热/不规则热）、脉搏（相对缓脉提示伤寒）、呼吸、血压（感染性休克低血压）、血氧","一般情况：神志（感染中毒性脑病/嗜睡/谵妄）、精神状态、面容（伤寒面容/二尖瓣面容）、体位、有无寒战","皮肤黏膜：皮疹（形态/分布/出现时间：斑丘疹/出血疹/疱疹/荨麻疹）、瘀点瘀斑（脑膜炎双球菌）、黄疸、溃疡、焦痂（恙虫病）、脓肿、红肿热痛","淋巴结：全身/局部淋巴结肿大（压痛/质地/活动度）","头颈部：结膜充血/出血、咽充血、扁桃体肿大/渗出、口腔溃疡、颈强直（脑膜刺激征）","胸部：心率心律、双肺呼吸音/啰音（肺部感染）","腹部：压痛（部位）、反跳痛、肝脾肿大、腹水征、肠鸣音","神经系统：意识状态、脑膜刺激征、病理征、局灶体征","其他：感染灶寻找（皮肤/呼吸道/消化道/泌尿道/胆道）"],"lab_tests":["血常规（急查，动态观察白细胞、中性粒细胞及血小板变化，评估感染及DIC风险）","病原学检查：皮肤炭疽取水疱液、溃疡分泌物，肺炭疽取血、痰，肠炭疽取粪便及血行血培养＋涂片革兰染色查找炭疽芽孢杆菌（抗菌治疗前采集）","CRP、PCT（感染及炎症指标动态监测，评估疗效）","影像学：肺炭疽行胸部X线/CT（观察纵隔增宽、胸腔积液及肺部浸润），肠炭疽行腹部CT/超声（肠壁水肿、腹水、肠系膜淋巴结肿大）","血清学检查：炭疽抗体（急性期与恢复期双份血清）及毒素检测，用于回顾性确诊","凝血功能、肝肾功能、血气分析及血氧饱和度监测（重症/肺炭疽，评估DIC及多器官功能损伤）"],"nursing":["严密隔离：肺炭疽行空气隔离＋接触隔离（单间、负压病房，医护人员戴N95口罩），皮肤及肠炭疽行接触隔离；确诊后按规定时限网络直报疫情，密切接触者医学观察12天","皮肤炭疽病灶护理：局部保持清洁干燥，严禁挤压、切开或引流病灶（防败血症播散），更换敷料后焚烧或高压灭菌，观察溃疡、焦痂及周围水肿进展","病情观察：密切监测生命体征、神志、出血倾向及呼吸困难；肺炭疽监测血氧饱和度警惕呼吸衰竭，肠炭疽观察腹痛、腹泻及血便情况","发热护理：高热时物理降温或遵医嘱药物降温，及时补液，监测出入量，防止脱水及电解质紊乱","防并发症：观察有无败血症休克、炭疽脑膜炎（剧烈头痛、呕吐、颈强直）及DIC征象，配合抗感染治疗；病人分泌物、排泄物及被服污染物用含氯消毒剂消毒处理"],"diet":["给予高热量、高蛋白、富含维生素的流质或半流质饮食（如牛奶、蛋羹、鱼汤、米糊），保证能量及营养供给","肠炭疽急性期暂禁食或仅少量无渣流质，腹痛、腹泻缓解后逐步过渡到半流质、软食，避免粗纤维及刺激性食物","鼓励多饮水，高热、腹泻脱水者及时静脉补液，维持水、电解质及酸碱平衡","皮肤炭疽患者忌辛辣、油腻、海鲜等刺激性及致敏食物，避免搔抓或摩擦病灶","重症或进食不足者给予肠内营养支持，必要时辅以静脉营养，维持氮平衡促进恢复"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":381},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"ec2c965946ed58a52d8f7035d3665b3e01223c705c8893983d1f7d9cfc719db0","pinyin":"tanju","initials":"tj","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","皮肤炭疽（最常见，约95%）：暴露部位（面、颈、手、前臂）出现无痛性丘疹，迅速变为水疱，周围组织水肿，水疱破溃形成溃疡，中心黑色焦痂（炭末样），周围水肿明显但疼痛不显著，局部淋巴结肿大，伴发热、头痛、乏力\\n肺炭疽（吸入性，最严重）：初期类似感冒（低热、乏力、干咳、肌痛），2-4天后突然加重，高热、寒战、咳嗽、咯血、胸痛、呼吸困难、发绀、大汗，纵隔增宽，胸腔积液，常伴休克，病死率高\\n肠炭疽：恶心、呕吐、腹痛、腹泻、血水样便，严重时呕血、便血、腹膜炎、休克，病死率高\\n脑膜炭疽（炭疽性脑膜炎）：剧烈头痛、呕吐、颈强直、抽搐、意识障碍、昏迷，脑脊液呈血性或脓性，病情凶险，病死率极高\\n败血症型：高热、寒战、皮肤黏膜出血、休克、DIC、多器官衰竭，常继发于肺炭疽、肠炭疽或严重皮肤炭疽\\n全身症状：发热、寒战、乏力、头痛、食欲减退、出汗\\n严重并发症：感染性休克、DIC、呼吸衰竭、心力衰竭、急性肾损伤、脑膜炎",60],["摘要","由炭疽芽孢杆菌引起的人畜共患急性传染病，临床分为皮肤炭疽、肺炭疽、肠炭疽、脑膜炭疽和败血症型，皮肤炭疽最常见，肺炭疽和败血症型病死率高。",30],["疾病编码","A22.9",30],["原首字母","tanju",60]]},{"id":"orders-eda92f2db4c7708305c7","key":"v1-c9ccc21dfe2a3058|orders-eda92f2db4c7708305c7","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"鼠疫","category":"内科-感染","raw":{"name":"鼠疫","category":"内科-感染","summary":"由鼠疫耶尔森菌引起的自然疫源性烈性传染病，属于甲类传染病，临床分为腺鼠疫、肺鼠疫、败血症型鼠疫等，传染性强，病死率高。","symptoms":["腺鼠疫（最常见）：急起寒战、高热、头痛、乏力、全身酸痛，淋巴结肿大（腹股沟最常见，其次腋下、颈部），淋巴结明显红肿热痛、坚硬、与周围组织粘连，疼痛剧烈，4-5天后淋巴结化脓破溃，可发展为败血症","肺鼠疫（最严重，甲类）：急起寒战、高热、头痛、胸痛、咳嗽、咳大量粉红色泡沫痰或鲜血痰、呼吸困难、发绀，肺部体征少（与症状不平行），2-3天内死于心力衰竭、休克、败血症，传染性极强（飞沫传播）","败血症型鼠疫（最凶险）：高热或体温不升、寒战、头痛、谵妄、昏迷、广泛皮肤黏膜出血、鼻出血、呕血、便血、血尿、DIC、休克、多器官衰竭，常在2-3天内死亡，皮肤广泛出血坏死呈紫黑色（黑死病）","其他类型：皮肤鼠疫（红斑、水疱、脓疱、溃疡、黑色焦痂）、肠鼠疫（呕吐、腹痛、腹泻、血水样便）、眼鼠疫（结膜炎、化脓性角膜炎）、脑膜炎型鼠疫（头痛、呕吐、颈强直、谵妄、昏迷）","全身中毒症状：高热、寒战、头痛、乏力、恶心、呕吐、烦躁不安、意识模糊","严重并发症：感染性休克、DIC、呼吸衰竭、心力衰竭、急性肾损伤、多器官功能衰竭"],"diagnosis":["流行病学史：发病前10天内到过鼠疫疫区，接触过疫源动物（鼠类、旱獭）或其皮毛，被蚤类叮咬，接触过鼠疫患者","典型临床表现：急性淋巴结炎伴严重毒血症（腺鼠疫）、严重肺炎伴咯血呼吸困难（肺鼠疫）、败血症伴广泛出血（败血症型）","血常规：白细胞总数及中性粒细胞显著升高（20-30×10^9/L，可达100×10^9/L），血小板减少，贫血","病原学检查：淋巴结穿刺液、痰、血、脑脊液、粪便涂片革兰染色（革兰阴性球杆菌，两端浓染）、细菌培养（血琼脂平板，最适温度28-30℃）、动物接种（豚鼠或小鼠皮下接种）","血清学检查：间接血凝试验（IHA，检测F1抗体，滴度≥1:16或恢复期升高4倍）、ELISA、荧光抗体染色","分子生物学：PCR检测鼠疫耶尔森菌DNA（F1基因、毒力质粒基因）","影像学：胸部X线/CT（肺鼠疫：肺部浸润、实变、胸腔积液、肺水肿）","脑脊液：脑膜炎型压力升高、白细胞升高、蛋白升高、糖降低","鉴别诊断：腺鼠疫（急性淋巴结炎、丝虫病、兔热病、猫抓病）、肺鼠疫（大叶性肺炎、肺炭疽、钩体病肺出血型、SARS）、败血症型（其他细菌败血症、流行性出血热、钩体病）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：病原治疗（早期足量联合，首选氨基糖苷类）：腺鼠疫：0.9%NS 250ml + 庆大霉素8万U ivgtt q8h（或链霉素0.5g im q6h，首日2g，后1g/d）+ 0.9%NS 250ml + 多西环素0.1g ivgtt q12h，疗程10-14天〔调 ★ 8岁以下及妊娠期禁用；食管刺激（需直立饮水送服）〕","方案2（肺鼠疫、败血症型）：","用法：0.9%NS 250ml + 链霉素0.5g im q4-6h（首日4g，后2g/d）+ 0.9%NS 250ml + 氯霉素1g ivgtt q6h（透过血脑屏障）+ 0.9%NS 250ml + 多西环素0.1g ivgtt q12h，疗程10-14天〔调 ★ 8岁以下及妊娠期禁用；食管刺激（需直立饮水送服）〕","方案3（替代方案）：","用法：0.9%NS 250ml + 左氧氟沙星0.5g ivgtt qd 或 0.9%NS 250ml + 环丙沙星0.4g ivgtt q12h 或 0.9%NS 250ml + 头孢曲松2g ivgtt qd（联合用药）〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","方案4（抗休克）：","用法：快速补液（晶体+胶体）、升压药（多巴胺5-20μg/kg/min、去甲肾上腺素0.05-1μg/kg/min）、纠正酸中毒（5%碳酸氢钠）、糖皮质激素（氢化可的松200-300mg ivgtt qd）〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","方案5（DIC）：","用法：肝素钠5000-10000U iv q6h（监测凝血）、补充凝血因子（新鲜冰冻血浆）、血小板","方案6（呼吸衰竭）：","用法：吸氧、机械通气（肺鼠疫）","方案7（心力衰竭）：","用法：链霉素 1g 肌注 q12h（或庆大霉素、多西环素等）；对症支持治疗；仅在明确合并心衰/心律失常/心绞痛时使用去乙酰毛花苷、呋塞米、硝酸甘油","方案8（脑膜脑炎型）：","用法：20%甘露醇125ml ivgtt q6-8h（降颅压）、氯霉素（透过血脑屏障）、激素〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","方案9（腺鼠疫局部处理）：","用法：淋巴结切忌挤压，可用5%鱼石脂酒精外敷，化脓后可切开引流（需在足量抗生素基础上）","方案10（对症治疗）：","用法：退热（物理降温、对乙酰氨基酚）、镇静、止痛、营养支持、维持水电解质平衡〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（预防用药（接触者））：","用法：多西环素0.1g bid 或 四环素0.5g qid 或 磺胺嘧啶1g q6h，疗程7天〔调 ★ 8岁以下及妊娠期禁用；食管刺激（需直立饮水送服）〕","药物2（轻症口服）：","用法：多西环素0.1g bid 或 左氧氟沙星0.5g qd 或 复方磺胺甲噁唑2片 bid〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物3（对症）：","用法：对乙酰氨基酚0.5g prn（退热止痛）、补液、止吐、止泻〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物4：","用法：中医中药治疗（辅助）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["一般治疗：严格隔离（肺鼠疫呼吸道隔离，腺鼠疫接触隔离），就地治疗避免转运，卧床休息，加强营养，维持水电解质平衡，分泌物排泄物严格消毒","病原治疗：早期、足量、联合应用抗生素，氨基糖苷类首选（链霉素 0.5g 肌注 q6h 或 庆大霉素 80mg 静滴 q8h），联合多西环素 100mg 静滴 q12h、氯霉素 0.5g 静滴 q6h、喹诺酮类（环丙沙星 400mg 静滴 q12h），疗程10-14天，肺鼠疫和败血症型大剂量静脉给药","对症治疗：抗休克（多巴胺 5-20μg/kg·min 静滴）、纠正DIC（肝素 50-100mg 静滴 qd）、呼吸支持、强心利尿（西地兰 0.2-0.4mg 静推）、降颅压（甘露醇 0.25-0.5g/kg 静滴 q6-8h）、退热（对乙酰氨基酚 0.5g 口服 q6h）镇静（地西泮 5-10mg 静推）、营养支持","局部处理：腺鼠疫淋巴结切忌挤压，化脓后在足量抗生素基础上切开引流，皮肤鼠疫用抗生素软膏（如 莫匹罗星 涂患处 bid）","并发症治疗：感染性休克（补液+升压+激素，氢化可的松 200-300mg 静滴 qd）、DIC（肝素+凝血因子）、呼吸衰竭（机械通气）、心力衰竭（强心利尿扩血管）、急性肾损伤（血液透析）","疫情报告：甲类传染病，2小时内网络报告，同时电话报告","密切接触者医学观察9天，预防用药7天（多西环素 100mg 口服 bid 或 环丙沙星 500mg 口服 bid）","预防：管理传染源（灭鼠灭蚤、病畜处理）、切断传播途径（个人防护、消毒）、保护易感人群（鼠疫疫苗接种、预防用药）","定期随访：监测血常规、血培养、淋巴结情况（每 3-7 天复查 1 次）"],"management":["严格隔离：肺鼠疫呼吸道隔离，腺鼠疫接触隔离，患者分泌物、排泄物、污染物严格消毒（漂白粉、来苏水）","就地治疗，避免长途转运","卧床休息，避免劳累","清淡易消化饮食，保证营养，多饮水","监测生命体征、意识、淋巴结大小、皮肤出血、呼吸循环情况","腺鼠疫切忌挤压淋巴结，化脓后在足量抗生素基础上切开引流","规律足量抗生素治疗，完成疗程（10-14天），不可自行停药","注意药物副作用（链霉素耳毒性、肾毒性；庆大霉素肾毒性、耳毒性；氯霉素骨髓抑制；多西环素胃肠道反应、光敏）","肺鼠疫患者就地治疗，避免转运，医护人员严格防护（N95口罩、防护服、手套、护目镜）","密切接触者医学观察9天，预防用药7天","疫区工作者做好个人防护（戴口罩、手套、穿防护服、防蚤叮咬）","灭鼠灭蚤，避免接触疫源动物（鼠类、旱獭），不食用病死动物","鼠疫疫苗接种（疫区人群、职业人群，每年1次）","保持乐观心态，腺鼠疫预后较好（抗生素治疗后病死率<5%），肺鼠疫和败血症型病死率高（未经治疗>90%，早期治疗可降至10%以下）"],"notes":["又称黑死病，是甲类传染病（传染性最强、病死率最高），2小时内报告","病原体：鼠疫耶尔森菌，革兰阴性球杆菌，两端浓染，有荚膜，无鞭毛芽孢，最适温度28-30℃","传染源：鼠类等啮齿动物（主要）、肺鼠疫患者（人传人）","传播途径：鼠蚤叮咬（腺鼠疫，鼠-蚤-人）、呼吸道飞沫（肺鼠疫，人-人）、皮肤接触（破损皮肤接触疫源动物或患者分泌物）、消化道（食用未煮熟疫源动物）","临床分型：腺鼠疫（最常见，腹股沟淋巴结炎）、肺鼠疫（最严重，甲类，飞沫传播）、败血症型（最凶险，黑死病）、皮肤鼠疫、肠鼠疫、眼鼠疫、脑膜炎型","典型表现：腺鼠疫（急性淋巴结炎+严重毒血症，淋巴结疼痛剧烈）、肺鼠疫（严重肺炎+咯血+呼吸困难，肺部体征少与症状不平行）、败血症型（广泛出血+休克+DIC，皮肤紫黑）","实验室检查：白细胞显著升高，病原学检查（涂片、培养、动物接种）确诊，血清学检测F1抗体","治疗：链霉素首选，早期足量联合用药，肺鼠疫和败血症型大剂量静脉给药，疗程10-14天","腺鼠疫切忌挤压淋巴结，防止败血症","肺鼠疫按甲类传染病管理，2小时内报告，就地治疗避免转运","预防关键是灭鼠灭蚤和个人防护","历史上曾三次大流行，死亡数亿人","目前仍有散发，主要在非洲、亚洲、美洲部分地区","可用于生物恐怖主义，需警惕"],"emergency":["出现高热寒战、淋巴结剧烈肿痛（腺鼠疫）、咳嗽咯血呼吸困难发绀（肺鼠疫）、广泛皮肤黏膜出血休克意识障碍（败血症型）立即就医，严格隔离就地治疗，2小时内传染病报告"],"pinyin":"shuyi","icd10":"A20.9","physical_exam":["生命体征：体温（热型：稽留热/弛张热/间歇热/不规则热）、脉搏（相对缓脉提示伤寒）、呼吸、血压（感染性休克低血压）、血氧","一般情况：神志（感染中毒性脑病/嗜睡/谵妄）、精神状态、面容（伤寒面容/二尖瓣面容）、体位、有无寒战","皮肤黏膜：皮疹（形态/分布/出现时间：斑丘疹/出血疹/疱疹/荨麻疹）、瘀点瘀斑（脑膜炎双球菌）、黄疸、溃疡、焦痂（恙虫病）、脓肿、红肿热痛","淋巴结：全身/局部淋巴结肿大（压痛/质地/活动度）","头颈部：结膜充血/出血、咽充血、扁桃体肿大/渗出、口腔溃疡、颈强直（脑膜刺激征）","胸部：心率心律、双肺呼吸音/啰音（肺部感染）","腹部：压痛（部位）、反跳痛、肝脾肿大、腹水征、肠鸣音","神经系统：意识状态、脑膜刺激征、病理征、局灶体征","其他：感染灶寻找（皮肤/呼吸道/消化道/泌尿道/胆道）"],"lab_tests":["血常规+CRP+PCT：入院即刻检查，治疗期间动态复查（白细胞显著升高、血小板减少提示重症）","病原学检查：血培养、痰培养、淋巴结穿刺液/脓液培养，于抗菌药物使用前采集（双侧双瓶）","鼠疫耶尔森菌核酸检测（PCR）：血液、痰液、淋巴结穿刺液，快速确诊","血清学检查：鼠疫F1抗体（间接血凝试验/ELISA），急性期与恢复期双份血清对比","胸部X线/CT：入院即查，肺鼠疫可见肺部浸润、实变、空洞，病情变化时复查","淋巴结超声（腺鼠疫）：评估肿大淋巴结大小、脓腔及引流条件"],"nursing":["严格隔离：按甲类传染病管理，单间隔离（肺鼠疫置于负压病房），执行接触隔离+飞沫隔离，护理人员二级防护，患者痰液、脓液、分泌物、排泄物经含氯消毒剂严格处理后排放","疫情报告：确诊/疑似病例2小时内上报疾控部门，密切接触者登记并医学观察","病情观察：严密监测体温、心率、呼吸、血压、血氧饱和度及意识状态，警惕休克、DIC、呼吸衰竭、败血症征象","发热护理：高热以物理降温为主，遵医嘱用药，加强补液、监测出入量，防止脱水与休克","腺鼠疫局部护理：肿大淋巴结避免挤压、按摩，破溃后规范引流换药，保持创面清洁干燥；密切观察皮肤出血点、瘀斑变化"],"diet":["高热量、高蛋白、高维生素易消化流质/半流质饮食（如蛋羹、鱼汤、米粥），少量多餐","保证充足饮水，进食不足者静脉补液维持水电解质平衡，防止脱水与感染性休克","发热期忌油腻、辛辣刺激及生冷食物，以清淡易消化为主","重症或进食困难者予肠内营养支持，必要时肠外营养，维持营养状况","餐具专用并煮沸消毒，剩余食物按医疗废物规范处置"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":382},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"7c2e683c358280832529fdd934b0ca8379b57f2c0238a1d473e1c8f710526b2c","pinyin":"shuyi","initials":"sy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","腺鼠疫（最常见）：急起寒战、高热、头痛、乏力、全身酸痛，淋巴结肿大（腹股沟最常见，其次腋下、颈部），淋巴结明显红肿热痛、坚硬、与周围组织粘连，疼痛剧烈，4-5天后淋巴结化脓破溃，可发展为败血症\\n肺鼠疫（最严重，甲类）：急起寒战、高热、头痛、胸痛、咳嗽、咳大量粉红色泡沫痰或鲜血痰、呼吸困难、发绀，肺部体征少（与症状不平行），2-3天内死于心力衰竭、休克、败血症，传染性极强（飞沫传播）\\n败血症型鼠疫（最凶险）：高热或体温不升、寒战、头痛、谵妄、昏迷、广泛皮肤黏膜出血、鼻出血、呕血、便血、血尿、DIC、休克、多器官衰竭，常在2-3天内死亡，皮肤广泛出血坏死呈紫黑色（黑死病）\\n其他类型：皮肤鼠疫（红斑、水疱、脓疱、溃疡、黑色焦痂）、肠鼠疫（呕吐、腹痛、腹泻、血水样便）、眼鼠疫（结膜炎、化脓性角膜炎）、脑膜炎型鼠疫（头痛、呕吐、颈强直、谵妄、昏迷）\\n全身中毒症状：高热、寒战、头痛、乏力、恶心、呕吐、烦躁不安、意识模糊\\n严重并发症：感染性休克、DIC、呼吸衰竭、心力衰竭、急性肾损伤、多器官功能衰竭",60],["摘要","由鼠疫耶尔森菌引起的自然疫源性烈性传染病，属于甲类传染病，临床分为腺鼠疫、肺鼠疫、败血症型鼠疫等，传染性强，病死率高。",30],["疾病编码","A20.9",30],["原首字母","shuyi",60]]},{"id":"orders-2fdf4136d183e58a9fa2","key":"v1-c9ccc21dfe2a3058|orders-2fdf4136d183e58a9fa2","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"霍乱","category":"内科-感染","raw":{"name":"霍乱","category":"内科-感染","summary":"由霍乱弧菌引起的烈性肠道传染病，属于甲类传染病，典型表现为剧烈吐泻、米泔水样便、严重脱水、电解质紊乱、循环衰竭，病死率高。","symptoms":["潜伏期：数小时至5天，多数1-3天","泻吐期：剧烈腹泻（首发症状，无发热、无腹痛、无里急后重，米泔水样便或清水样便，量多次频，每日数十次甚至失禁）、呕吐（多在腹泻后，喷射性，初为胃内容物，后为米泔水样，无恶心）","脱水期：脱水（轻度：皮肤黏膜干燥、弹性稍差、尿量减少；中度：皮肤弹性差、眼窝凹陷、声音嘶哑、血压下降、尿量减少；重度：皮肤干皱、弹性消失、眼窝深凹、神志不清、血压测不出、无尿）、电解质紊乱（低钠：肌肉痉挛，腓肠肌和腹直肌最明显；低钾：肌张力减低、腱反射消失、鼓肠、心律失常）、代谢性酸中毒（呼吸深快、意识障碍）、循环衰竭（血压下降、脉搏细速、四肢厥冷、意识模糊、昏迷、少尿无尿）","恢复期/反应期：脱水纠正后症状消失，体温回升，可出现反应性发热（38-39℃，持续1-3天自行消退）","临床分型：轻型（仅有腹泻，无脱水）、中型（典型吐泻，中度脱水）、重型（重度脱水、循环衰竭）、暴发型/中毒型（干性霍乱，起病急骤，无明显吐泻即出现中毒性循环衰竭，迅速死亡）","并发症：急性肾衰竭（少尿无尿、氮质血症）、急性肺水肿（补液过快或酸中毒导致）、低钾血症、心律失常、流产、早产"],"diagnosis":["流行病学史：发病前5天内到过霍乱疫区，接触过霍乱患者或带菌者，食用过被污染的水或食物（海鲜、水产品）","典型临床表现：剧烈无痛性腹泻、米泔水样便、喷射性呕吐、严重脱水、循环衰竭、肌肉痉挛","粪便常规：水样便，无脓细胞或少量白细胞","病原学检查：粪便涂片革兰染色（革兰阴性弧菌，鱼群状排列）、悬滴检查（动力试验阳性，流星样穿梭运动，制动试验阳性）、细菌培养（碱性蛋白胨水增菌，TCBS琼脂平板培养，黄色菌落）、霍乱弧菌分型（O1群古典生物型/埃尔托生物型，O139群）","血清学检查：抗菌抗体（凝集试验，恢复期滴度≥1:100或升高4倍）、抗毒抗体","分子生物学：PCR检测霍乱弧菌毒素基因（ctxA、tcpA）","血常规：白细胞升高、血红蛋白升高（血液浓缩）、血小板正常","生化检查：尿素氮、肌酐升高（肾前性）、钠氯降低、钾降低、碳酸氢根降低（代谢性酸中毒）","鉴别诊断：急性细菌性痢疾（发热、腹痛、里急后重、黏液脓血便）、大肠杆菌性肠炎（发热、腹痛、水样便）、沙门菌肠炎（发热、腹痛、腹泻）、病毒性肠炎（发热、呕吐、水样便）、食物中毒（集体发病、呕吐为主、腹痛）、砷中毒（呕吐、腹泻、腹痛、循环衰竭）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（补液治疗；关键，早期、快速、足量）：","  用法：重度脱水：立即静脉补液，第一条静脉通道0.9%NS 1000-2000ml快速静滴（30分钟内），后用2:1液（2份0.9%NS+1份1.4%碳酸氢钠）或3:2:1液（3份5%GS+2份0.9%NS+1份1.4%碳酸氢钠），第一个24小时补液量8000-12000ml，先快后慢，先盐后糖，见尿补钾；中度脱水：第一个24小时4000-8000ml；轻度脱水：口服补液为主","","方案2（纠正电解质紊乱）：","  用法：低钠肌肉痉挛：0.9%NS 250ml ivgtt（补充钠盐）；低钾：见尿补钾，0.9%NS 500ml + 氯化钾10-15ml ivgtt（浓度<0.3%，速度<20mmol/h），严重低钾可静脉泵入","","方案3（纠正代谢性酸中毒）：","  用法：5%碳酸氢钠125-250ml ivgtt（根据血气分析）〔调 心衰/肾功能不全/钠潴留者慎用；代谢性碱中毒禁用〕","","方案4（病原治疗；辅助，缩短病程、减少排菌）：","  用法：0.9%NS 250ml + 多西环素0.1g ivgtt q12h 或 0.9%NS 250ml + 环丙沙星0.4g ivgtt q12h 或 0.9%NS 250ml + 左氧氟沙星0.5g ivgtt qd 或 0.9%NS 250ml + 阿奇霉素0.5g ivgtt qd，疗程3天","","方案5（抗休克）：","  用法：快速补液（晶体+胶体）、升压药（多巴胺、去甲肾上腺素，补液后血压仍低时）、糖皮质激素（氢化可的松200mg（5%GS 50ml；泵入，按体重配）ivgtt，重症）〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","","方案6（急性肾衰竭）：","  用法：限制液体、纠正高钾血症、血液透析（少尿无尿、严重高钾、酸中毒）","","方案7（急性肺水肿）：","  用法：停止或减慢补液、吸氧、利尿（呋塞米20-40mg iv）、扩血管、强心（西地兰）〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","","方案8（对症治疗）：","  用法：肌肉痉挛可局部热敷、按摩，严重时静脉补钙（10%葡萄糖酸钙10-20ml iv）；呕吐严重可甲氧氯普胺10mg im〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（口服补液盐（ORS））：","用法：轻中度脱水首选，重度脱水静脉补液纠正休克后改用口服，ORS III 250ml每15-30分钟一次，根据腹泻量调整","药物2（病原治疗口服）：","用法：多西环素0.1g bid（3天）或 环丙沙星0.5g bid（3天）或 左氧氟沙星0.5g qd（3天）或 阿奇霉素0.5g qd（3天）或 复方磺胺甲噁唑2片 bid（3天）〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物3（对症）：","用法：蒙脱石散3g tid（吸附毒素，保护肠黏膜）、双歧杆菌三联活菌胶囊2粒 tid（调节肠道菌群）、补液、补钾（氯化钾缓释片1g tid，见尿补钾）〔调 ★ 与其他药间隔1-2小时；肠梗阻禁用〕","药物4（预防用药（接触者））：","用法：多西环素0.1g bid 或 环丙沙星0.5g bid，疗程2天〔调 ★ 8岁以下及妊娠期禁用；食管刺激（需直立饮水送服）〕","药物5：","用法：中医中药治疗（辅助，如藿香正气水、葛根芩连汤）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["一般治疗：严格消化道隔离（甲类传染病），卧床休息，流质饮食，呕吐严重可暂禁食，恢复期逐渐恢复饮食","补液治疗（关键）：早期、快速、足量、先盐后糖、先快后慢、见尿补钾，静脉补液（重度脱水：生理盐水或 541 液 100ml/kg，最初 30 分钟 30ml/kg 快速静滴；轻度 3000-4000ml/d）+口服补液（口服补液盐 轻中度 75ml/kg，4-6 小时内服完），纠正脱水、电解质紊乱、酸中毒","病原治疗：抗生素辅助治疗，多西环素 200mg 口服 单剂（或 100mg bid×3天）、环丙沙星 500mg 口服 bid×3天、左氧氟沙星 500mg 口服 qd×3天、阿奇霉素 1g 口服 单剂，疗程3天，缩短病程、减少排菌量","对症治疗：肌肉痉挛（补钙，10% 葡萄糖酸钙 10ml 静推；热敷）、呕吐（甲氧氯普胺 10mg 肌注）、发热（物理降温）、急性肾衰竭（透析）、急性肺水肿（呋塞米 20-40mg 静推、西地兰 0.2-0.4mg 静推、扩血管）","并发症治疗：急性肾衰竭（限制液体、纠正高钾、血液透析）、急性肺水肿（停止补液、吸氧、呋塞米 20-40mg 静推、西地兰 0.2-0.4mg 静推）、低钾血症（氯化钾 1-2g 口服 tid 或 静滴 0.3% 浓度）、循环衰竭（补液+升压+激素）","疫情报告：甲类传染病，2小时内网络报告，同时电话报告","密切接触者医学观察5天，预防用药2天（多西环素 100mg 口服 bid）","预防：管理传染源（患者隔离治疗至症状消失后6天，粪便培养连续2次阴性；带菌者隔离治疗）、切断传播途径（饮水消毒、食物煮熟、饭前便后洗手、灭蝇）、保护易感人群（霍乱疫苗接种、注意饮食卫生）","定期随访：监测粪便培养、肾功能、电解质（每 1-3 天复查 1 次，连续 2 次阴性）"],"management":["严格消化道隔离：患者排泄物、呕吐物、污染物严格消毒（漂白粉、来苏水），餐具单独消毒","卧床休息，避免劳累","流质饮食，呕吐严重暂禁食，恢复期逐渐增加饮食（清淡易消化）","密切监测生命体征、神志、皮肤弹性、眼窝凹陷、尿量、呕吐腹泻量、电解质","记录24小时出入量","口服补液盐（ORS）轻中度脱水首选，少量多次","规律足量抗生素治疗，完成疗程（3天）","注意药物副作用（多西环素胃肠道反应、光敏；喹诺酮类关节痛、肌腱炎；复方磺胺甲噁唑过敏、肾损伤）","患者隔离至症状消失后6天，粪便培养连续2次阴性方可解除隔离","密切接触者医学观察5天，预防用药2天","注意饮食卫生：饮水消毒、食物煮熟、饭前便后洗手、不喝生水、不吃生冷食物","灭蝇防蝇，保持环境卫生","霍乱疫苗接种（疫区人群、旅行者、职业人群）","保持乐观心态，轻型预后好，重型未经治疗病死率可达50%以上，早期正确补液治疗病死率<1%"],"notes":["又称二号病，是甲类传染病（传染性最强），2小时内报告","病原体：霍乱弧菌，革兰阴性弧菌，有鞭毛（运动活泼），O1群（古典生物型、埃尔托生物型）和O139群致病，产生霍乱肠毒素（CT）是主要致病物质","传染源：患者和带菌者（轻型患者、恢复期带菌者、健康带菌者是重要传染源）","传播途径：粪-口途径，水传播最常见（水源污染导致暴发流行），食物传播、接触传播、苍蝇传播","典型表现：剧烈无痛性腹泻（米泔水样便）、喷射性呕吐、严重脱水、电解质紊乱、循环衰竭、肌肉痉挛（腓肠肌）","实验室检查：粪便悬滴动力试验阳性、制动试验阳性，粪便培养确诊，血常规血液浓缩","治疗关键：早期快速足量补液（静脉+口服），纠正脱水和电解质紊乱，抗生素辅助","补液原则：先盐后糖、先快后慢、见尿补钾、纠酸补钙","病原治疗：多西环素、环丙沙星、左氧氟沙星、阿奇霉素，疗程3天","并发症：急性肾衰竭（最常见）、急性肺水肿、低钾血症、循环衰竭","预防关键：饮水消毒、饮食卫生、灭蝇、疫苗接种","历史上曾七次大流行，目前主要在亚洲、非洲部分地区流行","O139群是1992年发现的新流行株，可感染成人","可用于生物恐怖主义，需警惕"],"emergency":["出现剧烈腹泻（米泔水样便）、喷射性呕吐、严重脱水（皮肤干皱、眼窝凹陷、血压下降、少尿无尿）、肌肉痉挛、意识障碍立即就医，严格消化道隔离，2小时内传染病报告，快速静脉补液"],"pinyin":"huoluan","icd10":"A00.9","physical_exam":["生命体征：体温（热型：稽留热/弛张热/间歇热/不规则热）、脉搏（相对缓脉提示伤寒）、呼吸、血压（感染性休克低血压）、血氧","一般情况：神志（感染中毒性脑病/嗜睡/谵妄）、精神状态、面容（伤寒面容/二尖瓣面容）、体位、有无寒战","皮肤黏膜：皮疹（形态/分布/出现时间：斑丘疹/出血疹/疱疹/荨麻疹）、瘀点瘀斑（脑膜炎双球菌）、黄疸、溃疡、焦痂（恙虫病）、脓肿、红肿热痛","淋巴结：全身/局部淋巴结肿大（压痛/质地/活动度）","头颈部：结膜充血/出血、咽充血、扁桃体肿大/渗出、口腔溃疡、颈强直（脑膜刺激征）","胸部：心率心律、双肺呼吸音/啰音（肺部感染）","腹部：压痛（部位）、反跳痛、肝脾肿大、腹水征、肠鸣音","神经系统：意识状态、脑膜刺激征、病理征、局灶体征","其他：感染灶寻找（皮肤/呼吸道/消化道/泌尿道/胆道）"],"lab_tests":["粪便培养：霍乱弧菌培养及药敏（确诊金标准，抗菌治疗前留取新鲜粪便/肛拭子，注意及时送检）","粪便霍乱弧菌快速检测（胶体金法）及PCR核酸检测（疑似病例快速筛查，2小时内疫情报告依据之一）","血常规、CRP、PCT（评估感染程度及脱水后血液浓缩，动态复查）","血电解质（钾、钠、氯）、血气分析、肾功能（肌酐、尿素氮）、血糖（警惕低钾、代谢性酸中毒、低血糖）","尿常规及尿比重、心电图（动态监测，评估脱水与低钾相关心律失常，补钾期间复查）","腹部超声（必要时，排除其他腹泻病因；重型合并休克时评估血流动力学）"],"nursing":["消化道（接触）隔离：单间隔离，专人防护，严格执行手卫生，患者排泄物、呕吐物用含氯消毒剂消毒后处理，防止交叉感染","疫情报告与登记：确诊/疑似病例2小时内上报疾控，完善传染病报告卡及密切接触者登记，协助流行病学调查","严密病情观察：监测神志、血压、心率、皮肤弹性、眼窝凹陷及24小时出入量，动态评估脱水程度，警惕低血容量性休克、急性肾衰竭","补液护理：建立两条以上静脉通路，按补液方案快速输注，密切观察滴速与反应，防止输液过快诱发心衰、肺水肿","肛周皮肤护理：频繁水样便致肛周浸渍糜烂，便后温水清洗、擦干后涂氧化锌软膏保护"],"diet":["急性期暂禁食，以口服补液盐（ORS）少量多次补充为主，先纠正脱水与电解质紊乱","恢复期给予米汤、稀粥、藕粉等易消化流质，少量多餐，逐渐过渡至半流质","忌油腻、生冷、辛辣刺激性食物及牛奶、豆浆等易产气致腹胀食物","循序渐进增加蛋白质摄入（蛋羹、鱼泥、瘦肉粥），保证能量与营养支持","持续口服补液盐巩固补液，记录饮水量及尿量，防止再度脱水"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":383},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"f461271b99421ec9f86ea5e72a240d507d94887d375b98491317ab35d872966e","pinyin":"huoluan","initials":"hl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","潜伏期：数小时至5天，多数1-3天\\n泻吐期：剧烈腹泻（首发症状，无发热、无腹痛、无里急后重，米泔水样便或清水样便，量多次频，每日数十次甚至失禁）、呕吐（多在腹泻后，喷射性，初为胃内容物，后为米泔水样，无恶心）\\n脱水期：脱水（轻度：皮肤黏膜干燥、弹性稍差、尿量减少；中度：皮肤弹性差、眼窝凹陷、声音嘶哑、血压下降、尿量减少；重度：皮肤干皱、弹性消失、眼窝深凹、神志不清、血压测不出、无尿）、电解质紊乱（低钠：肌肉痉挛，腓肠肌和腹直肌最明显；低钾：肌张力减低、腱反射消失、鼓肠、心律失常）、代谢性酸中毒（呼吸深快、意识障碍）、循环衰竭（血压下降、脉搏细速、四肢厥冷、意识模糊、昏迷、少尿无尿）\\n恢复期/反应期：脱水纠正后症状消失，体温回升，可出现反应性发热（38-39℃，持续1-3天自行消退）\\n临床分型：轻型（仅有腹泻，无脱水）、中型（典型吐泻，中度脱水）、重型（重度脱水、循环衰竭）、暴发型/中毒型（干性霍乱，起病急骤，无明显吐泻即出现中毒性循环衰竭，迅速死亡）\\n并发症：急性肾衰竭（少尿无尿、氮质血症）、急性肺水肿（补液过快或酸中毒导致）、低钾血症、心律失常、流产、早产",60],["摘要","由霍乱弧菌引起的烈性肠道传染病，属于甲类传染病，典型表现为剧烈吐泻、米泔水样便、严重脱水、电解质紊乱、循环衰竭，病死率高。",30],["疾病编码","A00.9",30],["原首字母","huoluan",60]]},{"id":"orders-89d6aee8e6868a36d0d0","key":"v1-c9ccc21dfe2a3058|orders-89d6aee8e6868a36d0d0","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"副伤寒","category":"内科-感染","raw":{"name":"副伤寒","category":"内科-感染","summary":"由副伤寒甲、乙、丙沙门菌引起的急性肠道传染病，临床表现与伤寒相似但较轻，病程较短，并发症较少，丙型副伤寒可表现为急性胃肠炎或脓毒血症。","symptoms":["副伤寒甲、乙：起病较急，先有急性胃肠炎症状（腹痛、呕吐、腹泻），2-3天后出现发热，体温波动大，热型不规则或弛张热，相对缓脉少见，全身中毒症状较轻，玫瑰疹少见或出现早、数量多、形态大，肝脾肿大常见，病程较短（2-3周），并发症少","副伤寒丙：临床表现复杂，可分为伤寒型（类似伤寒但较轻）、急性胃肠炎型（发热、腹痛、呕吐、腹泻，病程短，2-5天）、脓毒血症型（重症，寒战、高热、不规则热型，可出现肺部、骨骼、关节、脑膜、心包、软组织等迁徙性化脓病灶，肝脾肿大，黄疸，病程长，并发症多）","全身症状：乏力、食欲减退、头痛、肌肉酸痛","消化系统：腹痛、腹泻、恶心、呕吐、腹胀","皮疹：副伤寒甲、乙可见玫瑰疹，出现较早，数量较多，形态较大","并发症：肠出血、肠穿孔（少见，较伤寒轻）、迁徙性脓肿（丙型副伤寒脓毒血症型）、支气管炎、肺炎、中毒性肝炎、溶血性贫血"],"diagnosis":["流行病学史：夏秋季，接触过副伤寒患者或带菌者，饮用过被污染的水或食物","典型临床表现：类似伤寒但较轻，病程短，胃肠炎症状明显，丙型可表现为胃肠炎或脓毒血症","血常规：白细胞总数正常或减少，嗜酸性粒细胞减少或消失","病原学检查：血培养（急性期阳性）、骨髓培养、粪便培养（胃肠炎型和带菌者阳性）、脓液培养（脓毒血症型迁徙性病灶）","血清学检查：肥达反应（副伤寒甲、乙的H抗体升高，O抗体也升高）、ELISA","分子生物学：PCR检测副伤寒沙门菌DNA","鉴别诊断：伤寒、急性细菌性痢疾、病毒性肠炎、沙门菌食物中毒、败血症、疟疾"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（病原治疗）：","  用法：0.9%NS 250ml + 左氧氟沙星0.5g ivgtt qd 或 0.9%NS 250ml + 环丙沙星0.4g ivgtt q12h，疗程10-14天〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","","方案2（第三代头孢菌素；儿童、孕妇、重症）：","  用法：0.9%NS 100ml + 头孢曲松2g ivgtt qd 或 0.9%NS 100ml + 头孢噻肟2g ivgtt q8h，疗程10-14天〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","方案3（脓毒血症型）：","  用法：联合用药，第三代头孢菌素+氨基糖苷类，疗程延长至2-3周，迁徙性脓肿需外科引流","","方案4（急性胃肠炎型）：","  用法：轻症不用抗生素，重症或有并发症者用抗生素","","方案5（对症治疗）：","  用法：补液（口服补液盐或静脉补液）、退热、止吐、止泻、维持水电解质平衡","","方案6（并发症治疗）：","  用法：迁徙性脓肿（抗生素+外科引流）、肠出血（止血、输血）、肠穿孔（手术）","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（轻症口服）：","用法：左氧氟沙星0.5g qd 或 环丙沙星0.5g bid 或 头孢克肟0.2g bid，疗程10-14天〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物2（急性胃肠炎型）：","用法：口服补液盐（ORS）、蒙脱石散3g tid、双歧杆菌三联活菌胶囊2粒 tid，重症加用抗生素〔调 ★ 与其他药间隔1-2小时；肠梗阻禁用〕","药物3（对症）：","用法：对乙酰氨基酚0.5g prn（退热）、甲氧氯普胺10mg prn（止吐）、蒙脱石散3g tid（止泻）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物4（慢性带菌者）：","用法：阿莫西林0.5g qid + 丙磺舒0.5g qid（疗程4-6周）或喹诺酮类（疗程4周）〔调 CrCl<30 减量；青霉素过敏禁用〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["一般治疗：消化道隔离，卧床休息，流质或半流质饮食，补充维生素（维生素C 0.1g 口服 tid、复合维生素B 1片 口服 tid），维持水电解质平衡","病原治疗：第三代喹诺酮类首选（左氧氟沙星 500mg 口服/静滴 qd 或环丙沙星 500mg 口服 bid），第三代头孢菌素用于儿童孕妇重症（头孢曲松 2g 静滴 qd 或头孢噻肟 2g 静滴 q8h），疗程10-14天，脓毒血症型延长至2-3周","对症治疗：补液（生理盐水/葡萄糖静滴）、退热（对乙酰氨基酚 0.5g 口服 q6h 或布洛芬 0.4g 口服 q8h）、止吐（甲氧氯普胺 10mg 口服/肌注 tid）、止泻（蒙脱石散 3g 口服 tid）","并发症治疗：迁徙性脓肿（抗生素+外科引流，如头孢曲松 2g 静滴 qd 联合甲硝唑 0.5g 静滴 q8h）、肠出血（止血、输血）、肠穿孔（手术）","慢性带菌者治疗：长疗程抗生素（如环丙沙星 500mg 口服 bid，疗程4-6周），合并胆囊病变者胆囊切除","疫情报告：乙类传染病，24小时内报告","预防：管理传染源、切断传播途径（饮水消毒、饮食卫生、灭蝇）、保护易感人群"],"management":["消化道隔离，排泄物消毒","卧床休息，避免劳累","清淡易消化饮食，少量多餐","监测体温、腹痛、腹泻、大便颜色变化","规律足量抗生素治疗，完成疗程","注意药物副作用","急性胃肠炎型注意补液，防止脱水","脓毒血症型注意迁徙性病灶的观察和处理","患者隔离至症状消失后，粪便培养连续2次阴性","注意饮食卫生，灭蝇防蝇","保持乐观心态，预后较伤寒好，病死率低"],"notes":["由副伤寒甲、乙、丙沙门菌引起，乙类传染病","临床表现与伤寒相似但较轻，病程短（2-3周），并发症少","副伤寒甲、乙：先有胃肠炎症状，后发热，热型不规则，玫瑰疹少见或出现早数量多","副伤寒丙：临床表现复杂，可分为伤寒型、急性胃肠炎型、脓毒血症型，脓毒血症型可出现迁徙性脓肿","治疗同伤寒，第三代喹诺酮类首选，脓毒血症型联合用药延长疗程","预后较伤寒好，病死率低","预防同伤寒"],"emergency":["出现高热不退、寒战、意识障碍、迁徙性脓肿、剧烈腹痛、大量血便立即就医"],"pinyin":"fushanghan","icd10":"A01.4","physical_exam":["生命体征：体温（热型：稽留热/弛张热/间歇热/不规则热）、脉搏（相对缓脉提示伤寒）、呼吸、血压（感染性休克低血压）、血氧","一般情况：神志（感染中毒性脑病/嗜睡/谵妄）、精神状态、面容（伤寒面容/二尖瓣面容）、体位、有无寒战","皮肤黏膜：皮疹（形态/分布/出现时间：斑丘疹/出血疹/疱疹/荨麻疹）、瘀点瘀斑（脑膜炎双球菌）、黄疸、溃疡、焦痂（恙虫病）、脓肿、红肿热痛","淋巴结：全身/局部淋巴结肿大（压痛/质地/活动度）","头颈部：结膜充血/出血、咽充血、扁桃体肿大/渗出、口腔溃疡、颈强直（脑膜刺激征）","胸部：心率心律、双肺呼吸音/啰音（肺部感染）","腹部：压痛（部位）、反跳痛、肝脾肿大、腹水征、肠鸣音","神经系统：意识状态、脑膜刺激征、病理征、局灶体征","其他：感染灶寻找（皮肤/呼吸道/消化道/泌尿道/胆道）"],"lab_tests":["血培养（含沙门菌培养+药敏）：抗菌药物使用前、寒战高热时采集，双侧双瓶，病程第1周阳性率最高","粪便培养：病程第2周起阳性率升高，用于病原学确诊及解除隔离判断（需连续2次阴性）","血常规：观察白细胞减少及嗜酸性粒细胞减少趋势，辅助诊断与疗效评估","血清肥达试验（伤寒、副伤寒抗体）：病程第2周起检测，动态观察滴度≥4倍升高有诊断价值","炎症指标CRP/PCT：监测感染严重程度及疗效，指导抗菌治疗","腹部超声/CT：病程第2-3周出现突发剧烈腹痛、腹胀或便血时急查，排查肠出血、肠穿孔"],"nursing":["按消化道（接触）隔离：单间或床旁隔离，排泄物、呕吐物及餐具严格消毒，疫情按规定时限报告；解除隔离需连续2次粪便培养阴性","发热护理：每4小时监测体温，高热以物理降温为主，慎用退热药，防止大汗虚脱及诱发肠穿孔；及时补充水分","病情观察：重点观察腹痛、腹胀、便血及血压心率变化，病程第2-3周突发剧烈腹痛或腹膜炎体征提示肠穿孔，立即报告医生","卧床休息：发热期绝对卧床，减少活动与用力排便，降低肠出血、肠穿孔风险","皮肤皮疹护理：观察玫瑰疹出现与消退，保持皮肤清洁干燥，瘙痒时避免抓挠，防继发感染"],"diet":["进少渣流质或半流质饮食（米汤、藕粉、蒸蛋羹、鱼泥、去油肉汤），少量多餐，保证热量与蛋白质","禁食粗纤维及带渣食物（芹菜、韭菜、粗粮、坚果等），减少肠壁刺激，预防肠出血、肠穿孔","忌辛辣刺激、生冷油腻及暴饮暴食；病程第3周并发症高发期严格限制食物种类，恢复期逐步过渡至软食","足量补充水分与电解质，鼓励少量多次饮水，必要时口服补液盐或静脉补液，维持出入量平衡","餐具煮沸消毒、便后洗手，避免污染他人食物，防止交叉感染"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":384},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"15d776d47e2ff97d48e5ebcb39052711847468714991d3d2fee80db69b2376c8","pinyin":"fushanghan","initials":"fsh","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","副伤寒甲、乙：起病较急，先有急性胃肠炎症状（腹痛、呕吐、腹泻），2-3天后出现发热，体温波动大，热型不规则或弛张热，相对缓脉少见，全身中毒症状较轻，玫瑰疹少见或出现早、数量多、形态大，肝脾肿大常见，病程较短（2-3周），并发症少\\n副伤寒丙：临床表现复杂，可分为伤寒型（类似伤寒但较轻）、急性胃肠炎型（发热、腹痛、呕吐、腹泻，病程短，2-5天）、脓毒血症型（重症，寒战、高热、不规则热型，可出现肺部、骨骼、关节、脑膜、心包、软组织等迁徙性化脓病灶，肝脾肿大，黄疸，病程长，并发症多）\\n全身症状：乏力、食欲减退、头痛、肌肉酸痛\\n消化系统：腹痛、腹泻、恶心、呕吐、腹胀\\n皮疹：副伤寒甲、乙可见玫瑰疹，出现较早，数量较多，形态较大\\n并发症：肠出血、肠穿孔（少见，较伤寒轻）、迁徙性脓肿（丙型副伤寒脓毒血症型）、支气管炎、肺炎、中毒性肝炎、溶血性贫血",60],["摘要","由副伤寒甲、乙、丙沙门菌引起的急性肠道传染病，临床表现与伤寒相似但较轻，病程较短，并发症较少，丙型副伤寒可表现为急性胃肠炎或脓毒血症。",30],["疾病编码","A01.4",30],["原首字母","fushanghan",60]]},{"id":"orders-9f6b6be65619ecf8cabe","key":"v1-c9ccc21dfe2a3058|orders-9f6b6be65619ecf8cabe","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"阿米巴病","category":"内科-感染","raw":{"name":"阿米巴病","category":"内科-感染","summary":"由溶组织内阿米巴原虫感染引起的疾病，最常见为肠阿米巴病（阿米巴痢疾），可引起肠外并发症如阿米巴肝脓肿、肺脓肿、脑脓肿等。","symptoms":["肠阿米巴病（阿米巴痢疾）：无症状带虫者（90%，排包囊但无症状）、普通型（起病缓，低热或不发热，腹痛、腹泻，每日数次至十余次，大便量中等，呈果酱样黏液血便，有腥臭味，里急后重轻，右下腹压痛，病程数日至数周，易复发转为慢性）、暴发型（少见，起病急，高热、寒战、剧烈腹痛、腹泻，每日数十次，血水样便，里急后重明显，呕吐、脱水、电解质紊乱、酸中毒，可并发肠出血、肠穿孔、腹膜炎，病死率高）、慢性型（病程超过2个月，腹泻便秘交替，腹痛、腹胀、消瘦、贫血、乏力，可触及增厚的结肠，肝大，易因饮食不当、受凉、劳累诱发急性发作）","阿米巴肝脓肿（最常见肠外并发症）：长期不规则发热（弛张热或间歇热，38-39℃）、盗汗、乏力、食欲减退、消瘦、贫血、肝区疼痛（持续性钝痛，深呼吸及体位变化时加重，向右肩放射）、肝大（右叶多见，肝大、质中、压痛、叩击痛）、右下胸壁水肿、压痛，可伴反应性胸膜炎、胸腔积液，脓肿穿破可致膈下脓肿、脓胸、肺脓肿、腹膜炎","其他肠外并发症：阿米巴肺脓肿（发热、咳嗽、咳巧克力色痰、胸痛、呼吸困难）、阿米巴脑脓肿（头痛、呕吐、意识障碍、抽搐、局灶神经体征，预后差）、皮肤阿米巴病（肛周、会阴部皮肤溃疡，边缘不整，剧痛）、泌尿生殖系统阿米巴病（阴道炎、尿道炎、前列腺炎）","全身症状：发热、盗汗、乏力、消瘦、贫血","消化系统：腹痛、腹泻、果酱样便、肝区疼痛、肝大","并发症：肠出血、肠穿孔、腹膜炎、阑尾炎、阿米巴瘤、肠狭窄、肝脓肿穿破、脓胸、肺脓肿、脑脓肿"],"diagnosis":["流行病学史：到过阿米巴病流行区（热带、亚热带），有不洁饮食史，接触过阿米巴病患者或带虫者","典型临床表现：腹痛、腹泻、果酱样黏液血便（肠阿米巴病）；长期发热、肝区疼痛、肝大（阿米巴肝脓肿）","粪便检查：生理盐水涂片（活动的滋养体，吞噬红细胞）、碘液染色（包囊）、浓集法（提高包囊检出率），需多次检查（连续3天）","病原学检查：粪便培养（Robinson培养基）、免疫荧光检查、ELISA检测抗原抗体、PCR检测阿米巴DNA","影像学：腹部B超/CT/MRI（肝脓肿：圆形或卵圆形低密度灶，增强后环形强化，右叶多见，单房或多房）、胸部X线/CT（肺脓肿、胸腔积液、右膈抬高）、钡剂灌肠（慢性肠阿米巴病可见充盈缺损、痉挛、狭窄）","乙状结肠镜/结肠镜：肠黏膜可见散在溃疡，口小底大（烧瓶样），边缘整齐，周围红晕，溃疡间黏膜正常，取溃疡边缘分泌物查滋养体","肝脓肿穿刺：脓液呈巧克力色（棕褐色），黏稠，有腥臭味，可找到滋养体（脓液边缘）","血常规：急性期白细胞升高（10-20×10^9/L），中性粒细胞升高，慢性期贫血、血沉增快","肝功能：肝脓肿时转氨酶轻度升高，碱性磷酸酶升高，白蛋白降低","鉴别诊断：肠阿米巴病（细菌性痢疾、血吸虫病、肠结核、结肠癌、溃疡性结肠炎、克罗恩病）、阿米巴肝脓肿（细菌性肝脓肿、肝癌、肝囊肿、肝包虫病、胆囊炎）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（病原治疗；肠阿米巴病）：","  用法：0.9%NS 250ml + 甲硝唑0.5g ivgtt q8h（或替硝唑0.8g ivgtt qd），疗程7-10天，后接杀包囊药（二氯尼特500mg tid 或 巴龙霉素0.5g qid，疗程7天）〔调 肝功能不全减量；妊娠早期禁用；用药期间及停药3日内禁酒〕","","方案2（暴发型）：","  用法：甲硝唑静脉给药+广谱抗生素（合并细菌感染）+补液+抗休克+对症〔调 肝功能不全减量；妊娠早期禁用；用药期间及停药3日内禁酒〕","","方案3（阿米巴肝脓肿）：","  用法：0.9%NS 250ml + 甲硝唑0.5g ivgtt q8h（或替硝唑0.8g ivgtt qd），疗程10-14天，后接口服杀包囊药；脓肿较大（>5cm）或药物治疗无效者在B超引导下穿刺引流（抽尽脓液，可注入甲硝唑），必要时手术切开引流〔调 肝功能不全减量；妊娠早期禁用；用药期间及停药3日内禁酒〕","","方案4（肠外并发症）：","  用法：甲硝唑静脉给药，疗程延长（14-21天），对症支持治疗〔调 肝功能不全减量；妊娠早期禁用；用药期间及停药3日内禁酒〕","","方案5（对症治疗）：","  用法：补液（口服补液盐或静脉补液）、退热、止痛、止血、纠正电解质紊乱、营养支持","","方案6（并发症治疗）：","  用法：肠出血（止血、输血）、肠穿孔（手术修补+抗生素+甲硝唑）、腹膜炎（抗生素+甲硝唑+手术）、肝脓肿穿破（穿刺引流+手术）〔调 肝功能不全减量；妊娠早期禁用；用药期间及停药3日内禁酒〕","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（肠阿米巴病普通型）：","用法：甲硝唑0.4g tid（7-10天）或 替硝唑2g qd（3-5天）或 奥硝唑0.5g bid（5-10天），后接杀包囊药（二氯尼特500mg tid 10天 或 巴龙霉素0.5g qid 7天 或 双碘喹啉0.6g tid 20天）〔调 肝功能不全减量；妊娠早期禁用；用药期间及停药3日内禁酒〕","药物2（无症状带虫者）：","用法：二氯尼特500mg tid（10天）或 巴龙霉素0.5g qid（7天）（杀包囊，防止传播和复发）","药物3（阿米巴肝脓肿）：","用法：甲硝唑0.4g tid（10-14天）或 替硝唑2g qd（5-10天），后接杀包囊药，可加用氯喹0.25g bid（前2天0.5g bid，后0.25g bid，疗程20天，肝脓肿辅助）〔调 肝功能不全减量；妊娠早期禁用；用药期间及停药3日内禁酒〕","药物4（对症）：","用法：对乙酰氨基酚0.5g prn（退热止痛）、口服补液盐（腹泻脱水）、蒙脱石散3g tid（腹泻）、复合维生素B、铁剂（贫血）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物5：","用法：中医中药治疗（辅助，如白头翁汤、葛根芩连汤）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["一般治疗：急性期卧床休息，流质或半流质饮食，补充维生素（维生素C 0.1g 口服 tid、复合维生素B 1片 口服 tid），维持水电解质平衡，慢性期加强营养","病原治疗：甲硝唑 0.4-0.6g 口服 tid（或替硝唑 2g 口服 qd，疗程3-5天）杀滋养体，治疗肠内外阿米巴病，+杀包囊药（二氯尼特 0.5g 口服 tid 疗程10天、巴龙霉素 0.5g 口服 tid 疗程7天、双碘喹啉 0.6g 口服 tid 疗程20天），清除肠腔内包囊，防止复发和传播，联合用药","对症治疗：补液（生理盐水/葡萄糖静滴）、退热（对乙酰氨基酚 0.5g 口服 q6h）、止痛、止血、营养支持","局部治疗：阿米巴肝脓肿穿刺引流（B超引导下，抽尽脓液，可注入甲硝唑 0.5g）、皮肤阿米巴病局部换药","手术治疗：肠穿孔、腹膜炎、大量肠出血、阑尾炎、阿米巴瘤致肠梗阻、肝脓肿穿破、药物治疗无效的肝脓肿","并发症治疗：肠出血（止血、输血）、肠穿孔（手术）、腹膜炎（抗生素+甲硝唑 0.5g 静滴 q8h+手术）、肝脓肿穿破（穿刺+手术）、脓胸（穿刺引流+抗生素）、肺脓肿（抗生素+甲硝唑 0.5g 静滴 q8h+体位引流）","疫情报告：乙类传染病，24小时内报告","密切接触者检查和治疗","预防：管理传染源（患者隔离治疗、带虫者治疗，从事饮食行业者需调离）、切断传播途径（饮水消毒、食物煮熟、饭前便后洗手、灭蝇灭蟑螂、粪便无害化处理）、保护易感人群（注意个人卫生，目前无有效疫苗）","定期随访：监测粪便检查、肝脓肿B超、血常规、肝功能，每1-3个月复查1次"],"management":["消化道隔离，患者排泄物、污染物严格消毒，餐具单独消毒","卧床休息，避免劳累","饮食：急性期流质或半流质，少量多餐，避免生冷油腻辛辣，慢性期高蛋白高维生素饮食，加强营养","监测体温、腹痛、腹泻次数、大便性状、肝区疼痛、肝大变化","记录大便次数和性状","口服补液盐（ORS）轻中度脱水首选","规律足量抗阿米巴治疗，完成疗程（甲硝唑+杀包囊药联合），不可自行停药，防止复发和转为慢性","注意药物副作用（甲硝唑胃肠道反应、金属味、戒酒；二氯尼特胃肠道反应；巴龙霉素胃肠道反应、肾毒性）","肝脓肿患者避免剧烈活动和腹部外伤（防脓肿穿破）","穿刺引流后注意观察引流液性状和量，保持引流管通畅","慢性期患者注意饮食卫生，避免受凉劳累，增强体质，预防急性发作","从事饮食行业、托幼机构工作人员需定期粪便检查，带虫者需调离岗位","注意饮食卫生：饮水消毒、食物煮熟、饭前便后洗手、不喝生水、不吃生冷食物","灭蝇灭蟑螂，保持环境卫生，粪便无害化处理","保持乐观心态，普通型预后好，暴发型和有严重并发症者预后差，阿米巴脑脓肿病死率高"],"notes":["又称阿米巴痢疾、阿米巴肝脓肿，是乙类传染病","病原体：溶组织内阿米巴原虫，生活史有滋养体（致病型，活动、吞噬红细胞）和包囊（感染型，抵抗力强，粪-口传播）","传染源：无症状带虫者（最重要，排包囊）、慢性患者、恢复期患者","传播途径：粪-口途径，摄入被包囊污染的水或食物，水传播、食物传播、接触传播、苍蝇蟑螂传播","致病机制：包囊在小肠脱囊→滋养体→侵入结肠黏膜→烧瓶样溃疡→分泌溶组织酶→组织坏死→经血行播散至肝、肺、脑等","临床分型：肠阿米巴病（无症状带虫者、普通型、暴发型、慢性型）、肠外阿米巴病（肝脓肿最常见，肺脓肿、脑脓肿、皮肤阿米巴病等）","典型表现：肠阿米巴病（果酱样黏液血便，有腥臭味，里急后重轻，右下腹压痛）；阿米巴肝脓肿（长期发热、肝区疼痛、肝大、盗汗、消瘦）","实验室检查：粪便生理盐水涂片找滋养体（吞噬红细胞），碘液染色找包囊，需多次检查；肝脓肿穿刺脓液呈巧克力色","影像学：B超/CT显示肝脓肿，右叶多见，单房或多房，增强环形强化","治疗：甲硝唑/替硝唑杀滋养体（肠内外均有效）+杀包囊药（二氯尼特、巴龙霉素，清除肠腔包囊防复发），联合用药","肝脓肿较大者需穿刺引流（B超引导下）","预防关键是饮食卫生、饮水消毒、灭蝇、粪便无害化处理","无症状带虫者是最重要传染源，需治疗（杀包囊药）","慢性肠阿米巴病易误诊为结肠癌、溃疡性结肠炎，需结肠镜检查鉴别","阿米巴肝脓肿需与细菌性肝脓肿、肝癌鉴别","甲硝唑治疗期间需戒酒（双硫仑样反应）"],"emergency":["出现大量血便、剧烈腹痛、腹肌紧张（肠出血/肠穿孔/腹膜炎）、高热不退、肝区剧痛、呼吸困难胸痛（肝脓肿穿破/肺脓肿）、意识障碍抽搐（脑脓肿）、严重脱水休克立即就医"],"pinyin":"amibabing","icd10":"A06.9","physical_exam":["生命体征：体温（热型：稽留热/弛张热/间歇热/不规则热）、脉搏（相对缓脉提示伤寒）、呼吸、血压（感染性休克低血压）、血氧","一般情况：神志（感染中毒性脑病/嗜睡/谵妄）、精神状态、面容（伤寒面容/二尖瓣面容）、体位、有无寒战","皮肤黏膜：皮疹（形态/分布/出现时间：斑丘疹/出血疹/疱疹/荨麻疹）、瘀点瘀斑（脑膜炎双球菌）、黄疸、溃疡、焦痂（恙虫病）、脓肿、红肿热痛","淋巴结：全身/局部淋巴结肿大（压痛/质地/活动度）","头颈部：结膜充血/出血、咽充血、扁桃体肿大/渗出、口腔溃疡、颈强直（脑膜刺激征）","胸部：心率心律、双肺呼吸音/啰音（肺部感染）","腹部：压痛（部位）、反跳痛、肝脾肿大、腹水征、肠鸣音","神经系统：意识状态、脑膜刺激征、病理征、局灶体征","其他：感染灶寻找（皮肤/呼吸道/消化道/泌尿道/胆道）"],"lab_tests":["粪便常规+阿米巴滋养体/包囊镜检：取新鲜粪便保温送检（禁用泻剂取便），急性期连续查3次以上，活动性滋养体为确诊依据","血常规、CRP、PCT：评估感染及炎症程度，动态监测白细胞、血红蛋白变化，警惕肠道出血","阿米巴血清学抗体检测（ELISA/间接血凝法）：急性肠阿米巴病及肝脓肿阳性率高，用于鉴别诊断与既往感染","腹部超声/CT：怀疑阿米巴肝脓肿时首选，脓肿多单发位于肝右叶，超声引导下可穿刺引流并送检","粪便阿米巴培养及PCR（必要时）：鉴别致病性溶组织内阿米巴与迪斯帕内阿米巴，指导流行病学与随访","结肠镜检查（诊断不明或慢性病例）：镜下可见典型烧瓶样溃疡，于溃疡边缘取活检送病理及镜检"],"nursing":["消化道隔离：餐具、便器专用并每日消毒，粪便用含氯消毒剂处理后再排放，隔离至症状消失且粪便连续3次镜检阴性","疫情报告：按乙类传染病规范网络直报，采集流行病学史（疫区旅居、饮用水源）并及时上报","病情观察：监测腹痛部位、腹泻次数及粪便性状（果酱样血便），观察有无高热、肝区胀痛、腹膜刺激征，警惕肠穿孔、大出血及肝脓肿破溃","发热及肛周护理：高热时物理降温并监测体温，腹泻频繁者便后温水清洗肛周、涂保护性软膏，保持皮肤黏膜完整","手卫生与终末消毒：接触患者粪便后严格洗手，出院或转科后对被褥、便器行终末消毒，防止院内传播"],"diet":["急性期予清淡流质或半流质（米汤、藕粉、蒸蛋羹），少渣易消化，减轻肠道负担","忌辛辣、油腻、生冷及粗纤维食物，禁饮酒，避免刺激性饮食诱发肠道症状","充分补液：口服补液盐少量多次，频繁腹泻伴脱水者配合静脉补液，维持水电解质平衡","恢复期逐步增加高蛋白、高维生素饮食（鱼、瘦肉、蛋、新鲜蔬果汁），少食多餐，促进肠道黏膜修复","强调饮食卫生：不饮生水、不食生冷蔬果及不洁食物，饭前便后洗手，防止病从口入及交叉感染"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":385},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"185f4aac75af3486d1854b21595834f5163ad096c00e43f1a8aa4e26f42d7caf","pinyin":"amibabing","initials":"ambb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","肠阿米巴病（阿米巴痢疾）：无症状带虫者（90%，排包囊但无症状）、普通型（起病缓，低热或不发热，腹痛、腹泻，每日数次至十余次，大便量中等，呈果酱样黏液血便，有腥臭味，里急后重轻，右下腹压痛，病程数日至数周，易复发转为慢性）、暴发型（少见，起病急，高热、寒战、剧烈腹痛、腹泻，每日数十次，血水样便，里急后重明显，呕吐、脱水、电解质紊乱、酸中毒，可并发肠出血、肠穿孔、腹膜炎，病死率高）、慢性型（病程超过2个月，腹泻便秘交替，腹痛、腹胀、消瘦、贫血、乏力，可触及增厚的结肠，肝大，易因饮食不当、受凉、劳累诱发急性发作）\\n阿米巴肝脓肿（最常见肠外并发症）：长期不规则发热（弛张热或间歇热，38-39℃）、盗汗、乏力、食欲减退、消瘦、贫血、肝区疼痛（持续性钝痛，深呼吸及体位变化时加重，向右肩放射）、肝大（右叶多见，肝大、质中、压痛、叩击痛）、右下胸壁水肿、压痛，可伴反应性胸膜炎、胸腔积液，脓肿穿破可致膈下脓肿、脓胸、肺脓肿、腹膜炎\\n其他肠外并发症：阿米巴肺脓肿（发热、咳嗽、咳巧克力色痰、胸痛、呼吸困难）、阿米巴脑脓肿（头痛、呕吐、意识障碍、抽搐、局灶神经体征，预后差）、皮肤阿米巴病（肛周、会阴部皮肤溃疡，边缘不整，剧痛）、泌尿生殖系统阿米巴病（阴道炎、尿道炎、前列腺炎）\\n全身症状：发热、盗汗、乏力、消瘦、贫血\\n消化系统：腹痛、腹泻、果酱样便、肝区疼痛、肝大\\n并发症：肠出血、肠穿孔、腹膜炎、阑尾炎、阿米巴瘤、肠狭窄、肝脓肿穿破、脓胸、肺脓肿、脑脓肿",60],["摘要","由溶组织内阿米巴原虫感染引起的疾病，最常见为肠阿米巴病（阿米巴痢疾），可引起肠外并发症如阿米巴肝脓肿、肺脓肿、脑脓肿等。",30],["疾病编码","A06.9",30],["原首字母","amibabing",60]]},{"id":"orders-8f755007d93425e79903","key":"v1-c9ccc21dfe2a3058|orders-8f755007d93425e79903","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"干眼症","category":"眼科","raw":{"name":"干眼症","category":"眼科","summary":"泪液分泌不足或泪液蒸发过快导致泪膜不稳定和眼表损害，表现为眼干涩、异物感、烧灼感、畏光、视物模糊、视疲劳，是最常见的眼科疾病之一。","symptoms":["眼干涩、异物感、磨砂感","眼烧灼感、刺痛","畏光、流泪（反射性）","视物模糊、视力波动（眨眼后改善）","视疲劳（阅读、看屏幕后加重）","眼痒、眼红","眼睑沉重、睁眼困难","丝状分泌物","严重时角膜上皮缺损、角膜溃疡、视力下降"],"diagnosis":["典型症状（干涩、异物感、烧灼感、视疲劳）","泪液分泌试验（Schirmer试验，<10mm/5min为分泌减少，<5mm为干眼症）","泪膜破裂时间（BUT，<10秒为泪膜不稳定，<5秒为干眼症）","角膜荧光素染色（角膜上皮缺损点染）","泪液渗透压测定（>316mOsm/L）","睑板腺功能检查（睑板腺开口堵塞、分泌物异常）","眼表分析仪（泪河高度、脂质层厚度、眼红分析）","排除其他眼病（结膜炎、角膜炎、青光眼等）","询问病史（长期看屏幕、空调环境、戴隐形眼镜、全身疾病、用药史）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般无需静脉输液；人工泪液（0.1%玻璃酸钠滴眼液）1滴 滴眼 qid；0.05%环孢素滴眼液 1滴 滴眼 bid","方案2（严重干眼症伴角膜溃疡）：","用法：0.9%NS 250ml + 维生素C 2g ivgtt qd（促进角膜修复）","方案3（合并感染）：","用法：0.9%NS 100ml + 抗生素 ivgtt qd（根据病原选择）","方案4（全身免疫相关干燥综合征）：","用法：玻璃酸钠滴眼液 1滴 滴眼 qid；环孢素滴眼液 1滴 滴眼 bid；0.9%NS 适量 滴眼 按需（必要时）（糖皮质激素、免疫抑制剂）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（人工泪液（首选，基础治疗））：","用法：玻璃酸钠滴眼液、聚乙二醇滴眼液、羧甲基纤维素钠滴眼液、右旋糖酐滴眼液，每日4-6次，按需使用","药物2（润滑眼膏（夜间用））：","用法：红霉素眼膏、四环素可的松眼膏、卡波姆眼用凝胶，睡前涂眼","药物3（促进泪液分泌）：","用法：溴己新16mg tid、盐酸毛果芸香碱5-10mg tid（促进腺体分泌，注意副作用）、西维美林30mg tid","药物4（抗炎治疗）：","用法：低浓度糖皮质激素滴眼液（氟米龙0.1%、泼尼松龙0.5%，短期使用，注意眼压）、免疫抑制剂（环孢素A滴眼液0.05%、他克莫司滴眼液0.03%，中重度干眼症）〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物5（睑板腺功能障碍）：","用法：热敷+睑板腺按摩、抗生素眼膏（红霉素、四环素）、口服多西环素100mg bid（严重睑板腺炎）〔调 ★ 8岁以下及妊娠期禁用；食管刺激（需直立饮水送服）〕","药物6（维生素A）：","用法：维生素A胶丸2.5万U qd（维生素A缺乏相关干眼）","药物7（Omega-3脂肪酸）：","用法：鱼油胶囊1-2g qd（改善睑板腺功能）","药物8（中医中药）：","用法：明目地黄丸、杞菊地黄丸、石斛夜光丸（辨证使用）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["一般治疗：去除病因（避免长时间看屏幕、空调环境，增加环境湿度，减少隐形眼镜佩戴时间）、有意识多眨眼、定时休息（20-20-20法则：每20分钟看20英尺外20秒）、热敷（40-45℃热毛巾敷眼10-15分钟，每日2次）、睑板腺按摩（热敷后沿睑缘方向按摩睑板腺）","药物治疗：人工泪液（基础治疗，按需使用）、润滑眼膏（夜间）、抗炎治疗（激素、免疫抑制剂，中重度）、促进泪液分泌（溴己新、毛果芸香碱）、治疗睑板腺功能障碍（热敷、按摩、抗生素）","物理治疗：睑板腺热敷按摩、IPL强脉冲光治疗（睑板腺功能障碍）、泪小点栓塞（泪小点栓子，减少泪液流失，中重度干眼）、湿房镜（严重干眼）、治疗性角膜接触镜（严重角膜上皮缺损）","手术治疗：泪小点封闭（烧灼或激光封闭泪小点，严重干眼）、颌下腺移植（严重干眼，其他治疗无效）、睑缘缝合（严重角膜暴露）","治疗全身病：干燥综合征（风湿免疫科治疗）、糖尿病（控制血糖）、甲状腺疾病（治疗原发病）、帕金森病（治疗原发病）","停用或减少致干眼药物：抗组胺药、抗抑郁药、抗高血压药、利尿剂、激素等（与开药医生沟通）","定期随访：评估干眼程度、角膜情况、治疗效果，调整治疗方案"],"management":["用眼卫生：避免长时间连续用眼，每30-40分钟休息5-10分钟，看远处放松眼睛；有意识多眨眼（正常15-20次/分，看屏幕时减少至5-7次/分）；保持正确坐姿和阅读距离（30-40cm）","环境：保持室内适宜湿度（50-60%），使用加湿器；避免空调、风扇直吹眼睛；避免烟尘、风沙环境；外出戴防护眼镜（防风、防紫外线）","隐形眼镜：减少佩戴时间（每日不超过8小时），选择高透氧性镜片，避免过夜佩戴，干眼严重时改戴框架眼镜","饮食：多饮水，多吃富含维生素A（胡萝卜、动物肝脏、蛋黄）、维生素C（新鲜蔬果）、维生素E（坚果、植物油）、Omega-3脂肪酸（深海鱼、亚麻籽）的食物；避免辛辣刺激、烟酒","热敷按摩：每日热敷1-2次（40-45℃，10-15分钟），热敷后睑板腺按摩（沿睑缘方向轻柔按摩）","用药：按医嘱使用人工泪液，不要滥用眼药水（尤其是含防腐剂的眼药水长期使用可加重干眼）；使用多种眼药水时间隔5-10分钟；眼膏睡前使用","症状监测：观察眼干涩、异物感、视力变化，如症状加重、出现眼痛、畏光明显、视力下降，及时就医","定期复查：中重度干眼症定期眼科复查，检查角膜情况，调整治疗方案","预防：长期看屏幕者注意定时休息和眨眼；空调环境使用加湿器；戴隐形眼镜者注意佩戴时间和卫生；全身免疫疾病患者注意眼部表现"],"notes":["又称角结膜干燥症、干眼，是最常见的眼科疾病之一，患病率随年龄增长而增加，女性多于男性","分类：水液缺乏型干眼（泪液分泌减少，如干燥综合征、年龄相关）、蒸发过强型干眼（泪液蒸发过快，如睑板腺功能障碍、长时间看屏幕、空调环境）、黏蛋白缺乏型干眼（眼表上皮损伤，如药物毒性、化学伤）、泪液动力学异常型干眼（眼睑异常、瞬目异常、结膜松弛）、混合型干眼（最常见，两种以上类型同时存在）","发病机制：泪液分泌减少、泪液蒸发过快、泪膜不稳定、眼表炎症、神经感觉异常，多种因素相互作用","危险因素：年龄（>40岁）、女性（绝经后）、长期看屏幕（电脑、手机）、空调/干燥环境、戴隐形眼镜、眼部手术（LASIK、白内障）、全身疾病（干燥综合征、糖尿病、甲状腺疾病、帕金森病、类风湿关节炎）、药物（抗组胺药、抗抑郁药、抗高血压药、利尿剂、激素、抗胆碱能药）、维生素A缺乏、眼部炎症（睑缘炎、结膜炎）","诊断标准：症状+泪膜不稳定（BUT<5s或Schirmer<5mm）+眼表上皮损害（角膜荧光素染色阳性），排除其他眼病","人工泪液选择：含防腐剂的人工泪液（每日使用<4次可选）、不含防腐剂的人工泪液（每日使用≥4次或长期使用首选，单支装）、凝胶型（作用时间长，适合中重度或夜间）、眼膏（夜间使用，可能影响视力）","泪小点栓塞：适用于中重度水液缺乏型干眼，人工泪液效果不佳者，可暂时（可吸收栓子）或永久（不可吸收栓子）封闭泪小点，减少泪液流失","糖皮质激素使用注意：短期使用（<2周），定期监测眼压，避免长期使用导致青光眼、白内障、感染","环孢素A/他克莫司滴眼液：适用于中重度干眼伴眼表炎症，起效慢（2-4周），需长期使用，注意局部刺激","睑板腺功能障碍是蒸发过强型干眼最常见原因，热敷+按摩是基础治疗，IPL强脉冲光治疗效果好","严重干眼可致角膜上皮缺损、角膜溃疡、角膜新生血管、角膜瘢痕，严重影响视力，需积极治疗","干眼症是慢性疾病，需长期管理和治疗，不可根治，但可有效控制症状"],"emergency":["出现眼痛剧烈、畏光明显、视力骤降（角膜溃疡、角膜炎，立即就医）","出现眼红、眼痛、分泌物增多（合并感染，及时就医）","出现角膜异物感明显、无法睁眼（角膜上皮大面积缺损，及时就医）","出现视野缺损、闪光感、黑影飘动（排除视网膜脱离、玻璃体出血，立即就医）","出现眼外伤、化学物溅入眼内：立即就地大量清水持续冲洗至少30分钟（碱烧伤如石灰、氨水应延长至30-60分钟以上，直至pH试纸中性），同时清除固体颗粒，边冲洗边尽快就医"],"pinyin":"ganyanzheng","icd10":"H04.1","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态","视力检查：远视力（标准对数视力表）、近视力、矫正视力、裸眼视力","眼压检查：指测法（Tn/T+1/T+2/T+3）或眼压计（正常10-21mmHg）","眼睑：红肿/下垂/内翻/外翻/倒睫/肿块/瘢痕/闭合不全","泪器：泪点位置/泪道冲洗/泪囊区红肿压痛/溢泪","结膜：球结膜（充血/水肿/出血/滤泡/乳头）、睑结膜（充血/滤泡/乳头/瘢痕/结石）、穹窿部","角膜：透明度/上皮缺损（荧光素染色）/浸润/溃疡/瘢痕/新生血管/异物/曲率（K1/K2）","巩膜：黄染/充血/结节/葡萄肿","前房：深度（浅/中/深）、房水闪辉（Tyndall征）、房水细胞、积脓/积血","虹膜：颜色/纹理/粘连（前粘连/后粘连）/结节/萎缩/根部离断","瞳孔：大小/形状/位置/对光反射（直接/间接）/调节反射","晶状体：透明度（皮质/核/后囊下混浊）、位置（脱位/半脱位）、人工晶体","玻璃体：混浊/积血/增殖膜/脱离","眼底：视盘（边界/颜色/C/D比/水肿/萎缩）、视网膜（出血/渗出/水肿/脱离/色素紊乱）、黄斑（中心凹反光/水肿/裂孔/变性）、血管（管径/比例/交叉压迹/新生血管）","眼肌：眼球运动（各方向）、斜视（内斜/外斜/垂直斜）、复视、眼球震颤","视野：手动/自动视野计检查（青光眼/视神经病变）","色觉：色盲本检查"],"lab_tests":["视力检查（裸眼及矫正视力）——基线及随访对比","裂隙灯显微镜检查——观察睑缘、睑板腺开口、泪河高度、结膜及角膜情况","泪膜破裂时间（BUT）——评估泪膜稳定性","角膜荧光素染色——评估角膜上皮点状缺损及染色范围","泪液分泌试验（Schirmer I试验）——评估泪液分泌量","睑板腺红外成像或泪液渗透压测定（疑似睑板腺功能障碍者选做）"],"nursing":["病情观察：观察眼干涩、异物感、畏光、视物模糊等症状变化，发现角膜染色加重、眼痛、分泌物增多及时报告","眼部护理：遵医嘱正确滴用人工泪液，瓶口勿触及睫毛或眼睑，两种眼药间隔≥5分钟；每日用40-45℃毛巾热敷双眼10-15分钟，并协助睑缘清洁","用药观察：观察滴药后有无眼痒、红肿、刺痛等过敏反应；使用环孢素等免疫抑制剂者注意局部刺激症状，异常时停药并报告","环境与用眼指导：避免空调或风扇直吹眼部，室内使用加湿器；每用眼20分钟远眺20秒以上，减少持续注视电子屏幕","防跌倒宣教：滴眼后可能出现一过性视物模糊，嘱患者闭目休息片刻，起身时扶稳、避免走动"],"diet":["忌辛辣刺激、过烫及油腻食物，少饮浓茶、咖啡及酒精饮料，减少泪液蒸发","多食富含维生素A的食物：动物肝脏、蛋黄、胡萝卜、南瓜、菠菜，维持角膜上皮及泪腺功能","多食富含维生素C的新鲜蔬果：猕猴桃、柑橘、草莓、青椒，促进角膜上皮修复","适量摄入富含Omega-3脂肪酸的食物：深海鱼（三文鱼、沙丁鱼）、核桃、亚麻籽，改善睑板腺脂质分泌","保证充足饮水（每日1500-2000ml），避免过度节食及长期进食流质软食致营养单一"],"topical_medication":["玻璃酸钠滴眼液 1滴 滴眼 qid；聚乙烯醇滴眼液 1滴 滴眼 qid；卡波姆眼用凝胶 涂眼 qn"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":386},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"ea5f325fbf1b0c907e0953d019813af19d3b2a32513588164f17da3a66a49e4b","pinyin":"ganyanzheng","initials":"gyz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","眼干涩、异物感、磨砂感\\n眼烧灼感、刺痛\\n畏光、流泪（反射性）\\n视物模糊、视力波动（眨眼后改善）\\n视疲劳（阅读、看屏幕后加重）\\n眼痒、眼红\\n眼睑沉重、睁眼困难\\n丝状分泌物\\n严重时角膜上皮缺损、角膜溃疡、视力下降",60],["摘要","泪液分泌不足或泪液蒸发过快导致泪膜不稳定和眼表损害，表现为眼干涩、异物感、烧灼感、畏光、视物模糊、视疲劳，是最常见的眼科疾病之一。",30],["疾病编码","H04.1",30],["原首字母","ganyanzheng",60]]},{"id":"orders-9bc0e50e869f29350940","key":"v1-c9ccc21dfe2a3058|orders-9bc0e50e869f29350940","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"睑腺炎（麦粒肿）","category":"眼科","raw":{"name":"睑腺炎（麦粒肿）","category":"眼科","summary":"眼睑腺体的急性化脓性炎症，分为外睑腺炎（睫毛毛囊或附属皮脂腺感染，Zeis腺、Moll腺）和内睑腺炎（睑板腺感染），多为金黄色葡萄球菌感染，表现为眼睑红肿热痛，可形成脓肿。","symptoms":["外睑腺炎：眼睑缘部红肿、疼痛，局部硬结，压痛明显，可伴同侧耳前淋巴结肿大，脓肿成熟后睫毛根部出现黄白色脓点，可自行破溃排脓","内睑腺炎：眼睑红肿、疼痛，睑结膜面局限性充血、肿胀，睑结膜面可见黄白色脓点，疼痛较外睑腺炎剧烈，脓肿成熟后可向结膜面破溃","全身症状：严重时可伴发热、寒战、头痛、乏力","并发症：眼睑蜂窝织炎（整个眼睑红肿、疼痛剧烈）、海绵窦血栓（严重并发症，高热、头痛、呕吐、意识障碍，危及生命）、败血症、眼睑瘢痕、眼睑外翻"],"diagnosis":["典型症状（眼睑红肿热痛、硬结、压痛）","眼睑检查（视诊红肿部位、触诊硬结和压痛、翻转眼睑检查睑结膜面脓点）","耳前淋巴结检查（肿大压痛）","血常规（白细胞升高、中性粒细胞比例升高，严重感染时）","脓液培养+药敏（反复发作或严重感染，明确病原菌和敏感药物）","排除睑板腺囊肿（霰粒肿，慢性无痛性硬结）、眼睑肿瘤、眼睑蜂窝织炎"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（轻度）：","  用法：无需静脉输液，口服抗生素+局部用药","","方案2（严重感染；眼睑蜂窝织炎、伴全身症状）：","  用法：0.9%NS 100ml + 头孢呋辛1.5g ivgtt q8h 或 头孢曲松2g ivgtt qd 或 左氧氟沙星0.5g ivgtt qd，根据药敏调整〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","","方案3（伴海绵窦血栓）：","  用法：广谱抗生素联合（头孢曲松+甲硝唑+万古霉素），神经外科协同治疗，抗凝治疗〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","方案4（伴败血症）：","  用法：血培养+广谱抗生素静脉给药，根据药敏调整","","方案5（补液支持）：","  用法：0.9%NS或5%GNS ivgtt，维持水电解质平衡","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（抗生素（首选））：","用法：头孢类（头孢氨苄0.5g qid、头孢拉定0.5g qid、头孢呋辛0.25g bid）、青霉素类（阿莫西林0.5g tid、阿莫西林克拉维酸钾0.625g tid）、大环内酯类（红霉素0.5g qid、阿奇霉素0.5g qd）、喹诺酮类（左氧氟沙星0.5g qd，18岁以下禁用），疗程5-7天","药物2（止痛退热）：","用法：对乙酰氨基酚0.5g prn、布洛芬0.2g prn（疼痛或发热时）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物3（清热解毒中成药）：","用法：牛黄解毒片、黄连上清丸、蒲地蓝消炎口服液（辅助治疗）","药物4（局部用药）：","用法：抗生素滴眼液（左氧氟沙星滴眼液、妥布霉素滴眼液、氯霉素滴眼液，每2-4小时1次）、抗生素眼膏（红霉素眼膏、金霉素眼膏、四环素可的松眼膏，睡前涂眼）〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物5（脓肿成熟后）：","用法：切开排脓（外睑腺炎切口与睑缘平行，内睑腺炎切口与睑缘垂直），术后继续抗生素治疗","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["早期（硬结期，未化脓）：热敷（40-45℃热毛巾敷眼，每次10-15分钟，每日3-4次，促进炎症吸收或脓肿成熟）、局部抗生素（滴眼液+眼膏）、口服抗生素（严重或伴全身症状）、超短波理疗（促进炎症吸收）、避免挤压（防止感染扩散）","脓肿成熟期（出现黄白色脓点，有波动感）：切开排脓（外睑腺炎皮肤面切口与睑缘平行，内睑腺炎结膜面切口与睑缘垂直），排出脓液，放置引流条（必要时），术后继续抗生素治疗+局部换药，每日换药","并发症治疗：眼睑蜂窝织炎（静脉抗生素+局部治疗+支持治疗）、海绵窦血栓（广谱抗生素联合+抗凝+神经外科协同+脱水降颅压）、败血症（血培养+广谱抗生素静脉+支持治疗）","反复发作：查找诱因（睑缘炎、睑板腺功能障碍、糖尿病、免疫功能低下、屈光不正），治疗原发病，注意眼部卫生，增强体质","中医治疗：早期清热解毒（仙方活命饮、五味消毒饮），成脓期托毒排脓，溃后期扶正祛邪；耳尖放血（早期）","预防：注意眼部卫生，不用脏手揉眼；睑缘炎患者积极治疗；糖尿病患者控制血糖；增强体质，避免过度劳累；避免使用不洁化妆品和毛巾"],"management":["热敷护理：早期每日热敷3-4次，每次10-15分钟，温度40-45℃，避免烫伤；热敷后可轻柔按摩眼睑（未化脓时），促进炎症吸收","用药护理：按医嘱使用抗生素滴眼液（每2-4小时1次，滴入下穹窿部）和眼膏（睡前涂眼）；口服抗生素按时按量，足疗程，不可自行停药；观察药物疗效和副作用","疼痛护理：评估疼痛程度，疼痛明显时按医嘱用止痛药；避免挤压和触碰患处；取舒适体位，避免压迫患眼","病情观察：观察眼睑红肿、疼痛、硬结变化，注意脓点形成和破溃；观察有无眼睑蜂窝织炎（整个眼睑红肿加重、疼痛剧烈）、海绵窦血栓（高热、头痛、呕吐、意识障碍）等并发症，一旦出现立即就医","脓肿切开后护理：保持伤口清洁，按医嘱换药（每日1-2次），观察引流情况和伤口愈合；避免伤口沾水，避免挤压；继续使用抗生素","饮食：清淡易消化饮食，多饮水，多吃新鲜蔬果，避免辛辣刺激、油腻、烟酒、海鲜等发物","休息与活动：保证充足睡眠，避免熬夜和过度用眼；避免剧烈运动；避免去烟尘、风沙环境","个人卫生：勤洗手，不用脏手揉眼；毛巾、脸盆个人专用，定期消毒；避免与他人共用化妆品；患病期间避免眼部化妆","心理护理：安慰患者，解释疾病过程和治疗方法，消除焦虑；告知不可自行挤压（防止感染扩散致海绵窦血栓等严重并发症）","定期复查：按医嘱复查，观察炎症消退和伤口愈合；反复发作需查找诱因并治疗"],"notes":["又称麦粒肿、针眼，是眼睑腺体的急性化脓性炎症，分为外睑腺炎和内睑腺炎","外睑腺炎：睫毛毛囊或其附属皮脂腺（Zeis腺）、变态汗腺（Moll腺）感染，位于睑缘部，红肿疼痛较表浅，脓点在皮肤面，破溃后从皮肤面排脓","内睑腺炎：睑板腺感染，位于睑板内，红肿疼痛较剧烈，脓点在睑结膜面，破溃后从结膜面排脓","病原菌：多为金黄色葡萄球菌（占多数），少数为链球菌、葡萄球菌等","诱因：睑缘炎、睑板腺功能障碍、屈光不正、糖尿病、免疫功能低下、营养不良、过度劳累、用眼卫生不良、脏手揉眼、使用不洁化妆品和毛巾","临床表现：眼睑红肿热痛的急性炎症表现，局部硬结和压痛，脓肿成熟后出现黄白色脓点，可自行破溃排脓，严重时伴全身症状和并发症","治疗原则：早期热敷+抗生素（局部+全身），促进炎症吸收或脓肿成熟；脓肿成熟后切开排脓；并发症积极治疗；切忌挤压（防止感染扩散）","切开排脓注意：外睑腺炎切口与睑缘平行（与皮纹一致，减少瘢痕），内睑腺炎切口与睑缘垂直（避免损伤睑板腺管）；切口足够大，保证引流通畅；脓肿较大时放置引流条；术后每日换药","挤压危险：眼睑静脉无静脉瓣，挤压可使感染沿静脉扩散至海绵窦，引起海绵窦血栓性静脉炎、败血症，危及生命，故严禁挤压","反复发作需查找诱因：睑缘炎、睑板腺功能障碍、糖尿病、免疫功能低下、屈光不正等，治疗原发病，注意眼部卫生，增强体质","儿童、老年人、糖尿病患者、免疫功能低下者症状较重，易扩散，需积极治疗，密切观察","预后：一般预后良好，1-2周痊愈，可遗留轻微皮肤瘢痕（外睑腺炎）；严重并发症（海绵窦血栓、败血症）预后差，可危及生命","预防：注意眼部卫生，勤洗手，不用脏手揉眼；积极治疗睑缘炎和睑板腺功能障碍；糖尿病患者控制血糖；增强体质，避免过度劳累；毛巾脸盆个人专用，定期消毒；避免使用不洁化妆品"],"emergency":["出现整个眼睑红肿加重、疼痛剧烈、睁眼困难（眼睑蜂窝织炎，立即就医，静脉抗生素）","出现高热、寒战、头痛、呕吐、意识障碍（海绵窦血栓、败血症，危及生命，立即急诊）","出现耳前淋巴结明显肿大压痛、面部肿胀（感染扩散，及时就医）","脓肿破溃后脓液排出不畅、红肿疼痛加重（引流不畅，及时就医切开引流）","出现视力下降、眼痛、畏光（累及眼球，角膜炎、眶蜂窝织炎，及时就医）","儿童、老年人、糖尿病患者、免疫功能低下者出现睑腺炎（易扩散，尽早就医）"],"pinyin":"jianxianyan（mailizhong）","icd10":"H00.0","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态","视力检查：远视力（标准对数视力表）、近视力、矫正视力、裸眼视力","眼压检查：指测法（Tn/T+1/T+2/T+3）或眼压计（正常10-21mmHg）","眼睑：红肿/下垂/内翻/外翻/倒睫/肿块/瘢痕/闭合不全","泪器：泪点位置/泪道冲洗/泪囊区红肿压痛/溢泪","结膜：球结膜（充血/水肿/出血/滤泡/乳头）、睑结膜（充血/滤泡/乳头/瘢痕/结石）、穹窿部","角膜：透明度/上皮缺损（荧光素染色）/浸润/溃疡/瘢痕/新生血管/异物/曲率（K1/K2）","巩膜：黄染/充血/结节/葡萄肿","前房：深度（浅/中/深）、房水闪辉（Tyndall征）、房水细胞、积脓/积血","虹膜：颜色/纹理/粘连（前粘连/后粘连）/结节/萎缩/根部离断","瞳孔：大小/形状/位置/对光反射（直接/间接）/调节反射","晶状体：透明度（皮质/核/后囊下混浊）、位置（脱位/半脱位）、人工晶体","玻璃体：混浊/积血/增殖膜/脱离","眼底：视盘（边界/颜色/C/D比/水肿/萎缩）、视网膜（出血/渗出/水肿/脱离/色素紊乱）、黄斑（中心凹反光/水肿/裂孔/变性）、血管（管径/比例/交叉压迹/新生血管）","眼肌：眼球运动（各方向）、斜视（内斜/外斜/垂直斜）、复视、眼球震颤","视野：手动/自动视野计检查（青光眼/视神经病变）","色觉：色盲本检查"],"lab_tests":["裂隙灯显微镜检查（首选必做）：明确睑缘及睑板腺开口充血、肿胀、压痛部位，鉴别内睑腺炎与外睑腺炎，排除睑板腺囊肿及睑缘炎","视力检查：初诊及每次复诊常规评估，排除因眼睑高度肿胀压迫或继发角结膜病变引起的视力下降","眼压测量：眼睑高度红肿、疼痛剧烈时测量，排除严重感染引起的继发性眼压升高（必要时复查）","血常规及C反应蛋白：反复发作、伴发热或耳前淋巴结肿大时检查，评估全身炎症反应程度","细菌培养及药敏试验：脓肿切开排脓后留取脓液送检，反复发作或常规抗感染治疗无效者明确病原菌（多为金黄色葡萄球菌）及敏感抗生素"],"nursing":["眼部热敷护理：每日3-4次、每次10-15分钟，40-45℃温热湿毛巾敷于患眼，促进炎症局限及脓点成熟，注意温度防烫伤","病情观察：观察眼睑红肿范围及脓点形成情况，若红肿迅速扩散至眶周、伴眼球突出、眼球运动受限或发热，警惕眶蜂窝织炎，立即报告医生","严禁挤压：反复宣教禁止用手或器械挤压病灶，防止感染经无瓣静脉逆行扩散至海绵窦引起颅内感染","用药观察：指导正确滴用抗生素滴眼液、睡前涂抗生素眼膏，观察有无过敏反应；行切开排脓后观察切口渗血、引流情况及脓液是否排净","基础卫生护理：保持眼部及双手清洁，勤剪指甲、勤洗手，毛巾、脸盆专人专用并定期煮沸消毒，避免交叉感染及反复发作"],"diet":["忌辛辣刺激：禁食辣椒、花椒、芥末、姜蒜等辛辣刺激性食物，以免加重局部炎症反应","忌高糖油腻：少食油炸、肥肉等高脂食物及甜食糕点，高糖高脂饮食易致睑板腺分泌物淤积，诱发或加重睑腺炎","多食富含维生素A食物：如胡萝卜、南瓜、蛋黄、猪肝等，维护睑板腺及眼表上皮健康、促进炎症修复","多食富含维生素C食物：如猕猴桃、橙子、草莓、西兰花、青椒等，增强机体抵抗力，促进炎症消退","清淡多饮水：多饮温水、多吃新鲜蔬果及清淡易消化饮食，保持大便通畅，忌饮酒及浓茶咖啡"],"topical_medication":["左氧氟沙星滴眼液 1滴 滴眼 qid；红霉素眼膏 涂眼 qn"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":387},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"0453efce5ccf903c79161c3ec3c2a4fa81794346d287ef1facb129a778e062a6","pinyin":"jianxianyan（mailizhong）","initials":"jxy（mlz）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","外睑腺炎：眼睑缘部红肿、疼痛，局部硬结，压痛明显，可伴同侧耳前淋巴结肿大，脓肿成熟后睫毛根部出现黄白色脓点，可自行破溃排脓\\n内睑腺炎：眼睑红肿、疼痛，睑结膜面局限性充血、肿胀，睑结膜面可见黄白色脓点，疼痛较外睑腺炎剧烈，脓肿成熟后可向结膜面破溃\\n全身症状：严重时可伴发热、寒战、头痛、乏力\\n并发症：眼睑蜂窝织炎（整个眼睑红肿、疼痛剧烈）、海绵窦血栓（严重并发症，高热、头痛、呕吐、意识障碍，危及生命）、败血症、眼睑瘢痕、眼睑外翻",60],["摘要","眼睑腺体的急性化脓性炎症，分为外睑腺炎（睫毛毛囊或附属皮脂腺感染，Zeis腺、Moll腺）和内睑腺炎（睑板腺感染），多为金黄色葡萄球菌感染，表现为眼睑红肿热痛，可形成脓肿。",30],["疾病编码","H00.0",30],["原首字母","jianxianyan（mailizhong）",60]]},{"id":"orders-7798030ace49d1675d4f","key":"v1-c9ccc21dfe2a3058|orders-7798030ace49d1675d4f","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"睑板腺囊肿（霰粒肿）","category":"眼科","raw":{"name":"睑板腺囊肿（霰粒肿）","category":"眼科","summary":"睑板腺出口阻塞，腺体分泌物潴留引起的睑板腺慢性无菌性肉芽肿性炎症，表现为眼睑皮下无痛性硬结，进展缓慢，可单发或多发，上下睑均可发生。","symptoms":["眼睑皮下圆形硬结，大小不一（米粒至黄豆大），边界清楚，与皮肤无粘连，无压痛或轻微压痛","对应睑结膜面局限性充血，呈紫红色或灰红色","硬结较大时可有眼睑沉重感、异物感、视物模糊（压迫角膜致散光）","一般无疼痛、红肿（与睑腺炎区别）","继发感染时出现红肿热痛，表现同睑腺炎","硬结可自行破溃，排出胶样内容物，形成肉芽肿（息肉样突起）","可单发或多发，上下睑均可，上睑多见","儿童可多发，反复发作"],"diagnosis":["典型表现（眼睑皮下无痛性硬结，边界清，无压痛，进展缓慢）","眼睑检查（触诊硬结大小、数量、活动度、有无压痛，翻转眼睑检查睑结膜面）","排除睑腺炎（急性红肿热痛）、眼睑肿瘤（基底细胞癌、鳞状细胞癌、睑板腺癌，中老年患者、硬结质地硬、与皮肤粘连、表面皮肤破溃、睫毛脱落、反复发作者需警惕）、眼睑血管瘤、眼睑囊肿","病理检查（反复发作、老年患者、硬结质地硬、表面破溃者手术切除后送病理，排除恶性肿瘤）","B超（较大硬结，评估大小和范围）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1：","  用法：一般无需静脉输液；热敷 10~15min qid；左氧氟沙星滴眼液 1滴 滴眼 qid（合并感染时）","","方案2（继发感染；急性睑腺炎表现）：","  用法：同睑腺炎治疗，口服或静脉抗生素","","方案3：","  用法：手术前后一般无需静脉抗生素，局部用药即可","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（小而无症状）：","用法：无需用药，观察或热敷","药物2（继发感染）：","用法：抗生素（头孢氨苄0.5g qid、阿莫西林0.5g tid、左氧氟沙星0.5g qd），同睑腺炎〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物3（局部用药）：","用法：抗生素滴眼液（左氧氟沙星滴眼液、妥布霉素滴眼液，每日4-6次）、抗生素眼膏（红霉素眼膏、金霉素眼膏，睡前涂眼），继发感染时使用〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物4（糖皮质激素）：","用法：硬结内注射曲安奈德0.1-0.2ml（5-10mg），适用于较小或不宜手术者，可促进吸收，注意局部皮肤萎缩、色素脱失等副作用","药物5（中医中药）：","用法：化痰散结（化坚二陈汤、温胆汤加减），外敷（如意金黄散、玉露膏，未破溃时）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["小而无症状：观察，部分可自行吸收，或热敷（40-45℃，每次10-15分钟，每日2-3次，促进吸收）","中等大小：热敷+局部抗生素（预防感染）+糖皮质激素硬结内注射（曲安奈德），观察1-2个月，不吸收者手术","大或有症状：手术切除（睑板腺囊肿刮除术，局麻下翻转眼睑，睑结膜面垂直切口，刮除内容物，剪除囊壁，术后压迫止血，抗生素眼膏包扎），术后1-2天恢复","继发感染：先按睑腺炎治疗（热敷+抗生素），炎症消退后手术切除残留硬结","肉芽肿（破溃后息肉样突起）：手术切除肉芽肿+刮除囊壁","反复发作或老年患者：手术切除后送病理检查，排除睑板腺癌等恶性肿瘤","儿童多发或反复发作：检查有无睑缘炎、睑板腺功能障碍、屈光不正、维生素A缺乏，治疗原发病，注意眼部卫生和营养","预防：注意眼部卫生，积极治疗睑缘炎和睑板腺功能障碍，避免过度用眼，增强体质，均衡营养"],"management":["热敷护理：小硬结每日热敷2-3次，每次10-15分钟，温度40-45℃，促进吸收；热敷后轻柔按摩眼睑（沿睑缘方向），促进睑板腺分泌物排出","用药护理：按医嘱使用抗生素滴眼液和眼膏（继发感染时）；糖皮质激素硬结内注射后观察局部反应（皮肤萎缩、色素脱失、出血）；口服抗生素按时按量","病情观察：观察硬结大小、数量、颜色变化，注意有无继发感染（红肿热痛）、破溃、肉芽肿形成；老年患者、反复发作、硬结质地硬、表面破溃、睫毛脱落者警惕恶性肿瘤，及时就医病理检查","手术后护理：术后压迫止血10-15分钟；术后当日眼垫包扎，次日打开；术后抗生素滴眼液+眼膏，每日4-6次；术后1-2天可有轻微红肿、异物感，属正常；避免揉眼、伤口沾水；术后1周复查","饮食：清淡易消化饮食，多饮水，多吃新鲜蔬果，避免辛辣刺激、油腻、烟酒；儿童注意营养均衡，补充维生素A","休息与活动：保证充足睡眠，避免熬夜和过度用眼；术后避免剧烈运动、游泳；避免烟尘、风沙环境","个人卫生：勤洗手，不用脏手揉眼；毛巾脸盆个人专用，定期消毒；避免与他人共用化妆品；睑缘炎患者积极治疗，定期清洁睑缘","心理护理：安慰患者，解释疾病性质（慢性无菌性炎症，非肿瘤）和治疗方法，消除焦虑；告知手术简单安全，恢复快","定期复查：小硬结观察1-2个月不吸收者就医手术；术后1周复查；反复发作或老年患者术后病理检查并定期随访"],"notes":["又称霰粒肿、睑板腺囊肿，是睑板腺出口阻塞、分泌物潴留引起的慢性无菌性肉芽肿性炎症，是常见的眼睑疾病","发病机制：睑板腺出口阻塞（睑缘炎、睑板腺功能障碍、慢性结膜炎、皮脂腺分泌旺盛）→腺体分泌物潴留→刺激周围组织→慢性肉芽肿性炎症（纤维结缔组织包绕，内含睑板腺分泌物、巨噬细胞、多核巨细胞、淋巴细胞、浆细胞）","与睑腺炎区别：睑板腺囊肿是慢性无菌性肉芽肿，无痛性硬结，进展缓慢，无红肿热痛；睑腺炎是急性化脓性炎症，红肿热痛明显，有压痛，进展快，可形成脓肿","分型：小型（<3mm）、中型（3-5mm）、大型（>5mm）；单发或多发；上下睑均可，上睑多见（上睑睑板腺丰富）","好发人群：儿童和青少年（皮脂腺分泌旺盛）、睑缘炎患者、睑板腺功能障碍患者、屈光不正者、维生素A缺乏者、卫生习惯不良者","临床表现：眼睑皮下无痛性硬结，边界清，与皮肤无粘连，无压痛，对应睑结膜面紫红色充血，硬结大可有眼睑沉重感、异物感、散光，继发感染时同睑腺炎，可自行破溃形成肉芽肿","治疗原则：小而无症状观察或热敷；中等大小热敷+激素注射；大或有症状手术切除；继发感染先抗感染后手术；反复发作或老年患者手术送病理","手术注意：局麻下翻转眼睑，睑结膜面垂直切口（与睑缘垂直，避免损伤睑板腺管），刮匙刮除内容物，剪除囊壁（防止复发），压迫止血，抗生素眼膏包扎，一般无需缝合；术后1-2天恢复","糖皮质激素注射注意：曲安奈德5-10mg硬结内注射，可促进吸收，适用于较小或不宜手术者，副作用有局部皮肤萎缩、色素脱失、皮下出血、视网膜动脉阻塞（罕见但严重），需由有经验医生操作","复发原因：囊壁未剪除干净、睑板腺功能障碍未治疗、睑缘炎未治疗、多发囊肿、特殊体质；复发者需彻底切除囊壁，治疗原发病","恶性肿瘤鉴别：中老年患者、硬结质地硬、与皮肤粘连、表面皮肤破溃、睫毛脱落、反复发作者需警惕睑板腺癌、基底细胞癌、鳞状细胞癌，手术切除后必须送病理检查","儿童注意：儿童不配合手术可在全麻下进行；多发或反复发作需检查全身情况（营养、免疫、睑缘炎）","预后：一般预后良好，手术简单安全，恢复快，不留皮肤瘢痕（结膜面切口）；继发感染或破溃可形成肉芽肿；罕见严重并发症（激素注射致视网膜动脉阻塞）","预防：注意眼部卫生，勤洗手，不用脏手揉眼；积极治疗睑缘炎和睑板腺功能障碍（热敷、按摩、清洁睑缘）；避免过度用眼；均衡营养，补充维生素A；增强体质"],"emergency":["出现眼睑红肿热痛加重、疼痛剧烈（继发感染急性睑腺炎，及时就医抗感染）","出现硬结迅速增大、表面皮肤破溃、睫毛脱落、质地硬（警惕恶性肿瘤，尽快就医病理检查）","出现眼痛、视力下降、畏光（累及角膜或眼球，及时就医）","激素注射后出现视力骤降、视野缺损（视网膜动脉阻塞，立即就医）","手术后出血不止、眼睑严重肿胀（术后出血，压迫止血并就医）","儿童出现多发囊肿、反复发作、营养不良（需全面检查，治疗原发病）"],"pinyin":"jianbanxiannangzhong（xianlizhong）","icd10":"H00.1","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态","视力检查：远视力（标准对数视力表）、近视力、矫正视力、裸眼视力","眼压检查：指测法（Tn/T+1/T+2/T+3）或眼压计（正常10-21mmHg）","眼睑：红肿/下垂/内翻/外翻/倒睫/肿块/瘢痕/闭合不全","泪器：泪点位置/泪道冲洗/泪囊区红肿压痛/溢泪","结膜：球结膜（充血/水肿/出血/滤泡/乳头）、睑结膜（充血/滤泡/乳头/瘢痕/结石）、穹窿部","角膜：透明度/上皮缺损（荧光素染色）/浸润/溃疡/瘢痕/新生血管/异物/曲率（K1/K2）","巩膜：黄染/充血/结节/葡萄肿","前房：深度（浅/中/深）、房水闪辉（Tyndall征）、房水细胞、积脓/积血","虹膜：颜色/纹理/粘连（前粘连/后粘连）/结节/萎缩/根部离断","瞳孔：大小/形状/位置/对光反射（直接/间接）/调节反射","晶状体：透明度（皮质/核/后囊下混浊）、位置（脱位/半脱位）、人工晶体","玻璃体：混浊/积血/增殖膜/脱离","眼底：视盘（边界/颜色/C/D比/水肿/萎缩）、视网膜（出血/渗出/水肿/脱离/色素紊乱）、黄斑（中心凹反光/水肿/裂孔/变性）、血管（管径/比例/交叉压迹/新生血管）","眼肌：眼球运动（各方向）、斜视（内斜/外斜/垂直斜）、复视、眼球震颤","视野：手动/自动视野计检查（青光眼/视神经病变）","色觉：色盲本检查"],"lab_tests":["裂隙灯显微镜检查（初诊及复查必做）：观察睑板腺囊肿位置、大小、表面有无血管增生、有无破溃肉芽，与睑板腺癌、睑腺炎鉴别；同时排查结膜及角膜继发改变。","视力检查（初诊基线及术后复查）：评估肿块压迫或手术是否影响视力。","非接触式眼压测量（初诊及术前）：排除继发性青光眼；术前后对比，防范术后眼压波动。","眼底检查（经散瞳，初诊常规）：排除合并眼底病变，尤其反复发作、年龄偏大者。","眼睑B超（肿块较大或疑有囊性变时）：明确囊壁厚度及内容物性质，辅助判断手术时机。","睑板腺成像（睑板腺红外摄影，反复发作者）：评估睑板腺功能及腺体缺失情况，指导术后综合治疗；对长期不消退、质地硬、表面溃烂者建议手术切除后送病理活检，排除睑板腺癌。"],"nursing":["热敷护理：未破溃期遵医嘱用40～45℃湿热毛巾或热敷眼罩局部热敷，每次10～15分钟、每日2～3次，促进脂质软化吸收；注意水温防烫伤，敷后保持眼睑干燥清洁。","眼部卫生与病情观察：嘱勤洗手、勿揉搓患眼，避免挤压囊肿（防止炎症扩散）；每日观察肿块大小、颜色，有无红肿疼痛加重、破溃流液或继发感染，异常及时报告。","用药观察：按医嘱使用抗生素眼膏或滴眼液，观察有无眼睑红肿、瘙痒等过敏反应及角膜刺激症状；糖皮质激素眼膏按疗程使用，不可自行停用或延长。","术后护理：术后遵医嘱加压包扎或冷敷24小时止血消肿，嘱勿自行拆解敷料；观察切口有无渗血、渗液及角膜损伤（畏光、刺痛），按时点眼药，复诊拆线；术后一周避免揉眼及剧烈运动。","防跌倒护理：术后单眼包扎者立体视觉下降，行走需家属搀扶，病房环境保持地面干燥、床栏拉起，夜间如厕加强陪护。"],"diet":["忌口：忌辛辣刺激食物（辣椒、花椒、生姜）、忌烟酒及浓茶咖啡，减少刺激睑板腺分泌。","低脂低糖：少食油炸、肥腻、烧烤及高糖甜食，避免睑板腺分泌过旺加重囊肿或复发。","富含维生素A：适量进食动物肝脏、蛋黄、胡萝卜、南瓜、菠菜等，促进眼表上皮修复、维持睑板腺功能。","富含维生素C：多食新鲜蔬果（橙子、猕猴桃、番茄、西兰花等），增强抵抗力，促进炎症吸收。","多饮水、保持大便通畅：每日饮水1500～2000ml，多吃粗粮及绿叶蔬菜防便秘；术后当日进食温凉软食，避免过热过硬食物咀嚼牵拉伤口。"],"topical_medication":["妥布霉素地塞米松滴眼液 1滴 滴眼 tid"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":388},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"6ffb6b22c520a8bfae6705c1a287f23be52772b082541b880d993cc8745ede47","pinyin":"jianbanxiannangzhong（xianlizhong）","initials":"jbxnz（xlz）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","眼睑皮下圆形硬结，大小不一（米粒至黄豆大），边界清楚，与皮肤无粘连，无压痛或轻微压痛\\n对应睑结膜面局限性充血，呈紫红色或灰红色\\n硬结较大时可有眼睑沉重感、异物感、视物模糊（压迫角膜致散光）\\n一般无疼痛、红肿（与睑腺炎区别）\\n继发感染时出现红肿热痛，表现同睑腺炎\\n硬结可自行破溃，排出胶样内容物，形成肉芽肿（息肉样突起）\\n可单发或多发，上下睑均可，上睑多见\\n儿童可多发，反复发作",60],["摘要","睑板腺出口阻塞，腺体分泌物潴留引起的睑板腺慢性无菌性肉芽肿性炎症，表现为眼睑皮下无痛性硬结，进展缓慢，可单发或多发，上下睑均可发生。",30],["疾病编码","H00.1",30],["原首字母","jianbanxiannangzhong（xianlizhong）",60]]},{"id":"orders-f3c1672beaa4371eebc8","key":"v1-c9ccc21dfe2a3058|orders-f3c1672beaa4371eebc8","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"沙眼","category":"眼科","raw":{"name":"沙眼","category":"眼科","summary":"沙眼衣原体感染引起的慢性传染性结膜角膜炎，是致盲性眼病之一，表现为眼痒、异物感、流泪、黏液脓性分泌物、结膜充血、乳头增生、滤泡形成，晚期可致睑内翻倒睫、角膜混浊、视力损害。","symptoms":["急性期：眼痒、异物感、烧灼感、流泪、畏光、黏液脓性分泌物增多、眼睑红肿、结膜充血（弥漫性）、乳头增生、滤泡形成（上穹窿和上睑结膜）、可伴耳前淋巴结肿大、发热等全身症状","慢性期：症状减轻，仅有眼痒、异物感、干燥、烧灼感、视疲劳，结膜充血减轻，乳头滤泡增生，瘢痕形成（睑结膜白色线状、网状瘢痕，Arlt线），角膜血管翳（角膜上缘新生血管伸入角膜）","晚期并发症：睑内翻倒睫（最常见，瘢痕收缩致睑缘内翻、睫毛摩擦角膜）、角膜混浊溃疡（倒睫摩擦+角膜血管翳致角膜混浊、溃疡、新生血管）、上睑下垂（睑结膜和睑板肥厚、Müller肌受累）、睑球粘连（穹窿部结膜瘢痕收缩）、实质性结膜干燥症（结膜杯状细胞和副泪腺破坏、泪腺开口阻塞）、慢性泪囊炎（泪道黏膜瘢痕狭窄阻塞）","视力损害：晚期角膜混浊、溃疡、瘢痕致视力下降，严重者失明","重复感染：反复感染加重瘢痕和并发症","儿童症状不典型，可自愈或转为慢性"],"diagnosis":["典型临床表现（上睑结膜乳头滤泡增生、瘢痕、角膜血管翳）","WHO诊断标准（至少满足2项）：上睑结膜5个以上滤泡、典型睑结膜瘢痕、角膜缘滤泡或Herbert小凹、广泛角膜血管翳","实验室检查：结膜刮片Giemsa染色（找包涵体）、沙眼衣原体培养（金标准）、直接荧光抗体检测（DFA）、酶联免疫吸附试验（ELISA）、PCR检测（敏感快速）","排除慢性结膜炎、春季卡他性结膜炎、过敏性结膜炎、滤泡性结膜炎","并发症检查：角膜荧光素染色（角膜上皮缺损溃疡）、泪液分泌试验（结膜干燥症）、泪道冲洗（慢性泪囊炎）、视力检查、验光"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1（急性期或严重感染）：","用法：0.9%NS 100ml + 阿奇霉素0.5g ivgtt qd 或 红霉素0.5-1g ivgtt q6h（不能口服者）","方案2（合并角膜溃疡）：","用法：0.9%NS 250ml + 维生素C 2g ivgtt qd（促进角膜修复）","方案3（合并全身感染）：","用法：阿奇霉素 0.5g + 5%GS 500ml 静滴 qd；或多西环素 100mg 口服 q12h","方案4：","用法：一般慢性期无需静脉输液，口服+局部用药即可","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（抗生素（全身））：","用法：阿奇霉素1g顿服（首选，单次口服，方便，疗效好）、多西环素100mg bid×14天、四环素0.5g qid×14天（8岁以下儿童、孕妇、哺乳期禁用）、红霉素0.5g qid×14天（儿童、孕妇可用）、螺旋霉素、米诺环素〔调 ★ 8岁以下及妊娠期禁用；食管刺激（需直立饮水送服）〕","药物2（局部用药）：","用法：抗生素滴眼液（利福平滴眼液、磺胺醋酰钠滴眼液、氯霉素滴眼液、左氧氟沙星滴眼液、妥布霉素滴眼液，每日4-6次）、抗生素眼膏（四环素眼膏、红霉素眼膏、金霉素眼膏，睡前涂眼），疗程至少10-12周〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物3（角膜血管翳/角膜混浊）：","用法：糖皮质激素滴眼液（氟米龙0.1%、泼尼松龙0.5%，短期使用，注意眼压和感染加重）、促进角膜修复（重组人表皮生长因子滴眼液、重组牛碱性成纤维细胞生长因子滴眼液、玻璃酸钠滴眼液）〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物4（并发症治疗）：","用法：睑内翻倒睫（手术矫正：睑内翻矫正术、倒睫电解术、睫毛拔除）、角膜溃疡（抗生素+促进修复+散瞳，必要时角膜移植）、实质性结膜干燥症（人工泪液、泪小点栓塞、颌下腺移植）、慢性泪囊炎（泪囊鼻腔吻合术）","药物5（中医中药）：","用法：清热解毒（银翘散、桑菊饮加减），祛风清热（除风清脾饮），活血化瘀（桃红四物汤，角膜血管翳）","药物6（预防）：","用法：注意个人卫生，勤洗手，不用脏手揉眼，毛巾脸盆个人专用，定期消毒，避免接触传染，改善环境卫生，治疗患者和带菌者","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["药物治疗：全身抗生素（阿奇霉素1g顿服首选，或多西环素/四环素/红霉素14天）+局部抗生素（滴眼液+眼膏，疗程10-12周），急性期和严重感染全身用药，慢性期局部用药为主，重复感染需重复治疗","并发症治疗：睑内翻倒睫（手术矫正，是防止角膜损害和失明的关键，睑内翻矫正术、倒睫电解、睫毛拔除）、角膜混浊溃疡（抗生素+促进修复+散瞳，角膜瘢痕严重者角膜移植术）、上睑下垂（手术矫正）、睑球粘连（手术分离+黏膜移植）、实质性结膜干燥症（人工泪液+泪小点栓塞+颌下腺移植）、慢性泪囊炎（泪囊鼻腔吻合术）","手术治疗：滤泡挤压术（慢性期滤泡多者，用滤泡挤压镊挤破滤泡，配合药物治疗，减少传染源）、乳头摩擦术（乳头增生明显者）、睑内翻矫正术（并发症）、角膜移植术（角膜瘢痕致视力严重损害）","公共卫生措施：筛查和治疗患者（尤其是儿童和育龄妇女）、改善环境卫生（供水、厕所、垃圾处理）、健康教育（洗脸卫生、不用脏手揉眼、毛巾个人专用）、面部清洁（FACE策略：面部清洁、抗生素治疗、环境改善）","随访：治疗后定期复查，评估疗效和并发症，重复感染及时治疗，晚期并发症及时手术","预防：注意个人卫生和公共卫生，勤洗手，不用脏手揉眼，毛巾脸盆个人专用定期消毒，避免接触传染，改善环境卫生，治疗患者和带菌者，儿童定期体检"],"management":["用药护理：按医嘱足量足疗程使用抗生素（全身+局部），不可自行停药（易复发和产生耐药）；使用多种眼药水时间隔5-10分钟；眼膏睡前使用；观察药物疗效和副作用（四环素类胃肠道反应、光敏反应，阿奇霉素胃肠道反应）","眼部护理：保持眼部清洁，用无菌棉签拭去分泌物；避免揉眼；急性期隔离（毛巾脸盆个人专用，避免传染他人）；避免去公共场所（游泳池、浴室）；外出戴防护眼镜（防风、防尘、防紫外线）","病情观察：观察眼部分泌物、结膜充血、乳头滤泡变化，注意角膜情况（有无混浊、溃疡、血管翳加重），观察视力变化；注意并发症（睑内翻倒睫、角膜溃疡、上睑下垂），一旦出现及时就医","并发症护理：睑内翻倒睫者注意角膜保护（避免睫毛摩擦，及时手术）；角膜溃疡者按医嘱用药，避免压迫眼球；结膜干燥症者规律使用人工泪液；慢性泪囊炎者注意泪囊区清洁，避免挤压","饮食：清淡易消化饮食，多饮水，多吃富含维生素A（胡萝卜、动物肝脏、蛋黄）、维生素C（新鲜蔬果）、维生素B2的食物；避免辛辣刺激、油腻、烟酒","休息与活动：保证充足睡眠，避免熬夜和过度用眼；急性期避免剧烈运动；避免烟尘、风沙、强光环境","个人卫生与隔离：勤洗手，不用脏手揉眼；毛巾、脸盆、枕巾个人专用，定期煮沸消毒；避免与他人共用毛巾、化妆品；患病期间避免眼部化妆；急性期避免去公共场所（游泳池、浴室、理发店）；家属注意检查和治疗","心理护理：安慰患者，解释疾病传染性和可治性，消除焦虑；告知坚持足疗程治疗的重要性；晚期并发症患者给予心理支持，鼓励积极治疗","健康教育：讲解沙眼的传播途径（接触传染）和预防方法；强调个人卫生和公共卫生的重要性；告知并发症的危害（睑内翻倒睫可致失明），及时治疗；指导正确滴眼药方法；定期复查","家庭防护：家庭成员同时检查，发现感染及时治疗；毛巾脸盆分开使用；定期消毒；改善家庭卫生条件"],"notes":["沙眼是沙眼衣原体（Chlamydia trachomatis，A、B、Ba、C血清型）感染引起的慢性传染性结膜角膜炎，是世界卫生组织认定的致盲性眼病之一，曾是我国首位致盲眼病，现已明显减少，但在卫生条件差的地区仍有流行","传播途径：接触传染（眼-手-眼、共用毛巾脸盆、苍蝇传播），母婴传播，卫生条件差、拥挤、缺水地区易流行","临床分期（MacCallan分期）：Ⅰ期（浸润初期，上睑结膜和穹窿结膜充血、滤泡增生，角膜血管翳）、Ⅱ期（活动期，乳头滤泡增生，可有角膜上皮炎，传染性强）、Ⅲ期（瘢痕前期，瘢痕开始形成）、Ⅳ期（瘢痕期，完全瘢痕化，无传染性，出现并发症）","WHO简化分期：滤泡性沙眼（TF，上睑结膜≥5个滤泡）、浸润性沙眼（TI，上睑结膜弥漫性浸润增厚，>50%睑板血管模糊）、瘢痕性沙眼（TS，睑结膜瘢痕）、沙眼性倒睫（TT，至少1根倒睫摩擦角膜）、角膜混浊（CO，瞳孔区角膜混浊，视力<6/18）","角膜血管翳：沙眼特征性表现，角膜上缘新生血管伸入角膜，呈垂帘状，血管末端可形成滤泡，滤泡破溃后形成小凹（Herbert小凹），是沙眼的特异性体征","Arlt线：上睑结膜瘢痕，呈白色线状，平行于睑缘，是沙眼的特征性瘢痕","并发症：睑内翻倒睫（最常见，是致盲的主要原因，瘢痕收缩致睑板肥厚变形、睑缘内翻、睫毛摩擦角膜）、角膜混浊溃疡（倒睫摩擦+角膜血管翳+感染致角膜混浊、溃疡、新生血管、瘢痕，严重者失明）、上睑下垂、睑球粘连、实质性结膜干燥症、慢性泪囊炎","治疗原则：全身+局部抗生素治疗（阿奇霉素1g顿服首选，局部抗生素10-12周），并发症手术治疗（睑内翻矫正术是防盲关键），公共卫生措施（筛查治疗、改善环境、健康教育）","阿奇霉素治疗：WHO推荐阿奇霉素1g单次口服（成人），儿童20mg/kg单次口服，每年1次，连续3年，可有效控制沙眼流行；副作用轻（胃肠道反应）","局部用药疗程：至少10-12周，因为沙眼衣原体生命周期长，短期用药易复发","手术治疗：滤泡挤压术和乳头摩擦术是辅助治疗，配合药物，减少传染源；睑内翻矫正术是并发症治疗和防盲关键；角膜移植术用于角膜瘢痕致严重视力损害","FACE策略：WHO推荐的沙眼控制策略，包括面部清洁（Facial cleanliness）、抗生素治疗（Antibiotic treatment）、环境改善（Environmental improvement），加上手术（Surgery）组成SAFE策略（Surgery手术、Antibiotic抗生素、Facial cleanliness面部清洁、Environmental improvement环境改善）","预后：早期治疗预后良好，可完全恢复；晚期并发症（睑内翻倒睫、角膜混浊）可致视力损害甚至失明；重复感染加重病情；及时治疗和预防并发症是防盲关键","预防：注意个人卫生（勤洗手、不用脏手揉眼、毛巾个人专用）、改善环境卫生（供水、厕所、垃圾处理、灭蝇）、筛查和治疗患者（尤其是儿童和育龄妇女）、健康教育、避免接触传染","我国现状：随着生活水平提高和卫生条件改善，沙眼发病率已明显下降，重症和并发症减少，但在部分农村和卫生条件差地区仍有散发，需继续防治"],"emergency":["出现角膜溃疡、眼痛剧烈、畏光明显、视力骤降（角膜感染溃疡，立即就医，可能致角膜穿孔）","出现睑内翻倒睫、睫毛摩擦角膜、角膜混浊加重（并发症，尽快手术矫正，防止失明）","出现急性结膜炎加重、分泌物大量增多、眼睑红肿（急性发作或合并其他感染，及时就医）","出现视力进行性下降、角膜白斑（晚期并发症，尽快眼科评估，必要时角膜移植）","儿童出现大量流泪、分泌物、眼睑红肿（急性沙眼，及时治疗，避免转为慢性和并发症）","出现全身发热、耳前淋巴结明显肿大（严重感染，及时就医）"],"pinyin":"shayan","icd10":"A71.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态","视力检查：远视力（标准对数视力表）、近视力、矫正视力、裸眼视力","眼压检查：指测法（Tn/T+1/T+2/T+3）或眼压计（正常10-21mmHg）","眼睑：红肿/下垂/内翻/外翻/倒睫/肿块/瘢痕/闭合不全","泪器：泪点位置/泪道冲洗/泪囊区红肿压痛/溢泪","结膜：球结膜（充血/水肿/出血/滤泡/乳头）、睑结膜（充血/滤泡/乳头/瘢痕/结石）、穹窿部","角膜：透明度/上皮缺损（荧光素染色）/浸润/溃疡/瘢痕/新生血管/异物/曲率（K1/K2）","巩膜：黄染/充血/结节/葡萄肿","前房：深度（浅/中/深）、房水闪辉（Tyndall征）、房水细胞、积脓/积血","虹膜：颜色/纹理/粘连（前粘连/后粘连）/结节/萎缩/根部离断","瞳孔：大小/形状/位置/对光反射（直接/间接）/调节反射","晶状体：透明度（皮质/核/后囊下混浊）、位置（脱位/半脱位）、人工晶体","玻璃体：混浊/积血/增殖膜/脱离","眼底：视盘（边界/颜色/C/D比/水肿/萎缩）、视网膜（出血/渗出/水肿/脱离/色素紊乱）、黄斑（中心凹反光/水肿/裂孔/变性）、血管（管径/比例/交叉压迹/新生血管）","眼肌：眼球运动（各方向）、斜视（内斜/外斜/垂直斜）、复视、眼球震颤","视野：手动/自动视野计检查（青光眼/视神经病变）","色觉：色盲本检查"],"lab_tests":["视力检查（裸眼及矫正视力）：评估角膜混浊、血管翳对视功能的影响，作为分期与疗效判断的基线，复诊时定期复查","裂隙灯显微镜检查：重点观察上睑结膜滤泡、乳头增生与瘢痕（Arlt线）、角膜上方血管翳及Herbert小凹，按WHO简化分级分期","角膜荧光素染色检查：明确倒睫、睑内翻所致角膜上皮点状缺损或溃疡范围，评估角膜损伤程度，指导手术时机","眼压测量：沙眼常需局部应用糖皮质激素及长期用药，监测眼压以排除继发性青光眼","沙眼衣原体病原学检查：结膜刮片Giemsa染色找包涵体，或免疫荧光/核酸扩增法检测衣原体抗原，用于初诊确诊及停药前转阴评估","泪膜功能检查（泪膜破裂时间、Schirmer试验）：评估睑板腺受累所致泪膜不稳定与干眼，指导人工泪液辅助用药"],"nursing":["病情观察：观察眼部分泌物量及性状、结膜充血与滤泡变化，有无畏光、流泪及异物感加重，发现角膜溃疡或视力骤降及时报告","眼部护理：滴眼前后洗手，滴眼瓶口勿触及眼睑睫毛；分泌物多时用无菌棉签蘸生理盐水自内眦向外轻拭，严禁揉眼","用药观察：遵医嘱足疗程用药（四环素类、阿奇霉素等），观察局部刺激与过敏反应，口服阿奇霉素注意胃肠道反应，勿擅自停药","隔离与卫生宣教：沙眼具传染性，毛巾、脸盆、枕巾专人专用并煮沸消毒，勤洗手、不共用眼部用品，防止家庭内传播","术后护理（倒睫/睑内翻矫正术后）：观察术区渗血、肿胀及缝线情况，避免揉搓与用力挤眼，按时复诊换药拆线"],"diet":["忌辛辣刺激及油腻食物（辣椒、大蒜、油炸食品等），减少眼部炎症刺激","忌烟酒，避免加重眼睑充血与炎症反应，影响疗效","多食富含维生素A食物：动物肝脏、胡萝卜、南瓜、蛋黄、鱼肝油，维持角膜上皮完整与泪膜稳定","多食富含维生素C食物：猕猴桃、橙子、青椒、番茄、草莓，增强免疫力、促进结膜组织修复","清淡饮食、多饮水，宜软食细嚼，保持大便通畅，保证营养均衡以利恢复"],"topical_medication":["利福平滴眼液 1滴 滴眼 qid；磺胺醋酰钠滴眼液 1滴 滴眼 tid；红霉素眼膏 涂眼 qn"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":389},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"a1384e6f1b5ec94fa82a644a4800295f634b865435b551fd817971549e861e01","pinyin":"shayan","initials":"sy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","急性期：眼痒、异物感、烧灼感、流泪、畏光、黏液脓性分泌物增多、眼睑红肿、结膜充血（弥漫性）、乳头增生、滤泡形成（上穹窿和上睑结膜）、可伴耳前淋巴结肿大、发热等全身症状\\n慢性期：症状减轻，仅有眼痒、异物感、干燥、烧灼感、视疲劳，结膜充血减轻，乳头滤泡增生，瘢痕形成（睑结膜白色线状、网状瘢痕，Arlt线），角膜血管翳（角膜上缘新生血管伸入角膜）\\n晚期并发症：睑内翻倒睫（最常见，瘢痕收缩致睑缘内翻、睫毛摩擦角膜）、角膜混浊溃疡（倒睫摩擦+角膜血管翳致角膜混浊、溃疡、新生血管）、上睑下垂（睑结膜和睑板肥厚、Müller肌受累）、睑球粘连（穹窿部结膜瘢痕收缩）、实质性结膜干燥症（结膜杯状细胞和副泪腺破坏、泪腺开口阻塞）、慢性泪囊炎（泪道黏膜瘢痕狭窄阻塞）\\n视力损害：晚期角膜混浊、溃疡、瘢痕致视力下降，严重者失明\\n重复感染：反复感染加重瘢痕和并发症\\n儿童症状不典型，可自愈或转为慢性",60],["摘要","沙眼衣原体感染引起的慢性传染性结膜角膜炎，是致盲性眼病之一，表现为眼痒、异物感、流泪、黏液脓性分泌物、结膜充血、乳头增生、滤泡形成，晚期可致睑内翻倒睫、角膜混浊、视力损害。",30],["疾病编码","A71.9",30],["原首字母","shayan",60]]},{"id":"orders-b66be7b72fd8dba4faf7","key":"v1-c9ccc21dfe2a3058|orders-b66be7b72fd8dba4faf7","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"翼状胬肉","category":"眼科","raw":{"name":"翼状胬肉","category":"眼科","summary":"睑裂部球结膜及结膜下组织增生肥厚，呈三角形向角膜侵入，形似翼状，多发生于鼻侧，与紫外线照射、风沙、干燥等刺激有关，可影响视力和眼球运动。","symptoms":["小而静止期：无明显症状，或仅有轻微异物感、干涩感，睑裂部球结膜三角形增厚，尖端指向角膜，基底位于眦部","进行期：胬肉充血、肥厚、增生，向角膜中央方向生长，异物感、干涩感加重，可伴眼红、流泪","侵入瞳孔区：影响视力（散光、遮挡瞳孔），严重者视力明显下降","较大或术后复发：可影响眼球运动（限制眼球转动，复视），睑球粘连","多发生于鼻侧（占多数），也可颞侧或双侧，双眼可同时或先后发病","户外工作者、农民、渔民、长期日晒风沙者多见","一般无疼痛，合并炎症时可有眼红、疼痛"],"diagnosis":["典型表现（睑裂部球结膜三角形增生肥厚，向角膜侵入，尖端指向角膜，基底位于眦部）","眼部检查（视力、验光、裂隙灯检查胬肉大小、充血程度、侵入角膜范围、是否累及瞳孔区、角膜厚度、前房、眼底）","排除睑裂斑（不侵入角膜，位于睑裂部球结膜，黄白色斑块）、假性胬肉（角膜溃疡、烧伤、外伤后结膜与角膜粘连，无进行性，可发生于任何部位）、结膜肿瘤（鳞状细胞癌、黑色素瘤，表面不光滑、易出血、生长快，病理可鉴别）、角膜缘上皮内瘤变","角膜地形图（评估散光程度和角膜形态）","术前检查：角膜厚度、角膜内皮计数、泪液分泌试验、血常规、凝血功能、传染病筛查"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般无需静脉输液；0.1%氟米龙滴眼液 1滴 滴眼 qid（术后）；左氧氟沙星滴眼液 1滴 滴眼 qid（术后）","方案2：","用法：术后一般无需静脉抗生素，口服或局部抗生素即可","方案3（合并感染或术后感染）：","用法：0.9%NS 100ml + 抗生素 ivgtt qd（根据病原选择）","方案4：","用法：全身疾病患者（糖尿病、高血压）按内科方案控制血糖血压","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（小而静止期）：","用法：无需口服药，局部用眼药水（人工泪液、抗生素滴眼液，有炎症时用低浓度激素）","药物2（进行期或术后）：","用法：抗生素（头孢氨苄0.5g qid、阿莫西林0.5g tid，预防感染）、非甾体抗炎药（布洛芬0.2g tid，止痛抗炎）、维生素（维生素C 0.2g tid、维生素B2 10mg tid，促进愈合）〔调 CrCl<30 减量；青霉素过敏禁用〕","药物3（局部用药）：","用法：抗生素滴眼液（左氧氟沙星滴眼液、妥布霉素滴眼液，每日4-6次，术后用）、糖皮质激素滴眼液（氟米龙0.1%、泼尼松龙0.5%，术后抗炎抗增殖，逐渐减量，注意眼压）、非甾体抗炎滴眼液（普拉洛芬滴眼液、双氯芬酸钠滴眼液，每日4次，抗炎止痛）、人工泪液（玻璃酸钠滴眼液，术后干眼）、抗代谢药物（丝裂霉素C 0.02%，术中或术后使用，防止复发，注意角膜毒性）","药物4（术后复发）：","用法：再次手术+抗代谢药物+角膜缘干细胞移植","药物5（中医中药）：","用法：祛风清热（栀子胜奇散），活血化瘀（桃红四物汤），术后调理（益气养血、清热解毒）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["小而静止期（未侵入角膜或侵入<2mm，无充血，不影响视力）：观察，避免刺激（戴防紫外线眼镜、防风沙），有炎症时用低浓度激素滴眼液和人工泪液","进行期（胬肉充血肥厚，侵入角膜>2mm，或影响视力、眼球运动，或影响美观）：手术治疗（翼状胬肉切除术，联合角膜缘干细胞移植、羊膜移植、自体结膜移植，降低复发率），术后用抗生素+激素+非甾体抗炎滴眼液，逐渐减量，随访6-12个月","侵入瞳孔区影响视力：尽早手术，避免角膜瘢痕影响视力","术后复发：再次手术（联合角膜缘干细胞移植、羊膜移植、抗代谢药物丝裂霉素C），必要时角膜移植","合并睑球粘连影响眼球运动：手术分离粘连+黏膜移植/羊膜移植","预防：户外工作者戴防紫外线眼镜、防风沙眼镜，避免长时间日晒和风沙刺激，积极治疗慢性结膜炎，注意眼部卫生","定期随访：术后定期复查（1周、2周、1月、3月、6月、12月），观察伤口愈合、有无复发、角膜情况、眼压，及时处理"],"management":["术前护理：完善术前检查（视力、验光、裂隙灯、角膜地形图、角膜厚度、角膜内皮、泪液、血常规、凝血、传染病）；控制全身疾病（糖尿病、高血压）；术前3天抗生素滴眼液（每日4-6次）；术前冲洗泪道、结膜囊；解释手术过程和注意事项，消除焦虑","术后护理：术后当日眼垫包扎，次日打开；术后抗生素滴眼液（每日4-6次）+糖皮质激素滴眼液（每日4次，逐渐减量，持续1-3个月）+非甾体抗炎滴眼液（每日4次）+人工泪液；术后1周内避免揉眼、伤口沾水、剧烈运动；术后1周拆线（如有缝线）；观察伤口愈合、角膜上皮修复、有无感染和复发","用药护理：按医嘱使用多种眼药水，每种间隔5-10分钟；糖皮质激素滴眼液不可自行停药或长期使用（注意眼压、白内障、感染），按医嘱逐渐减量；丝裂霉素C使用后注意角膜毒性（角膜上皮缺损、混浊）；观察药物疗效和副作用","病情观察：观察胬肉大小、充血、侵入角膜范围变化；术后观察伤口愈合、角膜上皮修复、有无感染（眼红、眼痛、分泌物增多、视力下降）、有无复发（角膜缘新生血管和增生组织）；观察视力、眼压变化；出现异常及时就医","饮食：清淡易消化饮食，多饮水，多吃富含维生素A、C、B2的食物（胡萝卜、动物肝脏、蛋黄、新鲜蔬果）；避免辛辣刺激、油腻、烟酒、海鲜等发物（术后）","休息与活动：保证充足睡眠，避免熬夜和过度用眼；术后1周内避免剧烈运动、游泳、揉眼；避免烟尘、风沙、强光环境；户外戴防紫外线眼镜、防风沙眼镜","个人卫生：勤洗手，不用脏手揉眼；毛巾脸盆个人专用，定期消毒；术后伤口避免沾水；避免与他人共用化妆品","心理护理：安慰患者，解释疾病性质和手术方法，告知术后复发可能及预防措施，消除焦虑；术后不适（异物感、流泪、轻度疼痛）属正常，严重不适及时就医","健康教育：讲解翼状胬肉的病因（紫外线、风沙、干燥刺激）和预防方法（户外戴防护眼镜）；告知手术指征和术后注意事项；强调术后定期复查的重要性（复发多发生在术后6-12个月）；指导正确滴眼药方法；出现眼红、眼痛、视力下降、增生组织复发及时就医","预防复发：术后规范使用激素和非甾体抗炎滴眼液（逐渐减量，持续1-3个月）；避免刺激（紫外线、风沙）；积极治疗慢性结膜炎；定期复查；复发高危者（年轻、复发型、胬肉较大）联合角膜缘干细胞移植、羊膜移植、抗代谢药物"],"notes":["翼状胬肉是睑裂部球结膜及结膜下组织增生肥厚，呈三角形向角膜侵入，形似翼状，是常见的眼表疾病，患病率随年龄增长而增加，户外工作者多见","病因：紫外线照射（最主要，户外工作者、赤道地区居民多见）、风沙粉尘刺激、干燥气候、慢性结膜炎、泪液异常、遗传因素、免疫因素、HPV感染可能有关","好发部位：多发生于鼻侧睑裂部（占70-80%），也可颞侧或双侧，双眼可同时或先后发病","临床分期：静止期（胬肉薄、不充血、头部平坦，生长缓慢或不生长）、进行期（胬肉肥厚、充血、头部隆起，前端角膜灰色浸润，生长较快）","与睑裂斑区别：睑裂斑位于睑裂部球结膜，黄白色斑块，不侵入角膜，无需手术；翼状胬肉侵入角膜，呈三角形，可影响视力，需手术","与假性胬肉区别：假性胬肉是角膜溃疡、烧伤、化学伤、外伤后结膜与角膜粘连形成，无进行性，可发生于任何部位，有外伤史，探针可通过胬肉下；真性翼状胬肉有进行性，多发生于鼻侧睑裂部，探针不能通过","手术指征：进行期胬肉侵入角膜>2mm；胬肉侵入瞳孔区影响视力；胬肉引起明显散光影响视力；胬肉影响眼球运动或睑球粘连；胬肉反复炎症不适；影响美观（患者要求）","手术方式：单纯切除术（复发率高，30-50%，现已少用）、切除+自体结膜移植（复发率低，5-10%，常用）、切除+角膜缘干细胞移植（复发率最低，<5%，适用于复发型和巨大胬肉）、切除+羊膜移植（适用于睑球粘连、角膜缘干细胞缺乏）、切除+抗代谢药物（丝裂霉素C术中或术后使用，降低复发，注意角膜毒性）","术后复发：复发率与手术方式、胬肉大小、是否复发型、年龄有关；单纯切除复发率高，联合移植复发率低；复发多发生在术后6-12个月；复发型胬肉生长更快、更肥厚、更易睑球粘连，治疗更困难","丝裂霉素C使用：术中用0.02%丝裂霉素C棉片敷于巩膜面3-5分钟，然后用大量生理盐水冲洗；术后可用0.02%丝裂霉素C滴眼液每日2次×5天；注意角膜毒性（角膜上皮缺损、角膜混浊、角膜穿孔）、巩膜坏死、白内障、青光眼，需由有经验医生使用","角膜缘干细胞移植：取自体健眼角膜缘干细胞组织，移植于胬肉切除后的角膜缘缺损区，可重建角膜缘屏障，防止复发，是目前复发率最低的术式","术后用药：抗生素滴眼液（1-2周）+糖皮质激素滴眼液（逐渐减量，持续1-3个月，抗增殖抗炎）+非甾体抗炎滴眼液（2-4周，抗炎止痛）+人工泪液（术后干眼）；定期复查眼压（激素可致高眼压）","预后：小而静止期预后良好，不影响视力；进行期及时手术预后好，可恢复视力；晚期侵入瞳孔区或术后复发可遗留角膜瘢痕影响视力；严重睑球粘连可影响眼球运动","预防：户外工作者戴防紫外线眼镜、防风沙眼镜；避免长时间日晒和风沙刺激；积极治疗慢性结膜炎；注意眼部卫生；出现胬肉及时就医，定期复查"],"emergency":["出现胬肉迅速增大、充血明显、头部隆起（进行期，及时就医评估手术）","出现视力下降、散光加重、胬肉侵入瞳孔区（尽快手术，避免角膜瘢痕影响视力）","术后出现眼痛剧烈、畏光、视力骤降、分泌物增多（术后感染或角膜溃疡，立即就医）","术后出现伤口裂开、出血、植片脱落（立即就医）","出现眼球运动受限、复视、睑球粘连（并发症，及时就医手术）","出现角膜上皮缺损长期不愈合、角膜混浊（丝裂霉素C毒性或角膜病变，及时就医）","术后复发且生长迅速（再次手术评估，联合干细胞移植）"],"pinyin":"yizhuangnurou","icd10":"H11.0","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态","视力检查：远视力（标准对数视力表）、近视力、矫正视力、裸眼视力","眼压检查：指测法（Tn/T+1/T+2/T+3）或眼压计（正常10-21mmHg）","眼睑：红肿/下垂/内翻/外翻/倒睫/肿块/瘢痕/闭合不全","泪器：泪点位置/泪道冲洗/泪囊区红肿压痛/溢泪","结膜：球结膜（充血/水肿/出血/滤泡/乳头）、睑结膜（充血/滤泡/乳头/瘢痕/结石）、穹窿部","角膜：透明度/上皮缺损（荧光素染色）/浸润/溃疡/瘢痕/新生血管/异物/曲率（K1/K2）","巩膜：黄染/充血/结节/葡萄肿","前房：深度（浅/中/深）、房水闪辉（Tyndall征）、房水细胞、积脓/积血","虹膜：颜色/纹理/粘连（前粘连/后粘连）/结节/萎缩/根部离断","瞳孔：大小/形状/位置/对光反射（直接/间接）/调节反射","晶状体：透明度（皮质/核/后囊下混浊）、位置（脱位/半脱位）、人工晶体","玻璃体：混浊/积血/增殖膜/脱离","眼底：视盘（边界/颜色/C/D比/水肿/萎缩）、视网膜（出血/渗出/水肿/脱离/色素紊乱）、黄斑（中心凹反光/水肿/裂孔/变性）、血管（管径/比例/交叉压迹/新生血管）","眼肌：眼球运动（各方向）、斜视（内斜/外斜/垂直斜）、复视、眼球震颤","视野：手动/自动视野计检查（青光眼/视神经病变）","色觉：色盲本检查"],"lab_tests":["视力检查（裸眼及矫正视力）：初诊及术前必查，评估胬肉对角膜牵引所致散光对视力的影响，术后复查对比","裂隙灯显微镜检查：核心检查，观察胬肉头部是否越过角膜缘及侵入角膜深度、体部充血及炎症活动度，评估手术时机","眼压测量：排除胬肉或药物所致继发性青光眼，作为术前基线","角膜地形图：术前术后各查一次，量化胬肉牵拉引起的角膜散光及不规则度，评估手术疗效","散瞳眼底检查：排除合并眼底病变，尤其中老年患者，保证术后视力评估的准确性","泪膜功能检查（泪膜破裂时间BUT、泪液分泌试验）：术前评估干眼及泪膜状况，胬肉术后干眼风险高，便于术后随访"],"nursing":["病情观察：观察胬肉头部是否进行性越过角膜缘、体部有无充血增厚，询问有无眼红、异物感、畏光加重，进展快或炎症明显者及时通知医师","眼部护理：嘱勿揉眼、勿用力挤眼，避免风沙、烟尘、强光刺激，外出佩戴防紫外线墨镜；滴眼药前洗净双手，瓶口勿触及睫毛及眼表","用药观察：遵医嘱按时滴用抗生素及糖皮质激素眼药，观察有无眼痛加剧、分泌物增多、视力骤降等感染或激素不良反应征象","术后护理：术后包扎患眼，勿自行揭开；嘱避免用力咳嗽、打喷嚏、低头及提重物，防止植片移位或出血；观察敷料有无渗血渗液、缝线有无松脱","防跌倒：术后单眼包扎或遮盖致双眼视差、视物模糊，嘱卧床休息、下床活动放缓，夜间如厕由家属搀扶，床栏拉起"],"diet":["忌辛辣刺激食物及烟酒，减少眼表充血及术后炎症反应","多食富含维生素A食物（动物肝脏、蛋黄、胡萝卜、南瓜、菠菜），促进角膜上皮修复","多食富含维生素C食物（猕猴桃、柑橘、青椒、西兰花），促进创面愈合、减少瘢痕形成","术后早期进软食，食物宜温凉，避免过硬、过烫食物及长时间用力咀嚼牵拉眼部","多饮水、适当增加膳食纤维，保持大便通畅，避免用力排便导致术后眼压升高及创口出血"],"topical_medication":["普拉洛芬滴眼液 1滴 滴眼 qid；玻璃酸钠滴眼液 1滴 滴眼 qid"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":390},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"4cb7aaf483a7f3691dcbea66418cc30d1ae29d68a446fa542b97079909d79990","pinyin":"yizhuangnurou","initials":"yznr","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","小而静止期：无明显症状，或仅有轻微异物感、干涩感，睑裂部球结膜三角形增厚，尖端指向角膜，基底位于眦部\\n进行期：胬肉充血、肥厚、增生，向角膜中央方向生长，异物感、干涩感加重，可伴眼红、流泪\\n侵入瞳孔区：影响视力（散光、遮挡瞳孔），严重者视力明显下降\\n较大或术后复发：可影响眼球运动（限制眼球转动，复视），睑球粘连\\n多发生于鼻侧（占多数），也可颞侧或双侧，双眼可同时或先后发病\\n户外工作者、农民、渔民、长期日晒风沙者多见\\n一般无疼痛，合并炎症时可有眼红、疼痛",60],["摘要","睑裂部球结膜及结膜下组织增生肥厚，呈三角形向角膜侵入，形似翼状，多发生于鼻侧，与紫外线照射、风沙、干燥等刺激有关，可影响视力和眼球运动。",30],["疾病编码","H11.0",30],["原首字母","yizhuangnurou",60]]},{"id":"orders-a3a26d34ed859aa5e1b0","key":"v1-c9ccc21dfe2a3058|orders-a3a26d34ed859aa5e1b0","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"视网膜脱离","category":"眼科","raw":{"name":"视网膜脱离","category":"眼科","summary":"视网膜神经上皮层与色素上皮层分离，分为孔源性、牵拉性和渗出性，表现为眼前闪光感、黑影飘动、视野缺损、视力下降，是致盲性眼病，需及时手术治疗。","symptoms":["前驱症状：眼前闪光感（玻璃体牵拉视网膜，闪光感多在颞侧视野，眼球运动时明显）、黑影飘动（玻璃体混浊、出血，突然增多或变大）、飞蚊症突然加重","视野缺损：与视网膜脱离范围对应的视野出现幕状黑影遮挡，多从周边开始，逐渐向中心扩展，上方脱离可致下方视野缺损","视力下降：黄斑受累时视力明显下降，视物变形，中心视力丧失；脱离范围大或时间长者视力严重下降甚至光感","眼压：脱离眼眼压多偏低（视网膜脱离致房水生成减少）","眼底检查：玻璃体混浊、色素颗粒（烟灰样）、视网膜脱离区呈青灰色或灰白色隆起，起伏不平，血管爬行其上，可找到视网膜裂孔（红色裂孔，多位于周边部，上方颞侧多见）","牵拉性视网膜脱离：有糖尿病视网膜病变、视网膜静脉阻塞、眼外伤等病史，玻璃体视网膜增殖牵拉，视网膜呈漏斗状脱离，可无裂孔","渗出性视网膜脱离：有葡萄膜炎、葡萄膜渗漏综合征、肿瘤、高血压等病史，视网膜脱离随体位变化（下方脱离，平卧后减轻），无视网膜裂孔","并发症：增殖性玻璃体视网膜病变（PVR，视网膜表面和玻璃体增殖膜形成，视网膜僵硬、固定皱褶、漏斗状脱离，手术难度大）、白内障、青光眼、眼球萎缩（长期脱离）"],"diagnosis":["典型症状（闪光感、黑影飘动、视野缺损、视力下降）+眼底检查（视网膜青灰色隆起、裂孔）可确诊","散瞳眼底检查（直接检眼镜、间接检眼镜，详细检查视网膜全周，寻找裂孔，评估脱离范围和PVR分级）","眼部B超（屈光间质混浊时，如白内障、玻璃体积血，可显示视网膜脱离光带，评估脱离范围和玻璃体增殖情况）","OCT（黄斑区视网膜脱离、黄斑裂孔、黄斑前膜，评估黄斑受累情况）","眼底照相（记录脱离范围和裂孔位置）","视野检查（评估视野缺损范围）","眼压测量（脱离眼多偏低）","排除视网膜劈裂、脉络膜脱离、玻璃体后脱离、中心性浆液性脉络膜视网膜病变","分型诊断：孔源性（有裂孔，最常见）、牵拉性（有玻璃体视网膜增殖牵拉，无裂孔或有继发性裂孔）、渗出性（有原发病，视网膜脱离随体位变化，无裂孔）","术前检查：角膜内皮计数、泪液分泌试验、血常规、凝血功能、传染病筛查、心电图、胸部X线（全麻手术）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1：","  用法：术前一般无需静脉输液；术后 0.9%NS 250ml + 头孢呋辛 1.5g 静滴 q12h（预防感染，24小时内停用）","","方案2（术后）：","  用法：0.9%NS 250ml + 止血敏2g + 氨甲环酸0.5g ivgtt qd（止血，术后1-3天）、0.9%NS 100ml + 抗生素 ivgtt qd（预防感染，术后1-3天）、0.9%NS 250ml + 维生素C 2g ivgtt qd（促进恢复）〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","","方案3（合并葡萄膜炎或术后炎症反应重）：","  用法：0.9%NS 100ml + 地塞米松10mg ivgtt qd（逐渐减量）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案4（恶心呕吐；术后眼压高或体位不适）：","  用法：甲氧氯普胺10mg im prn〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","","方案5（疼痛明显）：","  用法：布桂嗪100mg im prn 或 哌替啶50-100mg im prn（剧烈疼痛）","","方案6：","  用法：全麻手术按麻醉方案补液","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（术前）：","用法：抗生素滴眼液（左氧氟沙星滴眼液、妥布霉素滴眼液，每日4-6次，术前3天）、散瞳剂（复方托吡卡胺滴眼液，术前散瞳检查）、降眼压药（眼压高时，乙酰唑胺0.25g tid、噻吗洛尔滴眼液bid）〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物2（术后）：","用法：抗生素（头孢氨苄0.5g qid、阿莫西林0.5g tid，预防感染，3-5天）、止血药（安络血5mg tid、止血敏0.5g tid，3-5天）、维生素（维生素C 0.2g tid、维生素B1 10mg tid、维生素B12 500μg qd，促进神经恢复）、非甾体抗炎药（布洛芬0.2g tid，止痛抗炎）","药物3（局部用药）：","用法：抗生素滴眼液（左氧氟沙星滴眼液、妥布霉素滴眼液，每日4-6次，术后2-4周）、糖皮质激素滴眼液（氟米龙0.1%、泼尼松龙0.5%、地塞米松滴眼液，每日4-6次，逐渐减量，持续1-3个月，抗炎）、散瞳剂（复方托吡卡胺滴眼液、阿托品眼膏，活动瞳孔，防止虹膜后粘连，术后1-2周）、非甾体抗炎滴眼液（普拉洛芬滴眼液、双氯芬酸钠滴眼液，每日4次，抗炎止痛）","药物4（眼压高）：","用法：降眼压药（乙酰唑胺0.25g tid、噻吗洛尔滴眼液bid、布林佐胺滴眼液tid，必要时前房穿刺放液）","药物5（合并葡萄膜炎）：","用法：糖皮质激素全身+局部，散瞳，免疫抑制剂（顽固病例）","药物6（中医中药）：","用法：术后调理（益气养血、活血化瘀、滋补肝肾），明目地黄丸、石斛夜光丸（恢复期）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["紧急处理：一旦怀疑视网膜脱离，立即散瞳检查，确诊后尽快手术（孔源性视网膜脱离手术时机：黄斑未脱离者24-72小时内手术，黄斑已脱离者尽早手术，脱离时间越长视力恢复越差）；术前避免剧烈活动，卧床休息，包扎双眼，防止脱离范围扩大","孔源性视网膜脱离手术：根据脱离范围、裂孔位置和大小、PVR分级选择术式——巩膜扣带术（巩膜外加压+环扎+冷凝/光凝封闭裂孔，适用于简单病例、单个裂孔、PVR A-B级）、玻璃体切割术（切除玻璃体，解除牵拉，眼内激光封闭裂孔，气体或硅油填充，适用于复杂病例、多发裂孔、巨大裂孔、PVR C-D级、玻璃体增殖明显、合并玻璃体积血、黄斑裂孔）、气体填充（C3F8、SF6，术后保持特定体位，使气体顶压裂孔）、硅油填充（复杂病例、PVR严重、硅油依赖眼，术后3-6个月取硅油）","牵拉性视网膜脱离：玻璃体切割术，解除玻璃体视网膜牵拉，封闭裂孔，气体或硅油填充，治疗原发病（糖尿病视网膜病变全视网膜光凝）","渗出性视网膜脱离：治疗原发病（葡萄膜炎用激素+免疫抑制剂、肿瘤手术/放疗、高血压控制血压、葡萄膜渗漏综合征手术），一般不需视网膜手术，原发病控制后视网膜脱离可自行复位","术前准备：散瞳检查明确裂孔和脱离范围；抗生素滴眼液清洁结膜囊；控制全身疾病（糖尿病、高血压）；完善术前检查；解释手术过程和术后体位要求","术后处理：抗生素+激素+散瞳滴眼液；保持特定体位（气体填充者面向下体位，使气体顶压裂孔，每日12-16小时，持续1-2周；硅油填充者也需面向下体位）；观察视力、眼压、眼底；避免剧烈活动、揉眼、外伤；定期复查（1周、2周、1月、3月、6月、12月）","并发症处理：术后高眼压（降眼压药、前房穿刺）、术后感染（玻璃体腔注射抗生素、玻璃体切割）、白内障（激素引起或术后加重，白内障手术）、复发性脱离（再次手术）、硅油乳化（取硅油）、眼球萎缩（长期脱离，预后差）","预防：高度近视者避免剧烈运动、重体力劳动、外伤；定期眼底检查，发现视网膜变性、干孔及时激光封闭；眼外伤及时就医；糖尿病患者控制血糖，定期眼底检查，及时激光治疗","随访：术后定期复查眼底，观察视网膜复位情况、有无复发、裂孔封闭情况、眼压、视力、白内障进展；气体吸收前避免坐飞机（气压变化致气体膨胀）；硅油填充者3-6个月取硅油；长期随访防止复发"],"management":["术前护理：绝对卧床休息，包扎双眼，减少眼球活动，防止脱离范围扩大；避免剧烈咳嗽、打喷嚏、用力排便；完善术前检查（视力、眼压、散瞳眼底、B超、OCT、角膜内皮、泪液、血常规、凝血、传染病、心电图、胸片）；术前3天抗生素滴眼液（每日4-6次）；术前冲洗泪道、结膜囊；解释手术过程、术后体位要求和注意事项，消除焦虑","术后护理：术后按医嘱保持特定体位（气体/硅油填充者面向下体位，每日12-16小时，持续1-2周，可在床上或椅子上保持头低位，定时变换姿势避免压疮）；术后当日眼垫包扎，次日打开；术后抗生素+激素+散瞳滴眼液（每种间隔5-10分钟）；术后1周内避免揉眼、伤口沾水、剧烈运动、咳嗽、打喷嚏、用力排便；观察视力、眼压、眼痛、头痛、恶心呕吐（高眼压表现），出现异常及时告知医生","体位护理：气体填充者面向下体位使气体顶压裂孔，促进复位；告知患者体位的重要性，不可随意改变；定时协助变换姿势，防止压疮、颈部肌肉疲劳；可使用面向枕、U型枕辅助；气体未吸收前避免坐飞机、潜水（气压变化致气体膨胀，眼压骤升）","用药护理：按医嘱使用多种眼药水，每种间隔5-10分钟；糖皮质激素滴眼液逐渐减量，不可自行停药或长期使用（注意眼压、白内障、感染）；散瞳剂使用后可有畏光、视近模糊，属正常；口服药按时按量；观察药物疗效和副作用","病情观察：观察视力变化（术后视力恢复需要时间，黄斑脱离者视力恢复较差）；观察眼压（术后可出现一过性高眼压，表现为眼痛、头痛、恶心呕吐，及时降眼压）；观察眼痛、分泌物（感染征象）；观察眼底复位情况（定期散瞳检查）；观察有无复发性脱离（闪光感、黑影飘动、视野缺损再次出现）；出现异常及时就医","饮食：清淡易消化饮食，多饮水，多吃富含维生素A、C、B1、B12的食物（胡萝卜、动物肝脏、蛋黄、新鲜蔬果、粗粮、瘦肉）；避免辛辣刺激、油腻、烟酒；保持大便通畅，避免用力排便（多吃膳食纤维，必要时用缓泻剂）","休息与活动：术后保证充足睡眠；术后1周内避免剧烈运动、重体力劳动、跑步、跳跃、游泳；术后1-3个月避免剧烈活动和重体力劳动；避免揉眼、眼部外伤；避免长时间低头、弯腰；气体未吸收前避免坐飞机、潜水；恢复后可正常活动，但高度近视者仍需避免剧烈运动和外伤","个人卫生：勤洗手，不用脏手揉眼；毛巾脸盆个人专用，定期消毒；术后伤口避免沾水（1周内避免洗头洗脸水入眼，可擦脸）；避免与他人共用化妆品；术后1个月内避免眼部化妆","心理护理：安慰患者，解释疾病严重性和手术必要性，告知术后视力恢复需要时间（黄斑脱离者视力恢复可能不理想），消除焦虑恐惧；术后不适（眼痛、异物感、体位不适）给予关心和指导；鼓励患者积极配合治疗和体位要求；告知定期复查的重要性，防止复发","健康教育：讲解视网膜脱离的病因、症状和危害，强调及时就医的重要性（闪光感、黑影飘动突然加重、视野缺损立即就医）；高度近视者避免剧烈运动、重体力劳动、外伤，定期眼底检查；糖尿病患者控制血糖，定期眼底检查，及时激光治疗；术后按医嘱保持体位、用药、复查；气体未吸收前避免坐飞机；出现视力下降、眼痛、闪光感、黑影飘动再次出现及时就医；术后3-6个月取硅油（硅油填充者）；长期随访防止复发","家庭护理：家属协助患者保持体位，观察病情变化，提醒用药和复查；患者起床、活动时有人陪同，防止跌倒（面向下体位后突然起身可头晕）；帮助患者清洁面部（避免水入眼）；给予心理支持"],"notes":["视网膜脱离是视网膜神经上皮层与色素上皮层分离，是常见的致盲性眼病，患病率约1/10000，高度近视者、老年人、眼外伤者、糖尿病患者多见","分型：孔源性视网膜脱离（最常见，占90%，视网膜裂孔形成，玻璃体液体进入视网膜下，多见于高度近视、老年人、眼外伤、白内障术后）、牵拉性视网膜脱离（玻璃体视网膜增殖膜牵拉视网膜，多见于糖尿病视网膜病变、视网膜静脉阻塞、眼外伤、早产儿视网膜病变，可无裂孔或有继发性裂孔）、渗出性视网膜脱离（视网膜毛细血管或色素上皮屏障破坏，液体渗出积聚于视网膜下，多见于葡萄膜炎、葡萄膜渗漏综合征、脉络膜肿瘤、高血压、妊娠高血压综合征、Coats病，视网膜脱离随体位变化，无裂孔）","高危因素：高度近视（>-6D，眼轴延长，视网膜变性变薄，易形成裂孔）、老年人（玻璃体后脱离牵拉视网膜）、眼外伤（钝挫伤、穿通伤）、白内障术后（无晶状体眼、玻璃体牵拉）、糖尿病视网膜病变（增殖期）、视网膜静脉阻塞、家族史、对侧眼视网膜脱离史、早产儿视网膜病变","前驱症状：闪光感（玻璃体牵拉视网膜，刺激视细胞，多在颞侧视野，眼球运动时明显，是视网膜脱离的重要预警症状）、飞蚊症突然加重（玻璃体后脱离、玻璃体积血、视网膜色素颗粒进入玻璃体）、眼前黑影飘动（玻璃体混浊、出血）","视野缺损：与视网膜脱离范围对应的视野出现幕状黑影遮挡，多从周边开始，逐渐向中心扩展；上方视网膜脱离致下方视野缺损，下方脱离致上方视野缺损，颞侧脱离致鼻侧视野缺损","视力下降：黄斑未脱离时视力可正常或轻度下降；黄斑受累时视力明显下降，视物变形，中心视力丧失；脱离范围大或时间长者视力严重下降甚至仅存光感","眼底表现：玻璃体混浊、色素颗粒（烟灰样，是孔源性视网膜脱离的特征）；视网膜脱离区呈青灰色或灰白色隆起，起伏不平，血管爬行其上，随眼球运动而飘动；可找到视网膜裂孔（红色裂孔，多位于周边部，上方颞侧多见，马蹄形裂孔常见）；眼压多偏低","PVR分级：增殖性玻璃体视网膜病变是孔源性视网膜脱离的严重并发症，也是手术失败的主要原因，分为A-B-C-D四级（A级：玻璃体混浊和色素颗粒；B级：视网膜内表面皱褶、裂孔卷边、视网膜僵硬；C级：全层视网膜固定皱褶，分C1-C3（1-3个象限）；D级：四个象限固定皱褶，视网膜呈漏斗状脱离，分D1-D3（宽漏斗、窄漏斗、闭合漏斗））","手术时机：孔源性视网膜脱离是眼科急症，黄斑未脱离者应在24-72小时内手术，黄斑已脱离者尽早手术（脱离时间越长，黄斑功能恢复越差，脱离超过1个月视力恢复明显下降）；术前卧床休息，包扎双眼，防止脱离范围扩大","手术方式选择：简单病例（单个裂孔、上方脱离、PVR A-B级、无明显玻璃体增殖）首选巩膜扣带术（巩膜外加压+环扎+冷凝/光凝）；复杂病例（多发裂孔、巨大裂孔、下方脱离、PVR C-D级、玻璃体增殖明显、合并玻璃体积血、黄斑裂孔、无晶状体眼）首选玻璃体切割术+气体/硅油填充","气体填充：常用C3F8（全氟丙烷，吸收时间约6-8周）、SF6（六氟化硫，吸收时间约2-3周）、空气（吸收时间约5-7天）；术后保持面向下体位，使气体顶压裂孔，促进复位；气体未吸收前避免坐飞机、潜水（气压变化致气体膨胀，眼压骤升，可致视网膜中央动脉阻塞）","硅油填充：适用于复杂病例、PVR严重、巨大裂孔、硅油依赖眼；硅油不吸收，术后3-6个月需再次手术取硅油；硅油并发症：硅油乳化、高眼压、白内障、角膜病变、硅油进入前房","术后视力恢复：黄斑未脱离者视力恢复好；黄斑已脱离者视力恢复取决于脱离时间（脱离越短恢复越好）、脱离高度、PVR程度、手术时机；脱离超过1个月黄斑功能恢复较差；部分患者术后视物变形可持续数月","预后：简单病例手术成功率90-95%，视力恢复好；复杂病例（PVR C-D级、巨大裂孔、复发性脱离）手术成功率60-80%，视力恢复较差；长期脱离、PVR D级、眼球萎缩者预后差，可致失明","预防：高度近视者避免剧烈运动、重体力劳动、眼部外伤，定期（每年）散瞳眼底检查，发现视网膜变性、干性裂孔及时激光封闭；眼外伤及时就医；糖尿病患者控制血糖，定期眼底检查，增殖期及时全视网膜光凝；白内障术后定期眼底检查；一眼视网膜脱离者，对侧眼定期检查，发现裂孔及时激光","复发：视网膜脱离术后复发率5-10%，多发生在术后6-12个月；复发原因：新裂孔形成、原裂孔未封闭、PVR进展、牵拉未解除；复发后需再次手术；定期复查可早期发现复发"],"emergency":["出现眼前闪光感突然加重、黑影飘动明显增多、视野出现幕状黑影（视网膜脱离可能，立即散瞳眼底检查，确诊后尽快手术）","出现视力骤降、视物变形、中心视野缺损（黄斑脱离，尽快手术，越早视力恢复越好）","术后出现眼痛剧烈、头痛、恶心呕吐、视力骤降（术后高眼压或感染，立即就医降眼压/抗感染）","术后出现伤口裂开、大量出血、眼内容物脱出（立即就医）","出现光感消失、眼球变软（视网膜全脱离或眼球萎缩，立即就医）","硅油填充眼出现视力突然下降、眼痛（硅油乳化移位、高眼压，及时就医）","高度近视者剧烈运动/外伤后出现闪光感、黑影飘动、视野缺损（立即就医，排除视网膜脱离）"],"pinyin":"shiwangmotuoli","icd10":"H33.0","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态","视力检查：远视力（标准对数视力表）、近视力、矫正视力、裸眼视力","眼压检查：指测法（Tn/T+1/T+2/T+3）或眼压计（正常10-21mmHg）","眼睑：红肿/下垂/内翻/外翻/倒睫/肿块/瘢痕/闭合不全","泪器：泪点位置/泪道冲洗/泪囊区红肿压痛/溢泪","结膜：球结膜（充血/水肿/出血/滤泡/乳头）、睑结膜（充血/滤泡/乳头/瘢痕/结石）、穹窿部","角膜：透明度/上皮缺损（荧光素染色）/浸润/溃疡/瘢痕/新生血管/异物/曲率（K1/K2）","巩膜：黄染/充血/结节/葡萄肿","前房：深度（浅/中/深）、房水闪辉（Tyndall征）、房水细胞、积脓/积血","虹膜：颜色/纹理/粘连（前粘连/后粘连）/结节/萎缩/根部离断","瞳孔：大小/形状/位置/对光反射（直接/间接）/调节反射","晶状体：透明度（皮质/核/后囊下混浊）、位置（脱位/半脱位）、人工晶体","玻璃体：混浊/积血/增殖膜/脱离","眼底：视盘（边界/颜色/C/D比/水肿/萎缩）、视网膜（出血/渗出/水肿/脱离/色素紊乱）、黄斑（中心凹反光/水肿/裂孔/变性）、血管（管径/比例/交叉压迹/新生血管）","眼肌：眼球运动（各方向）、斜视（内斜/外斜/垂直斜）、复视、眼球震颤","视野：手动/自动视野计检查（青光眼/视神经病变）","色觉：色盲本检查"],"lab_tests":["视力检查（最佳矫正视力）：入院时及术后每日复查，动态评估视力变化趋势。","裂隙灯联合三面镜（或前置镜）眼底检查：明确视网膜脱离范围、裂孔位置与数目，术前定位及术后复查的关键检查。","眼压测量：术前常规并术后每日监测，气体或硅油填充后易发生高眼压，需重点观察。","眼部B超检查：屈光间质混浊（如白内障、玻璃体积血）无法看清眼底时进行，明确脱离范围及有无增殖性玻璃体视网膜病变。","光学相干断层扫描（OCT）：评估黄斑区是否受累及有无囊样水肿，协助判断手术时机。","视野检查：评估视野缺损范围；疑似渗出性脱离时加做眼底血管荧光造影（FFA）以鉴别。"],"nursing":["病情观察：密切观察眼前黑影、闪光感及视野缺损变化，黑影突然扩大或视力骤降时立即报告医生。","体位护理：气体或硅油填充者术后严格遵医嘱保持俯卧（或侧卧）位，日间、夜间持续至医生指示改变体位，避免仰卧使气泡接触晶状体诱发白内障。","眼部护理：保持术眼敷料清洁干燥，勿揉眼、勿用力挤眼，遵医嘱按时滴用抗生素、激素及散瞳眼药水。","用药观察：滴药后观察有无眼胀、眼痛、恶心呕吐等高眼压表现，出现时立即报告并测眼压。","防跌倒：视力差或双眼遮盖者卧床时拉起床栏，下床活动需他人搀扶，夜间留灯照明。"],"diet":["忌辛辣刺激食物及烟酒，避免诱发咳嗽、喷嚏、用力导致眼压波动。","多食富含维生素A、C的食物：胡萝卜、南瓜、菠菜等深绿叶蔬菜、柑橘、猕猴桃，促进视网膜修复。","术后予清淡易消化软食，避免过硬食物过度咀嚼牵动头面部。","适量补充优质蛋白（鱼、蛋、瘦肉、豆制品），利于创口愈合。","多饮水、多食粗纤维（香蕉、燕麦、新鲜蔬菜）保持大便通畅，避免排便用力。"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":391},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"1f3c07e46eae6c2cef977abbbc585e98e53b870ed5cb492cfbc10eca1e1f2c55","pinyin":"shiwangmotuoli","initials":"swmtl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","前驱症状：眼前闪光感（玻璃体牵拉视网膜，闪光感多在颞侧视野，眼球运动时明显）、黑影飘动（玻璃体混浊、出血，突然增多或变大）、飞蚊症突然加重\\n视野缺损：与视网膜脱离范围对应的视野出现幕状黑影遮挡，多从周边开始，逐渐向中心扩展，上方脱离可致下方视野缺损\\n视力下降：黄斑受累时视力明显下降，视物变形，中心视力丧失；脱离范围大或时间长者视力严重下降甚至光感\\n眼压：脱离眼眼压多偏低（视网膜脱离致房水生成减少）\\n眼底检查：玻璃体混浊、色素颗粒（烟灰样）、视网膜脱离区呈青灰色或灰白色隆起，起伏不平，血管爬行其上，可找到视网膜裂孔（红色裂孔，多位于周边部，上方颞侧多见）\\n牵拉性视网膜脱离：有糖尿病视网膜病变、视网膜静脉阻塞、眼外伤等病史，玻璃体视网膜增殖牵拉，视网膜呈漏斗状脱离，可无裂孔\\n渗出性视网膜脱离：有葡萄膜炎、葡萄膜渗漏综合征、肿瘤、高血压等病史，视网膜脱离随体位变化（下方脱离，平卧后减轻），无视网膜裂孔\\n并发症：增殖性玻璃体视网膜病变（PVR，视网膜表面和玻璃体增殖膜形成，视网膜僵硬、固定皱褶、漏斗状脱离，手术难度大）、白内障、青光眼、眼球萎缩（长期脱离）",60],["摘要","视网膜神经上皮层与色素上皮层分离，分为孔源性、牵拉性和渗出性，表现为眼前闪光感、黑影飘动、视野缺损、视力下降，是致盲性眼病，需及时手术治疗。",30],["疾病编码","H33.0",30],["原首字母","shiwangmotuoli",60]]},{"id":"orders-b9adb1bf7dcc139d7655","key":"v1-c9ccc21dfe2a3058|orders-b9adb1bf7dcc139d7655","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"年龄相关性黄斑变性","category":"眼科","raw":{"name":"年龄相关性黄斑变性","category":"眼科","summary":"又称老年性黄斑变性，是与年龄相关的黄斑区视网膜退行性病变，分为干性（萎缩型）和湿性（渗出型/新生血管型），是老年人致盲的主要原因之一，表现为视力下降、视物变形、中心暗点。","symptoms":["干性AMD：早期无症状或仅有视物模糊、视力轻度下降，进展缓慢；晚期出现中心视力下降、视物变形、阅读困难、色觉异常，双眼可先后发病，中心暗点","湿性AMD：突然视力下降、视物变形（直线变弯曲）、中心暗点、色觉异常，进展快，可在数周内视力严重下降；眼底可见黄斑区出血、渗出、水肿、新生血管膜","眼底表现：干性——黄斑区玻璃膜疣（黄白色小点，硬性/软性）、色素紊乱、地图样萎缩（RPE萎缩，脉络膜血管暴露）；湿性——黄斑区出血（暗红色）、渗出（黄白色）、水肿、视网膜下新生血管膜、盘状瘢痕","Amsler方格检查：视物变形、方格扭曲、中心暗点（阳性）","视力：中心视力下降，周边视力一般不受影响","可伴对比敏感度下降、色觉减退","晚期可致中心视力丧失（法定盲），但周边视力保留，患者仍可生活自理"],"diagnosis":["典型症状（老年人视力下降、视物变形、中心暗点）+眼底检查（黄斑区玻璃膜疣、出血、渗出、萎缩）","眼底检查（散瞳后直接/间接检眼镜，检查黄斑区玻璃膜疣、色素紊乱、出血、渗出、水肿、萎缩、新生血管膜）","Amsler方格表（自查视物变形，早期发现黄斑病变）","OCT（光学相干断层扫描，金标准，可显示黄斑区视网膜各层结构、玻璃膜疣、RPE改变、视网膜下积液、脉络膜新生血管、黄斑水肿、萎缩，是诊断和随访的重要手段）","眼底荧光血管造影（FFA，显示脉络膜新生血管、渗漏、出血遮蔽荧光，区分干性和湿性，指导治疗）","吲哚青绿血管造影（ICGA，显示脉络膜新生血管，尤其是隐匿性新生血管、息肉样脉络膜血管病变）","视野检查（中心暗点）","对比敏感度、色觉检查","排除中心性浆液性脉络膜视网膜病变、黄斑裂孔、黄斑前膜、糖尿病黄斑水肿、高血压视网膜病变、脉络膜肿瘤","分型诊断：干性（萎缩型，占80-90%，玻璃膜疣+RPE萎缩，无新生血管）、湿性（渗出型/新生血管型，占10-20%，脉络膜新生血管+出血渗出水肿，进展快，视力损害重）","分期：早期（玻璃膜疣，视力正常或轻度下降）、中期（大玻璃膜疣或地图样萎缩，视力下降）、晚期（地图样萎缩或新生血管膜，视力严重下降）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般无需静脉输液；雷珠单抗 0.5mg 玻璃体腔注射（每月1次）；或康柏西普 0.5mg 玻璃体腔注射","方案2（湿性AMD抗VEGF治疗）：","用法：玻璃体腔注射抗VEGF药物（雷珠单抗、康柏西普、阿柏西普、贝伐珠单抗），不是静脉输液","方案3：","用法：合并全身疾病（高血压、糖尿病）按内科方案治疗","方案4（出血较多或全身用药）：","用法：0.9%NS 250ml + 止血敏2g + 氨甲环酸0.5g ivgtt qd（辅助止血）〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","方案5（营养支持）：","用法：0.9%NS 250ml + 维生素C 2g ivgtt qd（辅助）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（干性AMD）：","用法：抗氧化维生素和矿物质（AREDS配方：维生素C 500mg、维生素E 400IU、β-胡萝卜素15mg、锌80mg、铜2mg，每日1次，可延缓中期AMD进展为晚期，吸烟者避免β-胡萝卜素）、叶黄素10mg qd、玉米黄质2mg qd、Omega-3脂肪酸1-2g qd、锌剂","药物2（湿性AMD）：","用法：抗VEGF玻璃体腔注射为一线治疗（见治疗）；口服药物辅助：止血药（安络血5mg tid、止血敏0.5g tid）、维生素（维生素C 0.2g tid、维生素E 0.1g qd、芦丁20mg tid）、碘制剂（卵磷脂络合碘1.5mg tid，促进出血渗出吸收）","药物3（中医中药）：","用法：滋补肝肾、活血化瘀（杞菊地黄丸、明目地黄丸、石斛夜光丸、复方血栓通胶囊），辨证使用","药物4（合并高血压、糖尿病）：","用法：控制血压血糖","药物5：","用法：戒烟（吸烟是AMD重要危险因素，戒烟可延缓进展）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["干性AMD：尚无特效治疗，以预防和延缓进展为主——抗氧化维生素和矿物质（AREDS配方）、叶黄素、玉米黄质、Omega-3脂肪酸；戒烟；控制血压、血脂；避免强光直射，戴防紫外线眼镜；定期随访（每6-12个月OCT和眼底检查）；Amsler方格自查（发现视物变形及时就医）；低视力辅助（放大镜、助视器）","湿性AMD：抗VEGF玻璃体腔注射为一线标准治疗——雷珠单抗0.5mg/0.05ml玻璃体腔注射，每月1次，连续3次负荷剂量，之后按需治疗（1+PRN）或每月治疗；康柏西普0.5mg/0.05ml玻璃体腔注射，每月1次连续3次，之后每3个月1次；阿柏西普2mg/0.05ml玻璃体腔注射，每月1次连续3次，之后每2个月1次；贝伐珠单抗1.25mg/0.05ml玻璃体腔注射（超说明书使用，便宜，效果类似）；治疗目的是消退新生血管、减少渗出出血、稳定视力，部分患者视力可提高","光动力疗法（PDT）：维替泊芬静脉注射+特定波长激光照射，适用于典型性脉络膜新生血管、息肉样脉络膜血管病变，可单独或联合抗VEGF","激光光凝：适用于黄斑中心凹外的典型性新生血管，现已少用（可致瘢痕和视力下降）","手术治疗：黄斑下出血清除术、黄斑转位术、新生血管膜切除术，效果有限，现已少用，主要用于抗VEGF无效的严重病例","低视力康复：晚期中心视力丧失者使用低视力辅助设备（放大镜、电子助视器、读屏软件），生活技能训练","随访：湿性AMD抗VEGF治疗后定期复查（每月OCT，评估是否需要再次注射）；干性AMD每6-12个月复查；Amsler方格自查；出现视力突然下降、视物变形加重及时就医","预防：戒烟（最重要）、控制血压血脂血糖、均衡饮食（多吃深色蔬菜、鱼类、坚果）、补充抗氧化维生素（高危人群）、避免强光直射、定期眼科检查（50岁以上每年1次）"],"management":["用药护理：按医嘱使用抗氧化维生素和矿物质，注意AREDS配方中β-胡萝卜素吸烟者禁用（增加肺癌风险）；抗VEGF玻璃体腔注射后观察眼部反应（眼痛、视力变化、分泌物），按医嘱复查；口服药按时按量；观察药物疗效和副作用","眼部护理：避免强光直射，外出戴防紫外线眼镜、遮阳帽；避免长时间用眼，注意休息；保持眼部清洁，避免感染；抗VEGF注射后1周内避免揉眼、游泳、眼部化妆；Amsler方格自查（每日1次，发现视物变形、暗点加重及时就医）","病情观察：观察视力变化（中心视力、视物变形、暗点大小）；观察眼底变化（定期OCT和眼底检查）；湿性AMD注意有无突然视力下降（出血加重）；观察治疗效果（抗VEGF注射后视力、OCT变化）；出现视力骤降、眼痛、眼红、分泌物增多及时就医","饮食：均衡饮食，多吃富含抗氧化维生素的食物（深色蔬菜如菠菜、甘蓝、西兰花，水果，坚果）、富含叶黄素和玉米黄质的食物（蛋黄、玉米、菠菜）、富含Omega-3脂肪酸的食物（深海鱼如三文鱼、金枪鱼，亚麻籽）、富含锌的食物（牡蛎、瘦肉、豆类）；戒烟限酒；控制血压血脂血糖；避免高脂高糖饮食","休息与活动：保证充足睡眠，避免熬夜和过度用眼；避免剧烈运动（湿性AMD出血期避免剧烈活动和重体力劳动，防止出血加重）；避免长时间低头、弯腰；适当户外活动（戴防紫外线眼镜）","个人卫生：勤洗手，不用脏手揉眼；抗VEGF注射后伤口避免沾水；毛巾脸盆个人专用，定期消毒；避免与他人共用化妆品","心理护理：安慰患者，解释疾病性质（慢性退行性病变，目前无法根治，但可治疗和延缓进展），消除焦虑恐惧；湿性AMD患者视力突然下降易焦虑，给予心理支持；告知抗VEGF治疗的效果和必要性，鼓励积极治疗；晚期低视力患者给予康复指导和心理支持，鼓励使用助视器，保持生活自理","健康教育：讲解AMD的病因、分型、症状和危害；强调戒烟的重要性（吸烟是最重要的可干预危险因素）；指导Amsler方格自查方法（每日1次，单眼检查，发现方格扭曲、暗点、缺失及时就医）；告知定期眼科检查的重要性（50岁以上每年1次，高危人群每6个月）；指导正确使用抗氧化维生素（AREDS配方，吸烟者避免β-胡萝卜素）；湿性AMD患者告知抗VEGF治疗的方案和随访要求，不可自行中断治疗；出现视力突然下降、视物变形加重、眼痛、眼红及时就医；低视力患者学会使用助视器和生活适应技巧","家庭护理：家属协助患者Amsler方格自查和用药提醒；帮助患者适应低视力生活（改善照明、使用大字读物、防滑防跌倒）；给予心理支持；陪同定期复查"],"notes":["年龄相关性黄斑变性（AMD）又称老年性黄斑变性，是与年龄相关的黄斑区视网膜色素上皮和神经上皮退行性病变，是50岁以上人群致盲的主要原因之一，发达国家首位致盲原因，我国患病率随人口老龄化而增加","分型：干性AMD（萎缩型，占80-90%，黄斑区玻璃膜疣形成、RPE萎缩、地图样萎缩，无脉络膜新生血管，进展缓慢，视力逐渐下降）、湿性AMD（渗出型/新生血管型，占10-20%，脉络膜新生血管形成，突破Bruch膜进入视网膜下，引起出血、渗出、水肿、瘢痕，进展快，视力突然严重下降，是AMD致盲的主要类型）","玻璃膜疣：是AMD的特征性表现，RPE代谢产物沉积于Bruch膜，呈黄白色小点，分为硬性（小、边界清、散在）和软性（大、边界不清、融合），软性玻璃膜疣与湿性AMD进展关系密切","地图样萎缩：干性AMD晚期表现，RPE和脉络膜毛细血管萎缩，眼底可见边界清楚的黄白色萎缩区，脉络膜大血管暴露，萎缩累及中心凹时视力严重下降","脉络膜新生血管（CNV）：湿性AMD的核心病理改变，脉络膜毛细血管新生血管突破Bruch膜进入RPE下或视网膜下，血管通透性高，引起出血、渗出、水肿，最终形成盘状瘢痕，破坏黄斑结构","危险因素：年龄（>50岁，患病率随年龄增加）、吸烟（最重要的可干预危险因素，吸烟者AMD风险增加2-3倍）、遗传（家族史、补体因子H基因多态性）、高血压、高血脂、肥胖、心血管疾病、长期强光暴露、饮食缺乏抗氧化维生素、女性、白人","临床表现：早期无症状，中期出现视物模糊、视物变形、阅读困难，晚期中心视力下降、中心暗点，湿性AMD可突然视力下降；Amsler方格检查阳性（方格扭曲、中心暗点）","OCT是诊断和随访AMD的金标准，可清晰显示视网膜各层结构、玻璃膜疣、RPE改变、视网膜下积液、脉络膜新生血管、黄斑水肿、萎缩，无创、快速、可重复","FFA和ICGA用于显示脉络膜新生血管，指导治疗和判断疗效","AREDS研究：抗氧化维生素（维生素C、E、β-胡萝卜素）+锌+铜可延缓中期AMD进展为晚期AMD，降低视力丧失风险；AREDS2研究用叶黄素和玉米黄质替代β-胡萝卜素（吸烟者β-胡萝卜素增加肺癌风险），效果相当","抗VEGF治疗是湿性AMD的一线标准治疗，通过玻璃体腔注射抗VEGF药物（雷珠单抗、康柏西普、阿柏西普、贝伐珠单抗）抑制脉络膜新生血管，减少渗出出血，稳定或提高视力；常用方案：3次负荷剂量后按需治疗（1+PRN）或固定间隔治疗；需长期治疗和随访，停药易复发","光动力疗法（PDT）：维替泊芬静脉注射后用特定波长激光照射黄斑区，激活药物产生自由基，损伤新生血管内皮细胞，封闭新生血管，适用于典型性CNV和息肉样脉络膜血管病变，可单独或联合抗VEGF","预后：干性AMD进展缓慢，晚期地图样萎缩累及中心凹时视力严重下降；湿性AMD进展快，不治疗者2年内多数视力严重下降（<0.1），抗VEGF治疗可使约1/3患者视力提高，多数患者视力稳定，早期治疗效果好；AMD致中心视力丧失，但周边视力保留，患者仍可生活自理","预防：戒烟（最重要）、控制血压血脂血糖、均衡饮食（多吃深色蔬菜、鱼类、坚果）、补充抗氧化维生素（高危人群）、避免强光直射（戴防紫外线眼镜）、定期眼科检查（50岁以上每年1次）、Amsler方格自查（高危人群）","我国现状：随着人口老龄化，AMD患病率逐年增加，已成为老年人致盲的主要原因之一，但公众认知度低，很多患者就诊时已到晚期，需加强健康教育和筛查"],"emergency":["出现视力突然下降、视物变形加重、中心暗点扩大（湿性AMD急性出血或新生血管活动，立即就医，抗VEGF治疗）","出现眼痛、眼红、畏光、分泌物增多（抗VEGF注射后感染或眼内炎，立即就医，急症）","出现光感消失、眼球剧痛（严重并发症，立即就医）","抗VEGF注射后出现视力骤降、眼痛（眼内炎或视网膜脱离，立即就医）","出现视野缺损、闪光感、黑影飘动（合并视网膜脱离或玻璃体出血，立即就医）","出现眼部外伤后视力下降（立即就医）"],"pinyin":"nianlingxiangguanxinghuangbanbianxing","icd10":"H35.3","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态","视力检查：远视力（标准对数视力表）、近视力、矫正视力、裸眼视力","眼压检查：指测法（Tn/T+1/T+2/T+3）或眼压计（正常10-21mmHg）","眼睑：红肿/下垂/内翻/外翻/倒睫/肿块/瘢痕/闭合不全","泪器：泪点位置/泪道冲洗/泪囊区红肿压痛/溢泪","结膜：球结膜（充血/水肿/出血/滤泡/乳头）、睑结膜（充血/滤泡/乳头/瘢痕/结石）、穹窿部","角膜：透明度/上皮缺损（荧光素染色）/浸润/溃疡/瘢痕/新生血管/异物/曲率（K1/K2）","巩膜：黄染/充血/结节/葡萄肿","前房：深度（浅/中/深）、房水闪辉（Tyndall征）、房水细胞、积脓/积血","虹膜：颜色/纹理/粘连（前粘连/后粘连）/结节/萎缩/根部离断","瞳孔：大小/形状/位置/对光反射（直接/间接）/调节反射","晶状体：透明度（皮质/核/后囊下混浊）、位置（脱位/半脱位）、人工晶体","玻璃体：混浊/积血/增殖膜/脱离","眼底：视盘（边界/颜色/C/D比/水肿/萎缩）、视网膜（出血/渗出/水肿/脱离/色素紊乱）、黄斑（中心凹反光/水肿/裂孔/变性）、血管（管径/比例/交叉压迹/新生血管）","眼肌：眼球运动（各方向）、斜视（内斜/外斜/垂直斜）、复视、眼球震颤","视野：手动/自动视野计检查（青光眼/视神经病变）","色觉：色盲本检查"],"lab_tests":["最佳矫正视力（国际标准视力表）：初诊及每次随访必查，评估病情进展与疗效","裂隙灯显微镜联合前置镜（或三面镜）眼底检查：观察黄斑区玻璃膜疣、出血、渗出及色素上皮改变","光学相干断层扫描（OCT）：初诊及每次复查，量化黄斑中心厚度，判断视网膜下液、RPE脱离及黄斑裂孔","荧光素眼底血管造影（FFA）：疑诊湿性AMD时明确脉络膜新生血管（CNV）范围及渗漏","吲哚菁绿血管造影（ICGA）：FFA不典型或疑似息肉样脉络膜血管病变（PCV）时鉴别","视野检查：评估中心暗点范围，用于中晚期功能随访"],"nursing":["病情观察：每日询问视力变化，指导患者用Amsler方格表自测，出现视物变形、中心暗点加重或眼前黑影增大及时报告","抗VEGF玻璃体腔注射后护理：注射后24～48小时监测眼压，观察眼痛、眼红、畏光及漂浮物，出现剧烈眼痛、视力骤降立即报告","防跌倒：视力低下及视野缺损者下床活动须有人搀扶，夜间拉起床栏、保持通道无障碍，床头呼叫器置于易取处","用药观察：遵医嘱予叶黄素等抗氧化剂，观察有无恶心、皮肤黄染等不适，宣教按时复诊、规律用药"],"diet":["多食富含叶黄素与玉米黄质的食物：深绿色叶菜（菠菜、羽衣甘蓝）、玉米、蛋黄","多食富含维生素C、维生素E的食物：柑橘类水果、猕猴桃、坚果（核桃、杏仁）","每周食用2～3次深海鱼类（三文鱼、鲭鱼），补充Omega-3多不饱和脂肪酸","戒烟限酒，避免高脂高糖及油炸食品，控制体重","高龄或咀嚼吞咽困难者予软食、半流食，少量多餐"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":392},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"9f042f9bfa440490858565454af97fb654a980973a307b2e49d2bba6b2ee3d24","pinyin":"nianlingxiangguanxinghuangbanbianxing","initials":"nlxgxhbbx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","干性AMD：早期无症状或仅有视物模糊、视力轻度下降，进展缓慢；晚期出现中心视力下降、视物变形、阅读困难、色觉异常，双眼可先后发病，中心暗点\\n湿性AMD：突然视力下降、视物变形（直线变弯曲）、中心暗点、色觉异常，进展快，可在数周内视力严重下降；眼底可见黄斑区出血、渗出、水肿、新生血管膜\\n眼底表现：干性——黄斑区玻璃膜疣（黄白色小点，硬性/软性）、色素紊乱、地图样萎缩（RPE萎缩，脉络膜血管暴露）；湿性——黄斑区出血（暗红色）、渗出（黄白色）、水肿、视网膜下新生血管膜、盘状瘢痕\\nAmsler方格检查：视物变形、方格扭曲、中心暗点（阳性）\\n视力：中心视力下降，周边视力一般不受影响\\n可伴对比敏感度下降、色觉减退\\n晚期可致中心视力丧失（法定盲），但周边视力保留，患者仍可生活自理",60],["摘要","又称老年性黄斑变性，是与年龄相关的黄斑区视网膜退行性病变，分为干性（萎缩型）和湿性（渗出型/新生血管型），是老年人致盲的主要原因之一，表现为视力下降、视物变形、中心暗点。",30],["疾病编码","H35.3",30],["原首字母","nianlingxiangguanxinghuangbanbianxing",60]]},{"id":"orders-c8588a64df67b1142978","key":"v1-c9ccc21dfe2a3058|orders-c8588a64df67b1142978","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"糖尿病视网膜病变","category":"眼科","raw":{"name":"糖尿病视网膜病变","category":"眼科","summary":"糖尿病引起的视网膜微血管病变，是糖尿病患者致盲的主要原因，分为非增殖期和增殖期，表现为微血管瘤、出血、渗出、黄斑水肿、新生血管、玻璃体出血、视网膜脱离，早期可无症状，晚期视力严重下降。","symptoms":["早期（非增殖期轻度）：无症状，或仅有轻微视物模糊、视力波动（血糖变化时）","非增殖期中重度：视物模糊、视力下降、视物变形（黄斑水肿）、眼前黑影飘动（出血进入玻璃体）、视野缺损","增殖期：视力明显下降、眼前大量黑影飘动（玻璃体出血）、视野缺损、视物变形（黄斑水肿/牵拉），严重者视力丧失","黄斑水肿：视力下降、视物变形、中心暗点、对比敏感度下降，是糖尿病患者视力下降的最常见原因","玻璃体出血：突然眼前大量黑影飘动、视力骤降，大量出血时视力可降至光感","视网膜脱离：视野缺损、视力下降、闪光感、黑影飘动，牵拉性视网膜脱离","新生血管性青光眼：眼痛、头痛、眼红、畏光、视力下降、眼压升高，是严重并发症，预后差","眼底表现：非增殖期——微血管瘤（小红点，最早体征）、点状/斑状出血、硬性渗出（黄白色）、棉絮斑（白色，神经纤维层梗死）、视网膜水肿、黄斑水肿；增殖期——视网膜新生血管（视盘或视网膜表面）、玻璃体出血、纤维增殖膜、牵拉性视网膜脱离、新生血管性青光眼","可伴糖尿病其他并发症（糖尿病肾病、神经病变、心血管疾病）"],"diagnosis":["糖尿病病史（1型糖尿病病程>5年、2型糖尿病确诊时即应筛查）+眼底检查","散瞳眼底检查（直接/间接检眼镜，检查微血管瘤、出血、渗出、棉絮斑、黄斑水肿、新生血管、玻璃体出血、视网膜脱离）","眼底照相（彩色眼底照相，记录病变，远程筛查）","OCT（黄斑水肿、视网膜厚度、玻璃体牵拉，评估黄斑水肿程度和治疗效果）","眼底荧光血管造影（FFA，显示微血管病变、无灌注区、新生血管、黄斑水肿，指导激光治疗和抗VEGF治疗）","眼压检查（排除新生血管性青光眼）","视力、验光","排除高血压视网膜病变、视网膜静脉阻塞、葡萄膜炎、血液系统疾病","分期诊断（我国分期）：Ⅰ期（微血管瘤或合并小出血点）、Ⅱ期（黄白色硬性渗出或合并出血斑）、Ⅲ期（棉絮斑或合并出血斑）——非增殖期（单纯型/背景型）；Ⅳ期（新生血管或合并玻璃体出血）、Ⅴ期（新生血管和纤维增殖）、Ⅵ期（牵拉性视网膜脱离）——增殖期","国际临床分级：无明显DR、轻度非增殖期（仅有微血管瘤）、中度非增殖期（微血管瘤+出血/渗出，但不到重度）、重度非增殖期（4-2-1法则：4个象限出血、2个象限静脉串珠、1个象限视网膜内微血管异常）、增殖期（新生血管、玻璃体出血、纤维增殖）","黄斑水肿分级：无黄斑水肿、有黄斑水肿（累及/未累及中心凹）","全身评估：血糖（空腹、餐后2小时、糖化血红蛋白HbA1c）、血压、血脂、肾功能（尿微量白蛋白、肌酐）、糖尿病神经病变、心血管疾病"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般无需静脉输液；雷珠单抗 0.5mg 玻璃体腔注射（每月1次）；羟苯磺酸钙 0.5g 口服 tid（眼部治疗以局部和玻璃体腔注射为主）","方案2（玻璃体出血较多）：","用法：0.9%NS 250ml + 止血敏2g + 氨甲环酸0.5g ivgtt qd（辅助止血，3-5天）〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","方案3（合并感染或术后）：","用法：0.9%NS 100ml + 抗生素 ivgtt qd（预防感染）","方案4（全身疾病治疗）：","用法：控制血糖（胰岛素静脉泵入，糖尿病酮症酸中毒时）、控制血压（静脉降压药，高血压急症时）、改善微循环（0.9%NS 250ml + 银杏叶提取物/前列地尔 ivgtt qd，辅助）","方案5（营养支持）：","用法：0.9%NS 250ml + 维生素C 2g ivgtt qd","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（控制血糖）：","用法：口服降糖药（二甲双胍、磺脲类、格列奈类、α-糖苷酶抑制剂、DPP-4抑制剂、SGLT2抑制剂、GLP-1受体激动剂）或胰岛素，目标HbA1c<7%（个体化）","药物2（控制血压）：","用法：ACEI/ARB类（贝那普利、氯沙坦，同时保护肾脏和视网膜）、钙通道阻滞剂、β受体阻滞剂，目标血压<130/80mmHg","药物3（控制血脂）：","用法：他汀类（阿托伐他汀、瑞舒伐他汀，降低低密度脂蛋白，减少硬性渗出和黄斑水肿）、贝特类（甘油三酯高时）〔调 ★ 活动性肝病禁用；甲减/肌病史慎用；妊娠哺乳禁用〕","药物4（改善微循环）：","用法：羟苯磺酸钙0.5g tid（改善视网膜微循环，减少渗出）、胰激肽原酶、银杏叶提取物、复方丹参滴丸、血栓通胶囊","药物5（抗血小板）：","用法：阿司匹林100mg qd（合并心血管疾病时，注意玻璃体出血风险）〔调 ★ 活动性溃疡禁用；阿司匹林哮喘禁用；儿童病毒感染禁用〕","药物6（黄斑水肿）：","用法：抗VEGF玻璃体腔注射为一线（见治疗），口服药物辅助（改善微循环、降脂）","药物7（中医中药）：","用法：活血化瘀、益气养阴（复方血栓通胶囊、银杏叶片、石斛夜光丸、杞菊地黄丸），辨证使用","药物8（维生素）：","用法：维生素C 0.2g tid、维生素E 0.1g qd、芦丁20mg tid（辅助抗氧化）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["全身治疗（基础）：控制血糖（HbA1c<7%，个体化，避免低血糖和血糖剧烈波动）、控制血压（<130/80mmHg，ACEI/ARB首选）、控制血脂（他汀类，LDL-C<2.6mmol/L）、戒烟、控制体重、定期全身检查（肾功能、神经、心血管）","非增殖期轻度/中度：控制全身危险因素+定期随访（每6-12个月眼底检查）+改善微循环药物（羟苯磺酸钙）；黄斑水肿累及中心凹时抗VEGF治疗","非增殖期重度：全视网膜光凝（PRP，预防新生血管形成，降低增殖期发生风险，是重度非增殖期和增殖期的标准治疗）；黄斑水肿累及中心凹时抗VEGF治疗或黄斑格栅光凝","增殖期：全视网膜光凝（PRP，标准治疗，封闭无灌注区，促使新生血管消退）；抗VEGF玻璃体腔注射（新生血管活跃、玻璃体出血、黄斑水肿时，可单独或联合PRP）；玻璃体切割术（玻璃体出血不吸收、牵拉性视网膜脱离、黄斑前膜、严重纤维增殖）","黄斑水肿：抗VEGF玻璃体腔注射为一线（雷珠单抗0.5mg、康柏西普0.5mg、阿柏西普2mg、贝伐珠单抗1.25mg，每月1次连续3次负荷剂量，之后按需或固定间隔治疗）；黄斑格栅光凝（抗VEGF无效或不能负担时）；糖皮质激素玻璃体腔注射（地塞米松缓释植入剂，适用于合并炎症或抗VEGF无效者，注意高眼压和白内障）","玻璃体出血：少量出血保守治疗（半卧位休息、止血药、促进吸收），观察1-3个月；大量出血不吸收（>1-3个月）或合并视网膜脱离、新生血管时玻璃体切割术","牵拉性视网膜脱离：玻璃体切割术+解除牵拉+眼内激光+气体/硅油填充","新生血管性青光眼：抗VEGF注射（促使新生血管消退）+全视网膜光凝+抗青光眼治疗（药物降眼压、睫状体光凝、引流阀植入），预后差，以止痛和保存眼球为主","手术治疗：玻璃体切割术（增殖期DR合并玻璃体出血、牵拉性视网膜脱离、黄斑前膜、严重纤维增殖，切除玻璃体和增殖膜，解除牵拉，眼内激光，气体或硅油填充）；白内障手术（合并白内障时，注意术后DR进展和黄斑水肿加重）","随访：糖尿病患者定期眼底筛查（1型糖尿病病程5年后每年1次，2型糖尿病确诊时即筛查，之后每年1次；已有DR者根据分期每3-12个月复查；妊娠糖尿病患者每3个月复查）；治疗后定期复查OCT和眼底，评估疗效和是否需要再次治疗","预防：控制血糖血压血脂是预防DR发生和进展的关键；戒烟；定期眼底筛查；早期发现早期治疗；糖尿病患者妊娠前和妊娠期密切监测眼底","低视力康复：晚期视力丧失者使用低视力辅助设备，生活技能训练"],"management":["全身管理：严格控制血糖（定时定量进餐，按医嘱用降糖药或胰岛素，监测空腹和餐后血糖，目标HbA1c<7%，避免低血糖和血糖剧烈波动）；控制血压（每日监测，ACEI/ARB首选，目标<130/80mmHg）；控制血脂（他汀类，定期复查血脂）；戒烟；控制体重；定期全身检查（肾功能、尿微量白蛋白、神经病变、心血管）","用药护理：按医嘱使用降糖药、降压药、降脂药，不可自行停药或调整剂量；改善微循环药物（羟苯磺酸钙）按时服用；抗VEGF玻璃体腔注射后观察眼部反应（眼痛、视力变化、分泌物），按医嘱复查；口服药注意副作用（降糖药低血糖、降压药低血压、他汀类肝功能和肌痛）；观察药物疗效","眼部护理：避免强光直射，外出戴防紫外线眼镜；避免长时间用眼，注意休息；保持眼部清洁，避免感染；玻璃体出血期半卧位休息（使血液下沉，避免遮挡黄斑）；抗VEGF注射后1周内避免揉眼、游泳、眼部化妆；避免剧烈运动和重体力劳动（增殖期DR和玻璃体出血期防止出血加重）；避免突然用力、咳嗽、打喷嚏（防止新生血管破裂出血）","病情观察：观察视力变化（中心视力、视物变形、黑影飘动）；观察眼底变化（定期OCT和眼底检查）；注意有无玻璃体出血（突然黑影增多、视力骤降）、视网膜脱离（视野缺损、闪光感）、新生血管性青光眼（眼痛头痛、眼红、眼压升高）；出现视力骤降、眼痛、视野缺损、闪光感及时就医","饮食：糖尿病饮食（控制总热量，低糖低脂高纤维，定时定量，少食多餐）；多吃新鲜蔬菜（深色蔬菜）、优质蛋白（鱼、禽、蛋、奶、豆制品）；避免高糖、高脂、高盐饮食；戒烟限酒；控制体重；合并肾病时优质低蛋白饮食","休息与活动：保证充足睡眠，避免熬夜；增殖期DR和玻璃体出血期避免剧烈运动、重体力劳动、突然用力、咳嗽、打喷嚏；避免长时间低头、弯腰；适当轻度活动（散步、太极拳）；血糖稳定时适当运动有助于控制血糖","个人卫生：勤洗手，不用脏手揉眼；抗VEGF注射后伤口避免沾水；毛巾脸盆个人专用，定期消毒；糖尿病患者注意足部护理（预防糖尿病足）","心理护理：安慰患者，解释DR是糖尿病常见并发症，早期治疗可延缓进展和保护视力，消除焦虑恐惧；增殖期DR和视力下降患者易焦虑抑郁，给予心理支持；告知定期筛查和治疗的重要性，鼓励积极控制血糖和配合治疗；晚期低视力患者给予康复指导和心理支持","健康教育：讲解DR的病因、分期、症状和危害；强调控制血糖血压血脂是预防和延缓DR进展的关键；告知定期眼底筛查的重要性（1型糖尿病5年后、2型糖尿病确诊时即筛查，之后每年1次）；指导血糖自我监测（空腹、餐后2小时）；告知抗VEGF治疗和激光治疗的方案和随访要求，不可自行中断治疗；出现视力突然下降、黑影增多、眼痛、视野缺损、闪光感及时就医；玻璃体出血期半卧位休息，避免剧烈活动；戒烟；糖尿病患者妊娠前和妊娠期密切监测眼底；学会使用低视力辅助设备","家庭护理：家属协助患者血糖监测和用药提醒；帮助患者适应低视力生活（改善照明、使用大字读物、防滑防跌倒）；给予心理支持；陪同定期复查；注意患者足部护理（预防糖尿病足）"],"notes":["糖尿病视网膜病变（DR）是糖尿病引起的视网膜微血管病变，是工作年龄人群首位致盲原因，糖尿病病程越长、血糖控制越差，患病率越高；1型糖尿病病程20年以上几乎100%有DR，2型糖尿病病程20年以上约60%有DR","发病机制：长期高血糖导致视网膜微血管内皮细胞损伤、周细胞丧失、基底膜增厚、毛细血管闭塞、视网膜缺血缺氧，诱发血管内皮生长因子（VEGF）表达增加，导致微血管通透性增加（黄斑水肿）和新生血管形成（增殖期）","危险因素：糖尿病病程（最重要）、高血糖（HbA1c每降低1%，DR风险降低35%）、高血压、高血脂、吸烟、糖尿病肾病、妊娠、肥胖、遗传、贫血","分期：非增殖期（NPDR，单纯型/背景型，Ⅰ-Ⅲ期，微血管瘤、出血、渗出、棉絮斑、黄斑水肿，无新生血管）、增殖期（PDR，Ⅳ-Ⅵ期，新生血管形成、玻璃体出血、纤维增殖、牵拉性视网膜脱离）","黄斑水肿（DME）：可发生于任何分期，是糖尿病患者视力下降的最常见原因，表现为黄斑区视网膜增厚和积液，OCT可准确测量和随访","4-2-1法则：重度非增殖期DR的诊断标准——4个象限均有视网膜内出血、2个象限有静脉串珠、1个象限有视网膜内微血管异常（IRMA），满足任意1项即为重度NPDR","全视网膜光凝（PRP）：是重度非增殖期和增殖期DR的标准治疗，用激光光凝视网膜周边部无灌注区，减少视网膜耗氧量，促使新生血管消退，预防玻璃体出血和视网膜脱离；治疗后周边视野可能缩小，夜间视力下降","抗VEGF治疗：玻璃体腔注射抗VEGF药物（雷珠单抗、康柏西普、阿柏西普、贝伐珠单抗）是黄斑水肿和增殖期DR新生血管的一线治疗，可消退新生血管、减轻黄斑水肿、稳定或提高视力；需长期治疗和随访，停药易复发","玻璃体切割术：适用于增殖期DR合并玻璃体出血不吸收（>1-3个月）、牵拉性视网膜脱离、黄斑前膜、严重纤维增殖；切除玻璃体和增殖膜，解除牵拉，眼内激光，气体或硅油填充；手术难度大，术后视力恢复取决于黄斑功能","新生血管性青光眼：是增殖期DR的严重并发症，虹膜和前房角新生血管形成，阻塞房水流出，眼压升高，眼痛头痛，视力丧失；治疗困难，预后差，以抗VEGF+全视网膜光凝+降眼压治疗为主，晚期以止痛和保存眼球为目的","筛查：1型糖尿病患者病程5年后开始每年眼底筛查；2型糖尿病患者确诊时即应筛查，之后每年1次；已有DR者根据分期每3-12个月复查；糖尿病患者妊娠前和妊娠期每3个月复查；筛查方法包括散瞳眼底检查、眼底照相、OCT","预后：早期DR（非增殖期轻度/中度）控制全身危险因素可稳定，视力预后好；重度非增殖期和增殖期及时激光和抗VEGF治疗可保护视力；晚期玻璃体出血、视网膜脱离、新生血管性青光眼视力预后差，可致盲；DR是可防可治的，关键是早期筛查和早期治疗","我国现状：我国糖尿病患者超过1亿，DR患病率约25-30%，但筛查率低，很多患者就诊时已到增殖期，致盲率高；需加强糖尿病患者健康教育和眼底筛查，推广远程眼底筛查和AI辅助诊断","预防：控制血糖（HbA1c<7%）、血压（<130/80mmHg）、血脂（LDL-C<2.6mmol/L）是预防DR发生和进展的关键；戒烟；定期眼底筛查；早期发现早期治疗；糖尿病患者妊娠前和妊娠期密切监测眼底"],"emergency":["出现视力突然下降、眼前大量黑影飘动（玻璃体出血，立即就医，评估是否需要手术）","出现视野缺损、闪光感、黑影飘动加重（牵拉性视网膜脱离，立即就医，玻璃体切割手术）","出现眼痛、头痛、眼红、畏光、视力骤降、恶心呕吐（新生血管性青光眼急性发作，立即降眼压治疗）","抗VEGF注射后出现眼痛、视力骤降、眼红、分泌物增多（眼内炎，立即就医，急症）","出现光感消失、眼球剧痛（严重并发症，立即就医）","出现眼部外伤后视力下降（立即就医）","血糖剧烈波动（低血糖或酮症酸中毒）时视力突然变化（及时控制血糖，眼科评估）"],"pinyin":"tangniaobingshiwangmobingbian","icd10":"E11.3","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态","视力检查：远视力（标准对数视力表）、近视力、矫正视力、裸眼视力","眼压检查：指测法（Tn/T+1/T+2/T+3）或眼压计（正常10-21mmHg）","眼睑：红肿/下垂/内翻/外翻/倒睫/肿块/瘢痕/闭合不全","泪器：泪点位置/泪道冲洗/泪囊区红肿压痛/溢泪","结膜：球结膜（充血/水肿/出血/滤泡/乳头）、睑结膜（充血/滤泡/乳头/瘢痕/结石）、穹窿部","角膜：透明度/上皮缺损（荧光素染色）/浸润/溃疡/瘢痕/新生血管/异物/曲率（K1/K2）","巩膜：黄染/充血/结节/葡萄肿","前房：深度（浅/中/深）、房水闪辉（Tyndall征）、房水细胞、积脓/积血","虹膜：颜色/纹理/粘连（前粘连/后粘连）/结节/萎缩/根部离断","瞳孔：大小/形状/位置/对光反射（直接/间接）/调节反射","晶状体：透明度（皮质/核/后囊下混浊）、位置（脱位/半脱位）、人工晶体","玻璃体：混浊/积血/增殖膜/脱离","眼底：视盘（边界/颜色/C/D比/水肿/萎缩）、视网膜（出血/渗出/水肿/脱离/色素紊乱）、黄斑（中心凹反光/水肿/裂孔/变性）、血管（管径/比例/交叉压迹/新生血管）","眼肌：眼球运动（各方向）、斜视（内斜/外斜/垂直斜）、复视、眼球震颤","视野：手动/自动视野计检查（青光眼/视神经病变）","色觉：色盲本检查"],"lab_tests":["视力与矫正视力（裸眼及最佳矫正视力，初诊及每次复诊必查）","裂隙灯显微镜联合三面镜/前置镜眼底检查（散瞳后详查，判断新生血管、玻璃体积血）","免散瞳/散瞳眼底照相 + 荧光素眼底血管造影（FFA，评估无灌注区及新生血管渗漏，指导激光时机）","光学相干断层扫描（OCT，查黄斑水肿及厚度，治疗前后对比）；黄斑水肿疑有玻璃体牵拉者加OCT血管成像（OCTA）","眼压测量（排除新生血管性青光眼，尤其FFA示广泛无灌注区者）","全身评估：糖化血红蛋白、血糖、肾功能及血脂（眼病与全身微血管病变同步管理）"],"nursing":["用药观察：注射抗VEGF药物（雷珠单抗/康柏西普等）及行眼底激光后，观察有无眼痛、眼胀、视力骤降，警惕眼压升高及眼内感染，遵医嘱按时滴抗生素眼液","眼部护理：避免揉眼及外力碰撞；玻璃体积血者嘱半卧位休息、减少活动，避免头低位及剧烈运动（如提重物、憋气用力）","病情观察：每日询问视力、眼前黑影飘动及闪光感变化；突然黑影增大、视物遮挡或眼胀痛伴恶心呕吐时立即报告医师","术后/治疗后护理：玻璃体切割或激光治疗后按医嘱保持相应体位（如硅油填充者俯卧位），勿擅自改变；保持眼部敷料清洁干燥，防感染","防跌倒：双眼视力差者夜间留灯、床栏保护，下床活动有人搀扶，卫生间加防滑垫"],"diet":["严格控制总热量与糖类摄入，低糖低脂饮食，主食粗细搭配，少食多餐，避免餐后血糖骤升骤降","富含维生素A、C、E食物：胡萝卜、南瓜、西兰花、菠菜、柑橘、猕猴桃等，有助于视网膜保护","适量优质蛋白与富含叶黄素食物：鸡蛋黄、玉米、枸杞、深绿色蔬菜，支持视网膜修复","忌辛辣刺激及过烫食物，戒烟限酒；玻璃体积血早期宜进温凉软食，避免用力咀嚼及硬食","控制盐分摄入（每日<5g），合并肾病者遵医嘱限制蛋白，防止血压波动加重眼底病变"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":393},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"1501c060ad83abb7ff4e924a63277b7f71a995fccd4339ac67036a0e44ebef27","pinyin":"tangniaobingshiwangmobingbian","initials":"tnbswmbb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","早期（非增殖期轻度）：无症状，或仅有轻微视物模糊、视力波动（血糖变化时）\\n非增殖期中重度：视物模糊、视力下降、视物变形（黄斑水肿）、眼前黑影飘动（出血进入玻璃体）、视野缺损\\n增殖期：视力明显下降、眼前大量黑影飘动（玻璃体出血）、视野缺损、视物变形（黄斑水肿/牵拉），严重者视力丧失\\n黄斑水肿：视力下降、视物变形、中心暗点、对比敏感度下降，是糖尿病患者视力下降的最常见原因\\n玻璃体出血：突然眼前大量黑影飘动、视力骤降，大量出血时视力可降至光感\\n视网膜脱离：视野缺损、视力下降、闪光感、黑影飘动，牵拉性视网膜脱离\\n新生血管性青光眼：眼痛、头痛、眼红、畏光、视力下降、眼压升高，是严重并发症，预后差\\n眼底表现：非增殖期——微血管瘤（小红点，最早体征）、点状/斑状出血、硬性渗出（黄白色）、棉絮斑（白色，神经纤维层梗死）、视网膜水肿、黄斑水肿；增殖期——视网膜新生血管（视盘或视网膜表面）、玻璃体出血、纤维增殖膜、牵拉性视网膜脱离、新生血管性青光眼\\n可伴糖尿病其他并发症（糖尿病肾病、神经病变、心血管疾病）",60],["摘要","糖尿病引起的视网膜微血管病变，是糖尿病患者致盲的主要原因，分为非增殖期和增殖期，表现为微血管瘤、出血、渗出、黄斑水肿、新生血管、玻璃体出血、视网膜脱离，早期可无症状，晚期视力严重下降。",30],["疾病编码","E11.3",30],["原首字母","tangniaobingshiwangmobingbian",60]]},{"id":"orders-092d48a9faa803ef9f8a","key":"v1-c9ccc21dfe2a3058|orders-092d48a9faa803ef9f8a","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"慢性化脓性中耳炎","category":"耳鼻喉","raw":{"name":"慢性化脓性中耳炎","category":"耳鼻喉","summary":"中耳黏膜、骨膜或深达骨质的慢性化脓性炎症，多因急性化脓性中耳炎未及时治疗或治疗不当迁延而来，表现为长期或间歇性耳流脓、鼓膜穿孔、听力下降，可引起颅内外并发症。","symptoms":["耳流脓：长期或间歇性，脓液性质可为黏液性、黏脓性、脓性，胆脂瘤型可有豆腐渣样物、恶臭","听力下降：传导性耳聋为主，程度与穿孔大小、位置、听骨链破坏有关，长期病变可致混合性聋","耳鸣：部分患者可有低调或高调耳鸣","耳痛：一般无耳痛，急性发作时可有耳痛、头痛","眩晕：病变累及内耳时可有眩晕、平衡障碍","鼓膜穿孔：紧张部或松弛部穿孔，大小不一，穿孔内可见肉芽、胆脂瘤上皮","急性发作时：耳痛加重、流脓增多、发热、头痛、恶心呕吐","并发症：耳后骨膜下脓肿（耳后红肿疼痛、耳廓向前外方耸立）、面瘫（面神经受累）、迷路炎（眩晕、恶心呕吐、听力下降）、脑膜炎、脑脓肿、乙状窦血栓性静脉炎（颅内外并发症，危及生命）"],"diagnosis":["典型病史（急性中耳炎史、长期耳流脓、听力下降）+耳部检查（鼓膜穿孔、流脓）","耳镜检查（外耳道及鼓膜，观察穿孔位置大小、脓液性质、有无肉芽胆脂瘤）","听力检查（纯音测听，传导性或混合性耳聋，评估听力损失程度）","颞骨CT（明确病变范围、骨质破坏、听骨链情况、有无胆脂瘤、并发症，是术前必查）","脓液培养+药敏（急性发作时，明确病原菌和敏感药物）","排除中耳癌、结核性中耳炎、外耳道炎、脑脊液耳漏","分型：单纯型（病变局限于黏膜，鼓膜紧张部中央性穿孔，流脓间歇性，无骨质破坏，并发症少）、骨疡型（病变深达骨质，有肉芽或息肉，鼓膜边缘性穿孔，流脓持续性，有骨质破坏，可引起并发症）、胆脂瘤型（胆脂瘤形成，鼓膜松弛部或紧张部后上边缘性穿孔，流脓恶臭，有豆腐渣样物，骨质破坏明显，易引起颅内外并发症）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1（急性发作或合并颅内外并发症）：","  用法：0.9%NS 100ml + 头孢曲松2g ivgtt qd 或 头孢呋辛1.5g ivgtt q8h 或 左氧氟沙星0.5g ivgtt qd，根据药敏调整〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","","方案2（合并颅内并发症；脑膜炎、脑脓肿）：","  用法：广谱抗生素联合（头孢曲松+甲硝唑+万古霉素），足量足疗程，神经外科协同〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","方案3（合并迷路炎）：","  用法：抗生素+糖皮质激素（地塞米松10mg（NS 100ml 或 5%GS 100ml；亦可直接静推）ivgtt qd）+改善微循环〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案4：","  用法：术前术后一般无需长期静脉抗生素，术后3-5天预防感染","","方案5（补液支持）：","  用法：0.9%NS或5%GNS ivgtt，维持水电解质平衡","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（急性发作）：","用法：抗生素（头孢克肟0.2g bid、阿莫西林克拉维酸钾0.625g tid、左氧氟沙星0.5g qd），疗程5-7天，根据药敏调整〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（局部用药）：","用法：3%过氧化氢溶液清洗外耳道脓液（每日2-3次），然后滴抗生素滴耳液（氧氟沙星滴耳液、左氧氟沙星滴耳液、氯霉素滴耳液，每日3-4次）；鼓膜穿孔小、脓液多时用酒精制剂（硼酸酒精滴耳液，杀菌消肿）；脓液减少、炎症消退时用粉剂（硼酸粉、磺胺噻唑粉，吹耳，保持干燥）〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物3（糖皮质激素）：","用法：急性发作炎症重时口服泼尼松10mg tid（短期3-5天），或地塞米松滴耳液〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","药物4（促排剂）：","用法：桉柠蒎肠溶软胶囊0.3g tid、标准桃金娘油0.3g tid（促进分泌物排出）","药物5（止痛）：","用法：布洛芬0.2g prn（急性发作耳痛时）〔调 ★ 肾功能不全禁用/慎用；活动性溃疡禁用；★ 妊娠晚期禁用〕","药物6（中医中药）：","用法：清热解毒、利湿排脓（龙胆泻肝丸、中耳炎散），辨证使用","药物7（手术前后）：","用法：术前3天抗生素滴耳液清洁耳道；术后抗生素3-5天预防感染","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["单纯型：以局部用药为主，清洁耳道+抗生素滴耳液，干耳后可行鼓膜修补术（提高听力、防止复发）","骨疡型：引流通畅者局部用药（同单纯型），定期复查；引流不畅、有肉芽息肉、疑有并发症者手术治疗（乳突根治术+鼓室成形术）","胆脂瘤型：一旦确诊应尽早手术治疗（乳突根治术+鼓室成形术，彻底清除胆脂瘤和病变组织，预防并发症，尽可能重建听力），不能保守治疗","手术治疗：鼓室成形术（鼓膜修补术+听骨链重建术，适用于干耳、炎症控制后，提高听力）、乳突根治术（彻底清除乳突、鼓窦、鼓室内病变，适用于骨疡型、胆脂瘤型、并发症）、改良乳突根治术（保留与传音功能有关的结构，提高听力）、人工耳蜗（极重度感音神经性聋）","并发症治疗：耳后骨膜下脓肿（切开引流+抗生素+乳突手术）、面瘫（抗生素+激素+手术减压）、迷路炎（抗生素+激素+手术）、颅内并发症（脑膜炎、脑脓肿、乙状窦血栓性静脉炎，需急诊手术+大剂量抗生素+神经外科协同，危及生命）","急性发作：清洁耳道+局部抗生素滴耳液+口服或静脉抗生素，炎症控制后评估是否手术","预防：积极治疗急性化脓性中耳炎（及时足量抗生素，防止迁延为慢性）；避免污水入耳（游泳、洗澡时用耳塞）；不要用不洁物品挖耳；增强体质，预防上呼吸道感染；鼓膜穿孔者避免游泳","随访：术后定期复查（清理耳道、观察愈合、评估听力），干耳后评估听力和是否需要二期手术"],"management":["耳道护理：保持耳道清洁干燥，用3%过氧化氢溶液清洗脓液（每日2-3次），清洗后用棉签拭干再滴药；滴耳药时患耳朝上，滴入后按压耳屏，保持体位5-10分钟；避免污水入耳（游泳、洗澡时用耳塞或棉球堵塞外耳道口）；不要用不洁物品挖耳","用药护理：按医嘱使用抗生素（口服或静脉），足疗程，不可自行停药；局部用药前先清洁耳道脓液（否则药物不能进入中耳，影响疗效）；观察药物疗效和副作用（抗生素胃肠道反应、过敏）；多种滴耳液使用时间隔10-15分钟","病情观察：观察耳流脓的量、颜色、气味、性质变化；观察听力变化；观察有无并发症征象（耳后红肿疼痛、耳廓耸立、面瘫、眩晕、恶心呕吐、头痛、发热、意识障碍），一旦出现立即就医（颅内外并发症可危及生命）；急性发作时观察体温、耳痛、头痛变化","饮食：清淡易消化饮食，多饮水，多吃新鲜蔬果；避免辛辣刺激、油腻、烟酒；急性发作时避免腥发食物（海鲜、羊肉）；保持大便通畅","休息与活动：保证充足睡眠，避免熬夜和过度劳累；急性发作时卧床休息；避免剧烈运动和重体力劳动；避免游泳、潜水（鼓膜穿孔者）；避免乘坐飞机（气压变化可能加重不适，必要时用滴鼻剂保持咽鼓管通畅）","个人卫生：勤洗手，避免上呼吸道感染；不要用不洁物品挖耳；毛巾脸盆个人专用；擤鼻涕时不要两侧同时用力（应一侧一侧擤，防止分泌物经咽鼓管进入中耳）","心理护理：安慰患者，解释疾病性质和治疗方法，消除焦虑；需手术患者解释手术目的、过程和注意事项，减轻恐惧；听力下降患者给予沟通支持（说话时面对患者、语速放慢），鼓励使用助听器","健康教育：讲解慢性化脓性中耳炎的病因、分型和危害（胆脂瘤型可引起颅内外并发症，危及生命）；强调及时治疗急性中耳炎的重要性；指导正确清洁耳道和滴耳药方法；告知手术指征（胆脂瘤型、骨疡型引流不畅、并发症、单纯型干耳后提高听力）；术后定期复查的重要性；出现耳后红肿、面瘫、眩晕、头痛、发热、意识障碍立即就医；鼓膜穿孔者避免游泳和污水入耳；增强体质，预防上呼吸道感染","家庭护理：家属协助患者清洁耳道和滴药；观察病情变化，发现并发症征象及时就医；术后患者注意耳道护理，避免进水和挖耳；陪同定期复查"],"notes":["慢性化脓性中耳炎是中耳黏膜、骨膜或深达骨质的慢性化脓性炎症，是耳科常见病，多因急性化脓性中耳炎未及时治疗或治疗不当、细菌毒力强、机体抵抗力差、咽鼓管功能障碍、鼻腔鼻窦疾病等迁延而来，病程超过6-8周","分型：单纯型（最常见，病变局限于中耳黏膜，鼓膜紧张部中央性穿孔，流脓为间歇性，脓液为黏液性或黏脓性，无臭味，无骨质破坏，听力损失轻，并发症少，预后好）、骨疡型（病变深达骨质，有肉芽或息肉形成，鼓膜边缘性穿孔，流脓为持续性，脓液为脓性，可有臭味，有骨质破坏，可引起并发症，需手术治疗）、胆脂瘤型（胆脂瘤形成，是角化鳞状上皮在中耳内堆积形成的囊性结构，并非真性肿瘤，但具有破坏性，可侵蚀骨质，鼓膜松弛部或紧张部后上边缘性穿孔，流脓为持续性，脓液恶臭，有豆腐渣样物，骨质破坏明显，易引起颅内外并发症，一旦确诊应尽早手术）","胆脂瘤：并非真性肿瘤，是角化鳞状上皮在中耳乳突内堆积形成的囊性结构，囊内充满脱落上皮和角化物，具有破坏性，可分泌酶类和炎症介质，侵蚀周围骨质，引起颅内外并发症（面瘫、迷路炎、脑膜炎、脑脓肿、乙状窦血栓性静脉炎），是慢性化脓性中耳炎中最危险的类型","并发症：颅外并发症（耳后骨膜下脓肿、耳下颈深部脓肿、面瘫、迷路炎、岩尖炎、外耳道炎、颞肌下脓肿）、颅内并发症（硬脑膜外脓肿、硬脑膜下脓肿、脑膜炎、乙状窦血栓性静脉炎、脑脓肿、脑积水），颅内并发症可危及生命，是慢性化脓性中耳炎的主要死亡原因","鼓膜穿孔分类：中央性穿孔（穿孔周围有鼓膜边缘，单纯型多见，预后好）、边缘性穿孔（穿孔达鼓沟，无鼓膜边缘，骨疡型和胆脂瘤型多见，提示病变较重）；松弛部穿孔（胆脂瘤型特征性表现）、紧张部穿孔","听力损失：传导性耳聋为主，程度与穿孔大小（穿孔越大听力损失越重）、位置（穿孔位于鼓膜紧张部后上方对听力影响大）、听骨链破坏（听骨链中断或固定致听力损失重）有关；长期病变毒素进入内耳可致感音神经性聋，形成混合性聋","治疗原则：消除病因、控制感染、清除病灶、通畅引流、恢复听力；单纯型以局部用药为主，干耳后鼓膜修补；骨疡型引流通畅者局部用药，引流不畅或有并发症者手术；胆脂瘤型尽早手术","手术方式：鼓室成形术（Wullstein分型，Ⅰ型鼓膜修补术、Ⅱ型砧骨搭桥、Ⅲ型镫骨加高、Ⅳ型小鼓室成形、Ⅴ型外半规管开窗，现多根据听骨链情况选择鼓膜修补+听骨链重建）、乳突根治术（彻底清除乳突、鼓窦、上鼓室、中鼓室内病变，使乳突腔与外耳道相通，适用于胆脂瘤型、骨疡型、并发症）、改良乳突根治术（保留外耳道后壁和与传音有关的结构，提高听力）、开放式乳突根治+鼓室成形术、完壁式乳突根治+鼓室成形术","术后注意：术后耳道填塞碘仿纱条1-2周，术后1-2周取出；术后3个月内耳道可能有少量渗液，属正常；术后定期复查清理耳道；术后3-6个月评估听力，必要时二期手术；术后避免感冒、游泳、挖耳","预后：单纯型预后好，干耳后鼓膜修补可提高听力；骨疡型手术可清除病灶，听力恢复取决于听骨链情况；胆脂瘤型手术可清除病灶预防并发症，但听力恢复可能不理想，术后需长期随访防止复发；出现颅内并发症者预后差，可危及生命","预防：积极治疗急性化脓性中耳炎（及时足量抗生素，疗程足够，防止迁延）；积极治疗鼻腔鼻窦疾病（鼻炎、鼻窦炎、腺样体肥大，改善咽鼓管功能）；避免污水入耳（游泳、洗澡时用耳塞）；不要用不洁物品挖耳；鼓膜穿孔者避免游泳和潜水；增强体质，预防上呼吸道感染；正确擤鼻（一侧一侧擤，不要两侧同时用力）","我国现状：慢性化脓性中耳炎仍是我国常见致聋原因之一，尤其是农村和基层地区，因急性中耳炎治疗不及时和不规范导致慢性化，需加强基层医疗建设和健康教育"],"emergency":["出现耳后红肿疼痛、耳廓向前外方耸立、发热（耳后骨膜下脓肿，立即就医，切开引流+抗生素+手术）","出现口角歪斜、闭眼不全、额纹消失（面瘫，面神经受累，立即就医，抗生素+激素+手术减压）","出现剧烈眩晕、恶心呕吐、平衡障碍、听力骤降（迷路炎，立即就医，抗生素+激素+手术）","出现剧烈头痛、发热、呕吐、意识障碍、抽搐（颅内并发症：脑膜炎、脑脓肿，危及生命，立即急诊，大剂量抗生素+神经外科协同+手术）","出现耳流脓突然减少或停止、头痛加重、发热（脓液引流不畅，可能引起颅内并发症，立即就医）","出现大量耳出血（颈静脉球瘤或骨质破坏侵蚀大血管，立即就医）","术后出现耳道大量出血、眼痛、视力下降、面瘫、眩晕（术后并发症，立即就医）","急性发作时出现高热、寒战、头痛、呕吐（感染扩散，立即就医）"],"pinyin":"manxinghuanongxingzhongeryan","icd10":"H66.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态、面容","耳部：耳廓（畸形/红肿/皮疹/瘘管）、外耳道（耵聍/异物/分泌物/红肿/狭窄/闭锁）、鼓膜（标志/充血/内陷/穿孔/钙化/液平/肉芽）、乳突（红肿/压痛）、听力（耳语/音叉试验：Rinne试验/Weber试验/Schwabach试验）、前庭功能（自发性眼震/位置试验）","鼻部：外鼻（畸形/红肿）、鼻前庭（红肿/疖肿/结痂）、鼻腔（鼻中隔偏曲/糜烂/出血/穿孔、下鼻甲肿大/息肉样变、中鼻甲息肉样变/气化、鼻道分泌物（黏脓/血性/水样）、息肉/新生物）、鼻窦（压痛：额窦/上颌窦/筛窦）、后鼻孔检查","咽喉部：口咽（黏膜充血/肿胀/溃疡、扁桃体大小（Ⅰ-Ⅳ度）/充血/隐窝脓栓/结石、咽后壁淋巴滤泡增生/脓性分泌物、悬雍垂水肿/偏斜、软腭运动）、喉咽（会厌充血/水肿/囊肿、杓状会厌襞、梨状窝新生物/积液）、喉部（间接喉镜/电子喉镜：声带充血/息肉/小结/麻痹/新生物、室带肥厚、声门闭合情况）","颈部：淋巴结肿大（部位/大小/质地/活动度/压痛）、甲状腺、包块、瘘管","其他：发音（声嘶/失声）、吞咽（困难/呛咳）、呼吸（喘鸣/呼吸困难）"],"lab_tests":["耳内镜检查（0°/30°耳内镜）：评估鼓膜穿孔部位、大小、残余鼓膜及鼓室黏膜情况，有无肉芽、息肉或胆脂瘤皮屑，术前及术后复查均需","纯音听阈测定＋声导抗测试（鼓室导抗图）：明确传导性/混合性听力损失程度及中耳传音功能，术前必查，术后3个月复查听力评估疗效","颞骨高分辨率CT（轴位+冠状位薄层扫描）：术前评估鼓室、鼓窦、乳突气化及骨质破坏情况，有无胆脂瘤、迷路瘘管、乙状窦或硬脑膜暴露，拟行乳突手术者必查","耳分泌物细菌培养＋药敏试验：反复流脓或术前各查1次，指导抗生素选择；怀疑真菌感染时加做真菌涂片及培养","咽鼓管功能评估（Valsalva试验/声导抗）：判断咽鼓管通畅度，预测鼓室成形术后愈合，功能差者先行鼓膜置管或药物治疗","前庭功能及眼震检查：伴眩晕、眼震或可疑迷路受累时进行，鉴别耳源性眩晕与其他眩晕病因"],"nursing":["耳部护理：保持外耳道清洁干燥，滴耳前用3%过氧化氢清洗外耳道脓液并拭干，再滴入抗生素滴耳液（患耳向上侧卧5～10分钟）；洗头洗澡时用棉球堵塞外耳道，严禁游泳","病情观察：密切观察耳流脓量、性状（黏液脓性/血性/恶臭）及有无耳痛、头痛、眩晕、恶心呕吐、面瘫、发热，警惕耳源性颅内并发症（脑膜炎、脑脓肿、乙状窦血栓性静脉炎）先兆，异常立即报告医师","术后护理：乳突根治/鼓室成形术后取平卧位患耳朝上，观察敷料渗血渗液及有无头晕，保持伤口干燥，避免术耳受压；术后48～72小时内避免用力擤鼻、咳嗽、打喷嚏，打喷嚏时张口进行","体位与防误吸：伴眩晕者卧床休息、缓慢变换体位，进食取坐位或半卧位以防呛咳误吸；术后患者下床活动时专人搀扶，防跌倒","健康教育：指导单侧交替擤鼻，避免乘飞机、潜水及剧烈气压变化；术后遵医嘱定期换药复诊，出现流脓增多、听力骤降或眩晕加重及时就诊"],"diet":["忌辛辣刺激食物及酒、咖啡，减少海鲜、牛羊肉等易致敏发物摄入，以免加重中耳黏膜充血渗出","术后当天进温凉流质（米汤、藕粉、果汁），次日过渡至半流质（粥、烂面条、蒸蛋羹），1周内避免过热、过硬、需大力咀嚼的食物，防止牵拉伤口及局部出血","加强高蛋白、高维生素营养支持，适量进食鱼、瘦肉、蛋、奶及新鲜蔬果，保证维生素C和锌摄入，促进创面愈合","多饮水，餐后漱口保持口腔清洁，防止口腔及鼻咽部感染经咽鼓管逆行传播；长期卧床或老年患者由护士协助口腔护理","合并糖尿病者严格血糖控制，遵医嘱监测血糖并按时用药，血糖控制不良不利于炎症消退及伤口愈合"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":394},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"4f1c453afc74ebfda48ebec428f2d7466bbad05a102cc7596940543e06d25ab3","pinyin":"manxinghuanongxingzhongeryan","initials":"mxhnxzey","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","耳流脓：长期或间歇性，脓液性质可为黏液性、黏脓性、脓性，胆脂瘤型可有豆腐渣样物、恶臭\\n听力下降：传导性耳聋为主，程度与穿孔大小、位置、听骨链破坏有关，长期病变可致混合性聋\\n耳鸣：部分患者可有低调或高调耳鸣\\n耳痛：一般无耳痛，急性发作时可有耳痛、头痛\\n眩晕：病变累及内耳时可有眩晕、平衡障碍\\n鼓膜穿孔：紧张部或松弛部穿孔，大小不一，穿孔内可见肉芽、胆脂瘤上皮\\n急性发作时：耳痛加重、流脓增多、发热、头痛、恶心呕吐\\n并发症：耳后骨膜下脓肿（耳后红肿疼痛、耳廓向前外方耸立）、面瘫（面神经受累）、迷路炎（眩晕、恶心呕吐、听力下降）、脑膜炎、脑脓肿、乙状窦血栓性静脉炎（颅内外并发症，危及生命）",60],["摘要","中耳黏膜、骨膜或深达骨质的慢性化脓性炎症，多因急性化脓性中耳炎未及时治疗或治疗不当迁延而来，表现为长期或间歇性耳流脓、鼓膜穿孔、听力下降，可引起颅内外并发症。",30],["疾病编码","H66.9",30],["原首字母","manxinghuanongxingzhongeryan",60]]},{"id":"orders-9f230076a1fadbbf3194","key":"v1-c9ccc21dfe2a3058|orders-9f230076a1fadbbf3194","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"分泌性中耳炎","category":"耳鼻喉","raw":{"name":"分泌性中耳炎","category":"耳鼻喉","summary":"又称渗出性中耳炎、卡他性中耳炎、非化脓性中耳炎，是以中耳积液和听力下降为特征的中耳非化脓性炎性疾病，多因咽鼓管功能障碍、感染、免疫反应引起，表现为耳闷、听力下降、耳鸣、耳痛，儿童多见，是儿童致聋的常见原因。","symptoms":["听力下降：传导性耳聋，程度不一，可随体位变化（卧位时听力改善，立位时下降，因积液离开蜗窗），自听增强（听自己说话声音变大，有回声）","耳闷胀感：耳内堵塞感、闷胀感，按压耳屏后可暂时减轻","耳鸣：低调间歇性耳鸣，如嗡嗡声、流水声，打哈欠、擤鼻时耳内可有气过水声","耳痛：一般不明显，或仅有轻微耳痛，急性发作时可有耳痛","儿童表现：听话迟钝、注意力不集中、学习成绩下降、看电视音量大、对声音反应差、婴幼儿抓耳、哭闹、睡眠不安","耳镜检查：鼓膜内陷（光锥缩短、变形或消失，锤骨柄向后上移位，锤骨短突明显外突）、鼓膜色泽改变（淡红色、橙红色、琥珀色、灰蓝色）、鼓室积液征（透过鼓膜可见液平面或气泡，液平面随头位变动而移动）、鼓膜活动度差（鼓气耳镜检查鼓膜活动受限）","并发症：粘连性中耳炎（长期不愈，鼓膜与鼓岬粘连）、胆固醇肉芽肿（积液中胆固醇结晶沉积，肉芽组织形成）、鼓室硬化症（鼓膜和鼓室内钙化斑）、后天原发性胆脂瘤（鼓膜内陷袋形成）"],"diagnosis":["典型症状（耳闷、听力下降、耳鸣、自听增强）+耳镜检查（鼓膜内陷、积液征）","听力检查：纯音测听（传导性耳聋，听力损失一般10-40dB，以低频为主）、声导抗测试（重要诊断依据，B型鼓室图提示中耳积液，C型提示咽鼓管功能障碍）、耳声发射（儿童不配合纯音测听时）","颞骨CT（鼓膜不能窥清、怀疑鼻咽部病变、胆固醇肉芽肿、粘连性中耳炎时，可见鼓室和乳突内软组织影，无骨质破坏）","鼻咽部检查（排除鼻咽癌、腺样体肥大、鼻咽部肿瘤，成人单侧分泌性中耳炎必须检查鼻咽部，排除鼻咽癌）","排除脑脊液耳漏、外淋巴漏、粘连性中耳炎、鼓室硬化、胆固醇肉芽肿、鼻咽癌","病因检查：鼻腔鼻窦检查（鼻炎、鼻窦炎、鼻息肉）、腺样体检查（儿童腺样体肥大）、鼻咽部检查（成人排除鼻咽癌）、咽鼓管功能检查","病程分类：急性（病程<3周）、亚急性（3周-3个月）、慢性（>3个月）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1：","  用法：一般无需静脉输液；糠酸莫米松鼻喷雾剂 每侧2喷 喷鼻 qd；桉柠蒎肠溶软胶囊 0.3g 口服 tid；阿莫西林克拉维酸钾 0.625g 口服 tid（合并细菌感染时）","","方案2（合并急性感染）：","  用法：0.9%NS 100ml + 抗生素 ivgtt qd（根据病原选择）","","方案3（围手术期；鼓膜置管术）：","  用法：一般无需静脉抗生素，口服抗生素预防感染即可","","方案4：","  用法：合并鼻咽部肿瘤或其他全身疾病按相应方案治疗","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（急性期）：","用法：抗生素（头孢克肟0.2g bid、阿莫西林0.5g tid、阿奇霉素0.5g qd×3天），有细菌感染证据时使用，疗程5-7天〔调 CrCl<30 减量；青霉素过敏禁用〕","药物2（糖皮质激素）：","用法：泼尼松10mg tid 或 地塞米松0.75mg tid（短期3-5天，减轻黏膜水肿和炎症，促进积液吸收，注意禁忌证）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","药物3（促排剂）：","用法：桉柠蒎肠溶软胶囊0.3g tid、标准桃金娘油0.3g tid、氨溴索30mg tid（稀化黏液，促进纤毛运动，利于积液排出）〔调 妊娠早期禁用；胃溃疡者慎用〕","药物4（鼻用糖皮质激素）：","用法：布地奈德鼻喷雾剂、糠酸莫米松鼻喷雾剂、氟替卡松鼻喷雾剂（每日1-2次，减轻鼻腔和咽鼓管咽口黏膜水肿，改善咽鼓管功能，是基础治疗）","药物5（鼻用减充血剂）：","用法：羟甲唑啉滴鼻液、麻黄碱滴鼻液（短期使用，不超过7天，减轻咽鼓管咽口水肿，通畅引流，长期使用可致药物性鼻炎）","药物6（抗组胺药）：","用法：氯雷他定10mg qd、西替利嗪10mg qd（合并过敏性鼻炎时）〔调 肝功能/肾功能不全减量；妊娠哺乳慎用〕","药物7（白三烯受体拮抗剂）：","用法：孟鲁司特钠10mg qn（合并过敏性鼻炎、哮喘时）","药物8（中医中药）：","用法：宣肺通窍、利湿排脓（通窍鼻炎片、鼻炎康、鼻窦炎口服液），辨证使用","药物9（止痛）：","用法：布洛芬0.2g prn（耳痛明显时）〔调 ★ 肾功能不全禁用/慎用；活动性溃疡禁用；★ 妊娠晚期禁用〕","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["病因治疗：治疗鼻炎鼻窦炎（鼻用激素+鼻腔冲洗+抗生素）、腺样体肥大（腺样体切除术，儿童）、鼻咽癌（放疗，成人单侧）、变应性鼻炎（抗过敏治疗）、胃食管反流（抑酸治疗）","非手术治疗（急性期和病程<3个月）：鼻用糖皮质激素（基础治疗）+鼻用减充血剂（短期）+促排剂+口服激素（短期）+抗生素（有感染证据）+咽鼓管吹张（捏鼻鼓气法、波氏球法、导管吹张法，改善咽鼓管通气）+鼓膜按摩（鼓气耳镜或按压耳屏，促进鼓膜活动和积液排出）+鼻腔冲洗（生理盐水或高渗盐水，清洁鼻腔，减轻黏膜水肿）","手术治疗（病程>3个月、非手术治疗无效、听力下降明显、合并并发症）：鼓膜穿刺抽液（抽出积液，可注入糖皮质激素或α-糜蛋白酶，可重复）、鼓膜切开术（积液黏稠无法穿刺抽出时）、鼓膜置管术（最常用，在鼓膜上放置通气管，改善中耳通气引流，留置6-12个月，自行脱落或取出，适用于慢性分泌性中耳炎、积液黏稠、复发者）、腺样体切除术（儿童合并腺样体肥大，堵塞咽鼓管咽口，可与鼓膜置管同时进行）、扁桃体切除术（合并慢性扁桃体炎反复发作者）、鼓室探查术（怀疑胆固醇肉芽肿、粘连性中耳炎、鼓室硬化时）","并发症治疗：粘连性中耳炎（鼓室成形术+听骨链重建）、胆固醇肉芽肿（鼓室探查+清除肉芽+通气引流）、鼓室硬化症（鼓室成形术+清除硬化灶+听骨链重建）、后天原发性胆脂瘤（乳突手术）","儿童治疗：积极治疗腺样体肥大和鼻炎鼻窦炎；非手术治疗3个月无效者鼓膜置管；双侧分泌性中耳炎伴听力下降>20dB应尽早手术；注意言语发育评估，听力下降影响言语发育者及时干预","预防：积极治疗鼻炎鼻窦炎、腺样体肥大、变应性鼻炎；增强体质，预防上呼吸道感染；正确擤鼻（一侧一侧擤）；避免用力擤鼻；乘坐飞机或潜水时做吞咽、咀嚼动作，保持咽鼓管通畅；婴幼儿避免平卧位喂奶（防止乳汁经咽鼓管进入中耳）","随访：治疗后定期复查（耳镜、声导抗、听力），观察积液吸收和听力恢复；鼓膜置管者定期复查通气管位置和通畅情况，脱落后评估中耳功能；慢性者长期随访防止并发症"],"management":["鼻腔护理：用生理盐水或高渗盐水冲洗鼻腔（每日1-2次），清洁鼻腔分泌物，减轻黏膜水肿；正确擤鼻（一侧一侧擤，不要两侧同时用力，防止分泌物经咽鼓管进入中耳）；避免用力擤鼻和挖鼻","用药护理：按医嘱使用鼻用糖皮质激素（每日1-2次，喷头朝向鼻腔外侧壁，避免直接喷向鼻中隔，长期使用注意鼻出血）；鼻用减充血剂不超过7天（长期使用可致药物性鼻炎）；促排剂饭前半小时服用（桉柠蒎、桃金娘油）；口服激素短期使用，不可长期服用；观察药物疗效和副作用","咽鼓管吹张：指导患者捏鼻鼓气法（深吸气后捏住鼻子、闭紧嘴巴，轻轻向鼻腔鼓气，感觉耳内有进气感即可，不要用力过猛，避免鼓膜穿孔）；波氏球法（用波氏球塞入一侧鼻孔，捏紧另一侧鼻孔，挤压球囊，空气经咽鼓管进入中耳）；急性上呼吸道感染时不要吹张（防止感染进入中耳）","鼓膜按摩：用鼓气耳镜或按压耳屏（反复按压耳屏，使外耳道压力变化，促进鼓膜活动和积液排出），每日2-3次，每次1-2分钟","病情观察：观察耳闷、听力下降、耳鸣变化；观察儿童听力和言语发育情况（对声音反应、说话清晰度、学习成绩）；观察有无并发症征象（耳痛加重、发热、眩晕、面瘫）；治疗后复查耳镜、声导抗、听力，评估疗效；出现听力骤降、耳痛、发热、眩晕及时就医","饮食：清淡易消化饮食，多饮水，多吃新鲜蔬果；避免辛辣刺激、油腻、烟酒；合并过敏性鼻炎者避免过敏原和致敏食物；婴幼儿避免平卧位喂奶","休息与活动：保证充足睡眠，避免熬夜和过度劳累；急性发作时适当休息；避免乘坐飞机和潜水（气压变化可能加重不适，必要时用鼻用减充血剂保持咽鼓管通畅，飞行时做吞咽咀嚼动作）；避免用力擤鼻和剧烈运动","个人卫生：勤洗手，预防上呼吸道感染；避免接触过敏原（合并过敏性鼻炎者）；毛巾脸盆个人专用；儿童注意玩具和手部卫生","心理护理：安慰患者，解释疾病性质和治疗方法，消除焦虑；儿童家长给予疾病知识指导，告知听力下降可能影响学习和言语发育，及时治疗的重要性；需手术患者解释手术目的和过程，减轻恐惧","健康教育：讲解分泌性中耳炎的病因（咽鼓管功能障碍最主要）、症状和危害（儿童可影响言语发育和学习，长期不愈可致粘连性中耳炎、胆脂瘤）；强调治疗鼻炎鼻窦炎和腺样体肥大的重要性；指导正确擤鼻和咽鼓管吹张方法；告知鼻用减充血剂不超过7天；儿童定期听力筛查，发现听力下降及时就医；成人单侧分泌性中耳炎必须检查鼻咽部，排除鼻咽癌；术后定期复查；增强体质，预防上呼吸道感染；婴幼儿避免平卧位喂奶","家庭护理：家属协助儿童鼻腔冲洗和用药；观察儿童听力和言语发育情况；陪同定期复查；术后注意耳道护理，避免进水和挖耳；鼓膜置管者避免游泳（除非戴耳塞），避免耳道进水"],"notes":["分泌性中耳炎（OME）又称渗出性中耳炎、卡他性中耳炎、非化脓性中耳炎、浆液性中耳炎、黏液性中耳炎，是以中耳积液（浆液性、黏液性或混合性）和听力下降为特征的中耳非化脓性炎性疾病，是耳鼻喉常见病，儿童发病率高于成人，是儿童致聋和影响言语发育的常见原因","病因：咽鼓管功能障碍（最主要，机械性阻塞如腺样体肥大、慢性鼻炎鼻窦炎、鼻息肉、鼻咽部肿瘤；功能性障碍如咽鼓管开闭肌肉无力、软骨弹性差、咽鼓管黏膜水肿）、感染（细菌如流感嗜血杆菌、肺炎链球菌，病毒如呼吸道合胞病毒，多为低毒性感染或细菌生物膜）、免疫反应（Ⅰ型和Ⅲ型变态反应，与过敏性鼻炎、哮喘相关）、胃食管反流（反流物经咽鼓管进入中耳）、气压损伤（飞行、潜水）","好发人群：儿童（咽鼓管短、平、宽，咽鼓管软骨弹性差，腺样体肥大，免疫力低，易患上呼吸道感染）、腭裂患儿（咽鼓管功能障碍）、老年人（咽鼓管功能减退）、过敏性鼻炎患者、鼻咽癌患者（肿瘤堵塞咽鼓管咽口）","临床表现：耳闷胀感（最常见）、听力下降（传导性，随体位变化，自听增强）、耳鸣（低调，气过水声）、耳痛（轻微或无）；儿童表现不典型，可表现为听话迟钝、注意力不集中、学习成绩下降、看电视音量大、对声音反应差、婴幼儿抓耳哭闹","耳镜表现：鼓膜内陷（光锥缩短变形消失、锤骨柄后上移位、锤骨短突外突）、鼓膜色泽改变（淡红、橙红、琥珀、灰蓝）、液平面（发丝状，凹面向上，随头位移动）、气泡（打哈欠或捏鼻鼓气后可见气泡）、鼓膜活动度差（鼓气耳镜检查）","声导抗：B型鼓室图（平坦型，提示中耳积液，是分泌性中耳炎的典型表现）、C型鼓室图（负压型，提示咽鼓管功能障碍，中耳负压）、As型（僵硬型，提示鼓室硬化或听骨链固定）、Ad型（超限型，提示鼓膜萎缩或听骨链中断）；声反射消失","纯音测听：传导性耳聋，听力损失一般10-40dB，以低频为主，积液排出后听力可恢复；长期不愈可致感音神经性聋（毒素吸收）","治疗原则：病因治疗+非手术治疗（鼻用激素+减充血剂+促排剂+激素+咽鼓管吹张），病程<3个月；非手术治疗无效或病程>3个月手术治疗（鼓膜穿刺/切开/置管+腺样体切除）","鼓膜置管术：是慢性分泌性中耳炎最常用的手术方式，在鼓膜前下或后下象限放置通气管（T型管、哑铃型管），改善中耳通气引流，留置6-12个月，多数自行脱落，脱落后鼓膜多可愈合；适应证：病程>3个月非手术治疗无效、双侧积液伴听力下降>20dB、复发者、积液黏稠、合并并发症；术后注意避免耳道进水（游泳、洗澡），定期复查通气管位置","儿童分泌性中耳炎：是儿童常见病，70%儿童3岁前至少患过一次，多数可自愈，但反复发作或长期不愈可影响言语发育和学习；美国儿科学会指南：单侧或双侧OME观察3个月，听力下降>20dB或有言语发育迟缓者手术；腺样体肥大堵塞咽鼓管咽口者同时腺样体切除","成人单侧分泌性中耳炎：必须详细检查鼻咽部，排除鼻咽癌（鼻咽癌可堵塞咽鼓管咽口引起分泌性中耳炎，是鼻咽癌的常见首发症状之一），尤其是伴回吸涕中带血、鼻塞、颈部淋巴结肿大者，必须行鼻咽镜和鼻咽部CT/MRI检查","并发症：粘连性中耳炎（长期不愈，鼓膜与鼓岬粘连，听骨链固定，听力损失重，治疗困难）、胆固醇肉芽肿（积液中胆固醇结晶沉积，刺激肉芽组织形成，鼓膜呈蓝黑色，需手术）、鼓室硬化症（鼓膜和鼓室内钙盐沉积，形成硬化斑，影响鼓膜和听骨链活动）、后天原发性胆脂瘤（鼓膜内陷袋形成，角化上皮堆积，侵蚀骨质）","预后：多数预后良好，急性期非手术治疗可痊愈；慢性者鼓膜置管后听力多可恢复；长期不愈或反复发作者可致粘连性中耳炎、胆脂瘤等并发症，影响听力；儿童长期听力下降可影响言语发育和学习，需重视","预防：积极治疗鼻炎鼻窦炎、腺样体肥大、变应性鼻炎；增强体质，预防上呼吸道感染；正确擤鼻（一侧一侧擤，不要两侧同时用力）；避免用力擤鼻；乘坐飞机或潜水时做吞咽、咀嚼动作，保持咽鼓管通畅；婴幼儿避免平卧位喂奶（防止乳汁经咽鼓管进入中耳）；腭裂患儿早期干预；儿童定期听力筛查","我国现状：儿童分泌性中耳炎发病率高，但家长认知度低，很多患儿因听力下降影响学习才就诊，需加强儿童听力筛查和家长健康教育"],"emergency":["出现耳痛剧烈、发热、头痛（急性化脓性中耳炎或合并感染，及时就医）","出现听力骤降、眩晕、恶心呕吐（合并内耳损伤或迷路炎，立即就医）","出现面瘫、口角歪斜（面神经受累，立即就医）","成人单侧分泌性中耳炎伴回吸涕中带血、鼻塞、颈部淋巴结肿大（排除鼻咽癌，尽快鼻咽镜检查）","儿童出现对声音无反应、言语发育迟缓、学习成绩明显下降（听力下降严重，尽快就医评估和干预）","鼓膜置管术后出现耳道大量流脓、耳痛、发热（通气管感染或急性中耳炎，及时就医）","出现耳内大量出血（颈静脉球瘤或骨质破坏，立即就医）","乘坐飞机后出现剧烈耳痛、听力下降、眩晕（气压损伤性中耳炎，及时就医）"],"pinyin":"fenmixingzhongeryan","icd10":"H65.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态、面容","耳部：耳廓（畸形/红肿/皮疹/瘘管）、外耳道（耵聍/异物/分泌物/红肿/狭窄/闭锁）、鼓膜（标志/充血/内陷/穿孔/钙化/液平/肉芽）、乳突（红肿/压痛）、听力（耳语/音叉试验：Rinne试验/Weber试验/Schwabach试验）、前庭功能（自发性眼震/位置试验）","鼻部：外鼻（畸形/红肿）、鼻前庭（红肿/疖肿/结痂）、鼻腔（鼻中隔偏曲/糜烂/出血/穿孔、下鼻甲肿大/息肉样变、中鼻甲息肉样变/气化、鼻道分泌物（黏脓/血性/水样）、息肉/新生物）、鼻窦（压痛：额窦/上颌窦/筛窦）、后鼻孔检查","咽喉部：口咽（黏膜充血/肿胀/溃疡、扁桃体大小（Ⅰ-Ⅳ度）/充血/隐窝脓栓/结石、咽后壁淋巴滤泡增生/脓性分泌物、悬雍垂水肿/偏斜、软腭运动）、喉咽（会厌充血/水肿/囊肿、杓状会厌襞、梨状窝新生物/积液）、喉部（间接喉镜/电子喉镜：声带充血/息肉/小结/麻痹/新生物、室带肥厚、声门闭合情况）","颈部：淋巴结肿大（部位/大小/质地/活动度/压痛）、甲状腺、包块、瘘管","其他：发音（声嘶/失声）、吞咽（困难/呛咳）、呼吸（喘鸣/呼吸困难）"],"lab_tests":["耳内镜检查（耳镜+鼓气耳镜）：观察鼓膜内陷、光锥消失、液平面及气泡征，鼓气时鼓膜活动度减弱，提示中耳积液","声导抗测试（鼓室导抗图）：呈B型（平坦型）曲线提示中耳积液，病程中动态复查以评估疗效","纯音听阈测试（纯音测听）：明确传导性听力损失程度，治疗后复查对比","鼻内镜检查：检查鼻腔、咽鼓管咽口及腺样体（儿童）；成人单侧反复积液者须检查鼻咽部，排除鼻咽部占位病变","颞骨高分辨率CT：病程超过3个月、保守治疗无效或疑有并发症（鼓室硬化、胆脂瘤）时检查","必要时行鼓膜穿刺抽液（兼具诊断与治疗）：积液送细菌培养及细胞学检查，除外感染及少见病变"],"nursing":["病情观察：监测耳闷胀感、听力下降有无加重，有无耳痛、耳流脓、眩晕、头痛，警惕继发急性化脓性中耳炎或并发症","术后护理（鼓膜切开或置管后）：保持外耳道干燥，洗头、沐浴时用干棉球或防水耳塞保护耳道，勿挖耳，避免水及污染液进入中耳","正确擤鼻与咽鼓管锻炼：单侧交替、轻柔擤鼻，避免双侧同时用力擤鼻；鼓膜完整者在医师指导下行捏鼻鼓气法（Valsalva）或反复吞咽、咀嚼以促进咽鼓管开放引流","体位与防误吸：全麻术后去枕平卧、头偏向一侧，清醒后半卧位进食；婴幼儿喂奶时抬高头部、少量多次，防止呛奶后经咽鼓管逆行感染"],"diet":["清淡饮食，忌辛辣、油腻、烟酒及过冷过热食物，减轻鼻咽部黏膜充血水肿","全麻手术（如鼓膜置管）术后：禁食禁饮6小时，先试饮少量温水，无恶心呕吐后再进半流质、软食","推荐高蛋白、富含维生素饮食：鱼、虾、蛋、瘦肉、豆制品及新鲜蔬果，增强机体抵抗力","进食细嚼慢咽、避免呛咳；有食物过敏史者避开致敏食物（如海鲜、牛奶等），合并过敏性鼻炎者尤需注意","多饮水，保持大便通畅，避免用力排便增加咽鼓管及中耳压力"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":395},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"285abc9dc8cb7c4927255fb401d42581d984a5c3305eef6c3cfb46133a8331e0","pinyin":"fenmixingzhongeryan","initials":"fmxzey","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","听力下降：传导性耳聋，程度不一，可随体位变化（卧位时听力改善，立位时下降，因积液离开蜗窗），自听增强（听自己说话声音变大，有回声）\\n耳闷胀感：耳内堵塞感、闷胀感，按压耳屏后可暂时减轻\\n耳鸣：低调间歇性耳鸣，如嗡嗡声、流水声，打哈欠、擤鼻时耳内可有气过水声\\n耳痛：一般不明显，或仅有轻微耳痛，急性发作时可有耳痛\\n儿童表现：听话迟钝、注意力不集中、学习成绩下降、看电视音量大、对声音反应差、婴幼儿抓耳、哭闹、睡眠不安\\n耳镜检查：鼓膜内陷（光锥缩短、变形或消失，锤骨柄向后上移位，锤骨短突明显外突）、鼓膜色泽改变（淡红色、橙红色、琥珀色、灰蓝色）、鼓室积液征（透过鼓膜可见液平面或气泡，液平面随头位变动而移动）、鼓膜活动度差（鼓气耳镜检查鼓膜活动受限）\\n并发症：粘连性中耳炎（长期不愈，鼓膜与鼓岬粘连）、胆固醇肉芽肿（积液中胆固醇结晶沉积，肉芽组织形成）、鼓室硬化症（鼓膜和鼓室内钙化斑）、后天原发性胆脂瘤（鼓膜内陷袋形成）",60],["摘要","又称渗出性中耳炎、卡他性中耳炎、非化脓性中耳炎，是以中耳积液和听力下降为特征的中耳非化脓性炎性疾病，多因咽鼓管功能障碍、感染、免疫反应引起，表现为耳闷、听力下降、耳鸣、耳痛，儿童多见，是儿童致聋的常见原因。",30],["疾病编码","H65.9",30],["原首字母","fenmixingzhongeryan",60]]},{"id":"orders-a1e38495d7bf44b7a4f5","key":"v1-c9ccc21dfe2a3058|orders-a1e38495d7bf44b7a4f5","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"良性阵发性位置性眩晕（耳石症）","category":"耳鼻喉","raw":{"name":"良性阵发性位置性眩晕（耳石症）","category":"耳鼻喉","summary":"又称耳石症，是头部运动到某一特定位置时诱发的短暂阵发性眩晕，伴眼震，是最常见的外周性前庭疾病，多因耳石脱落进入半规管引起，手法复位效果好。","symptoms":["眩晕：头部位置变化时（起床、躺下、翻身、低头、仰头）突然出现短暂旋转性眩晕，持续数秒至数十秒（一般<1分钟），伴视物旋转","眼震：眩晕发作时伴特征性眼震（水平扭转性或垂直性），方向与受累半规管有关","恶心呕吐：眩晕发作时可伴恶心、呕吐、出冷汗、心慌","平衡障碍：发作间期可有不稳感、平衡障碍","一般无听力下降、耳鸣（与梅尼埃病区别）","无头痛、意识障碍（与中枢性眩晕区别）","可反复发作，疲劳现象（反复诱发后眩晕减轻）","常见诱发体位：起床、躺下、床上翻身、低头捡东西、仰头看天","后半规管BPPV最常见（占80-90%），眩晕在悬头位或侧卧患耳向下时诱发；水平半规管BPPV（占10-15%），眩晕在仰卧转头时诱发；前半规管BPPV少见（<5%）"],"diagnosis":["典型病史（头部位置变化诱发短暂眩晕，持续<1分钟，反复发作）+位置试验阳性","Dix-Hallpike试验（诊断后半规管和前半规管BPPV的金标准：患者坐位，头向一侧转45°，迅速仰卧悬头位，观察眼震和眩晕；阳性表现为潜伏期数秒后出现旋转性眩晕和扭转性眼震，持续<1分钟，恢复坐位时再次出现反向眼震，反复诱发有疲劳现象）","滚转试验（Roll test，诊断水平半规管BPPV：患者仰卧位，头前倾30°，迅速向一侧转头90°，观察眼震；阳性表现为水平性眼震，向患侧转头时眼震向地性且强度大，向健侧转头时眼震背地性且强度小）","前庭功能检查（冷热试验、旋转试验，评估前庭功能，部分患者患侧半规管功能减退）","听力检查（纯音测听，一般正常，排除其他耳病）","排除梅尼埃病（眩晕持续20分钟至数小时，伴听力下降、耳鸣、耳闷）、前庭神经炎（眩晕持续数天，无位置性，伴前庭功能丧失）、突发性耳聋（眩晕伴听力骤降）、中枢性眩晕（脑干小脑病变，眩晕持续，伴神经系统体征，眼震方向不固定，无疲劳现象）、颈椎病（颈性眩晕，伴颈部疼痛和上肢症状）、体位性低血压（站立时头晕，非旋转性，伴血压下降）","分型：按受累半规管分为后半规管BPPV（最常见）、水平半规管BPPV、前半规管BPPV、混合型BPPV；按病因分为特发性（占50-70%，原因不明）和继发性（继发于头部外伤、病毒性神经炎、梅尼埃病、突发性耳聋、耳部手术、长期卧床等）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般无需静脉输液；手法复位（Epley法）；甲磺酸倍他司汀 6mg 口服 tid；氟桂利嗪 5mg 口服 qn","方案2（眩晕剧烈、恶心呕吐严重不能进食）：","用法：0.9%NS或5%GNS ivgtt，维持水电解质平衡；甲氧氯普胺10mg im 或 昂丹司琼8mg iv 止吐〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","方案3：","用法：合并其他疾病按相应方案治疗","方案4：","用法：手法复位后一般无需输液","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（急性期（眩晕剧烈、恶心呕吐））：","用法：前庭抑制剂（异丙嗪25mg im、地芬尼多25mg tid等；注：倍他司汀6-12mg tid为改善内耳微循环、促前庭代偿药，并非前庭抑制剂，急性止晕不用，宜于缓解期使用），短期使用（不超过3天，长期使用可抑制前庭代偿，延长恢复）；止吐药（甲氧氯普胺10mg im、昂丹司琼8mg）","药物2（缓解期）：","用法：改善微循环和前庭代偿（倍他司汀6-12mg tid、银杏叶提取物40mg tid、氟桂利嗪5mg qn），促进前庭功能恢复","药物3（抗焦虑）：","用法：地西泮2.5mg tid（短期，焦虑明显时）〔调 ★ 肝功能不全及老年减量；呼吸功能不全慎用；妊娠禁用〕","药物4（营养神经）：","用法：甲钴胺0.5mg tid、维生素B1 10mg tid（继发性或伴神经损伤时）","药物5（中医中药）：","用法：平肝熄风、化痰祛湿（天麻钩藤颗粒、半夏天麻丸、眩晕宁片），辨证使用","药物6（注意）：","用法：药物只是辅助，手法复位才是根本治疗，不可长期依赖前庭抑制剂","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["手法复位（首选，根本治疗）：根据受累半规管选择不同复位手法——Epley法（后半规管BPPV，通过头位变化使耳石从后半规管回到椭圆囊，成功率80-90%）、Barbecue翻滚法（水平半规管BPPV，向地性眼震型，通过仰卧位连续向健侧翻滚360°使耳石回到椭圆囊）、Gufoni法（水平半规管BPPV，背地性眼震型，侧卧患耳向下然后头向下转45°）、Semont法（后半规管BPPV，快速向健侧侧卧然后头向下转45°再向患侧侧卧，适用于Epley法无效或颈椎活动受限者）、Yacovino法（前半规管BPPV）；复位后保持头直立位24-48小时，避免剧烈活动和患耳向下侧卧，必要时戴颈托；一次复位成功率70-80%，无效者可重复复位（间隔1-2天），多次复位无效者重新评估诊断","家庭复位：指导患者在家自行复位（Epley法简化版），适用于反复发作、诊断明确者，但首次复位应在医院由医生操作确认","药物治疗：急性期短期前庭抑制剂止晕止吐，缓解期改善微循环促进前庭代偿，药物只是辅助，不能替代复位","手术治疗：顽固性BPPV（手法复位无效，病程>1年，严重影响生活）可行半规管阻塞术、前庭神经切断术（极少需要）","康复训练：前庭康复训练（Brandt-Daroff练习，每日2组，每组10次，通过反复体位刺激促进前庭适应和代偿，适用于复位后仍有不稳感或复发者）","病因治疗：继发性BPPV治疗原发病（头部外伤、梅尼埃病、突发性耳聋、病毒性神经炎）","预防：避免头部外伤；避免长期卧床（鼓励早期活动）；积极治疗耳部疾病；老年人起床翻身动作缓慢，避免突然头位变化；补充维生素D和钙（骨质疏松者BPPV发病率高）","随访：复位后1周复查，评估疗效，无效者再次复位；复发者重新评估分型和复位；多数预后良好，复发率约15-20%/年"],"management":["急性期护理：眩晕发作时立即坐下或躺下，避免跌倒受伤；保持环境安静，避免强光和噪音刺激；恶心呕吐时侧卧，防止误吸；暂禁食水，呕吐严重时静脉补液；观察眩晕持续时间、诱发体位、伴随症状（有无听力下降、耳鸣、头痛、意识障碍），与中枢性眩晕鉴别","复位后护理：复位后保持头直立位24-48小时，避免低头、仰头、剧烈转头、跳跃；避免患耳向下侧卧（可仰卧或健侧卧位）；睡觉时垫高枕头；必要时戴颈托限制颈部活动；复位后可能有短暂不稳感、头昏，属正常，逐渐恢复；避免驾驶和高空作业（复位后1-2天）","用药护理：按医嘱短期使用前庭抑制剂（不超过3天），不可长期使用（抑制前庭代偿，延长恢复）；观察药物副作用（异丙嗪嗜睡、口干，地芬尼多嗜睡、口干，氟桂利嗪嗜睡、体重增加、抑郁）；改善微循环药物按时服用；呕吐严重时按医嘱用止吐药","病情观察：观察眩晕发作频率、持续时间、诱发体位变化；观察有无听力下降、耳鸣（排除梅尼埃病、突发性耳聋）；观察有无头痛、肢体无力、言语不清、意识障碍（中枢性眩晕征象，立即就医）；复位后观察疗效（是否还有位置性眩晕）；出现中枢性眩晕征象或眩晕持续不缓解及时就医","饮食：清淡易消化饮食，多饮水，避免辛辣刺激、油腻、烟酒；呕吐严重时暂禁食，静脉补液；避免过饱（防止呕吐）；适当补充维生素D和钙（骨质疏松者）","休息与活动：急性期卧床休息，避免剧烈活动和突然头位变化；缓解期适当活动，促进前庭代偿；避免长期卧床（可加重BPPV和前庭功能减退）；起床翻身动作缓慢，先坐起适应再站立；避免低头捡东西、仰头看天等诱发体位；避免驾驶、高空作业、游泳（眩晕发作期和复位后1-2天）","个人卫生：保持环境整洁，地面防滑（防止眩晕发作时跌倒）；床栏拉起（急性期）；夜间留灯（方便起床）；避免穿滑底鞋","心理护理：安慰患者，解释BPPV是良性疾病，预后好，手法复位效果好，消除焦虑恐惧；眩晕发作时患者易紧张，给予安抚；指导患者避免诱发体位，减少发作；复发患者给予心理支持，告知复发率和应对方法","健康教育：讲解BPPV的病因（耳石脱落进入半规管）、典型表现（头位变化诱发短暂眩晕<1分钟）、诊断方法（位置试验）和治疗（手法复位是首选和根本，药物只是辅助）；指导患者识别诱发体位，避免突然头位变化；指导复位后注意事项（保持头直立位、避免剧烈活动）；指导家庭复位方法（诊断明确、反复发作时）；告知前庭抑制剂不可长期使用；出现眩晕持续不缓解、听力下降、头痛、肢体无力、意识障碍及时就医（排除中枢性眩晕和其他耳病）；老年人起床翻身动作缓慢，防止跌倒；适当补充维生素D和钙；定期复查，复发及时复位","家庭护理：家属了解疾病知识，眩晕发作时协助患者坐下或躺下，防止跌倒；复位后协助患者保持头直立位，避免剧烈活动；观察病情变化，出现中枢性眩晕征象及时就医；陪同定期复查；家庭环境防滑防跌倒"],"notes":["良性阵发性位置性眩晕（BPPV）又称耳石症，是头部运动到某一特定位置时诱发的短暂阵发性眩晕，伴特征性眼震，是最常见的外周性前庭疾病，约占所有眩晕的20-30%，占外周性眩晕的50%以上","发病机制：耳石（碳酸钙结晶，正常附着于椭圆囊和球囊的耳石膜上）因变性、外伤、感染等原因脱落，进入半规管（后半规管最常见，因位置最低），头部位置变化时耳石在半规管内移动，带动内淋巴流动，刺激壶腹嵴毛细胞，引起眩晕和眼震；耳石移动到新位置后停止刺激，眩晕缓解，故呈短暂性","分型：按受累半规管分——后半规管BPPV（最常见，占80-90%，悬头位或患耳向下侧卧时诱发，眼震为扭转性，向患耳）、水平半规管BPPV（占10-15%，仰卧转头时诱发，眼震为水平性，分向地性和背地性）、前半规管BPPV（少见，<5%，悬头位时诱发，眼震为垂直扭转性）、混合型BPPV（多个半规管受累）；按病因分——特发性（50-70%，原因不明，可能与耳石退化、骨质疏松、维生素D缺乏有关）、继发性（头部外伤、病毒性前庭神经炎、梅尼埃病、突发性耳聋、耳部手术、长期卧床、中耳炎等）","好发人群：中老年人（40-60岁多见，耳石退化）、女性（约2:1）、骨质疏松者（维生素D缺乏）、头部外伤者、长期卧床者、耳部疾病患者","临床表现：头部位置变化（起床、躺下、翻身、低头、仰头）时突然出现短暂旋转性眩晕，持续数秒至数十秒（一般<1分钟），伴眼震、恶心呕吐、出冷汗；发作间期可有不稳感；一般无听力下降、耳鸣、头痛；反复发作；疲劳现象（反复诱发后眩晕减轻）","Dix-Hallpike试验：诊断后半规管和前半规管BPPV的金标准；患者坐位，头向一侧转45°，迅速仰卧悬头位（头低于床面30°），观察眼震和眩晕；阳性：潜伏期3-5秒后出现旋转性眩晕和扭转性眼震（后半规管BPPV眼震向患耳，前半规管BPPV眼震向健耳），持续<1分钟，恢复坐位时再次出现反向眼震，反复诱发有疲劳现象；阴性：无眼震和眩晕","滚转试验（Roll test）：诊断水平半规管BPPV；患者仰卧位，头前倾30°，迅速向一侧转头90°，观察眼震；向地性眼震型（管结石症，向患侧转头时眼震向地且强）、背地性眼震型（嵴帽结石症，向患侧转头时眼震背地且强）","治疗原则：手法复位是首选和根本治疗（Epley法、Barbecue法、Gufoni法、Semont法等），药物只是辅助（急性期短期止晕止吐），手术极少需要（顽固性BPPV）","Epley法：治疗后半规管BPPV最常用手法；患者坐位，头向患侧转45°→迅速仰卧悬头位（保持30秒至眼震消失）→头向对侧转90°（保持30秒）→身体和头同时向对侧转90°呈侧卧头向下45°位（保持30秒）→缓慢坐起头前倾30°；通过头位变化使耳石从后半规管经总脚回到椭圆囊；一次成功率70-80%，无效可重复","复位后注意：保持头直立位24-48小时，避免低头、仰头、剧烈转头、跳跃；避免患耳向下侧卧；睡觉时垫高枕头；必要时戴颈托；复位后可能有短暂不稳感、头昏，属正常；1-2天内避免驾驶和高空作业","预后：良性疾病，预后好，手法复位有效率80-90%；部分患者复位后有短暂不稳感，数天至数周恢复；复发率约15-20%/年，5年复发率约50%；复发后再次复位仍有效；极少数顽固性BPPV需手术","与中枢性眩晕鉴别：中枢性眩晕（脑干、小脑病变）眩晕持续时间长（数小时至数天），无位置性或位置性不典型，眼震方向不固定、无疲劳现象，伴神经系统体征（肢体无力、共济失调、言语不清、吞咽困难、意识障碍），可伴头痛；BPPV眩晕短暂（<1分钟）、位置性、眼震有疲劳现象、无神经系统体征；中枢性眩晕是急症，需及时影像学检查（头颅CT/MRI）","预防：避免头部外伤；避免长期卧床（鼓励早期活动）；积极治疗耳部疾病；老年人起床翻身动作缓慢，避免突然头位变化；适当补充维生素D和钙（骨质疏松者）；反复发作患者学会家庭复位方法","我国现状：BPPV是临床最常见的眩晕疾病，但很多患者被误诊为颈椎病、脑供血不足、梅尼埃病，延误治疗，需加强眩晕诊疗规范化培训，推广位置试验和手法复位"],"emergency":["出现眩晕持续不缓解（>数小时）、伴剧烈头痛、呕吐（排除中枢性眩晕，如脑出血、脑梗死，立即就医，头颅CT/MRI）","出现眩晕伴肢体无力、麻木、言语不清、吞咽困难、共济失调、意识障碍（中枢性眩晕，脑干小脑病变，立即急诊）","出现眩晕伴听力骤降、耳鸣、耳闷（突发性耳聋或梅尼埃病，及时就医，突发性耳聋需尽早治疗）","出现眩晕伴发热、头痛、颈部抵抗（颅内感染，立即就医）","手法复位后出现剧烈颈痛、肢体麻木无力（颈椎损伤或椎动脉受压，立即就医）","出现眩晕伴严重呕吐、脱水、不能进食（静脉补液支持，及时就医）","老年人眩晕发作时跌倒（评估有无外伤、骨折，及时就医）","出现首次发作的眩晕、诊断不明确（及时就医，排除中枢性眩晕和其他严重疾病）"],"pinyin":"liangxingzhenfaxingweizhixingxuanyun（ershizheng）","icd10":"H81.1","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态、面容","耳部：耳廓（畸形/红肿/皮疹/瘘管）、外耳道（耵聍/异物/分泌物/红肿/狭窄/闭锁）、鼓膜（标志/充血/内陷/穿孔/钙化/液平/肉芽）、乳突（红肿/压痛）、听力（耳语/音叉试验：Rinne试验/Weber试验/Schwabach试验）、前庭功能（自发性眼震/位置试验）","鼻部：外鼻（畸形/红肿）、鼻前庭（红肿/疖肿/结痂）、鼻腔（鼻中隔偏曲/糜烂/出血/穿孔、下鼻甲肿大/息肉样变、中鼻甲息肉样变/气化、鼻道分泌物（黏脓/血性/水样）、息肉/新生物）、鼻窦（压痛：额窦/上颌窦/筛窦）、后鼻孔检查","咽喉部：口咽（黏膜充血/肿胀/溃疡、扁桃体大小（Ⅰ-Ⅳ度）/充血/隐窝脓栓/结石、咽后壁淋巴滤泡增生/脓性分泌物、悬雍垂水肿/偏斜、软腭运动）、喉咽（会厌充血/水肿/囊肿、杓状会厌襞、梨状窝新生物/积液）、喉部（间接喉镜/电子喉镜：声带充血/息肉/小结/麻痹/新生物、室带肥厚、声门闭合情况）","颈部：淋巴结肿大（部位/大小/质地/活动度/压痛）、甲状腺、包块、瘘管","其他：发音（声嘶/失声）、吞咽（困难/呛咳）、呼吸（喘鸣/呼吸困难）"],"lab_tests":["变位诱发试验（Dix-Hallpike试验、滚转试验，配合视频眼震图VNG记录）——确诊及定位受累半规管与侧别的金标准，复位治疗前后均应评估眼震变化","耳内镜检查——复位前常规检查，排除外耳道耵聍、鼓膜穿孔、分泌性中耳炎等可致眩晕的局部病变","纯音听阈测定（纯音测听）——伴耳鸣或听力下降时必查，用于鉴别梅尼埃病、突发性耳聋伴眩晕","头颅MRI（含内听道薄层扫描）——反复发作、复位疗效不佳或疑中枢性眩晕时行，排除小脑脑干梗死、听神经瘤等","前庭诱发肌源电位（VEMP）——可选，评估耳石器（球囊/椭圆囊）功能，复位后残留不稳感时协助判断残余功能损害"],"nursing":["体位护理——复位治疗时按医嘱协助患者快速变位（Epley法/Semont法等），每体位停留至眼震消失后约30s；复位后24-48h内避免低头、仰头、快速转头，睡眠时抬高床头30°-45°或取健侧卧位，防止耳石再脱落","病情观察——记录眩晕发作诱因、持续时间及伴随症状（恶心呕吐、耳鸣、听力变化），关注复位后迟发性眩晕；若出现剧烈头痛、言语含糊、肢体无力等中枢症状立即报告医师","防跌倒坠床——眩晕发作期嘱绝对卧床，拉起床栏，起床如厕遵循\"慢起、先坐片刻、再站立\"三步法，必要时专人搀扶","防误吸护理——复位过程或眩晕伴呕吐时嘱头偏向一侧，床旁备污物容器与吸引装置，呕吐后协助漱口、观察有无呛咳","健康宣教——告知耳石症为良性自限性疾病，减轻焦虑；教会患者识别复发征象（晨起翻身诱发短暂旋转感）及居家半规管自我复位方法"],"diet":["低盐饮食——每日食盐摄入控制在5g以下，减轻内淋巴水肿，利于前庭症状缓解","忌刺激性饮食——禁浓茶、咖啡、酒精及辛辣食物，避免诱发或加重眩晕发作","推荐高蛋白及B族维生素食物——鱼、蛋、瘦肉、豆制品及新鲜蔬果，营养神经、促进前庭功能恢复","清淡易消化、少食多餐——眩晕伴恶心呕吐时以粥、烂面条、蒸蛋羹等半流质为主，避免过饱；呕吐明显者注意补充水分与电解质，必要时静脉补液"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":396},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"07539c3c188937c3925208ebd93ada560ecbb1a1cedfd6fe07190574b9a892a9","pinyin":"liangxingzhenfaxingweizhixingxuanyun（ershizheng）","initials":"lxzfxwzxxy（esz）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","眩晕：头部位置变化时（起床、躺下、翻身、低头、仰头）突然出现短暂旋转性眩晕，持续数秒至数十秒（一般<1分钟），伴视物旋转\\n眼震：眩晕发作时伴特征性眼震（水平扭转性或垂直性），方向与受累半规管有关\\n恶心呕吐：眩晕发作时可伴恶心、呕吐、出冷汗、心慌\\n平衡障碍：发作间期可有不稳感、平衡障碍\\n一般无听力下降、耳鸣（与梅尼埃病区别）\\n无头痛、意识障碍（与中枢性眩晕区别）\\n可反复发作，疲劳现象（反复诱发后眩晕减轻）\\n常见诱发体位：起床、躺下、床上翻身、低头捡东西、仰头看天\\n后半规管BPPV最常见（占80-90%），眩晕在悬头位或侧卧患耳向下时诱发；水平半规管BPPV（占10-15%），眩晕在仰卧转头时诱发；前半规管BPPV少见（<5%）",60],["摘要","又称耳石症，是头部运动到某一特定位置时诱发的短暂阵发性眩晕，伴眼震，是最常见的外周性前庭疾病，多因耳石脱落进入半规管引起，手法复位效果好。",30],["疾病编码","H81.1",30],["原首字母","liangxingzhenfaxingweizhixingxuanyun（ershizheng）",60]]},{"id":"orders-cbeab96881b828a074d0","key":"v1-c9ccc21dfe2a3058|orders-cbeab96881b828a074d0","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"慢性鼻炎","category":"耳鼻喉","raw":{"name":"慢性鼻炎","category":"耳鼻喉","summary":"鼻腔黏膜和黏膜下层的慢性炎症，表现为鼻塞、流涕、嗅觉减退、头痛等，分为慢性单纯性鼻炎和慢性肥厚性鼻炎，多因急性鼻炎反复发作、鼻腔鼻窦疾病、环境因素等引起。","symptoms":["慢性单纯性鼻炎：间歇性鼻塞（白天、夏季、劳动运动时减轻，夜间、寒冷、静坐时加重）、交替性鼻塞（侧卧时下侧鼻腔阻塞，上侧通畅，翻身后相反）、鼻涕增多（黏液性，继发感染时脓性）、嗅觉减退（暂时性）、头痛头昏（鼻塞明显时）、说话呈闭塞性鼻音、鼻涕向后流入咽喉可引起咽异物感、多痰、咳嗽","慢性肥厚性鼻炎：持续性鼻塞（较重，无交替性）、鼻涕不多（黏液性或黏脓性，不易擤出）、嗅觉减退（明显）、闭塞性鼻音、耳鸣、耳闷（堵塞咽鼓管咽口）、头痛头昏、失眠、精神萎靡、记忆力下降（长期鼻塞缺氧）、咽干咽痛（长期张口呼吸）","鼻镜检查：慢性单纯性鼻炎——鼻黏膜充血（淡红色或暗红色）、肿胀（下鼻甲明显，表面光滑、柔软、有弹性，探针按压有凹陷，移去后立即恢复，对血管收缩剂敏感，滴用麻黄碱后下鼻甲明显缩小）；慢性肥厚性鼻炎——鼻黏膜肥厚（暗红色或紫红色）、下鼻甲肥大（表面不平，呈结节状或桑葚状，尤以下鼻甲前端和后端游离缘明显，探针按压硬实、无凹陷或凹陷不明显，对血管收缩剂不敏感，滴用麻黄碱后下鼻甲不缩小或缩小不明显）","可伴鼻中隔偏曲、鼻窦炎、腺样体肥大","并发症：鼻窦炎（鼻塞致鼻窦引流不畅）、中耳炎（堵塞咽鼓管咽口）、咽炎喉炎（长期张口呼吸和鼻涕后流刺激）、支气管炎（分泌物下流刺激）"],"diagnosis":["典型症状（鼻塞、流涕、嗅觉减退，病程>3个月）+鼻镜检查","前鼻镜检查（观察鼻黏膜色泽、肿胀肥厚程度、下鼻甲大小、表面形态、分泌物性质、鼻中隔情况）","鼻内镜检查（详细观察鼻腔各部位，尤其是下鼻甲后端、中鼻道、嗅裂，排除鼻窦炎、鼻息肉、肿瘤）","鼻窦CT（怀疑合并鼻窦炎、鼻息肉、鼻中隔偏曲时，明确鼻窦情况）","过敏原检测（怀疑过敏性鼻炎时，皮肤点刺试验或血清特异性IgE）","排除过敏性鼻炎（阵发性喷嚏、清水样涕、鼻痒，与过敏原接触有关）、血管运动性鼻炎（温度、情绪变化诱发）、萎缩性鼻炎（鼻黏膜萎缩、鼻腔宽大、脓痂、恶臭）、药物性鼻炎（长期使用减充血剂）、鼻中隔偏曲、鼻息肉、鼻腔肿瘤","分型：慢性单纯性鼻炎（鼻黏膜充血肿胀，无增生肥厚，对血管收缩剂敏感，可逆）、慢性肥厚性鼻炎（鼻黏膜增生肥厚，下鼻甲肥大，对血管收缩剂不敏感，不可逆，多由单纯性鼻炎发展而来）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1：","  用法：一般无需静脉输液；糠酸莫米松鼻喷雾剂 每侧2喷 喷鼻 qd；氯雷他定 10mg 口服 qd；0.9%NS 鼻腔冲洗 bid","","方案2（急性发作合并感染）：","  用法：0.9%NS 100ml + 抗生素 ivgtt qd（根据病原选择）","","方案3（围手术期；下鼻甲手术）：","  用法：一般无需静脉抗生素，口服抗生素预防感染即可","","方案4：","  用法：合并其他全身疾病按相应方案治疗","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（慢性单纯性鼻炎）：","用法：鼻用糖皮质激素（布地奈德、糠酸莫米松、氟替卡松鼻喷雾剂，每日1-2次，基础治疗，减轻黏膜炎症和水肿）、鼻用减充血剂（羟甲唑啉、麻黄碱滴鼻液，短期使用，不超过7天，缓解鼻塞，长期使用可致药物性鼻炎）、鼻腔冲洗（生理盐水或高渗盐水，每日1-2次，清洁鼻腔分泌物，减轻黏膜水肿）、中成药（通窍鼻炎片、鼻炎康、鼻渊舒口服液、香菊胶囊，辨证使用）","药物2（慢性肥厚性鼻炎）：","用法：鼻用糖皮质激素（同单纯性，但效果有限）、鼻腔冲洗；下鼻甲硬化剂注射（5%鱼肝油酸钠、50%葡萄糖，适用于早期肥厚性鼻炎，下鼻甲黏膜增生肥厚但无骨质增生者）；药物治疗无效者手术治疗","药物3（合并感染）：","用法：抗生素（头孢克肟0.2g bid、阿莫西林0.5g tid，有脓性涕时短期使用）〔调 CrCl<30 减量；青霉素过敏禁用〕","药物4（抗过敏）：","用法：合并过敏性鼻炎时用抗组胺药（氯雷他定10mg qd、西替利嗪10mg qd）、白三烯受体拮抗剂（孟鲁司特钠10mg qn）〔调 肝功能/肾功能不全减量；妊娠哺乳慎用〕","药物5（促排剂）：","用法：合并鼻窦炎时用桉柠蒎0.3g tid、标准桃金娘油0.3g tid","药物6（止痛）：","用法：头痛明显时布洛芬0.2g prn〔调 ★ 肾功能不全禁用/慎用；活动性溃疡禁用；★ 妊娠晚期禁用〕","药物7（中医中药）：","用法：辨证施治，风寒型用荆防败毒散，风热型用银翘散，脾虚型用参苓白术散，肺虚型用温肺止流丹","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["病因治疗：治疗鼻中隔偏曲（鼻中隔矫正术）、鼻窦炎（药物或手术）、腺样体肥大（腺样体切除术，儿童）、慢性扁桃体炎；避免接触诱发因素（粉尘、烟雾、刺激性气体、温度剧烈变化）；戒烟；改善工作和生活环境（通风、防尘、加湿）","慢性单纯性鼻炎：非手术治疗为主——鼻用糖皮质激素（基础治疗，连续使用1-3个月）+鼻用减充血剂（短期，不超过7天）+鼻腔冲洗+中成药；加强锻炼，增强体质，改善营养；治疗全身慢性疾病","慢性肥厚性鼻炎：早期（黏膜肥厚为主，无骨质增生）可试用鼻用激素+硬化剂注射+物理治疗（激光、射频、冷冻、微波，缩小下鼻甲）；药物和保守治疗无效、下鼻甲肥大明显、持续性鼻塞严重影响生活者手术治疗——下鼻甲部分切除术（切除下鼻甲肥大部分，原则上切除不超过下鼻甲1/3，避免萎缩性鼻炎）、下鼻甲黏骨膜下切除术（保留黏膜，切除增生骨质，更符合生理）、下鼻甲成形术（下鼻甲骨折外移术、下鼻甲等离子消融术，微创，保留黏膜功能）；手术原则是保留下鼻甲黏膜功能，避免过度切除致萎缩性鼻炎","物理治疗：激光（CO2激光、YAG激光）、射频、冷冻、微波、等离子消融，通过热效应使下鼻甲组织蛋白凝固、缩小，适用于早期肥厚性鼻炎，微创，但可能影响黏膜功能","并发症治疗：鼻窦炎（药物或手术）、中耳炎（改善咽鼓管功能，必要时鼓膜置管）、咽炎喉炎（治疗鼻炎，多饮水，含漱）","预防：积极治疗急性鼻炎（及时彻底，防止迁延为慢性）；增强体质，预防上呼吸道感染；避免长期接触粉尘、烟雾、刺激性气体；戒烟；改善工作和生活环境；正确擤鼻（一侧一侧擤）；避免长期使用减充血剂（防止药物性鼻炎）；积极治疗鼻腔鼻窦疾病和全身慢性疾病","随访：治疗后定期复查（鼻镜、鼻内镜），评估疗效；术后定期复查清理鼻腔（防止粘连）；慢性鼻炎易复发，需长期管理和避免诱发因素"],"management":["鼻腔护理：用生理盐水或高渗盐水冲洗鼻腔（每日1-2次），清洁鼻腔分泌物，减轻黏膜水肿，改善鼻腔通气；正确擤鼻（一侧一侧擤，不要两侧同时用力，防止分泌物经咽鼓管进入中耳引起中耳炎）；避免用力擤鼻和挖鼻；保持室内适宜湿度（50-60%），避免干燥","用药护理：按医嘱使用鼻用糖皮质激素（每日1-2次，喷头朝向鼻腔外侧壁，避免直接喷向鼻中隔，长期使用注意鼻出血，连续使用1-3个月评估疗效）；鼻用减充血剂不超过7天（长期使用可致药物性鼻炎，反跳性鼻塞加重）；多种鼻喷剂使用时间隔5-10分钟；口服药按时按量；观察药物疗效和副作用（鼻用激素鼻出血、鼻干，减充血剂心悸、血压升高、失眠）","病情观察：观察鼻塞程度（间歇性/持续性、单侧/双侧）、鼻涕性质（黏液性/脓性/血性）、嗅觉变化；观察有无并发症征象（脓涕增多、头痛加重、耳闷耳鸣、咽痛咳嗽）；治疗后复查鼻镜评估疗效；出现脓涕、头痛、发热（合并鼻窦炎）、耳闷耳鸣（中耳炎）、血性涕（排除肿瘤）及时就医","饮食：清淡易消化饮食，多饮水，多吃新鲜蔬果；避免辛辣刺激、油腻、烟酒、过冷过热食物；过敏性鼻炎者避免过敏原和致敏食物；保持大便通畅","休息与活动：保证充足睡眠，避免熬夜和过度劳累；急性发作时适当休息；适当体育锻炼（慢跑、游泳、太极拳），增强体质，改善鼻黏膜血液循环；避免长时间处于粉尘、烟雾、刺激性气体环境；寒冷季节外出戴口罩（避免冷空气刺激）；避免温度剧烈变化","个人卫生：勤洗手，预防上呼吸道感染；避免用手挖鼻；毛巾脸盆个人专用；保持室内清洁，定期吸尘（减少尘螨）；过敏者避免接触过敏原（花粉、尘螨、动物毛发）","环境管理：保持室内通风、清洁、适宜温湿度；避免接触粉尘、烟雾、刺激性气体（厨房油烟、香水、油漆）；戒烟（包括二手烟）；使用空气净化器（过敏者）；干燥季节使用加湿器","心理护理：安慰患者，解释慢性鼻炎是常见病，可治疗和控制，但易复发，消除焦虑；鼻塞影响睡眠和工作者给予关心，指导缓解方法；需手术患者解释手术目的、过程和注意事项，减轻恐惧","健康教育：讲解慢性鼻炎的病因、分型（单纯性vs肥厚性）和症状；强调积极治疗急性鼻炎的重要性（防止迁延为慢性）；指导正确鼻腔冲洗和擤鼻方法；告知鼻用减充血剂不超过7天（防止药物性鼻炎）；鼻用糖皮质激素需连续使用1-3个月评估疗效，不可用几天就停；避免长期接触粉尘、烟雾、刺激性气体，戒烟；增强体质，预防上呼吸道感染；出现脓涕、头痛、发热、耳闷、血性涕及时就医；术后定期复查清理鼻腔；慢性鼻炎易复发，需长期管理和避免诱发因素","家庭护理：家属协助患者鼻腔冲洗和用药；保持室内清洁、通风、适宜温湿度；避免在家中吸烟（二手烟）；观察病情变化，出现并发症征象及时就医；陪同定期复查；术后患者注意鼻腔护理，避免挖鼻和用力擤鼻"],"notes":["慢性鼻炎是鼻腔黏膜和黏膜下层的慢性炎症，病程超过3个月，是耳鼻喉最常见的疾病之一，发病率高，影响患者生活质量、睡眠和工作学习","病因：局部因素（急性鼻炎反复发作或治疗不彻底、鼻腔鼻窦慢性疾病刺激如鼻中隔偏曲、鼻窦炎、腺样体肥大、邻近感染灶如慢性扁桃体炎、鼻腔用药不当或过久如长期使用减充血剂致药物性鼻炎）、全身因素（慢性疾病如贫血、糖尿病、风湿病、结核、心肝肾疾病、便秘、内分泌失调如甲状腺功能减退、青春期、月经期、妊娠期、营养不良如维生素A/C缺乏、烟酒过度、免疫功能障碍）、环境因素（长期接触粉尘、水泥、烟草、煤尘、面粉、化学物质、刺激性气体，温度和湿度剧烈变化）","分型：慢性单纯性鼻炎（鼻黏膜慢性充血肿胀，腺体分泌增加，无组织增生，可逆，对血管收缩剂敏感，是慢性鼻炎的早期阶段）、慢性肥厚性鼻炎（鼻黏膜增生肥厚，下鼻甲肥大，可累及骨膜和骨质，不可逆，对血管收缩剂不敏感，多由单纯性鼻炎发展而来，是慢性鼻炎的晚期阶段）","临床表现：慢性单纯性鼻炎——间歇性、交替性鼻塞，黏液性鼻涕增多，嗅觉暂时减退，闭塞性鼻音，头痛头昏；慢性肥厚性鼻炎——持续性鼻塞，鼻涕不多不易擤出，嗅觉明显减退，闭塞性鼻音，耳鸣耳闷，头痛头昏，失眠，精神萎靡，记忆力下降","鼻镜表现：慢性单纯性鼻炎——鼻黏膜充血肿胀，下鼻甲大，表面光滑柔软有弹性，探针按压有凹陷，移去后立即恢复，对麻黄碱敏感（下鼻甲明显缩小）；慢性肥厚性鼻炎——鼻黏膜肥厚，暗红色或紫红色，下鼻甲肥大，表面不平呈结节状或桑葚状，探针按压硬实无凹陷，对麻黄碱不敏感（下鼻甲不缩小或缩小不明显）","治疗原则：病因治疗+非手术治疗（鼻用激素+减充血剂短期+鼻腔冲洗+中成药），慢性单纯性鼻炎以非手术为主；慢性肥厚性鼻炎早期保守治疗，无效者手术治疗（下鼻甲部分切除或成形术，原则是保留黏膜功能，避免过度切除）","下鼻甲手术原则：保留下鼻甲黏膜功能，切除不超过下鼻甲1/3，避免过度切除致萎缩性鼻炎（鼻腔宽大、干燥、脓痂、恶臭、嗅觉丧失）；优先选择黏膜下手术（黏骨膜下切除、等离子消融、骨折外移），保留黏膜","药物性鼻炎：长期（>10天）使用鼻用减充血剂（麻黄碱、萘甲唑啉、羟甲唑啉）引起的反跳性鼻塞，表现为鼻塞加重、对减充血剂依赖、鼻黏膜充血水肿，治疗需立即停用减充血剂，改用鼻用糖皮质激素+鼻腔冲洗，必要时短期口服激素，故减充血剂使用不超过7天","预后：慢性单纯性鼻炎预后好，去除病因和规范治疗后可痊愈或明显改善；慢性肥厚性鼻炎药物治疗效果有限，多需手术，术后鼻塞可改善，但黏膜功能可能受影响；慢性鼻炎易复发，需长期管理和避免诱发因素","预防：积极治疗急性鼻炎（及时彻底，防止迁延）；增强体质，预防上呼吸道感染；避免长期接触粉尘、烟雾、刺激性气体；戒烟；改善工作和生活环境；正确擤鼻；避免长期使用减充血剂；积极治疗鼻腔鼻窦疾病和全身慢性疾病；加强营养，补充维生素","我国现状：慢性鼻炎发病率高，但很多患者不重视，自行长期使用减充血剂（滴鼻净等），导致药物性鼻炎和肥厚性鼻炎，需加强健康教育和规范诊疗，推广鼻用糖皮质激素的规范使用"],"emergency":["出现鼻塞突然加重、大量脓涕、发热、剧烈头痛（急性鼻窦炎或合并感染，及时就医）","出现耳闷、耳鸣、听力下降（分泌性中耳炎，堵塞咽鼓管咽口，及时就医）","出现血性鼻涕、鼻出血、单侧进行性鼻塞（排除鼻腔肿瘤、鼻咽癌，尽快鼻内镜和CT检查）","出现剧烈头痛、呕吐、发热、意识障碍（颅内并发症，罕见但严重，立即急诊）","术后出现鼻腔大量出血（手术创面出血，立即就医压迫止血）","出现呼吸困难、喘息（过敏反应或合并哮喘，立即就医）","长期使用减充血剂后鼻塞加重、依赖（药物性鼻炎，立即停用减充血剂，就医规范治疗）","儿童出现鼻塞严重、张口呼吸、打鼾、睡眠呼吸暂停（腺样体肥大，及时就医评估手术）"],"pinyin":"manxingbiyan","icd10":"J31.0","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态、面容","耳部：耳廓（畸形/红肿/皮疹/瘘管）、外耳道（耵聍/异物/分泌物/红肿/狭窄/闭锁）、鼓膜（标志/充血/内陷/穿孔/钙化/液平/肉芽）、乳突（红肿/压痛）、听力（耳语/音叉试验：Rinne试验/Weber试验/Schwabach试验）、前庭功能（自发性眼震/位置试验）","鼻部：外鼻（畸形/红肿）、鼻前庭（红肿/疖肿/结痂）、鼻腔（鼻中隔偏曲/糜烂/出血/穿孔、下鼻甲肿大/息肉样变、中鼻甲息肉样变/气化、鼻道分泌物（黏脓/血性/水样）、息肉/新生物）、鼻窦（压痛：额窦/上颌窦/筛窦）、后鼻孔检查","咽喉部：口咽（黏膜充血/肿胀/溃疡、扁桃体大小（Ⅰ-Ⅳ度）/充血/隐窝脓栓/结石、咽后壁淋巴滤泡增生/脓性分泌物、悬雍垂水肿/偏斜、软腭运动）、喉咽（会厌充血/水肿/囊肿、杓状会厌襞、梨状窝新生物/积液）、喉部（间接喉镜/电子喉镜：声带充血/息肉/小结/麻痹/新生物、室带肥厚、声门闭合情况）","颈部：淋巴结肿大（部位/大小/质地/活动度/压痛）、甲状腺、包块、瘘管","其他：发音（声嘶/失声）、吞咽（困难/呛咳）、呼吸（喘鸣/呼吸困难）"],"lab_tests":["前鼻镜检查：观察鼻黏膜色泽、充血程度、下鼻甲大小及鼻腔分泌物性状，作为首诊基础检查","鼻内镜检查：重点检查后鼻孔、中鼻道及嗅裂，排除鼻息肉、鼻窦口堵塞（门诊常规检查，必要时拍照存档随访）","鼻窦CT（冠状位+轴位）：鼻塞持续不缓解、疑合并鼻窦炎或拟行手术治疗前评估","变应原检测（皮肤点刺试验或血清特异性IgE）：伴阵发喷嚏、流清涕者，用于鉴别变应性鼻炎","鼻分泌物涂片查嗜酸性粒细胞：辅助鉴别变应性与非变应性鼻炎","伴眼痒、流泪等眼部症状时加行裂隙灯检查及视力、眼压测定，排除过敏性结膜炎"],"nursing":["观察并记录鼻腔分泌物量、颜色及有无血性物，评估鼻塞程度及有无头痛、面部胀痛","指导单侧交替擤鼻，禁止双侧同时用力擤鼻，防止引发分泌性中耳炎","保持病室温度22~24℃、湿度50%~60%，每日2次生理盐水（海盐水）鼻腔冲洗，睡前1次可改善夜间鼻塞","鼻出血时嘱取半卧位、头前倾，指压双侧鼻翼10分钟，切勿仰头以防血液倒流误吸；行下鼻甲手术（切除/射频消融）者术后观察鼻腔渗血，避免用力擤鼻、打喷嚏及弯腰低头"],"diet":["忌辛辣、刺激性食物及酒精、咖啡因饮品，避免诱发鼻黏膜充血加重鼻塞","清淡饮食，少量多次温水，避免过烫食物刺激鼻黏膜，保持黏膜湿润","多食富含维生素A、维生素C的食物（胡萝卜、番茄、柑橘、西兰花等），促进鼻黏膜修复","疑似变应性鼻炎者避免鱼虾、蛋奶、花生等可疑致敏食物，观察症状变化"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":397},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"b425546c66a52332aac857a8270f8381e8d9e1727d10c56922b3cdaa2fb2137c","pinyin":"manxingbiyan","initials":"mxby","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","慢性单纯性鼻炎：间歇性鼻塞（白天、夏季、劳动运动时减轻，夜间、寒冷、静坐时加重）、交替性鼻塞（侧卧时下侧鼻腔阻塞，上侧通畅，翻身后相反）、鼻涕增多（黏液性，继发感染时脓性）、嗅觉减退（暂时性）、头痛头昏（鼻塞明显时）、说话呈闭塞性鼻音、鼻涕向后流入咽喉可引起咽异物感、多痰、咳嗽\\n慢性肥厚性鼻炎：持续性鼻塞（较重，无交替性）、鼻涕不多（黏液性或黏脓性，不易擤出）、嗅觉减退（明显）、闭塞性鼻音、耳鸣、耳闷（堵塞咽鼓管咽口）、头痛头昏、失眠、精神萎靡、记忆力下降（长期鼻塞缺氧）、咽干咽痛（长期张口呼吸）\\n鼻镜检查：慢性单纯性鼻炎——鼻黏膜充血（淡红色或暗红色）、肿胀（下鼻甲明显，表面光滑、柔软、有弹性，探针按压有凹陷，移去后立即恢复，对血管收缩剂敏感，滴用麻黄碱后下鼻甲明显缩小）；慢性肥厚性鼻炎——鼻黏膜肥厚（暗红色或紫红色）、下鼻甲肥大（表面不平，呈结节状或桑葚状，尤以下鼻甲前端和后端游离缘明显，探针按压硬实、无凹陷或凹陷不明显，对血管收缩剂不敏感，滴用麻黄碱后下鼻甲不缩小或缩小不明显）\\n可伴鼻中隔偏曲、鼻窦炎、腺样体肥大\\n并发症：鼻窦炎（鼻塞致鼻窦引流不畅）、中耳炎（堵塞咽鼓管咽口）、咽炎喉炎（长期张口呼吸和鼻涕后流刺激）、支气管炎（分泌物下流刺激）",60],["摘要","鼻腔黏膜和黏膜下层的慢性炎症，表现为鼻塞、流涕、嗅觉减退、头痛等，分为慢性单纯性鼻炎和慢性肥厚性鼻炎，多因急性鼻炎反复发作、鼻腔鼻窦疾病、环境因素等引起。",30],["疾病编码","J31.0",30],["原首字母","manxingbiyan",60]]},{"id":"orders-e3b148c61cb8f20ef794","key":"v1-c9ccc21dfe2a3058|orders-e3b148c61cb8f20ef794","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"慢性鼻窦炎","category":"耳鼻喉","raw":{"name":"慢性鼻窦炎","category":"耳鼻喉","summary":"鼻窦黏膜的慢性化脓性炎症，常继发于急性鼻窦炎，表现为脓涕、鼻塞、头痛、嗅觉减退，病程超过12周，可伴鼻息肉，是耳鼻喉常见病。","symptoms":["脓涕：大量黏脓性或脓性鼻涕，色黄或黄绿，前组鼻窦炎脓涕从前鼻孔擤出，后组鼻窦炎脓涕向后流入鼻咽部（回吸涕）","鼻塞：持续性，因鼻黏膜充血肿胀和分泌物堵塞，可伴闭塞性鼻音","头痛：一般不明显，多为钝痛、闷胀痛，前组鼻窦炎多在前额和鼻根部，后组鼻窦炎多在头顶、枕部或眼球后，头痛有时间和部位规律（上颌窦炎晨起轻午后重，额窦炎晨起重午后渐轻，筛窦炎内眦或鼻根痛，蝶窦炎眼球后或头顶枕部痛）","嗅觉减退或丧失：因鼻黏膜肿胀、脓涕堵塞嗅裂，或嗅神经末梢变性","全身症状：一般不明显，可有头昏、易倦、精神抑郁、萎靡不振、纳差、失眠、记忆力减退、注意力不集中、工作效率降低","鼻涕后流刺激咽喉：咽部异物感、多痰、咳嗽、咽干咽痛","耳部症状：堵塞咽鼓管咽口可致耳鸣、耳闷、听力下降","鼻镜检查：鼻黏膜充血肿胀，中鼻甲肥大或息肉样变，中鼻道或嗅裂有脓性分泌物，可伴鼻息肉","并发症：眶内并发症（眶周蜂窝织炎、眶骨膜下脓肿、眶内脓肿、球后视神经炎）、颅内并发症（硬膜外脓肿、脑膜炎、脑脓肿）、中耳炎、咽炎、支气管炎","急性发作时症状加重，伴发热、头痛加剧"],"diagnosis":["典型症状（脓涕、鼻塞、头痛、嗅觉减退，病程>12周）+鼻镜检查见中鼻道或嗅裂脓性分泌物","前鼻镜和鼻内镜检查（详细观察鼻腔各部位，中鼻甲、中鼻道、嗅裂、脓性分泌物来源、鼻息肉、鼻中隔偏曲）","鼻窦CT（诊断金标准，明确鼻窦病变范围和程度，黏膜增厚、窦腔积液、息肉、骨质改变，术前必查）","鼻窦X线（现已少用，可显示窦腔模糊、液平面）","上颌窦穿刺冲洗（诊断和治疗，冲出脓性分泌物可确诊）","鼻分泌物培养+药敏（急性发作或难治性鼻窦炎，明确病原菌）","过敏原检测（合并过敏性鼻炎时）","嗅觉功能检查（评估嗅觉损害程度）","排除急性鼻窦炎（病程<12周）、鼻腔肿瘤、鼻咽癌、脑脊液鼻漏、过敏性鼻炎","分型：慢性鼻窦炎不伴鼻息肉（CRSsNP）、慢性鼻窦炎伴鼻息肉（CRSwNP）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般无需静脉输液；阿莫西林克拉维酸钾 0.625g 口服 tid（急性发作期，疗程10~14天）；糠酸莫米松鼻喷雾剂 每侧2喷 喷鼻 qd；0.9%NS 鼻腔冲洗 bid","方案2（急性发作或合并眶内/颅内并发症）：","用法：0.9%NS 100ml + 头孢曲松2g ivgtt qd 或 头孢呋辛1.5g ivgtt q8h 或 阿莫西林克拉维酸钾1.2g ivgtt q8h，根据药敏调整〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","方案3（合并眶内并发症）：","用法：广谱抗生素联合（头孢曲松+甲硝唑），眼科协同，必要时手术〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","方案4（合并颅内并发症）：","用法：大剂量广谱抗生素（能透过血脑屏障，如头孢曲松、美罗培南），神经外科协同，紧急手术〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","方案5（围手术期）：","用法：术前3天口服抗生素，术后3-5天静脉或口服抗生素预防感染","方案6（补液支持）：","用法：发热、不能进食时静脉补液","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（抗生素）：","用法：急性发作时用，慢性期不推荐长期使用；阿莫西林克拉维酸钾0.625g tid、头孢克肟0.2g bid、克拉霉素0.5g qd（小剂量长期抗炎，12周以上，适用于难治性鼻窦炎）、多西环素0.1g qd，疗程急性发作7-14天〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（鼻用糖皮质激素（基础治疗））：","用法：布地奈德鼻喷雾剂64μg bid、糠酸莫米松鼻喷雾剂200μg qd、氟替卡松鼻喷雾剂200μg qd，减轻鼻黏膜炎症水肿，缩小鼻息肉，连续使用3-6个月","药物3（鼻腔冲洗）：","用法：生理盐水或高渗盐水（2-3%）冲洗鼻腔，每日1-2次，清洁脓涕，减轻黏膜水肿，改善通气引流，是基础治疗","药物4（口服糖皮质激素）：","用法：严重鼻息肉或急性发作时短期使用，泼尼松30-40mg qd（晨起顿服），5-7天逐渐减量，注意禁忌证和副作用〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物5（促排剂）：","用法：桉柠蒎肠溶软胶囊0.3g tid、标准桃金娘油0.3g tid、氨溴索30mg tid，稀化黏液，促进纤毛运动，利于脓涕排出〔调 妊娠早期禁用；胃溃疡者慎用〕","药物6（鼻用减充血剂）：","用法：羟甲唑啉滴鼻液、麻黄碱滴鼻液，短期使用（不超过7天），减轻鼻黏膜肿胀，通畅引流，长期使用可致药物性鼻炎","药物7（抗组胺药）：","用法：合并过敏性鼻炎时用氯雷他定10mg qd、西替利嗪10mg qd〔调 肝功能/肾功能不全减量；妊娠哺乳慎用〕","药物8（白三烯受体拮抗剂）：","用法：孟鲁司特钠10mg qn，合并过敏性鼻炎、哮喘、鼻息肉时","药物9（止痛药）：","用法：头痛明显时布洛芬0.2g prn〔调 ★ 肾功能不全禁用/慎用；活动性溃疡禁用；★ 妊娠晚期禁用〕","药物10（中医中药）：","用法：芳香通窍、清热解毒、利湿排脓（鼻渊舒口服液、鼻窦炎口服液、通窍鼻炎片、香菊胶囊、苍耳子鼻炎胶囊），辨证使用","药物11（免疫调节剂）：","用法：匹多莫德、胸腺肽（免疫功能低下者）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["药物治疗（首选，基础治疗）：鼻用糖皮质激素+鼻腔冲洗+促排剂，疗程3-6个月；急性发作加抗生素；严重鼻息肉短期口服激素；合并过敏性鼻炎加抗过敏药；药物治疗是慢性鼻窦炎的基础，即使手术前后也需规范药物治疗","手术治疗：药物治疗3个月无效、症状严重影响生活、伴鼻息肉、鼻中隔偏曲、解剖异常、并发症者行鼻内镜鼻窦手术（FESS，功能性内镜鼻窦手术，切除鼻息肉、纠正解剖异常、开放鼻窦开口、恢复鼻窦通气引流，是目前主流术式）；术前规范药物治疗2-4周，术后继续药物治疗和定期鼻内镜复查清理（术后6个月内是术腔上皮化关键期，需定期复查清理，防止粘连和息肉复发）","病因治疗：治疗鼻中隔偏曲（鼻中隔矫正术）、下鼻甲肥大（下鼻甲成形术）、变应性鼻炎（抗过敏治疗）、哮喘、胃食管反流、免疫缺陷等","并发症治疗：眶内并发症（抗生素+眼科协同+必要时鼻内镜手术引流）、颅内并发症（大剂量抗生素+神经外科协同+紧急手术）、中耳炎（改善咽鼓管功能，必要时鼓膜置管）","物理治疗：超声雾化吸入、鼻窦负压置换（适用于儿童和多鼻窦炎）、上颌窦穿刺冲洗（诊断和治疗上颌窦炎）","预防：积极治疗急性鼻窦炎（及时彻底，防止迁延为慢性）；增强体质，预防上呼吸道感染；积极治疗鼻炎、鼻中隔偏曲、腺样体肥大；正确擤鼻（一侧一侧擤）；避免长期接触粉尘、烟雾、刺激性气体；戒烟；游泳时避免跳水和呛水；过敏者避免接触过敏原","随访：药物治疗后定期复查（评估疗效，调整方案）；术后定期鼻内镜复查清理（术后1月内每周1次，2-3月每2周1次，3-6月每月1次，6月后每3-6月1次），防止粘连和息肉复发；慢性鼻窦炎易复发，需长期管理"],"management":["鼻腔护理：用生理盐水或高渗盐水冲洗鼻腔（每日1-2次），掌握正确冲洗方法（头前倾，冲洗器塞入一侧鼻孔，水流从另一侧流出，两侧交替），清洁脓涕，减轻黏膜水肿；正确擤鼻（一侧一侧擤，不要两侧同时用力，防止脓涕经咽鼓管进入中耳或挤入鼻窦加重感染）；避免用力擤鼻和挖鼻；保持室内适宜湿度","用药护理：按医嘱规范使用鼻用糖皮质激素（每日1-2次，喷头朝向鼻腔外侧壁，连续使用3-6个月评估疗效，不可用几天就停，长期使用注意鼻出血）；鼻用减充血剂不超过7天（防止药物性鼻炎）；抗生素按疗程使用，不可自行停药或长期使用；口服激素短期使用，注意副作用（血糖升高、血压升高、胃肠道反应、骨质疏松），不可长期使用；促排剂饭前半小时服用；观察药物疗效和副作用","病情观察：观察脓涕的量、颜色、气味变化；观察鼻塞、头痛、嗅觉变化；观察有无并发症征象（眼痛、眼睑红肿、视力下降、眼球突出、剧烈头痛、呕吐、发热、意识障碍），一旦出现立即就医（眶内/颅内并发症可危及生命或视力）；急性发作时观察体温、头痛变化；治疗后复查鼻内镜和CT评估疗效；出现眼痛、视力下降、剧烈头痛、发热、意识障碍及时就医","饮食：清淡易消化饮食，多饮水，多吃新鲜蔬果；避免辛辣刺激、油腻、烟酒、腥发食物（海鲜、羊肉，急性发作时）；保持大便通畅；过敏者避免致敏食物","休息与活动：保证充足睡眠，避免熬夜和过度劳累；急性发作时卧床休息；适当体育锻炼，增强体质；避免长时间处于粉尘、烟雾、刺激性气体环境；寒冷季节外出戴口罩；避免游泳跳水和呛水（发作期）","个人卫生：勤洗手，预防上呼吸道感染；避免用手挖鼻；毛巾脸盆个人专用；保持室内清洁，定期吸尘；过敏者避免接触过敏原（花粉、尘螨、动物毛发）","环境管理：保持室内通风、清洁、适宜温湿度；避免接触粉尘、烟雾、刺激性气体；戒烟（包括二手烟）；使用空气净化器（过敏者）；干燥季节使用加湿器","心理护理：安慰患者，解释慢性鼻窦炎是常见病，可治疗和控制，但易复发，需长期规范治疗，消除焦虑；头痛、鼻塞影响睡眠和工作者给予关心，指导缓解方法；需手术患者解释手术目的（鼻内镜微创，开放鼻窦引流）、过程和术后复查重要性，减轻恐惧","健康教育：讲解慢性鼻窦炎的病因、症状和危害（眶内/颅内并发症可危及视力和生命）；强调规范药物治疗的重要性（鼻用激素+鼻腔冲洗是基础，需3-6个月，不可自行停药）；告知鼻用减充血剂不超过7天；指导正确鼻腔冲洗和擤鼻方法；术后定期鼻内镜复查清理的重要性（防止粘连和息肉复发，术后6个月是关键期）；出现眼痛、视力下降、剧烈头痛、发热、意识障碍立即就医；积极治疗鼻炎、鼻中隔偏曲、腺样体肥大；增强体质，预防上呼吸道感染；戒烟；过敏者避免接触过敏原；慢性鼻窦炎易复发，需长期管理","家庭护理：家属协助患者鼻腔冲洗和用药；观察病情变化，发现并发症征象（眼痛、视力下降、剧烈头痛、发热）及时就医；陪同定期复查和术后清理；保持室内清洁、通风、适宜温湿度；避免在家中吸烟"],"notes":["慢性鼻窦炎是鼻窦黏膜的慢性化脓性炎症，病程超过12周，常继发于急性鼻窦炎，可累及单个或多个鼻窦，上颌窦炎最常见，其次为筛窦、额窦、蝶窦，是耳鼻喉常见病，发病率约5-15%，影响患者生活质量","病因：局部因素（急性鼻窦炎反复发作或治疗不彻底、鼻腔阻塞性疾病如鼻中隔偏曲、下鼻甲肥大、鼻息肉、肿瘤、邻近感染灶如慢性扁桃体炎、腺样体肥大、拔牙损伤上颌窦、鼻窦外伤骨折、异物）、全身因素（慢性疾病、营养不良、烟酒过度、免疫功能低下、过敏体质、支气管哮喘、胃食管反流）、环境因素（长期接触粉尘、烟雾、刺激性气体）","发病机制：鼻窦开口阻塞→鼻窦通气引流障碍→分泌物潴留→细菌感染→黏膜慢性炎症→息肉样变→加重阻塞，形成恶性循环","临床表现：脓涕（主要症状，前组鼻窦炎从前鼻孔擤出，后组鼻窦炎回吸涕）、鼻塞（持续性）、头痛（钝痛闷胀痛，有时间部位规律）、嗅觉减退、全身症状（头昏、易倦、记忆力减退、精神不振）、鼻涕后流刺激咽喉","头痛规律：上颌窦炎——前额部或面颊部痛，晨起轻，午后重，侧卧患侧向上时减轻；额窦炎——前额部周期性痛，晨起感头痛，渐加重，午后减轻，晚间消失，次日又发作（真空性头痛）；筛窦炎——内眦或鼻根部痛，可放射至头顶，眼球活动时痛；蝶窦炎——眼球深部或头顶、枕部痛，可放射至耳后，晨起轻午后重，压迫眼球时痛","鼻内镜检查：中鼻道或嗅裂有脓性分泌物是重要体征；中鼻甲肥大、息肉样变、钩突肥大、鼻中隔偏曲等解剖异常；鼻息肉","鼻窦CT：是诊断慢性鼻窦炎的金标准，可显示鼻窦黏膜增厚、窦腔积液、息肉、骨质改变、解剖异常，明确病变范围和程度，是术前必查","分型：慢性鼻窦炎不伴鼻息肉（CRSsNP，以炎症为主，药物治疗效果较好）、慢性鼻窦炎伴鼻息肉（CRSwNP，鼻息肉形成，易复发，常需手术，与过敏、哮喘关系密切）","治疗原则：药物治疗是基础（鼻用激素+鼻腔冲洗+促排剂，3-6个月），药物治疗无效或伴鼻息肉、解剖异常、并发症者手术治疗（鼻内镜鼻窦手术FESS），术前术后均需规范药物治疗和定期复查","鼻内镜鼻窦手术（FESS）：是目前慢性鼻窦炎的主流术式，通过鼻内镜切除鼻息肉、纠正解剖异常（鼻中隔偏曲、钩突肥大）、开放鼻窦开口（钩突切除、前筛开放、上颌窦开放、额窦开放、蝶窦开放），恢复鼻窦通气引流，微创、疗效好；术后定期鼻内镜复查清理是手术成功的关键（术后6个月内是术腔上皮化关键期，需定期清理痂皮、囊泡、粘连，防止息肉复发）","术后复查：术后1月内每周1次鼻内镜清理，2-3月每2周1次，3-6月每月1次，6月后每3-6月1次，至少随访1年；术后继续鼻用激素+鼻腔冲洗3-6个月","并发症：眶内并发症（眶周蜂窝织炎、眶骨膜下脓肿、眶内脓肿、球后视神经炎，可致视力丧失，需紧急处理）、颅内并发症（硬膜外脓肿、硬膜下脓肿、脑膜炎、脑脓肿、海绵窦血栓性静脉炎，危及生命，罕见但严重）、中耳炎、咽炎、支气管炎、下呼吸道感染","预后：规范药物治疗后多数患者症状可改善；药物治疗无效者手术有效率80-90%；伴鼻息肉、哮喘、过敏性鼻炎者易复发；术后定期复查可显著降低复发率；出现并发症者预后差，可致视力丧失或危及生命","预防：积极治疗急性鼻窦炎（及时彻底，防止迁延）；增强体质，预防上呼吸道感染；积极治疗鼻炎、鼻中隔偏曲、腺样体肥大、慢性扁桃体炎；正确擤鼻；避免长期接触粉尘、烟雾、刺激性气体；戒烟；游泳时避免跳水和呛水；过敏者避免接触过敏原，规范治疗过敏性鼻炎；胃食管反流者治疗反流","我国现状：慢性鼻窦炎发病率高，但很多患者不重视，自行长期使用减充血剂和抗生素，导致药物性鼻炎、细菌耐药和病情迁延；鼻内镜手术已普及，但术后复查依从性差，复发率较高；需加强健康教育和规范诊疗，推广鼻用激素和鼻腔冲洗的规范使用"],"emergency":["出现眼痛、眼睑红肿、视力下降、眼球突出、眼球运动受限（眶内并发症，立即就医，可能致视力丧失，需抗生素+手术）","出现剧烈头痛、呕吐、发热、意识障碍、抽搐、颈部抵抗（颅内并发症：脑膜炎、脑脓肿，危及生命，立即急诊，大剂量抗生素+神经外科+手术）","出现脓涕突然减少、头痛加重、发热（脓液引流不畅，可能引起并发症，立即就医）","出现高热、寒战、头痛剧烈（急性发作或感染扩散，及时就医）","术后出现鼻腔大量出血、视力下降、眼痛、头痛、意识障碍（术后并发症，立即就医）","出现单侧进行性鼻塞、血性涕、面部麻木、牙痛（排除鼻腔鼻窦肿瘤，尽快鼻内镜和CT检查）","出现耳闷、耳鸣、听力骤降（合并中耳炎或内耳受累，及时就医）","儿童出现高热、呕吐、嗜睡、囟门隆起（颅内并发症，立即急诊）"],"pinyin":"manxingbidouyan","icd10":"J32.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态、面容","耳部：耳廓（畸形/红肿/皮疹/瘘管）、外耳道（耵聍/异物/分泌物/红肿/狭窄/闭锁）、鼓膜（标志/充血/内陷/穿孔/钙化/液平/肉芽）、乳突（红肿/压痛）、听力（耳语/音叉试验：Rinne试验/Weber试验/Schwabach试验）、前庭功能（自发性眼震/位置试验）","鼻部：外鼻（畸形/红肿）、鼻前庭（红肿/疖肿/结痂）、鼻腔（鼻中隔偏曲/糜烂/出血/穿孔、下鼻甲肿大/息肉样变、中鼻甲息肉样变/气化、鼻道分泌物（黏脓/血性/水样）、息肉/新生物）、鼻窦（压痛：额窦/上颌窦/筛窦）、后鼻孔检查","咽喉部：口咽（黏膜充血/肿胀/溃疡、扁桃体大小（Ⅰ-Ⅳ度）/充血/隐窝脓栓/结石、咽后壁淋巴滤泡增生/脓性分泌物、悬雍垂水肿/偏斜、软腭运动）、喉咽（会厌充血/水肿/囊肿、杓状会厌襞、梨状窝新生物/积液）、喉部（间接喉镜/电子喉镜：声带充血/息肉/小结/麻痹/新生物、室带肥厚、声门闭合情况）","颈部：淋巴结肿大（部位/大小/质地/活动度/压痛）、甲状腺、包块、瘘管","其他：发音（声嘶/失声）、吞咽（困难/呛咳）、呼吸（喘鸣/呼吸困难）"],"lab_tests":["电子鼻内镜检查（初诊及随访常规）：重点观察中鼻道、嗅裂及窦口鼻道复合体，评估有无息肉、脓性分泌物及黏膜水肿，动态记录病变程度。","鼻窦CT（冠状位+轴位薄层扫描，保守治疗无效或拟手术前）：评估窦口阻塞、黏膜增厚及骨质改变，明确分型（伴或不伴鼻息肉）。","变应原检测（皮肤点刺试验或血清特异性IgE，疑合并过敏因素时）：筛查变应性鼻炎共病，指导综合治疗。","嗅觉功能检测（嗅棒试验）：量化评估嗅区病变及术后嗅觉恢复情况。","鼻分泌物细菌培养+药敏（脓性分泌物明显或急性加重期）：明确病原菌，指导抗生素选择。","出现眼球突出、复视、眼胀或视力下降时行眼眶CT并请眼科会诊：排查眶内并发症。"],"nursing":["病情观察：每日观察鼻腔分泌物性质、量及气味，询问头痛、面部胀痛变化；警惕眶周红肿、眼球突出、复视、视力下降等眶内并发症征兆，发现异常立即报告医生。","鼻腔冲洗护理：指导每日1-2次生理盐水或高渗盐水鼻腔冲洗，示范正确低头侧倾冲洗姿势，观察有无鼻出血、耳痛等不适。","术后护理（内镜鼻窦术后）：取半卧位、头部抬高30°，减轻局部水肿；观察鼻腔填塞物有无渗血，少量渗血予鼻部冷敷，活动性出血及时通知医生。","口腔护理：术后张口呼吸及填塞物致口咽干燥，每日用生理盐水或漱口液含漱2-3次，保持口腔清洁，预防口臭及继发感染。"],"diet":["忌辛辣刺激及过烫食物：避免辣椒、酒、浓茶咖啡等，防止刺激鼻腔黏膜及血管扩张加重鼻出血。","术后饮食循序渐进：当日进温凉流质（米汤、稀粥），次日过渡至半流质、软食，避免过热食物诱发填塞部位出血。","多饮水，每日1500-2000ml：保持鼻黏膜湿润，稀释分泌物，利于引流排出。","补充优质蛋白及维生素：多食鱼、蛋、奶及新鲜蔬果（富含维生素C），促进黏膜修复；避免生冷、坚硬及坚果类食物。"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":398},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"04efca3c4f3b9c7cc25fe0d3667447f6c30b28efca2a5964055a8343fabd74e7","pinyin":"manxingbidouyan","initials":"mxbdy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","脓涕：大量黏脓性或脓性鼻涕，色黄或黄绿，前组鼻窦炎脓涕从前鼻孔擤出，后组鼻窦炎脓涕向后流入鼻咽部（回吸涕）\\n鼻塞：持续性，因鼻黏膜充血肿胀和分泌物堵塞，可伴闭塞性鼻音\\n头痛：一般不明显，多为钝痛、闷胀痛，前组鼻窦炎多在前额和鼻根部，后组鼻窦炎多在头顶、枕部或眼球后，头痛有时间和部位规律（上颌窦炎晨起轻午后重，额窦炎晨起重午后渐轻，筛窦炎内眦或鼻根痛，蝶窦炎眼球后或头顶枕部痛）\\n嗅觉减退或丧失：因鼻黏膜肿胀、脓涕堵塞嗅裂，或嗅神经末梢变性\\n全身症状：一般不明显，可有头昏、易倦、精神抑郁、萎靡不振、纳差、失眠、记忆力减退、注意力不集中、工作效率降低\\n鼻涕后流刺激咽喉：咽部异物感、多痰、咳嗽、咽干咽痛\\n耳部症状：堵塞咽鼓管咽口可致耳鸣、耳闷、听力下降\\n鼻镜检查：鼻黏膜充血肿胀，中鼻甲肥大或息肉样变，中鼻道或嗅裂有脓性分泌物，可伴鼻息肉\\n并发症：眶内并发症（眶周蜂窝织炎、眶骨膜下脓肿、眶内脓肿、球后视神经炎）、颅内并发症（硬膜外脓肿、脑膜炎、脑脓肿）、中耳炎、咽炎、支气管炎\\n急性发作时症状加重，伴发热、头痛加剧",60],["摘要","鼻窦黏膜的慢性化脓性炎症，常继发于急性鼻窦炎，表现为脓涕、鼻塞、头痛、嗅觉减退，病程超过12周，可伴鼻息肉，是耳鼻喉常见病。",30],["疾病编码","J32.9",30],["原首字母","manxingbidouyan",60]]},{"id":"orders-6bb71bb8fc72a34e941a","key":"v1-c9ccc21dfe2a3058|orders-6bb71bb8fc72a34e941a","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"鼻息肉","category":"耳鼻喉","raw":{"name":"鼻息肉","category":"耳鼻喉","summary":"鼻腔和鼻窦黏膜的慢性疾病，以极度水肿的鼻黏膜在中鼻道形成单发或多发息肉为特征，表现为持续性鼻塞、流涕、嗅觉减退、头痛，常伴慢性鼻窦炎和哮喘，药物和手术综合治疗。","symptoms":["鼻塞：持续性，进行性加重，息肉增大后完全阻塞鼻腔，说话呈闭塞性鼻音，睡眠时打鼾，可致睡眠呼吸暂停","流涕：黏液性或脓性，量多少不一，后鼻孔息肉可致鼻涕后流","嗅觉减退或丧失：息肉堵塞嗅裂或嗅神经末梢变性，多为进行性","头痛：一般不明显，息肉阻塞鼻窦开口引起鼻窦炎时可有头痛、闷胀痛","耳部症状：巨大息肉堵塞咽鼓管咽口可致耳鸣、耳闷、听力下降","其他：口干咽干（长期张口呼吸）、咽炎、咳嗽、痰多（分泌物刺激）、面部胀痛、鼻背增宽（巨大息肉，蛙鼻）","鼻镜检查：鼻腔内可见一个或多个表面光滑、灰白色或淡红色、半透明、柔软如荔枝肉状的新生物，触之柔软不痛、可移动、不易出血，多来源于中鼻道、筛窦，可充满鼻腔，后鼻孔息肉多来源于上颌窦，经上颌窦开口坠入后鼻孔","可伴鼻中隔偏曲、鼻窦炎、哮喘、阿司匹林不耐受（Samter三联征：鼻息肉+哮喘+阿司匹林不耐受）","并发症：慢性鼻窦炎、分泌性中耳炎、咽炎、支气管炎、哮喘加重、蛙鼻畸形（巨大息肉）、眶内并发症（罕见）"],"diagnosis":["典型症状（持续性进行性鼻塞、嗅觉减退）+鼻镜检查见荔枝肉状新生物","前鼻镜和鼻内镜检查（详细观察息肉大小、数量、来源、基底、鼻腔堵塞情况，中鼻道、嗅裂、后鼻孔）","鼻窦CT（明确息肉范围、鼻窦病变、解剖异常，是术前必查，息肉表现为中鼻道或鼻腔软组织影，可伴鼻窦黏膜增厚、窦腔积液）","鼻窦MRI（鉴别息肉与肿瘤，T1低信号T2高信号，增强后边缘强化）","过敏原检测（合并过敏性鼻炎时）","肺功能检查（合并哮喘时）","鼻分泌物涂片（嗜酸性粒细胞增多）","病理检查（手术切除后送病理，确诊并排除内翻性乳头状瘤、鼻腔恶性肿瘤、鼻咽纤维血管瘤等）","排除鼻腔恶性肿瘤（单侧、质硬、易出血、表面溃烂、面部麻木、骨质破坏）、内翻性乳头状瘤（单侧、质较硬、易出血、乳头状、多来源于中鼻道和上颌窦，有恶变倾向）、鼻咽纤维血管瘤（青少年男性，易出血，来源于鼻咽部）、脑膜脑膨出（新生儿，位于鼻顶部，与颅内相通，禁忌活检）、鼻中隔偏曲、下鼻甲肥大","分型：单发性鼻息肉、多发性鼻息肉；按来源分中鼻道息肉、后鼻孔息肉（上颌窦后鼻孔息肉，多见于青少年）；嗜酸性粒细胞型、中性粒细胞型"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般无需静脉输液；糠酸莫米松鼻喷雾剂 每侧2喷 喷鼻 qd；泼尼松 30mg 口服 qd（疗程5~7天）；鼻内镜下息肉切除术（药物治疗无效时）","方案2（合并急性感染或围手术期）：","用法：0.9%NS 100ml + 抗生素 ivgtt qd（根据病原选择）","方案3：","用法：术前口服激素准备，一般无需静脉激素","方案4：","用法：术后3-5天静脉或口服抗生素预防感染","方案5：","用法：合并哮喘急性发作时按哮喘方案静脉用药","方案6（补液支持）：","用法：发热、不能进食时静脉补液","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（鼻用糖皮质激素（基础治疗，首选））：","用法：布地奈德鼻喷雾剂64-128μg bid、糠酸莫米松鼻喷雾剂200μg qd、氟替卡松鼻喷雾剂200μg qd，可使小息肉缩小或消失，大息肉术后防止复发，连续使用3-6个月甚至更长","药物2（糖皮质激素）：","用法：口服糖皮质激素（息肉较大、术前准备、术后复发）：泼尼松30-40mg qd（晨起顿服），5-7天，然后逐渐减量，总疗程10-14天，可使息肉明显缩小，改善鼻塞，为手术创造条件；注意禁忌证（糖尿病、高血压、胃溃疡、骨质疏松、感染）和副作用〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物3（抗生素）：","用法：合并感染时用，阿莫西林克拉维酸钾0.625g tid、头孢克肟0.2g bid、克拉霉素0.5g qd（小剂量长期抗炎），疗程7-14天〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物4（鼻腔冲洗）：","用法：生理盐水或高渗盐水冲洗鼻腔，每日1-2次，清洁分泌物，减轻黏膜水肿，是基础治疗","药物5（促排剂）：","用法：桉柠蒎0.3g tid、标准桃金娘油0.3g tid，稀化黏液，促进排出","药物6（抗组胺药）：","用法：合并过敏性鼻炎时氯雷他定10mg qd、西替利嗪10mg qd〔调 肝功能/肾功能不全减量；妊娠哺乳慎用〕","药物7（白三烯受体拮抗剂）：","用法：孟鲁司特钠10mg qn，合并哮喘、过敏性鼻炎、嗜酸性粒细胞型鼻息肉时","药物8（止痛药）：","用法：术后或头痛时布洛芬0.2g prn〔调 ★ 肾功能不全禁用/慎用；活动性溃疡禁用；★ 妊娠晚期禁用〕","药物9（中医中药）：","用法：芳香通窍、化痰散结（苍耳子散、温肺止流丹、二陈汤加减），辨证使用","药物10（免疫治疗）：","用法：合并过敏性鼻炎者特异性免疫治疗","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["药物治疗（基础治疗）：鼻用糖皮质激素（糠酸莫米松鼻喷剂 200μg 每侧鼻孔 qd 或布地奈德鼻喷剂 128μg 每侧 qd）+鼻腔冲洗（生理盐水 250ml 冲洗 bid）+口服激素（泼尼松 30mg 口服 qd 晨服，疗程7-14天，息肉较大或术前）+促排剂（桉柠蒎肠溶软胶囊 0.3g 口服 tid）+抗过敏药（氯雷他定 10mg 口服 qd），小息肉可通过药物治疗缩小或消失，大息肉药物治疗可缩小息肉、改善鼻塞、为手术创造条件、减少术中出血、术后防止复发","手术治疗（主要治疗方法）：药物治疗无效、息肉较大、鼻塞严重、影响鼻窦引流、合并鼻窦炎、解剖异常者行鼻内镜下鼻息肉切除术+鼻窦开放术（FESS，切除息肉、开放鼻窦、纠正解剖异常，恢复鼻腔通气引流，是目前主流术式）；术前规范药物治疗2-4周（口服泼尼松 30mg 口服 qd 晨服+鼻用激素+抗生素，如阿莫西林克拉维酸钾 0.625g 口服 tid），可缩小息肉、减少术中出血；术后继续药物治疗（鼻用激素+鼻腔冲洗3-6个月）和定期鼻内镜复查清理（防止粘连和息肉复发，术后6个月是关键期）","病因治疗：治疗过敏性鼻炎（抗过敏如氯雷他定 10mg 口服 qd、免疫治疗）、哮喘（呼吸科协同）、慢性鼻窦炎、鼻中隔偏曲、阿司匹林不耐受（避免阿司匹林和非甾体抗炎药）","并发症治疗：慢性鼻窦炎（药物或手术）、分泌性中耳炎（改善咽鼓管功能，鼓膜置管）、咽炎（治疗鼻息肉，多饮水）、睡眠呼吸暂停（手术切除息肉，必要时CPAP）","物理治疗：激光、射频、冷冻（现已少用，多被鼻内镜手术取代）","预防：积极治疗过敏性鼻炎和慢性鼻窦炎；增强体质，预防上呼吸道感染；避免接触过敏原；戒烟；避免长期接触粉尘、烟雾、刺激性气体；阿司匹林不耐受者避免阿司匹林和非甾体抗炎药；术后规范用药和定期复查防止复发","随访：药物治疗后定期复查（评估息肉大小变化，调整方案）；术后定期鼻内镜复查清理（术后1月内每周1次，2-3月每2周1次，3-6月每月1次，6月后每3-6月1次），防止粘连和息肉复发；鼻息肉易复发，需长期管理，术后5年复发率约20-40%"],"management":["鼻腔护理：用生理盐水或高渗盐水冲洗鼻腔（每日1-2次），清洁分泌物，减轻黏膜水肿；正确擤鼻（一侧一侧擤）；避免用力擤鼻和挖鼻；保持室内适宜湿度；术后避免鼻腔进水（1周内）","用药护理：按医嘱规范使用鼻用糖皮质激素（每日1-2次，连续使用3-6个月，不可自行停药，长期使用注意鼻出血）；口服激素短期使用，注意副作用（血糖、血压、胃肠道、睡眠），不可长期使用；抗生素按疗程使用；促排剂饭前半小时服用；观察药物疗效和副作用（息肉大小变化、鼻塞改善）","病情观察：观察鼻塞程度、鼻涕性质、嗅觉变化；观察有无并发症征象（脓涕增多、头痛加重、耳闷耳鸣、哮喘加重）；术后观察鼻腔出血、渗液、疼痛、体温变化；观察有无复发（鼻塞再次加重、嗅觉下降）；治疗后复查鼻内镜和CT评估疗效；出现大量鼻出血、剧烈头痛、发热、视力下降、哮喘急性发作及时就医","饮食：清淡易消化饮食，多饮水，多吃新鲜蔬果；避免辛辣刺激、油腻、烟酒、腥发食物（海鲜、羊肉）；口服激素期间注意低盐低糖高蛋白饮食；过敏者避免致敏食物；保持大便通畅","休息与活动：保证充足睡眠，避免熬夜和过度劳累；急性发作或术后适当休息；适当体育锻炼，增强体质；避免长时间处于粉尘、烟雾、刺激性气体环境；术后1周内避免剧烈运动、重体力劳动、游泳；避免用力擤鼻和挖鼻（术后）","个人卫生：勤洗手，预防上呼吸道感染；避免用手挖鼻；毛巾脸盆个人专用；保持室内清洁，定期吸尘；过敏者避免接触过敏原（花粉、尘螨、动物毛发）；阿司匹林不耐受者避免阿司匹林和非甾体抗炎药（包括感冒药中的解热镇痛药）","环境管理：保持室内通风、清洁、适宜温湿度；避免接触粉尘、烟雾、刺激性气体；戒烟（包括二手烟）；使用空气净化器（过敏者）；干燥季节使用加湿器","心理护理：安慰患者，解释鼻息肉是良性病变，可治疗，但易复发，需长期规范治疗和术后复查，消除焦虑；鼻塞影响睡眠和工作者给予关心，指导缓解方法；需手术患者解释手术目的（鼻内镜微创切除息肉、开放鼻窦）、过程和术后复查重要性，减轻恐惧；复发患者给予心理支持，告知复发后可再次手术或药物治疗","健康教育：讲解鼻息肉的病因（慢性炎症、过敏、嗜酸性粒细胞浸润）、症状和与慢性鼻窦炎、哮喘的关系；强调规范药物治疗的重要性（鼻用激素是基础，需长期使用，不可自行停药）；术前口服激素可缩小息肉、减少出血，按医嘱服用；术后定期鼻内镜复查清理的重要性（防止粘连和息肉复发，术后6个月是关键期，不可因症状缓解就停止复查）；指导正确鼻腔冲洗和擤鼻方法；出现大量鼻出血、剧烈头痛、发热、视力下降、哮喘急性发作及时就医；积极治疗过敏性鼻炎和哮喘；避免接触过敏原；戒烟；阿司匹林不耐受者避免阿司匹林和非甾体抗炎药；鼻息肉易复发，需长期管理，术后5年复发率约20-40%，规范治疗和复查可降低复发率","家庭护理：家属协助患者鼻腔冲洗和用药；观察病情变化，发现并发症征象及时就医；陪同定期复查和术后清理；保持室内清洁、通风、适宜温湿度；避免在家中吸烟；术后患者注意鼻腔护理，避免挖鼻和用力擤鼻，观察出血情况"],"notes":["鼻息肉是鼻腔和鼻窦黏膜的慢性疾病，以极度水肿的鼻黏膜在中鼻道形成单发或多发息肉为特征，是耳鼻喉常见病，成年人发病率约1-4%，男性多于女性，常伴慢性鼻窦炎、支气管哮喘、阿司匹林不耐受","病因：不完全明确，与多种因素有关——慢性炎症（慢性鼻窦炎长期刺激）、变态反应（过敏性鼻炎，嗜酸性粒细胞浸润，IgE升高）、嗜酸性粒细胞增多（鼻息肉组织中嗜酸性粒细胞大量浸润，释放炎症介质，是鼻息肉的重要特征）、遗传因素、免疫异常、解剖异常（鼻中隔偏曲、钩突肥大）、细菌超抗原、真菌、阿司匹林不耐受等","发病机制：多种因素致鼻黏膜慢性炎症→血管通透性增加→组织水肿→嗜酸性粒细胞浸润→炎症介质释放→黏膜极度水肿、下垂→形成息肉；息肉表面为假复层柱状上皮，间质水肿，有大量嗜酸性粒细胞、浆细胞、淋巴细胞浸润","好发部位：中鼻道（筛泡、钩突、中鼻甲）、筛窦，其次为上颌窦、额窦、蝶窦；后鼻孔息肉多来源于上颌窦，经上颌窦开口（副开口）坠入后鼻孔，多见于青少年，单侧","临床表现：持续性进行性鼻塞（主要症状）、流涕（黏液性或脓性）、嗅觉减退或丧失、头痛（合并鼻窦炎时）、闭塞性鼻音、打鼾、睡眠呼吸暂停、口干咽干、耳鸣耳闷（堵塞咽鼓管）；巨大息肉可致鼻背增宽形成蛙鼻","鼻镜表现：鼻腔内一个或多个表面光滑、灰白色或淡红色、半透明、柔软如荔枝肉状新生物，触之柔软不痛、可移动、不易出血，多来源于中鼻道；息肉可充满鼻腔，甚至突出前鼻孔；后鼻孔息肉需鼻内镜或间接鼻咽镜检查","Samter三联征（阿司匹林三联征）：鼻息肉+支气管哮喘+阿司匹林不耐受（服用阿司匹林或其他非甾体抗炎药后诱发哮喘发作、鼻炎、荨麻疹），此类患者鼻息肉多为双侧、嗜酸性粒细胞型、易复发、术后复发率高，治疗较困难","鼻窦CT：是术前必查，可显示鼻腔和鼻窦软组织影（息肉），多为中鼻道和鼻腔内，可伴鼻窦黏膜增厚、窦腔积液、窦口扩大、骨质吸收（息肉压迫），无骨质破坏（与恶性肿瘤鉴别）","病理：确诊靠病理，息肉表面为假复层柱状上皮（可鳞状化生），间质高度水肿，有大量嗜酸性粒细胞、浆细胞、淋巴细胞浸润，可有腺体增生和囊性变；嗜酸性粒细胞型预后较差，易复发；注意排除内翻性乳头状瘤（上皮向内翻入间质，乳头状，有恶变倾向）和恶性肿瘤","治疗原则：药物治疗是基础（鼻用激素+口服激素+鼻腔冲洗+抗过敏），药物治疗无效或息肉较大者手术治疗（鼻内镜下鼻息肉切除+鼻窦开放术），术前术后均需规范药物治疗和定期复查，鼻息肉易复发，需长期管理","术前准备：术前2-4周规范药物治疗（口服泼尼松30-40mg qd×5-7天+鼻用激素+抗生素+鼻腔冲洗），可使息肉明显缩小、改善鼻塞、减少术中出血、便于手术操作；术前完善CT、凝血、传染病等检查","术后处理：术后鼻腔填塞碘仿纱条或止血海绵24-48小时；术后抗生素3-5天预防感染；术后鼻用激素+鼻腔冲洗3-6个月；术后定期鼻内镜复查清理（术后1月内每周1次，清理痂皮、囊泡、粘连，2-3月每2周1次，3-6月每月1次），是防止粘连和息肉复发的关键","复发：鼻息肉术后复发率较高，术后5年复发率约20-40%，嗜酸性粒细胞型、Samter三联征、双侧多发息肉、哮喘患者复发率更高；复发后可再次药物治疗或手术治疗；规范术后用药和复查可显著降低复发率","与鼻腔恶性肿瘤鉴别：恶性肿瘤多为单侧、进行性鼻塞、血性涕、面部麻木、牙痛、视力下降、头痛，检查见新生物质硬、表面溃烂、易出血，CT可见骨质破坏，病理可确诊；鼻息肉多为双侧、质软、不易出血、无骨质破坏；单侧息肉或质硬易出血者必须病理检查排除肿瘤","预后：药物治疗可使小息肉缩小或消失，大息肉术后鼻塞可明显改善，嗅觉恢复取决于嗅神经损害程度（时间短者可恢复，长期压迫致嗅神经变性者恢复差）；鼻息肉易复发，需长期管理；巨大息肉长期不治疗可致蛙鼻畸形、睡眠呼吸暂停、慢性鼻窦炎等并发症；恶变罕见，但单侧息肉需病理排除肿瘤","预防：积极治疗过敏性鼻炎和慢性鼻窦炎；增强体质，预防上呼吸道感染；避免接触过敏原；戒烟；避免长期接触粉尘、烟雾、刺激性气体；阿司匹林不耐受者避免阿司匹林和非甾体抗炎药；术后规范用药和定期复查防止复发","我国现状：鼻内镜手术已普及，疗效好，但术后复查依从性差，复发率较高；很多患者对长期使用鼻用激素有顾虑，自行停药，导致复发；需加强健康教育，推广规范药物治疗和术后复查的重要性"],"emergency":["出现术后鼻腔大量出血（手术创面出血，立即就医压迫止血，必要时输血）","出现剧烈头痛、呕吐、发热、意识障碍、视力下降（颅内或眶内并发症，罕见但严重，立即急诊）","出现哮喘急性发作、呼吸困难、喘息（Samter三联征或合并哮喘，立即就医平喘治疗）","出现单侧进行性鼻塞、血性涕、面部麻木、牙痛、视力下降（排除鼻腔恶性肿瘤，尽快鼻内镜和CT检查，病理活检）","出现鼻息肉迅速增大、面部畸形、眼球突出、复视（排除恶性肿瘤或巨大息肉压迫，及时就医）","出现高热、寒战、头痛剧烈（急性感染或感染扩散，及时就医）","出现耳闷、耳鸣、听力骤降（堵塞咽鼓管或合并内耳受累，及时就医）","儿童出现鼻息肉（需排除囊性纤维化、不动纤毛综合征等全身疾病，及时就医检查）"],"pinyin":"bixirou","icd10":"J33.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态、面容","耳部：耳廓（畸形/红肿/皮疹/瘘管）、外耳道（耵聍/异物/分泌物/红肿/狭窄/闭锁）、鼓膜（标志/充血/内陷/穿孔/钙化/液平/肉芽）、乳突（红肿/压痛）、听力（耳语/音叉试验：Rinne试验/Weber试验/Schwabach试验）、前庭功能（自发性眼震/位置试验）","鼻部：外鼻（畸形/红肿）、鼻前庭（红肿/疖肿/结痂）、鼻腔（鼻中隔偏曲/糜烂/出血/穿孔、下鼻甲肿大/息肉样变、中鼻甲息肉样变/气化、鼻道分泌物（黏脓/血性/水样）、息肉/新生物）、鼻窦（压痛：额窦/上颌窦/筛窦）、后鼻孔检查","咽喉部：口咽（黏膜充血/肿胀/溃疡、扁桃体大小（Ⅰ-Ⅳ度）/充血/隐窝脓栓/结石、咽后壁淋巴滤泡增生/脓性分泌物、悬雍垂水肿/偏斜、软腭运动）、喉咽（会厌充血/水肿/囊肿、杓状会厌襞、梨状窝新生物/积液）、喉部（间接喉镜/电子喉镜：声带充血/息肉/小结/麻痹/新生物、室带肥厚、声门闭合情况）","颈部：淋巴结肿大（部位/大小/质地/活动度/压痛）、甲状腺、包块、瘘管","其他：发音（声嘶/失声）、吞咽（困难/呛咳）、呼吸（喘鸣/呼吸困难）"],"lab_tests":["硬性鼻内镜检查（0°/30°镜，含中鼻道、嗅裂观察）：首选检查，评估息肉大小、数量、蒂部来源及有无后鼻孔息肉，同时观察鼻黏膜水肿与分泌物情况","鼻窦CT薄层扫描（冠状位+轴位，骨窗+软组织窗）：术前必查，明确病变范围、骨质破坏、双侧筛窦/上颌窦/额窦受累程度，与内翻性乳头状瘤等占位鉴别","嗅觉功能检测（嗅棒测试/嗅觉心理物理测试）：客观评估嗅觉减退程度，作为疗效随访基线","过敏原检测（皮肤点刺试验或血清特异性IgE）：排查变应性因素，合并哮喘或阿司匹林耐受不良者重点评估","鼻功能检查（鼻阻力测定/鼻声反射）及鼻分泌物嗜酸性粒细胞检测：评估通气功能与嗜酸性炎症表型，指导用药","眼科会诊检查（视力、眼球运动、复视、眶周触诊）：巨大息肉或筛窦病变疑累及眶内、术前出现眶周胀痛或视力异常时完善，排除鼻源性眶内并发症"],"nursing":["体位护理：术后取半卧位，头部抬高15°~30°，减轻鼻面部肿胀与渗血；严禁用力擤鼻、喷嚏时张口、剧烈咳嗽，防压力性出血","出血观察：观察鼻腔及后鼻孔渗血量与色，口内血性分泌物嘱轻吐勿咽下，勿反复吞血，渗血多时及时通知医师","术后鼻腔冲洗：术后48小时起遵医嘱行鼻腔冲洗（生理盐水或高渗盐水，37℃左右），每日1~2次，动作轻柔，头前倾防呛咳","病情观察：术后重点观察有无眶周淤血、眼球胀痛、复视、视力下降等眶内并发症征象，出现立即报告并请眼科会诊","口腔护理：口内血痂及分泌物及时清理，保持口腔清洁，术后当日开始常规口腔护理，预防口腔异味与感染"],"diet":["术前：普通均衡饮食，忌辛辣刺激（辣椒、芥末、花椒）、烟酒，避免诱发鼻腔充血加重症状","术后当日：温凉流质/半流质，如凉粥、温牛奶、藕粉，禁食过热食物以防血管扩张再出血","术后恢复期：软食为主，避免过硬、过烫及粗糙食物（坚果、油炸食品、带骨肉类），细嚼慢咽","忌口：忌辛辣、烟酒、浓茶咖啡，忌过冷过热刺激（冰饮、热汤），伴阿司匹林耐受不良者同时避免含水杨酸类食物及药物","营养支持：多饮水，适量增加高蛋白（瘦肉、鱼、蛋、豆制品）及富含维生素C的新鲜蔬果，促进鼻黏膜修复"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":399},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"5184d71c716987cf798263b04284261897c9d2a6bd71d82760af6cfb116487f7","pinyin":"bixirou","initials":"bxr","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","鼻塞：持续性，进行性加重，息肉增大后完全阻塞鼻腔，说话呈闭塞性鼻音，睡眠时打鼾，可致睡眠呼吸暂停\\n流涕：黏液性或脓性，量多少不一，后鼻孔息肉可致鼻涕后流\\n嗅觉减退或丧失：息肉堵塞嗅裂或嗅神经末梢变性，多为进行性\\n头痛：一般不明显，息肉阻塞鼻窦开口引起鼻窦炎时可有头痛、闷胀痛\\n耳部症状：巨大息肉堵塞咽鼓管咽口可致耳鸣、耳闷、听力下降\\n其他：口干咽干（长期张口呼吸）、咽炎、咳嗽、痰多（分泌物刺激）、面部胀痛、鼻背增宽（巨大息肉，蛙鼻）\\n鼻镜检查：鼻腔内可见一个或多个表面光滑、灰白色或淡红色、半透明、柔软如荔枝肉状的新生物，触之柔软不痛、可移动、不易出血，多来源于中鼻道、筛窦，可充满鼻腔，后鼻孔息肉多来源于上颌窦，经上颌窦开口坠入后鼻孔\\n可伴鼻中隔偏曲、鼻窦炎、哮喘、阿司匹林不耐受（Samter三联征：鼻息肉+哮喘+阿司匹林不耐受）\\n并发症：慢性鼻窦炎、分泌性中耳炎、咽炎、支气管炎、哮喘加重、蛙鼻畸形（巨大息肉）、眶内并发症（罕见）",60],["摘要","鼻腔和鼻窦黏膜的慢性疾病，以极度水肿的鼻黏膜在中鼻道形成单发或多发息肉为特征，表现为持续性鼻塞、流涕、嗅觉减退、头痛，常伴慢性鼻窦炎和哮喘，药物和手术综合治疗。",30],["疾病编码","J33.9",30],["原首字母","bixirou",60]]},{"id":"orders-8f806de45d8843f535e3","key":"v1-c9ccc21dfe2a3058|orders-8f806de45d8843f535e3","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"鼻中隔偏曲","category":"耳鼻喉","raw":{"name":"鼻中隔偏曲","category":"耳鼻喉","summary":"鼻中隔偏离中线向一侧或两侧弯曲，或局部形成突起，引起鼻功能障碍或症状，表现为鼻塞、鼻出血、头痛，是耳鼻喉常见病，多数人有不同程度偏曲，有症状者需治疗。","symptoms":["鼻塞：主要症状，单侧或双侧，取决于偏曲类型和程度，C型偏曲多为单侧鼻塞，S型偏曲多为双侧鼻塞，偏曲凸面侧鼻塞明显，对侧下鼻甲代偿性肥大也可致鼻塞","鼻出血：偏曲凸面、骨棘或骨嵴处黏膜薄，受空气和尘埃刺激易糜烂出血，擤鼻或挖鼻后出血","头痛：偏曲部位压迫下鼻甲或中鼻甲，可引起同侧反射性头痛，多为钝痛，鼻塞加重时头痛加重，用血管收缩剂或表面麻醉后头痛可减轻","邻近器官症状：高位偏曲妨碍鼻窦引流，可继发鼻窦炎；影响咽鼓管功能可致耳鸣、耳闷；长期鼻塞张口呼吸可致咽炎、上呼吸道感染；鼻分泌物增多","鼻镜检查：鼻中隔呈C型、S型偏曲，或有骨棘（矩状突，尖锥样突起）、骨嵴（由前向后的条形山嵴样突起），偏曲凸面黏膜薄、充血或糜烂，对侧下鼻甲代偿性肥大","可伴慢性鼻炎、鼻窦炎、鼻息肉","并发症：鼻窦炎、分泌性中耳炎、咽炎、上呼吸道感染、睡眠呼吸暂停（严重鼻塞）"],"diagnosis":["典型症状（鼻塞、鼻出血、头痛）+鼻镜检查见鼻中隔偏曲","前鼻镜检查（观察鼻中隔偏曲类型、程度、部位，有无骨棘骨嵴，黏膜情况，下鼻甲代偿性肥大）","鼻内镜检查（详细观察鼻中隔各部位，尤其是后段偏曲，评估对鼻窦开口和咽鼓管的影响）","鼻窦CT（明确偏曲类型、程度、部位，评估鼻窦情况、下鼻甲肥大、钩突肥大，是术前必查）","鼻腔通气功能检查（鼻阻力测定、声反射鼻腔测量，客观评估鼻塞程度）","排除鼻中隔黏膜肥厚、鼻中隔血肿、鼻中隔脓肿、鼻中隔肿瘤、鼻腔异物、鼻息肉","分型：按形态分C型偏曲（向一侧弯曲）、S型偏曲（前后段分别向两侧弯曲）、骨棘（矩状突，尖锥样突起）、骨嵴（条形山嵴样突起）；按部位分软骨部偏曲、骨部偏曲、混合性偏曲；按程度分轻度（偏曲轻，无症状）、中度（偏曲明显，有症状）、重度（偏曲严重，明显影响功能）","诊断标准：鼻中隔偏离中线，伴有鼻功能障碍（鼻塞、鼻出血、头痛等）或症状者；多数人鼻中隔有不同程度偏曲，无症状者为生理性偏曲，不需诊断和治疗"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般无需静脉输液；鼻中隔偏曲以鼻用糖皮质激素喷鼻（如糠酸莫米松鼻喷雾剂 每侧2喷 喷鼻 qd）等局部治疗为主","方案2（围手术期）：","用法：术前一般无需静脉抗生素，术后3-5天静脉或口服抗生素预防感染","方案3（合并急性鼻窦炎或感染）：","用法：0.9%NS 100ml + 抗生素 ivgtt qd（根据病原选择）","方案4（术后出血较多）：","用法：止血药静脉输注（止血敏、氨甲环酸），必要时输血〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","方案5（补液支持）：","用法：0.9%NS 500ml 静滴 qd；5%GS 500ml 静滴 qd；10%氯化钾 10ml 加入上述液体静滴（维持水电解质平衡）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（无症状者）：","用法：无需用药","药物2（有症状者）：","用法：鼻用糖皮质激素（布地奈德、糠酸莫米松鼻喷雾剂，减轻鼻黏膜炎症水肿，改善鼻塞，合并鼻炎鼻窦炎时）、鼻用减充血剂（羟甲唑啉、麻黄碱滴鼻液，短期使用不超过7天，缓解鼻塞，术前准备）、鼻腔冲洗（生理盐水，清洁鼻腔，减轻黏膜炎症）、止血药（鼻出血时安络血5mg tid、止血敏0.5g tid）、抗生素（合并感染时头孢克肟0.2g bid、阿莫西林0.5g tid）、止痛药（头痛或术后布洛芬0.2g prn）","药物3（术前准备）：","用法：术前3天抗生素滴鼻液清洁鼻腔，术前1天鼻用减充血剂，术前根据情况口服抗生素","药物4（术后用药）：","用法：抗生素3-5天预防感染、止痛药、止血药、鼻用激素（术后1-2周开始，防止粘连和黏膜水肿）、鼻腔冲洗（术后1周开始，清洁术腔）","药物5（中医中药）：","用法：辨证使用，鼻塞为主用苍耳子散，出血为主用凉血止血方","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["无症状者（生理性偏曲）：无需治疗，观察","有症状者：手术治疗是唯一有效的方法——鼻中隔黏膜下切除术（切除偏曲的软骨和骨质，保留鼻中隔软骨支架，经典术式）、鼻中隔成形术（保留和复位偏曲的软骨和骨质，更符合生理，是目前主流术式，尤其适用于青少年和偏曲较轻者）、鼻中隔矫正术（在鼻内镜下矫正偏曲，微创，视野清晰，可同时处理下鼻甲肥大、鼻窦炎、鼻息肉）；手术指征：鼻中隔偏曲引起长期鼻塞、反复鼻出血、反射性头痛、影响鼻窦引流致鼻窦炎、影响咽鼓管功能致分泌性中耳炎、鼻腔鼻窦手术的前置手术、睡眠呼吸暂停","手术方式：鼻内镜下鼻中隔成形术（目前主流，微创，保留软骨支架，矫正偏曲，可同时处理下鼻甲、鼻窦）、鼻中隔黏膜下切除术（经典术式，切除偏曲软骨骨质，适用于严重偏曲）、鼻中隔二线减张术（矫正软骨部偏曲，微创）","同期手术：下鼻甲成形术（下鼻甲代偿性肥大时）、鼻窦开放术（合并鼻窦炎鼻息肉时）、腺样体切除术（儿童合并腺样体肥大时）","术前准备：完善CT、凝血、传染病等检查；术前3天抗生素滴鼻液清洁鼻腔（如左氧氟沙星滴鼻液 每侧2-3滴 tid）；术前1天鼻用减充血剂（羟甲唑啉鼻喷剂 每侧1喷 bid）；控制血压（高血压者）；避免服用抗凝药（阿司匹林、华法林，术前1周停用）","术后处理：术后鼻腔填塞碘仿纱条或止血海绵24-48小时（压迫止血，支撑鼻中隔）；术后抗生素3-5天预防感染（如阿莫西林 0.5g 口服 tid）；术后止痛药（对乙酰氨基酚 0.5g 口服 q6h）、止血药（氨甲环酸 0.5g 口服 tid）；术后24-48小时取出填塞物；术后1周开始鼻腔冲洗和鼻用激素（糠酸莫米松鼻喷剂 200μg 每侧 qd）；术后定期鼻内镜复查清理（防止粘连、血肿、脓肿，术后1月内每周1次，2-3月每2周1次）","并发症处理：鼻中隔血肿（术后出血积聚，需切开引流，辅以抗生素如阿莫西林 0.5g 口服 tid）、鼻中隔脓肿（感染，需切开引流+抗生素，如头孢曲松 2g 静滴 qd）、鼻中隔穿孔（术后并发症，小穿孔无症状，大穿孔可致鼻腔干燥、脓痂、呼吸哨音，需修补）、鼻腔粘连（术后定期复查可预防和处理）、鼻梁塌陷（切除过多鼻中隔软骨，少见）、脑脊液鼻漏（损伤筛板，罕见）","预防：避免鼻部外伤；积极治疗鼻炎鼻窦炎；出现鼻塞、鼻出血、头痛及时就医；术后定期复查防止并发症","随访：术后定期鼻内镜复查（至少3个月），观察术腔愈合、有无粘连、血肿、脓肿、穿孔；评估鼻塞、鼻出血、头痛改善情况"],"management":["术前护理：完善术前检查（CT、凝血、传染病、心电图、胸片）；术前3天抗生素滴鼻液清洁鼻腔（每日3-4次）；术前1天鼻用减充血剂（减轻黏膜水肿）；控制血压（高血压者术前血压控制在140/90以下）；术前1周停用抗凝药（阿司匹林、华法林、氯吡格雷）；术前禁食禁水（全麻手术）；解释手术目的、过程和注意事项，消除焦虑","术后护理：术后半卧位休息（减轻头部充血和出血）；术后24小时内冷敷鼻部（减轻肿胀和出血）；术后鼻腔填塞期间张口呼吸，口唇干燥可涂石蜡油或用湿纱布覆盖；术后24-48小时取出填塞物，取填塞时可能有少量出血，属正常；术后避免用力擤鼻、挖鼻、剧烈运动、打喷嚏（可张口深呼吸或按压人中）；术后1周内避免洗头洗澡水入鼻；术后1周开始鼻腔冲洗（每日1-2次）和鼻用激素；术后饮食温凉软食，避免辛辣刺激、过热食物（防止出血）；保持大便通畅，避免用力排便","用药护理：按医嘱使用抗生素（术后3-5天）、止痛药、止血药；术后1周开始鼻用激素（每日1-2次，连续1-3个月，防止黏膜水肿和粘连）；鼻腔冲洗（每日1-2次，清洁术腔，促进愈合）；观察药物疗效和副作用（抗生素胃肠道反应、止痛药胃肠道反应）","病情观察：观察鼻腔出血情况（术后少量渗血属正常，大量鲜血从鼻孔流出或频繁吞咽（血液后流）提示出血，需及时告知医生）；观察体温变化（发热提示感染或脓肿）；观察头痛、视力变化（罕见并发症）；观察有无鼻梁塌陷、鼻中隔穿孔征象；术后定期鼻内镜复查，观察术腔愈合、有无粘连、血肿、脓肿；出现大量出血、发热、剧烈头痛、视力下降及时就医","饮食：术后温凉软食（牛奶、豆浆、粥、面条、蒸蛋），避免辛辣刺激、过热、过硬食物（防止出血）；多饮水，多吃新鲜蔬果；保持大便通畅（避免用力排便致出血），必要时用缓泻剂；戒烟酒","休息与活动：术后保证充足睡眠，避免熬夜；术后1周内避免剧烈运动、重体力劳动、跑步、跳跃（防止出血）；术后2周内避免游泳、潜水；避免用力擤鼻、挖鼻、打喷嚏；术后1周可恢复轻度活动和工作；术后1个月可恢复正常活动","个人卫生：勤洗手，预防上呼吸道感染；避免用手挖鼻；术后1周内避免洗头洗澡水入鼻（可擦脸，洗头时头后仰）；毛巾脸盆个人专用；保持口腔清洁（餐后漱口，因张口呼吸口腔干燥）","心理护理：安慰患者，解释鼻中隔偏曲是常见病，手术效果好，消除焦虑；术后鼻腔填塞期间不适（鼻塞、头痛、口干、吞咽困难）给予解释和指导，告知取出填塞后会缓解；术后定期复查的重要性（防止粘连、血肿、脓肿），鼓励按时复查","健康教育：讲解鼻中隔偏曲的病因（外伤、发育异常、鼻腔鼻窦肿瘤压迫、遗传）、症状和手术指征；强调手术是唯一有效的治疗方法，药物只能缓解症状不能矫正偏曲；指导术前准备（停用抗凝药、控制血压、清洁鼻腔）；指导术后护理（避免用力擤鼻挖鼻、避免剧烈运动、温凉软食、鼻腔冲洗）；告知术后定期鼻内镜复查的重要性（至少3个月，防止粘连、血肿、脓肿、穿孔）；出现大量出血、发热、剧烈头痛、视力下降及时就医；无症状的生理性偏曲不需治疗；避免鼻部外伤","家庭护理：家属协助患者术后观察出血情况（频繁吞咽提示血液后流）；协助患者鼻腔冲洗和用药；术后饮食准备温凉软食；陪同定期复查；保持室内适宜温湿度，避免干燥"],"notes":["鼻中隔偏曲是鼻中隔偏离中线向一侧或两侧弯曲，或局部形成突起（骨棘、骨嵴），引起鼻功能障碍或症状，是耳鼻喉常见病，多数人有不同程度的鼻中隔偏曲（约90%），但有症状者仅约30%，无症状者为生理性偏曲，不需治疗","病因：外伤（鼻部外伤，儿童期外伤，产伤）、发育异常（鼻中隔骨和软骨发育不均衡，腺样体肥大致硬腭高拱限制鼻中隔发育）、鼻腔鼻窦肿瘤或息肉压迫（推压鼻中隔）、遗传因素","分型：按形态分——C型偏曲（鼻中隔向一侧呈弧形弯曲，最常见）、S型偏曲（鼻中隔前段向一侧、后段向另一侧弯曲，可致双侧鼻塞）、骨棘（矩状突，鼻中隔上呈尖锥样突起，多位于鼻中隔软骨与骨部交界处）、骨嵴（鼻中隔上呈由前向后的条形山嵴样突起，多位于上颌骨鼻嵴或腭骨鼻嵴处）；按部位分——软骨部偏曲（前部，多见）、骨部偏曲（后部，多见筛骨垂直板和犁骨）、混合性偏曲（软骨和骨部均偏曲）；按程度分——轻度（偏曲轻，与对侧鼻腔壁尚有间隙，无症状）、中度（偏曲明显，与对侧鼻腔壁接触，有症状）、重度（偏曲严重，完全堵塞鼻腔，明显影响功能）","临床表现：鼻塞（主要症状，C型多单侧，S型多双侧，凸面侧明显，对侧下鼻甲代偿性肥大也可致鼻塞）、鼻出血（凸面、骨棘骨嵴处黏膜薄，易糜烂出血，擤鼻挖鼻后）、头痛（偏曲压迫鼻甲致同侧反射性头痛，鼻塞加重时头痛加重，血管收缩剂或麻醉后减轻）、邻近器官症状（鼻窦炎、中耳炎、咽炎、上呼吸道感染、睡眠呼吸暂停）","诊断：前鼻镜和鼻内镜检查可明确偏曲类型、程度、部位；鼻窦CT可明确偏曲情况和鼻窦、下鼻甲情况，是术前必查；注意排除鼻中隔黏膜肥厚（探针触之柔软，偏曲触之硬）、鼻中隔血肿脓肿（有外伤或手术史，黏膜隆起，穿刺可抽出血液或脓液）、鼻中隔肿瘤（新生物，质硬，病理可确诊）","治疗原则：无症状者不需治疗；有症状者手术治疗是唯一有效的方法（鼻中隔黏膜下切除术或鼻中隔成形术），药物只能缓解症状不能矫正偏曲","手术指征：鼻中隔偏曲引起长期持续性鼻塞；反复鼻出血；反射性头痛；影响鼻窦引流致慢性鼻窦炎；影响咽鼓管功能致分泌性中耳炎；鼻腔鼻窦手术的前置手术（如鼻内镜鼻窦手术前矫正偏曲以利操作）；睡眠呼吸暂停低通气综合征（严重鼻塞所致）；过敏性鼻炎和血管运动性鼻炎经保守治疗无效，怀疑与鼻中隔偏曲有关","手术方式：鼻中隔黏膜下切除术（Killian术式，切除偏曲的软骨和骨质，保留鼻中隔软骨支架，经典术式，适用于严重偏曲，但切除软骨较多可致鼻梁塌陷）、鼻中隔成形术（保留和复位偏曲的软骨和骨质，通过减张、划痕、复位等方法矫正，更符合生理，是目前主流术式，尤其适用于青少年和偏曲较轻者，保留软骨支架，减少鼻梁塌陷风险）、鼻内镜下鼻中隔矫正术（在鼻内镜直视下操作，视野清晰，微创，可同时处理下鼻甲肥大、鼻窦炎、鼻息肉，是目前最常用的术式）","术后并发症：鼻中隔血肿（术后出血积聚于软骨膜下，表现为鼻塞、鼻梁胀痛，需切开引流，否则可致软骨坏死）、鼻中隔脓肿（血肿感染，表现为发热、鼻梁红肿疼痛，需切开引流+大剂量抗生素，可致软骨坏死、鼻梁塌陷）、鼻中隔穿孔（术后并发症，多因术中损伤两侧黏膜对应部位，小穿孔无症状，大穿孔可致鼻腔干燥、脓痂、呼吸哨音，需修补）、鼻腔粘连（术后鼻中隔与下鼻甲粘连，定期复查可预防和分离）、鼻梁塌陷（切除过多鼻中隔软骨，少见，成形术可避免）、脑脊液鼻漏（损伤筛板，罕见）、嗅觉减退（罕见）","术后复查：术后定期鼻内镜复查是手术成功的关键，术后1月内每周1次（清理痂皮、囊泡、分离粘连），2-3月每2周1次，3-6月每月1次，至少随访3个月；术后1周开始鼻腔冲洗和鼻用激素","预后：手术效果好，术后鼻塞、鼻出血、头痛多可明显改善或消失；手术并发症少见，规范操作和术后复查可显著降低并发症；无症状的生理性偏曲不需治疗","预防：避免鼻部外伤（尤其是儿童期）；积极治疗腺样体肥大（儿童，防止硬腭高拱影响鼻中隔发育）；积极治疗鼻腔鼻窦肿瘤；出现鼻塞、鼻出血、头痛及时就医；术后定期复查防止并发症","我国现状：鼻中隔偏曲是耳鼻喉常见病和多发病，鼻内镜下鼻中隔成形术已普及，微创、疗效好、并发症少；但很多患者对手术有顾虑，长期鼻塞不就医，导致鼻窦炎、中耳炎等并发症；需加强健康教育，告知手术是安全有效的"],"emergency":["出现术后鼻腔大量出血（鲜血从鼻孔涌出或频繁吞咽，提示术后出血，立即就医压迫止血，必要时输血）","出现术后发热、鼻梁红肿疼痛、胀痛（鼻中隔脓肿，立即就医切开引流+抗生素，可致软骨坏死和鼻梁塌陷）","出现剧烈头痛、呕吐、发热、意识障碍、视力下降（颅内并发症或眶内并发症，罕见但严重，立即急诊）","出现清水样鼻涕、低头加重、头痛（脑脊液鼻漏，损伤筛板，立即就医，半卧位，避免擤鼻，预防感染）","出现鼻部外伤后鼻塞、鼻出血、鼻梁歪斜、皮下气肿（鼻骨骨折或鼻中隔血肿，及时就医复位或引流）","出现单侧进行性鼻塞、血性涕、面部麻木、牙痛（排除鼻腔肿瘤，尽快鼻内镜和CT检查）","术后出现鼻梁塌陷、鞍鼻（软骨坏死，及时就医评估修补）","术后出现呼吸哨音、鼻腔干燥、脓痂（鼻中隔穿孔，就医评估是否需要修补）"],"pinyin":"bizhonggepianqu","icd10":"J34.2","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态、面容","耳部：耳廓（畸形/红肿/皮疹/瘘管）、外耳道（耵聍/异物/分泌物/红肿/狭窄/闭锁）、鼓膜（标志/充血/内陷/穿孔/钙化/液平/肉芽）、乳突（红肿/压痛）、听力（耳语/音叉试验：Rinne试验/Weber试验/Schwabach试验）、前庭功能（自发性眼震/位置试验）","鼻部：外鼻（畸形/红肿）、鼻前庭（红肿/疖肿/结痂）、鼻腔（鼻中隔偏曲/糜烂/出血/穿孔、下鼻甲肿大/息肉样变、中鼻甲息肉样变/气化、鼻道分泌物（黏脓/血性/水样）、息肉/新生物）、鼻窦（压痛：额窦/上颌窦/筛窦）、后鼻孔检查","咽喉部：口咽（黏膜充血/肿胀/溃疡、扁桃体大小（Ⅰ-Ⅳ度）/充血/隐窝脓栓/结石、咽后壁淋巴滤泡增生/脓性分泌物、悬雍垂水肿/偏斜、软腭运动）、喉咽（会厌充血/水肿/囊肿、杓状会厌襞、梨状窝新生物/积液）、喉部（间接喉镜/电子喉镜：声带充血/息肉/小结/麻痹/新生物、室带肥厚、声门闭合情况）","颈部：淋巴结肿大（部位/大小/质地/活动度/压痛）、甲状腺、包块、瘘管","其他：发音（声嘶/失声）、吞咽（困难/呛咳）、呼吸（喘鸣/呼吸困难）"],"lab_tests":["鼻内镜检查（术前常规，评估偏曲部位、方向、程度及棘突/嵴突，排除鼻息肉、新生物）","鼻窦CT（冠状位为主，偏曲程度重、伴鼻窦炎或拟行FESS联合手术者术前完善；术后复查随访可选）","前鼻镜检查（门诊初筛，观察鼻中隔偏曲及下鼻甲代偿性肥大情况）","鼻声反射/鼻阻力测定（评估鼻塞的客观通气功能，术前基线及术后疗效对照，可选）","听力学检查（纯音测听+声导抗，伴分泌性中耳炎或咽鼓管功能不良者，评估中耳受累）","血常规、凝血功能及心电图（术前准备，排除出血倾向等手术禁忌）"],"nursing":["术后观察鼻腔渗血：嘱患者吐出口中血液勿咽下，观察有无频繁吞咽动作及面色、脉搏变化，前鼻孔少量渗血可用冰袋冷敷鼻部，活动性出血及时报告医生","体位与休息：术后取半卧位，头抬高15°-30°以减轻鼻部肿胀和出血，避免剧烈咳嗽、打喷嚏、擤鼻及用力屏气2周","防误吸护理：鼻腔填塞物存在期间保持口鼻呼吸通畅，进食时小口慢咽、避免呛咳，防填塞物移位或血液误吸入气道","口腔护理：因鼻腔填塞需张口呼吸，每日以生理盐水或含漱液漱口2-3次，保持口腔湿润清洁，防口腔感染","填塞物观察与宣教：观察填塞物有无脱出、有无渗血浸透外敷料，术后24-48小时协助医生取出或更换，取塞后嘱勿抠鼻，遵医嘱鼻腔冲洗及使用滴鼻剂"],"diet":["术后当日及填塞期进温凉流质或半流质饮食（米汤、藕粉、稀粥），避免过热食物扩张血管诱发再出血","忌辛辣刺激、过烫及粗硬带渣食物（辣椒、火锅、坚果、油炸食品），防刺激黏膜充血出血","避免饮酒及活血类食物（酒精、参类），减少鼻出血风险","补充富含维生素C、K及优质蛋白食物（新鲜蔬果汁、瘦肉汤、蛋羹、鱼汤），促进黏膜修复","多饮水（温水少量多次），保持大便通畅，防止用力排便致鼻腔压力增高出血"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":400},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"5d1f22f6fa9100c0d4bb52219f97d920758e406f592804c651cf7a26a8e711df","pinyin":"bizhonggepianqu","initials":"bzgpq","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","鼻塞：主要症状，单侧或双侧，取决于偏曲类型和程度，C型偏曲多为单侧鼻塞，S型偏曲多为双侧鼻塞，偏曲凸面侧鼻塞明显，对侧下鼻甲代偿性肥大也可致鼻塞\\n鼻出血：偏曲凸面、骨棘或骨嵴处黏膜薄，受空气和尘埃刺激易糜烂出血，擤鼻或挖鼻后出血\\n头痛：偏曲部位压迫下鼻甲或中鼻甲，可引起同侧反射性头痛，多为钝痛，鼻塞加重时头痛加重，用血管收缩剂或表面麻醉后头痛可减轻\\n邻近器官症状：高位偏曲妨碍鼻窦引流，可继发鼻窦炎；影响咽鼓管功能可致耳鸣、耳闷；长期鼻塞张口呼吸可致咽炎、上呼吸道感染；鼻分泌物增多\\n鼻镜检查：鼻中隔呈C型、S型偏曲，或有骨棘（矩状突，尖锥样突起）、骨嵴（由前向后的条形山嵴样突起），偏曲凸面黏膜薄、充血或糜烂，对侧下鼻甲代偿性肥大\\n可伴慢性鼻炎、鼻窦炎、鼻息肉\\n并发症：鼻窦炎、分泌性中耳炎、咽炎、上呼吸道感染、睡眠呼吸暂停（严重鼻塞）",60],["摘要","鼻中隔偏离中线向一侧或两侧弯曲，或局部形成突起，引起鼻功能障碍或症状，表现为鼻塞、鼻出血、头痛，是耳鼻喉常见病，多数人有不同程度偏曲，有症状者需治疗。",30],["疾病编码","J34.2",30],["原首字母","bizhonggepianqu",60]]},{"id":"orders-4ac9b3c1aaac8fb5321f","key":"v1-c9ccc21dfe2a3058|orders-4ac9b3c1aaac8fb5321f","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"慢性咽炎","category":"耳鼻喉","raw":{"name":"慢性咽炎","category":"耳鼻喉","summary":"咽部黏膜、黏膜下及淋巴组织的慢性炎症，常为上呼吸道慢性炎症的一部分，表现为咽部异物感、干燥、灼热、痒感、微痛、刺激性咳嗽，病程长，易复发，是耳鼻喉最常见的疾病之一。","symptoms":["咽部异物感：最常见，咽内有异物感、梗阻感、痰黏感，咯之不出、咽之不下，不影响进食，空咽时明显，进食时减轻或消失","咽部干燥：咽部干燥、灼热、发紧，饮水后暂时缓解","咽部痒感：咽部发痒，引起刺激性咳嗽","微痛：咽部轻微疼痛，或隐痛、胀痛，不影响吞咽","刺激性咳嗽：咽痒引起阵发性咳嗽，无痰或少量黏痰，晨起时明显，刷牙时易恶心干呕","咽分泌物增多：咽部有少量黏痰，常作吭喀动作清除分泌物，重者可引起刺激性咳嗽和恶心","全身症状：一般不明显，可有头晕、乏力、消化不良、低热等全身或精神症状","咽反射敏感：刷牙、漱口、检查咽部时易恶心干呕","可伴慢性鼻炎鼻窦炎（鼻涕后流刺激咽部）、慢性扁桃体炎、龋齿、胃食管反流（反酸嗳气刺激咽部）、内分泌紊乱（更年期、甲状腺疾病）、精神因素（焦虑、抑郁、恐癌）","咽部检查：慢性单纯性咽炎——咽黏膜弥漫性充血，血管扩张，色暗红，附有少量黏稠分泌物，咽后壁可有散在淋巴滤泡；慢性肥厚性咽炎——咽黏膜增厚，弥漫充血，色暗红，咽后壁淋巴滤泡增生（颗粒状隆起，散在或融合成片），咽侧索增厚（条索状隆起），腭垂可增粗延长；萎缩性/干燥性咽炎——咽黏膜干燥、萎缩变薄，色苍白或发亮，咽后壁可有黏稠分泌物或痂皮，咽腔宽大","并发症：一般无严重并发症，长期不愈可影响生活质量，精神焦虑；萎缩性咽炎可向下蔓延引起喉气管干燥"],"diagnosis":["典型症状（咽部异物感、干燥、痒感、微痛、刺激性咳嗽，病程>3个月）+咽部检查见黏膜充血、淋巴滤泡增生","详细询问病史（鼻部疾病、胃食管反流、用嗓情况、烟酒嗜好、工作环境、精神因素、全身疾病）","咽部检查（间接喉镜或电子喉镜，观察咽黏膜、淋巴滤泡、咽侧索、腭垂、喉部情况，排除喉部肿瘤）","鼻内镜检查（排除慢性鼻炎鼻窦炎、鼻息肉、腺样体肥大，鼻涕后流是慢性咽炎常见原因）","胃镜或24小时食管pH监测（怀疑胃食管反流性咽炎时）","血常规（一般正常，急性发作时白细胞可升高）","排除咽部肿瘤（食管癌、喉癌、咽癌，尤其40岁以上、进行性吞咽困难、声音嘶哑、痰中带血、颈部肿块者）、扁桃体炎、咽部异物、茎突过长综合征、甲状腺疾病、食管疾病、精神疾病","分型：慢性单纯性咽炎（咽黏膜弥漫性充血，血管扩张，少量分泌物）、慢性肥厚性咽炎（咽黏膜增厚，淋巴滤泡增生，咽侧索增厚）、萎缩性/干燥性咽炎（咽黏膜萎缩变薄，干燥，痂皮）、反流性咽炎（胃食管反流引起）、过敏性咽炎"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般无需静脉输液；慢性咽炎以复方硼砂溶液含漱、西地碘含片 1片 含服 tid 等局部治疗为主","方案2（急性发作合并感染）：","用法：0.9%NS 100ml + 抗生素 ivgtt qd（根据病原选择）","方案3（萎缩性咽炎）：","用法：0.9%NS 250ml + 维生素C 2g ivgtt qd（辅助，促进黏膜修复）","方案4：","用法：合并其他全身疾病按相应方案治疗","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（慢性单纯性咽炎）：","用法：含漱液（复方硼砂溶液、呋喃西林溶液、生理盐水，每日3-4次含漱，清洁咽部，减轻炎症）、含片（西地碘含片、溶菌酶含片、西瓜霜含片、金嗓子喉宝、草珊瑚含片，每日3-4次，缓解症状）、中成药（咽炎片、清喉利咽颗粒、慢严舒柠、金嗓利咽丸、玄麦甘桔颗粒，辨证使用）、维生素（维生素A 2.5万U qd、维生素B2 10mg tid、维生素C 0.2g tid、维生素E 0.1g qd，促进黏膜修复，萎缩性咽炎尤其需要）","药物2（慢性肥厚性咽炎）：","用法：除上述药物外，淋巴滤泡增生明显者可用化学药物烧灼（20%硝酸银、铬酸）、冷冻、激光、射频、等离子消融治疗（消除增生淋巴滤泡，注意不可过度，避免咽部干燥和瘢痕）","药物3（萎缩性/干燥性咽炎）：","用法：咽部涂抹2%碘甘油（每日1次，促进腺体分泌，改善干燥）、口服维生素A/B2/C/E、小剂量碘剂（碘化钾0.1-0.3g tid，促进分泌，注意过敏和甲状腺疾病）、生理盐水雾化吸入（湿润咽部）","药物4（反流性咽炎）：","用法：抑酸药（奥美拉唑20mg qd、雷贝拉唑10mg qd，餐前30分钟，疗程8-12周）、促动力药（多潘立酮10mg tid、莫沙必利5mg tid，餐前15-30分钟）、黏膜保护剂（铝碳酸镁0.5g tid、硫糖铝1g qid）、生活方式调整（避免过饱、睡前进食、高脂饮食、咖啡浓茶、巧克力，抬高床头，戒烟酒，减肥）","药物5（过敏性咽炎）：","用法：抗组胺药（氯雷他定10mg qd、西替利嗪10mg qd）、白三烯受体拮抗剂（孟鲁司特钠10mg qn）、鼻用激素（合并过敏性鼻炎时）、避免过敏原〔调 肝功能/肾功能不全减量；妊娠哺乳慎用〕","药物6（急性发作）：","用法：抗生素（有细菌感染证据时，头孢克肟0.2g bid、阿莫西林0.5g tid，疗程5-7天）、抗病毒药（病毒感染时，蓝芩口服液、蒲地蓝消炎口服液）、解热镇痛药（发热咽痛明显时布洛芬0.2g prn）〔调 CrCl<30 减量；青霉素过敏禁用〕","药物7（中医中药）：","用法：辨证施治——肺阴虚型（养阴清肺汤）、肾阴虚型（六味地黄丸、知柏地黄丸）、肾阳虚型（金匮肾气丸）、痰郁互结型（半夏厚朴汤、消瘰丸）、肺脾气虚型（补中益气汤、参苓白术散）；中成药可选用咽炎片、清喉利咽颗粒、金嗓利咽丸、玄麦甘桔颗粒、慢严舒柠等","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["病因治疗（关键）：治疗慢性鼻炎鼻窦炎（鼻用激素如糠酸莫米松鼻喷剂 200μg 每侧 qd+鼻腔冲洗+抗生素，减少鼻涕后流刺激）、慢性扁桃体炎（反复发作者扁桃体切除术）、龋齿、牙周病（口腔科治疗）、胃食管反流（抑酸如奥美拉唑 20mg 口服 qd+促动力如莫沙必利 5mg 口服 tid+生活方式调整）、内分泌紊乱（更年期、甲状腺疾病，相应治疗）、纠正便秘和消化不良；避免接触粉尘、烟雾、刺激性气体；戒烟酒；改善工作和生活环境（通风、防尘、加湿）；避免过度用嗓；治疗全身慢性疾病，增强体质","局部治疗：含漱液（复方硼砂溶液或复方氯己定含漱液 10ml 含漱 tid-qid，每日3-4次）、含片（西地碘含片 1片 含服 tid-qid，每日3-4次）、咽部涂抹（碘甘油 涂布咽后壁 qd-bid，萎缩性咽炎）、雾化吸入（生理盐水+布地奈德混悬液 1mg 雾化 每日1-2次，减轻炎症和干燥）、物理治疗（超短波、药物离子导入、激光，慢性肥厚性咽炎淋巴滤泡增生明显时用冷冻、激光、射频、等离子消融，注意不可过度治疗）","药物治疗：根据分型选择药物（见口服药物），中成药辨证使用，维生素（维生素A 2.5万U 口服 qd、维生素C 0.1g 口服 tid、复合维生素B 1片 口服 tid）促进黏膜修复","手术治疗：慢性肥厚性咽炎淋巴滤泡增生明显、症状严重、药物治疗无效者，可考虑激光、射频、等离子消融治疗（消除增生淋巴滤泡），但需严格掌握指征，不可过度治疗（以免引起咽部干燥、萎缩、瘢痕）；慢性扁桃体炎反复发作者行扁桃体切除术；萎缩性咽炎一般不手术","心理治疗：伴明显焦虑、抑郁、恐癌者，给予心理疏导，必要时精神科会诊，抗焦虑抑郁药物（氟哌噻吨美利曲辛 1片 口服 qd 晨服、SSRI类如帕罗西汀 20mg 口服 qd）","预防：积极治疗急性咽炎（及时彻底，防止迁延为慢性）；积极治疗鼻炎鼻窦炎、扁桃体炎、龋齿、胃食管反流等；增强体质，预防上呼吸道感染；避免过度用嗓；戒烟酒；避免长期接触粉尘、烟雾、刺激性气体；改善工作和生活环境；保持口腔清洁；规律作息，避免熬夜；清淡饮食，避免辛辣刺激、过冷过热食物；保持心情舒畅，避免焦虑抑郁","随访：治疗后每1-3个月定期复查（评估疗效，调整方案）；慢性咽炎易复发，需长期管理和避免诱发因素；40岁以上、症状持续不缓解、进行性吞咽困难、声音嘶哑、痰中带血、颈部肿块者，需详细检查排除肿瘤（喉镜、颈部CT）"],"management":["咽部护理：用含漱液或生理盐水含漱（每日3-4次，饭后和睡前），清洁咽部，减轻炎症；保持口腔清洁（早晚刷牙，饭后漱口）；避免过度用嗓（长时间说话、大声喊叫、唱歌），用嗓后多饮水；避免用力清嗓（吭喀动作可刺激咽部黏膜，加重炎症，可改为饮水或吞咽）；室内保持适宜湿度（50-60%），避免干燥；干燥季节使用加湿器","用药护理：按医嘱使用含漱液、含片、中成药，不可长期滥用含片（可能引起口腔菌群失调和真菌感染）；维生素按时服用；反流性咽炎按医嘱用抑酸药（餐前30分钟，疗程8-12周，不可自行停药）；观察药物疗效和副作用（含片口腔不适、中成药胃肠道反应、抑酸药胃肠道反应）","病情观察：观察咽部异物感、干燥、痒感、疼痛、咳嗽变化；观察分泌物性质和量；观察有无报警症状（进行性吞咽困难、声音嘶哑、痰中带血、颈部肿块、体重下降、发热），一旦出现立即就医（排除咽喉部肿瘤）；治疗后复查咽部检查评估疗效；出现报警症状及时就医","饮食：清淡易消化饮食，多饮水（每日1500-2000ml，保持咽部湿润）；多吃新鲜蔬果（富含维生素，促进黏膜修复）；避免辛辣刺激、过冷过热、油炸、烧烤食物；避免烟酒（烟酒刺激咽部黏膜，加重炎症）；避免咖啡、浓茶、巧克力（反流性咽炎时）；反流性咽炎患者避免过饱（七八分饱）、睡前进食（睡前3小时不进食）、高脂饮食；规律进餐，细嚼慢咽；保持大便通畅","休息与活动：保证充足睡眠，避免熬夜和过度劳累；适当体育锻炼（慢跑、游泳、太极拳），增强体质，提高免疫力；避免长时间处于粉尘、烟雾、刺激性气体环境（厨房油烟、油漆、香水、二手烟）；寒冷季节外出戴口罩（避免冷空气刺激）；避免过度用嗓；用嗓职业者（教师、歌手、销售）注意嗓音保护（发声训练、适当休息、多饮水）","个人卫生：勤洗手，预防上呼吸道感染；保持口腔清洁（早晚刷牙，饭后漱口）；毛巾脸盆个人专用；避免与他人共用水杯；感冒时戴口罩，避免传染","环境管理：保持室内通风、清洁、适宜温湿度；避免接触粉尘、烟雾、刺激性气体；戒烟（包括二手烟）；厨房使用抽油烟机；使用空气净化器（过敏者）；干燥季节使用加湿器","心理护理：安慰患者，解释慢性咽炎是常见病，良性病变，不是癌症，可治疗和控制，但易复发，消除焦虑和恐癌心理；咽部异物感明显者易焦虑，给予解释和心理疏导；伴明显焦虑抑郁者建议精神科会诊；鼓励患者保持心情舒畅，避免精神紧张和抑郁（精神因素可加重咽部异物感）","健康教育：讲解慢性咽炎的病因（急性咽炎迁延、鼻炎鼻窦炎鼻涕后流、胃食管反流、用嗓过度、烟酒、粉尘刺激、全身疾病、精神因素）、分型和症状；强调病因治疗是关键（治疗鼻炎鼻窦炎、胃食管反流、扁桃体炎等），单纯对症治疗效果差、易复发；指导正确含漱和含片使用方法；告知不可长期滥用含片；反流性咽炎患者指导生活方式调整（避免过饱、睡前进食、高脂饮食，抬高床头，戒烟酒，减肥）；避免过度用嗓和烟酒；改善工作和生活环境；增强体质，预防上呼吸道感染；出现进行性吞咽困难、声音嘶哑、痰中带血、颈部肿块、体重下降及时就医（排除肿瘤）；慢性咽炎易复发，需长期管理和避免诱发因素；40岁以上、症状持续不缓解者需详细检查排除肿瘤","家庭护理：家属了解疾病知识，给予患者心理支持（避免加重其恐癌心理）；保持室内清洁、通风、适宜温湿度；避免在家中吸烟（二手烟）；饮食准备清淡、富含维生素食物；陪同定期复查；观察有无报警症状，及时就医"],"notes":["慢性咽炎是咽部黏膜、黏膜下及淋巴组织的慢性炎症，常为上呼吸道慢性炎症的一部分，是耳鼻喉最常见的疾病之一，多见于成年人，病程长，症状顽固，易复发，发病率高，占耳鼻喉门诊患者的30-40%","病因：局部因素（急性咽炎反复发作转为慢性、慢性鼻炎鼻窦炎鼻涕后流刺激咽部、慢性扁桃体炎、龋齿牙周病、长期张口呼吸、过度用嗓、长期烟酒、粉尘烟雾刺激性气体刺激）、全身因素（全身慢性疾病如贫血、消化不良、胃食管反流、心脏病、慢性支气管炎、支气管哮喘、风湿病、肝肾疾病、内分泌紊乱如更年期、甲状腺疾病、免疫功能低下、维生素缺乏、精神因素如焦虑抑郁）、环境因素（长期接触粉尘、烟雾、刺激性气体、干燥环境、温度剧烈变化）","发病机制：多种因素长期刺激咽部黏膜→黏膜慢性充血、淋巴细胞浸润、淋巴组织增生、黏膜增厚或萎缩→腺体分泌异常→咽部异物感、干燥、痒感、咳嗽等症状","分型：慢性单纯性咽炎（最常见，咽黏膜弥漫性充血，血管扩张，色暗红，少量黏稠分泌物，咽后壁可有散在淋巴滤泡，病变轻，预后好）、慢性肥厚性咽炎（咽黏膜增厚，弥漫充血，咽后壁淋巴滤泡增生（颗粒状隆起，散在或融合成片），咽侧索增厚（条索状），腭垂增粗延长，症状较重）、萎缩性/干燥性咽炎（少见，咽黏膜萎缩变薄，色苍白或发亮，腺体分泌减少，咽后壁可有黏稠分泌物或痂皮，咽腔宽大，可伴萎缩性鼻炎，多由萎缩性鼻炎蔓延或放疗后引起，治疗困难）、反流性咽炎（胃食管反流物刺激咽部引起，咽部异物感、声音嘶哑、慢性咳嗽，晨起明显，伴反酸嗳气烧心）、过敏性咽炎（过敏体质，咽部痒感、刺激性咳嗽，伴过敏性鼻炎）","临床表现：咽部异物感（最常见，咯之不出咽之不下，空咽明显进食减轻，不影响进食，是与食管肿瘤鉴别的要点）、干燥、灼热、痒感、微痛、刺激性咳嗽（晨起明显，刷牙恶心干呕）、分泌物增多、吭喀动作；一般无明显全身症状；症状因人而异，轻重不一，常在用嗓过度、受凉、疲劳、精神紧张时加重","与咽部肿瘤鉴别：咽部肿瘤（食管癌、喉癌、咽癌）多表现为进行性吞咽困难（进食受阻，与慢性咽炎进食时减轻相反）、声音嘶哑、痰中带血、颈部肿块、体重下降、年龄多在40岁以上；慢性咽炎不影响进食，无进行性加重，无颈部肿块和体重下降；40岁以上、症状持续不缓解、有报警症状者必须详细检查（电子喉镜、胃镜、颈部CT）排除肿瘤","治疗原则：病因治疗是关键（治疗鼻炎鼻窦炎、胃食管反流、扁桃体炎等），配合局部对症治疗（含漱液、含片、雾化）、中成药、维生素，慢性肥厚性咽炎淋巴滤泡增生明显者可物理治疗（激光、射频、等离子），但不可过度治疗；心理疏导；慢性咽炎易复发，需长期管理","过度治疗危害：慢性肥厚性咽炎淋巴滤泡增生行激光、射频、等离子消融时，如过度治疗（烧灼过深、范围过大）可引起咽部黏膜萎缩、干燥、瘢痕形成，反而加重咽部异物感和干燥，故需严格掌握指征和治疗范围，宁少勿多","反流性咽炎：是慢性咽炎的重要原因之一，约占慢性咽炎的30-50%，很多患者无明显反酸烧心，仅表现为咽部异物感、声音嘶哑、慢性咳嗽，晨起明显；治疗需抑酸（PPI 8-12周）+促动力+生活方式调整，单纯治疗咽炎效果差","预后：慢性单纯性咽炎预后好，去除病因和规范治疗后可痊愈或明显改善；慢性肥厚性咽炎症状较顽固，易复发；萎缩性/干燥性咽炎治疗困难，黏膜萎缩难以恢复；慢性咽炎一般不癌变，但长期不愈需排除肿瘤；精神因素明显者需心理治疗","预防：积极治疗急性咽炎（及时彻底，防止迁延）；积极治疗鼻炎鼻窦炎、扁桃体炎、龋齿、胃食管反流等；增强体质，预防上呼吸道感染；避免过度用嗓；戒烟酒；避免长期接触粉尘、烟雾、刺激性气体；改善工作和生活环境；保持口腔清洁；规律作息，避免熬夜；清淡饮食，避免辛辣刺激；保持心情舒畅，避免焦虑抑郁；用嗓职业者注意嗓音保护","我国现状：慢性咽炎发病率高，很多患者不重视，自行长期服用含片和清热解毒中成药，效果差且可能有副作用；很多慢性咽炎实际是反流性咽炎或鼻炎鼻窦炎鼻涕后流引起，单纯治疗咽炎效果差，需病因治疗；需加强健康教育，推广病因治疗和规范诊疗，避免过度治疗和滥用药物"],"emergency":["出现进行性吞咽困难、进食受阻、体重下降（排除食管癌、咽部肿瘤，尽快胃镜和喉镜检查）","出现声音嘶哑持续>2周、痰中带血、颈部肿块（排除喉癌、咽癌，尽快电子喉镜和颈部CT检查）","出现呼吸困难、喘息、喉梗阻（急性喉水肿或过敏，立即就医，保持呼吸道通畅）","出现高热、咽痛剧烈、吞咽困难、张口受限（急性扁桃体炎或扁桃体周围脓肿，及时就医抗生素+切开引流）","出现咽部大量出血（咯血或呕血，立即就医，排除咽喉部肿瘤或血管畸形）","出现过敏性休克（药物或食物过敏，呼吸困难、血压下降、意识障碍，立即急诊抢救）","慢性咽炎患者症状突然加重、伴发热、咽痛剧烈（急性发作，及时就医）","儿童出现咽部异物感、吞咽困难、流涎、拒食（排除咽部异物，及时就医喉镜检查）"],"pinyin":"manxingyanyan","icd10":"J31.2","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态、面容","耳部：耳廓（畸形/红肿/皮疹/瘘管）、外耳道（耵聍/异物/分泌物/红肿/狭窄/闭锁）、鼓膜（标志/充血/内陷/穿孔/钙化/液平/肉芽）、乳突（红肿/压痛）、听力（耳语/音叉试验：Rinne试验/Weber试验/Schwabach试验）、前庭功能（自发性眼震/位置试验）","鼻部：外鼻（畸形/红肿）、鼻前庭（红肿/疖肿/结痂）、鼻腔（鼻中隔偏曲/糜烂/出血/穿孔、下鼻甲肿大/息肉样变、中鼻甲息肉样变/气化、鼻道分泌物（黏脓/血性/水样）、息肉/新生物）、鼻窦（压痛：额窦/上颌窦/筛窦）、后鼻孔检查","咽喉部：口咽（黏膜充血/肿胀/溃疡、扁桃体大小（Ⅰ-Ⅳ度）/充血/隐窝脓栓/结石、咽后壁淋巴滤泡增生/脓性分泌物、悬雍垂水肿/偏斜、软腭运动）、喉咽（会厌充血/水肿/囊肿、杓状会厌襞、梨状窝新生物/积液）、喉部（间接喉镜/电子喉镜：声带充血/息肉/小结/麻痹/新生物、室带肥厚、声门闭合情况）","颈部：淋巴结肿大（部位/大小/质地/活动度/压痛）、甲状腺、包块、瘘管","其他：发音（声嘶/失声）、吞咽（困难/呛咳）、呼吸（喘鸣/呼吸困难）"],"lab_tests":["电子喉镜检查：观察咽后壁、咽侧索及舌根淋巴滤泡增生情况，排除声带病变及喉部占位，为诊断慢性咽炎的首选检查","鼻内镜检查：检查鼻腔、鼻咽部，排除鼻炎、鼻窦炎所致后鼻孔滴漏（鼻后滴漏综合征）引起的慢性咽炎","24小时食管pH监测：疑诊胃食管反流性咽喉炎时行此项检查，明确反流与咽部症状的关联","血常规、C反应蛋白：评估有无急慢性感染因素；伴过敏倾向者加做过敏原检测","喉部CT/颈部影像学检查：出现声嘶加重、吞咽困难或疑有占位性病变时安排","间接喉镜复诊检查：治疗后随访观察咽黏膜充血、肥厚及滤泡消退情况"],"nursing":["病情观察：监测咽痛、咽部异物感、声音嘶哑程度变化，注意有无痰中带血、吞咽困难、呼吸困难等警示症状，异常及时报告","口腔护理：指导早晚及餐后含漱淡盐水或复方氯己定含漱液，保持口腔清洁，减少咽部细菌定植","体位护理：疑及反流因素者抬高床头15～30cm，睡前2～3小时避免进食饮水，防止胃酸反流刺激咽喉","雾化吸入护理：遵医嘱行布地奈德等雾化治疗，治疗后30分钟内不进食、不漱口，使药液充分附着咽部黏膜","健康宣教：避免用力清嗓、长时间高声用嗓，戒烟限酒，避免粉尘及刺激性气体环境"],"diet":["忌辛辣、过烫、油炸、腌制食物及烟酒，避免浓茶、咖啡等刺激性饮品","急性发作期给予温凉流质或软食（粥、烂面条、蛋羹、藕粉），避免干硬粗糙食物机械刺激咽部","推荐多饮温水，可用罗汉果、胖大海、金银花、麦冬代茶饮，保持咽部黏膜湿润","反流性咽炎患者忌巧克力、高脂食物，少食多餐，餐后勿立即平卧","加强营养支持：多食梨、百合、银耳、新鲜蔬果，补充维生素A、C，促进咽黏膜修复"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":401},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"df62f7af993f19e1ffb0f8a6abf22af8f7e8c72973b77177566403ca9afae9ac","pinyin":"manxingyanyan","initials":"mxyy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","咽部异物感：最常见，咽内有异物感、梗阻感、痰黏感，咯之不出、咽之不下，不影响进食，空咽时明显，进食时减轻或消失\\n咽部干燥：咽部干燥、灼热、发紧，饮水后暂时缓解\\n咽部痒感：咽部发痒，引起刺激性咳嗽\\n微痛：咽部轻微疼痛，或隐痛、胀痛，不影响吞咽\\n刺激性咳嗽：咽痒引起阵发性咳嗽，无痰或少量黏痰，晨起时明显，刷牙时易恶心干呕\\n咽分泌物增多：咽部有少量黏痰，常作吭喀动作清除分泌物，重者可引起刺激性咳嗽和恶心\\n全身症状：一般不明显，可有头晕、乏力、消化不良、低热等全身或精神症状\\n咽反射敏感：刷牙、漱口、检查咽部时易恶心干呕\\n可伴慢性鼻炎鼻窦炎（鼻涕后流刺激咽部）、慢性扁桃体炎、龋齿、胃食管反流（反酸嗳气刺激咽部）、内分泌紊乱（更年期、甲状腺疾病）、精神因素（焦虑、抑郁、恐癌）\\n咽部检查：慢性单纯性咽炎——咽黏膜弥漫性充血，血管扩张，色暗红，附有少量黏稠分泌物，咽后壁可有散在淋巴滤泡；慢性肥厚性咽炎——咽黏膜增厚，弥漫充血，色暗红，咽后壁淋巴滤泡增生（颗粒状隆起，散在或融合成片），咽侧索增厚（条索状隆起），腭垂可增粗延长；萎缩性/干燥性咽炎——咽黏膜干燥、萎缩变薄，色苍白或发亮，咽后壁可有黏稠分泌物或痂皮，咽腔宽大\\n并发症：一般无严重并发症，长期不愈可影响生活质量，精神焦虑；萎缩性咽炎可向下蔓延引起喉气管干燥",60],["摘要","咽部黏膜、黏膜下及淋巴组织的慢性炎症，常为上呼吸道慢性炎症的一部分，表现为咽部异物感、干燥、灼热、痒感、微痛、刺激性咳嗽，病程长，易复发，是耳鼻喉最常见的疾病之一。",30],["疾病编码","J31.2",30],["原首字母","manxingyanyan",60]]},{"id":"orders-bf3946bf1952553a8965","key":"v1-c9ccc21dfe2a3058|orders-bf3946bf1952553a8965","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"慢性扁桃体炎","category":"耳鼻喉","raw":{"name":"慢性扁桃体炎","category":"耳鼻喉","summary":"扁桃体的慢性炎症，多因急性扁桃体炎反复发作或隐窝引流不畅引起，表现为咽部不适、异物感、干燥、痒感、刺激性咳嗽、口臭，扁桃体肥大，可引起全身并发症，是耳鼻喉常见病。","symptoms":["咽部不适：咽部异物感、干燥、灼热、痒感、微痛","刺激性咳嗽：咽痒引起阵发性咳嗽，无痰或少量白痰","口臭：扁桃体隐窝内潴留干酪样腐败物或厌氧菌感染，产生口臭","扁桃体肥大：儿童多见，可引起吞咽困难、说话含糊不清、呼吸不畅、睡眠打鼾、睡眠呼吸暂停","全身症状：一般不明显，可有消化不良、头痛、乏力、低热、易倦等（毒素吸收引起）","急性发作时：咽痛剧烈、吞咽困难、发热、畏寒、头痛、全身酸痛，扁桃体充血肿大、表面有脓性分泌物","咽部检查：扁桃体和腭舌弓慢性充血，呈暗红色；扁桃体大小不一，可肥大（Ⅰ-Ⅲ度）或萎缩，表面凹凸不平，有瘢痕，隐窝口可见黄白色干酪样点状物；下颌角淋巴结可肿大，轻度压痛","可伴慢性咽炎、鼻炎鼻窦炎、中耳炎","并发症：局部并发症（扁桃体周围脓肿、急性中耳炎、急性淋巴结炎、咽旁脓肿）、全身并发症（风湿热、急性肾炎、心肌炎、关节炎、银屑病、虹膜睫状体炎，与链球菌感染引起的变态反应有关）"],"diagnosis":["典型病史（急性扁桃体炎反复发作史，每年≥3次）+咽部检查见扁桃体慢性充血、肥大或萎缩、隐窝口有分泌物","详细询问病史（急性发作频率、症状、用药情况、有无并发症）","咽部检查（间接喉镜或电子喉镜，观察扁桃体大小、充血、隐窝、分泌物、瘢痕，同时检查咽部其他部位）","扁桃体大小分度：Ⅰ度（不超过腭咽弓）、Ⅱ度（超过腭咽弓）、Ⅲ度（达到或超过咽后壁中线）","实验室检查：血常规（急性发作时白细胞升高、中性粒细胞比例升高）、血沉、抗链球菌溶血素O（ASO，升高提示链球菌感染，与全身并发症有关）、C反应蛋白（CRP，急性发作时升高）","咽拭子培养+药敏（急性发作时，明确病原菌，A组β溶血性链球菌最常见）","排除扁桃体生理性肥大（儿童，无症状，无反复急性发作）、扁桃体肿瘤（单侧扁桃体肿大、质硬、表面溃烂、易出血、颈部淋巴结肿大，病理可确诊）、扁桃体角化症（扁桃体表面有白色角化物，硬，不易擦去）、咽白喉（灰白色假膜，不易擦去，全身中毒症状重）","分型：增生型（扁桃体肥大，质软，多见于儿童）、纤维型（扁桃体萎缩，质硬，有瘢痕，多见于成人）、隐窝型（隐窝内有干酪样物，易引起感染和口臭，最常见）","诊断标准：有急性扁桃体炎反复发作史（每年≥3次，连续2年以上），扁桃体慢性充血、肥大或萎缩、隐窝口有分泌物，可伴全身症状，排除其他疾病"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1：","  用法：一般无需静脉输液；慢性扁桃体炎急性发作时口服阿莫西林 0.5g 口服 tid（青霉素过敏者改用阿奇霉素 0.5g 口服 qd）","","方案2（急性发作或合并扁桃体周围脓肿）：","  用法：0.9%NS 100ml + 青霉素400-800万U ivgtt q8h 或 头孢呋辛1.5g ivgtt q8h 或 头孢曲松2g ivgtt qd，根据药敏调整，疗程5-7天〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案3（合并全身并发症；风湿热、肾炎、心肌炎）：","  用法：根据相应疾病方案治疗，大剂量抗生素+糖皮质激素+对症治疗","","方案4（围手术期）：","  用法：术前一般无需静脉抗生素，术后3-5天静脉或口服抗生素预防感染","","方案5（术后出血较多）：","  用法：止血药静脉输注，必要时输血","","方案6（补液支持）：","  用法：高热、不能进食时静脉补液","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（慢性期（非急性发作））：","用法：一般无需抗生素，以局部治疗和增强体质为主；含漱液（复方硼砂溶液、呋喃西林溶液、生理盐水，每日3-4次含漱，清洁咽部）、含片（西地碘含片、溶菌酶含片，每日3-4次）、中成药（咽炎片、清喉利咽颗粒、金嗓利咽丸，辨证使用）、维生素（维生素C 0.2g tid、维生素B2 10mg tid，增强抵抗力）","药物2（急性发作）：","用法：抗生素（首选青霉素类，阿莫西林0.5g tid、阿莫西林克拉维酸钾0.625g tid；青霉素过敏者用头孢类（头孢克肟0.2g bid）或大环内酯类（阿奇霉素0.5g qd×3天、红霉素0.5g qid）；疗程5-7天，A组链球菌感染需10天，防止风湿热和肾炎）、解热镇痛药（布洛芬0.2g tid或对乙酰氨基酚0.5g tid，发热咽痛时）、含漱液和含片、抗病毒药（病毒感染时，蓝芩口服液、蒲地蓝消炎口服液）","药物3（局部治疗）：","用法：扁桃体隐窝冲洗（用生理盐水或抗生素溶液冲洗隐窝，清除干酪样物，每周1-2次）、局部涂药（2%碘甘油涂抹扁桃体，每日1次，消炎收敛）、雾化吸入（生理盐水+布地奈德，每日1-2次，减轻炎症）","药物4（增强免疫力）：","用法：匹多莫德、胸腺肽、转移因子（免疫功能低下、反复发作者）、加强锻炼、增强体质","药物5（中医中药）：","用法：辨证施治——肺阴虚型（养阴清肺汤）、肾阴虚型（知柏地黄丸）、肺脾气虚型（补中益气汤、参苓白术散）、痰瘀互结型（会厌逐瘀汤、二陈汤）；中成药可选用咽炎片、清喉利咽颗粒、金嗓利咽丸等","药物6（术前准备）：","用法：术前1周用含漱液清洁口腔，术前3天口服抗生素，术前完善检查（血常规、凝血、传染病、心电图、胸片），术前禁食禁水","药物7（术后用药）：","用法：抗生素3-5天预防感染、止痛药、止血药、含漱液（术后24小时后开始）、软食","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["非手术治疗（适用于轻症、不愿手术或有手术禁忌者）：增强体质（加强锻炼、增强营养、注意口腔卫生）、局部治疗（含漱液、含片、隐窝冲洗、局部涂药、雾化吸入）、急性发作时抗生素治疗、治疗并发症、免疫调节剂；非手术治疗效果有限，不能根治，易复发","手术治疗（扁桃体切除术，是慢性扁桃体炎的根治方法）：手术指征——慢性扁桃体炎反复急性发作（每年≥3次，连续2年以上）；扁桃体过度肥大，妨碍吞咽、呼吸、发声，或引起睡眠呼吸暂停；慢性扁桃体炎引起全身并发症（风湿热、肾炎、心肌炎、关节炎、银屑病等）；扁桃体周围脓肿史；慢性扁桃体炎伴长期低热、口臭，保守治疗无效；扁桃体良性肿瘤（乳头状瘤、息肉）；白喉带菌者，保守治疗无效；不明原因的长期发热，排除其他疾病；手术方式——扁桃体剥离术（经典术式，全麻或局麻，沿被膜剥离切除扁桃体，适用于各种情况）、扁桃体挤切术（快速挤切，适用于儿童扁桃体肥大、粘连少者，现已少用）、等离子扁桃体切除术（微创，出血少，疼痛轻，恢复快，是目前主流术式）、扁桃体部分切除术（仅切除肥大的扁桃体组织，保留被膜和部分扁桃体，适用于儿童单纯扁桃体肥大引起睡眠呼吸暂停者，创伤小，恢复快，但保留的扁桃体可能复发炎症）；术前准备（完善检查、控制急性炎症、术前禁食禁水）；术后处理（术后半卧位、术后24小时内冷敷颈部、术后6小时可进冷流质饮食、术后24小时后开始含漱、抗生素3-5天预防感染、止痛药、观察出血、术后1-2周恢复软食、术后2周恢复正常饮食）","并发症治疗：急性发作（抗生素+对症）、扁桃体周围脓肿（切开引流+大剂量抗生素，炎症消退后扁桃体切除）、全身并发症（风湿热、肾炎、心肌炎等，相应科室协同治疗，大剂量抗生素+糖皮质激素+对症）","预防：积极治疗急性扁桃体炎（及时足量抗生素，疗程足够，防止迁延为慢性和并发症）；增强体质，预防上呼吸道感染；注意口腔卫生（早晚刷牙，饭后漱口）；避免过度劳累和受凉；戒烟酒；避免辛辣刺激食物；积极治疗鼻炎鼻窦炎；儿童定期体检","随访：非手术治疗者定期复查（观察急性发作频率、症状变化、并发症）；术后定期复查（观察伤口愈合、有无出血、感染、残留，术后1周、2周、1月复查）；术后注意发音和吞咽功能恢复"],"management":["术前护理：完善术前检查（血常规、凝血、传染病、心电图、胸片，必要时肝肾功能）；术前1周用含漱液清洁口腔（每日3-4次）；术前3天口服抗生素；术前控制急性炎症（急性发作需炎症消退后2-4周手术）；术前禁食禁水（全麻术前8小时禁食、4小时禁水）；解释手术目的、过程和术后注意事项，消除焦虑；术前停用抗凝药（阿司匹林、华法林，术前1周）","术后护理：术后半卧位休息（减轻头部充血和出血）；术后24小时内冷敷颈部（每次15-20分钟，减轻肿胀和疼痛，减少出血）；术后密切观察出血情况（唾液中带血丝属正常，大量鲜血或频繁吞咽提示出血，需及时告知医生）；术后6小时可进冷流质饮食（牛奶、豆浆、冷米汤，避免热食和硬食，防止出血）；术后1-2天进流质，3-5天进半流质，1周后进软食，2周恢复正常饮食；术后24小时后开始用含漱液漱口（每日3-4次，保持口腔清洁，促进伤口愈合）；术后避免用力咳嗽、清嗓、打喷嚏（可张口深呼吸或按压人中）；术后避免剧烈运动、重体力劳动（术后2周内）；术后疼痛明显时按医嘱用止痛药（术后1-3天疼痛最明显，之后逐渐减轻）；术后1周左右伤口白膜开始脱落，可有少量出血和疼痛加重，属正常，如大量出血及时就医","用药护理：急性发作时按医嘱使用抗生素（足量足疗程，A组链球菌感染需10天，防止风湿热和肾炎），不可自行停药；解热镇痛药按时服用；含漱液和含片按医嘱使用；术后抗生素3-5天预防感染；观察药物疗效和副作用（青霉素过敏、抗生素胃肠道反应、止痛药胃肠道反应）","病情观察：观察咽部症状（咽痛、异物感、口臭、咳嗽）变化；观察急性发作频率（每年发作次数）；观察有无并发症征象（心悸、关节痛、水肿、血尿、皮疹，提示全身并发症）；术后观察出血、体温、疼痛、伤口愈合情况；出现大量出血、高热、呼吸困难、心悸、关节痛、水肿血尿及时就医","饮食：清淡易消化饮食，多饮水，多吃新鲜蔬果（富含维生素，增强抵抗力）；避免辛辣刺激、过冷过热、油炸、烧烤食物；戒烟酒；急性发作时进流质或半流质（粥、面条、蒸蛋），多饮水；术后饮食按冷流质→流质→半流质→软食→正常饮食循序渐进，避免热食、硬食、辛辣刺激（防止出血和伤口损伤）；保持大便通畅","休息与活动：保证充足睡眠，避免熬夜和过度劳累；急性发作时卧床休息；适当体育锻炼（慢跑、游泳、太极拳），增强体质，提高免疫力；术后2周内避免剧烈运动、重体力劳动、跑步、跳跃（防止出血）；术后1个月可恢复正常活动；避免长时间处于粉尘、烟雾、刺激性气体环境；寒冷季节外出戴口罩","个人卫生：勤洗手，预防上呼吸道感染；保持口腔清洁（早晚刷牙，饭后漱口）；毛巾脸盆个人专用；避免与他人共用水杯、餐具（急性发作时链球菌可通过飞沫传播）；感冒时戴口罩，避免传染","环境管理：保持室内通风、清洁、适宜温湿度；避免接触粉尘、烟雾、刺激性气体；戒烟（包括二手烟）；厨房使用抽油烟机；干燥季节使用加湿器","心理护理：安慰患者，解释慢性扁桃体炎是常见病，可治疗，反复发作者手术效果好，消除焦虑；需手术患者解释手术目的、过程和术后注意事项（术后疼痛、饮食要求、出血风险），减轻恐惧；儿童患者给予鼓励和安抚，争取配合；全身并发症患者给予心理支持，鼓励积极治疗","健康教育：讲解慢性扁桃体炎的病因（急性扁桃体炎反复发作、隐窝引流不畅）、症状和危害（全身并发症：风湿热、肾炎、心肌炎）；强调急性发作时及时足量抗生素治疗的重要性（疗程足够，A组链球菌需10天，防止并发症）；告知手术指征和手术方式；指导术后饮食和护理（冷流质→软食循序渐进，避免热食硬食，避免剧烈运动，观察出血）；增强体质，预防上呼吸道感染；注意口腔卫生；戒烟酒；避免辛辣刺激食物；出现心悸、关节痛、水肿、血尿、皮疹等全身并发症征象及时就医；术后出现大量出血、高热、呼吸困难及时就医；慢性扁桃体炎反复发作者建议手术治疗（根治方法）","家庭护理：家属协助患者口腔护理和用药；急性发作时观察体温、咽痛变化，督促按时服药；术后患者饮食准备（冷流质、软食），观察出血情况（频繁吞咽提示出血）；陪同定期复查；保持室内清洁、通风、适宜温湿度；避免在家中吸烟"],"notes":["慢性扁桃体炎是扁桃体的慢性炎症，多因急性扁桃体炎反复发作或隐窝引流不畅、细菌病毒在隐窝内繁殖引起，是耳鼻喉常见病，多见于儿童和青少年，3-7岁儿童扁桃体多为生理性肥大，需结合症状和发作频率判断是否为慢性炎症","病因：急性扁桃体炎反复发作（最主要，治疗不彻底、抗生素疗程不足）、隐窝引流不畅（扁桃体隐窝深，引流差，细菌病毒潴留）、邻近器官感染（慢性鼻炎鼻窦炎、慢性咽炎）、全身因素（抵抗力低下、营养不良、内分泌紊乱、免疫功能异常）、环境因素（粉尘、烟雾、刺激性气体）","病原菌：A组β溶血性链球菌（最常见，与全身并发症关系密切）、葡萄球菌、肺炎链球菌、流感嗜血杆菌、腺病毒、鼻病毒等","发病机制：扁桃体隐窝内细菌病毒繁殖→隐窝内炎症→隐窝口堵塞→引流不畅→慢性炎症→扁桃体增生肥大或萎缩纤维化→隐窝内干酪样物积聚→口臭→反复急性发作→毒素吸收→全身并发症（变态反应）","临床表现：咽部不适（异物感、干燥、痒感、微痛）、刺激性咳嗽、口臭、扁桃体肥大（儿童可引起吞咽困难、打鼾、睡眠呼吸暂停）、全身症状（消化不良、头痛、乏力、低热）、反复急性发作（每年≥3次，咽痛、发热、扁桃体充血化脓）","扁桃体大小分度：Ⅰ度（扁桃体不超过腭咽弓）、Ⅱ度（超过腭咽弓）、Ⅲ度（达到或超过咽后壁中线）；注意扁桃体大小与炎症程度不一定平行，萎缩型扁桃体虽小但隐窝内感染重，也可引起反复急性发作和全身并发症","全身并发症：与A组β溶血性链球菌感染引起的变态反应有关，包括风湿热（游走性关节炎、心脏炎、皮下结节、环形红斑、舞蹈病）、急性肾小球肾炎（血尿、蛋白尿、水肿、高血压）、心肌炎（心悸、心律失常、心衰）、关节炎（游走性关节痛）、银屑病、虹膜睫状体炎、败血症等；慢性扁桃体炎是这些全身疾病的病灶，称为病灶性扁桃体炎","手术指征（扁桃体切除术）：慢性扁桃体炎反复急性发作（每年≥3次，连续2年以上）；扁桃体过度肥大，妨碍吞咽、呼吸、发声，或引起阻塞性睡眠呼吸暂停低通气综合征；慢性扁桃体炎引起全身并发症（风湿热、肾炎、心肌炎、关节炎、银屑病等）；扁桃体周围脓肿史；慢性扁桃体炎伴长期低热、口臭，保守治疗无效；扁桃体良性肿瘤；白喉带菌者，保守治疗无效；不明原因的长期发热，排除其他疾病；慢性扁桃体炎伴慢性中耳炎、鼻窦炎，反复发作，考虑与扁桃体有关","手术禁忌证：急性扁桃体炎发作期（需炎症消退后2-4周手术）；造血系统疾病及有凝血机制障碍者（白血病、再生障碍性贫血、血友病等）；严重全身性疾病（活动性肺结核、风湿性心脏病、心力衰竭、严重高血压、肝肾功能不全）；脊髓灰质炎及流感等呼吸道传染病流行季节或地区；妇女月经期和妊娠期；患者免疫球蛋白缺乏或自身免疫病发病率高者；白细胞计数特别低者（<3000/mm³）","手术方式：扁桃体剥离术（经典术式，沿扁桃体被膜剥离切除，适用于各种情况，全麻或局麻）、扁桃体挤切术（快速挤切，适用于儿童扁桃体肥大、粘连少者，手术快，但可能残留，现已少用）、等离子扁桃体切除术（用低温等离子刀切除扁桃体，微创，出血少，疼痛轻，恢复快，是目前主流术式）、扁桃体部分切除术（仅切除肥大的扁桃体组织，保留被膜和部分扁桃体，适用于儿童单纯扁桃体肥大引起睡眠呼吸暂停者，创伤小，恢复快，但保留的扁桃体可能复发炎症，不适合慢性炎症反复发作者）","术后出血：是扁桃体切除术最常见的并发症，分为原发性出血（术后24小时内，多因术中止血不彻底、肾上腺素后作用、咳嗽、吞咽）和继发性出血（术后5-10天，白膜脱落时，多因伤口感染、进食硬食、剧烈活动）；少量出血可压迫止血、冷敷；大量出血需手术止血，必要时输血；术后密切观察，频繁吞咽提示血液后流，需及时处理","术后疼痛：术后1-3天疼痛最明显，可放射至耳部，之后逐渐减轻；术后1周左右白膜脱落时疼痛可能再次加重；可使用止痛药、冷敷颈部、进食冷流质缓解；儿童术后疼痛可能影响进食和饮水，需鼓励进食和补液","术后饮食：术后6小时可进冷流质（牛奶、豆浆、冷米汤），避免热食（血管扩张致出血）；术后1-2天进流质；3-5天进半流质（粥、面条、蒸蛋）；1周后进软食；2周恢复正常饮食；避免辛辣刺激、硬食、油炸食物（损伤伤口致出血）；鼓励进食和饮水，促进伤口愈合和防止脱水","预后：慢性扁桃体炎非手术治疗效果有限，易复发；扁桃体切除术是根治方法，手术效果好，术后急性发作和全身并发症多可缓解或治愈；儿童单纯扁桃体肥大行部分切除术后可能复发炎症；术后出血、感染等并发症少见，规范操作和术后护理可显著降低；术后发音和免疫功能一般不受明显影响（扁桃体是外周免疫器官，儿童期有一定免疫功能，5岁以下儿童手术需谨慎，但反复感染和肥大引起并发症时手术利大于弊）","预防：积极治疗急性扁桃体炎（及时足量抗生素，疗程足够，A组链球菌需10天，防止迁延为慢性和并发症）；增强体质，预防上呼吸道感染；注意口腔卫生（早晚刷牙，饭后漱口）；避免过度劳累和受凉；戒烟酒；避免辛辣刺激食物；积极治疗鼻炎鼻窦炎；儿童定期体检；反复发作者建议手术治疗","我国现状：慢性扁桃体炎是耳鼻喉常见病和多发病，扁桃体切除术是耳鼻喉最常见的手术之一；但很多患者对手术有顾虑，长期反复急性发作不手术，导致全身并发症（风湿热、肾炎）；需加强健康教育，告知手术是安全有效的，反复发作者手术利大于弊；等离子微创手术已普及，出血少、疼痛轻、恢复快"],"emergency":["出现术后鼻腔大量鲜血涌出或频繁吞咽（术后出血，立即就医压迫止血，必要时输血和手术止血）","出现高热、寒战、咽痛剧烈、吞咽困难、张口受限、颈部肿胀（急性扁桃体炎或扁桃体周围脓肿，及时就医大剂量抗生素+切开引流）","出现心悸、胸闷、心律失常、呼吸困难（心肌炎或风湿性心脏病，立即就医）","出现关节红肿疼痛、游走性关节痛（风湿热，及时就医）","出现血尿、蛋白尿、水肿、高血压（急性肾炎，及时就医）","出现皮疹、关节痛、腹痛（过敏性紫癜或银屑病加重，及时就医）","出现呼吸困难、喘息、喉梗阻（急性喉水肿或过敏，立即就医保持呼吸道通畅）","儿童出现睡眠呼吸暂停、白天嗜睡、生长发育迟缓（扁桃体肥大引起阻塞性睡眠呼吸暂停，及时就医评估手术）","出现单侧扁桃体迅速肿大、质硬、表面溃烂、易出血、颈部淋巴结肿大（排除扁桃体恶性肿瘤，尽快病理活检）","急性发作时出现抽搐、意识障碍、严重脱水（高热惊厥或严重感染，立即急诊）"],"pinyin":"manxingbiantaotiyan","icd10":"J35.0","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态、面容","耳部：耳廓（畸形/红肿/皮疹/瘘管）、外耳道（耵聍/异物/分泌物/红肿/狭窄/闭锁）、鼓膜（标志/充血/内陷/穿孔/钙化/液平/肉芽）、乳突（红肿/压痛）、听力（耳语/音叉试验：Rinne试验/Weber试验/Schwabach试验）、前庭功能（自发性眼震/位置试验）","鼻部：外鼻（畸形/红肿）、鼻前庭（红肿/疖肿/结痂）、鼻腔（鼻中隔偏曲/糜烂/出血/穿孔、下鼻甲肿大/息肉样变、中鼻甲息肉样变/气化、鼻道分泌物（黏脓/血性/水样）、息肉/新生物）、鼻窦（压痛：额窦/上颌窦/筛窦）、后鼻孔检查","咽喉部：口咽（黏膜充血/肿胀/溃疡、扁桃体大小（Ⅰ-Ⅳ度）/充血/隐窝脓栓/结石、咽后壁淋巴滤泡增生/脓性分泌物、悬雍垂水肿/偏斜、软腭运动）、喉咽（会厌充血/水肿/囊肿、杓状会厌襞、梨状窝新生物/积液）、喉部（间接喉镜/电子喉镜：声带充血/息肉/小结/麻痹/新生物、室带肥厚、声门闭合情况）","颈部：淋巴结肿大（部位/大小/质地/活动度/压痛）、甲状腺、包块、瘘管","其他：发音（声嘶/失声）、吞咽（困难/呛咳）、呼吸（喘鸣/呼吸困难）"],"lab_tests":["口咽部间接喉镜检查：重点观察双侧扁桃体大小（分度）、隐窝口有无脓栓或瘢痕粘连、腭舌弓/腭咽弓充血程度及下颌角淋巴结有无肿大，为确诊及分型依据。","血常规＋CRP、血沉：评估急性发作期炎症程度，判断是否需要抗生素及抗炎治疗强度。","抗链球菌溶血素O（ASO）及咽拭子细菌培养＋药敏：明确有无链球菌感染及致病菌谱，指导抗菌药物选择，并随访滴度变化。","心电图及尿常规、肾功能：反复发作需排查链球菌感染后继发风湿性心脏病、急性肾小球肾炎等病灶相关性损害。","电子喉镜（必要时）：反复咽痛但扁桃体表现不典型者，排除下咽及喉部隐匿病变，观察咽侧索、舌根淋巴组织增生情况。","眼科裂隙灯检查（合并眼红、畏光、视力下降时）：排除慢性扁桃体炎作为感染病灶诱发的葡萄膜炎（虹膜睫状体炎）。"],"nursing":["病情观察：每4小时测体温，观察咽痛、吞咽痛变化，注意有无一侧咽痛加剧、张口受限、言语含糊等扁桃体周围脓肿先兆，及时报告医师。","术后出血观察（行扁桃体切除术者）：嘱患者口内分泌物轻吐于纸巾观察，若频繁吞咽动作或吐出鲜血、血凝块，立即头低侧卧位并通知医生。","体位护理：术后6小时内取半卧位，头偏向一侧，利于分泌物引流、防止血液误吸入气道；全麻清醒前去枕平卧、头偏一侧防误吸。","口腔护理：术后次日开始用复方氯己定含漱液或温生理盐水含漱，每日3-4次，避免用力鼓漱和刷牙触碰创面，预防创面感染。","疼痛与活动指导：术后颈部冰袋冷敷镇痛止血，指导少说话、避免剧烈咳嗽和用力擤鼻，减少创面牵拉出血。"],"diet":["忌口：禁食辛辣、油炸、过烫及粗糙硬质食物（坚果、带骨刺鱼、饼干），戒烟戒酒，避免刺激扁桃体及创面。","术后进食：术后6小时冷流质（冷牛奶、冰淇淋、凉米汤）开始，无出血后1-2天过渡至温凉半流质（粥、烂面条、蒸蛋羹），术后2周内禁硬食，防止创面出血。","推荐食物：多饮水（每日1500-2000ml），进食温凉、柔软、富含蛋白质和维生素的食物，如蛋羹、鱼泥、豆腐、蔬菜糊、鲜榨果汁。","营养支持：反复发作伴进食疼痛者，注意补充优质蛋白及维生素C、B族，必要时营养科会诊指导肠内营养，维持免疫功能。","餐后护理：进食后用温盐水或清水轻漱口，清除食物残渣滞留于隐窝，减少继发感染与口臭。"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":402},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"c28b201b4388476ed9ba1a67a572c2f39179c731b832f51850403677ee386a72","pinyin":"manxingbiantaotiyan","initials":"mxbtty","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","咽部不适：咽部异物感、干燥、灼热、痒感、微痛\\n刺激性咳嗽：咽痒引起阵发性咳嗽，无痰或少量白痰\\n口臭：扁桃体隐窝内潴留干酪样腐败物或厌氧菌感染，产生口臭\\n扁桃体肥大：儿童多见，可引起吞咽困难、说话含糊不清、呼吸不畅、睡眠打鼾、睡眠呼吸暂停\\n全身症状：一般不明显，可有消化不良、头痛、乏力、低热、易倦等（毒素吸收引起）\\n急性发作时：咽痛剧烈、吞咽困难、发热、畏寒、头痛、全身酸痛，扁桃体充血肿大、表面有脓性分泌物\\n咽部检查：扁桃体和腭舌弓慢性充血，呈暗红色；扁桃体大小不一，可肥大（Ⅰ-Ⅲ度）或萎缩，表面凹凸不平，有瘢痕，隐窝口可见黄白色干酪样点状物；下颌角淋巴结可肿大，轻度压痛\\n可伴慢性咽炎、鼻炎鼻窦炎、中耳炎\\n并发症：局部并发症（扁桃体周围脓肿、急性中耳炎、急性淋巴结炎、咽旁脓肿）、全身并发症（风湿热、急性肾炎、心肌炎、关节炎、银屑病、虹膜睫状体炎，与链球菌感染引起的变态反应有关）",60],["摘要","扁桃体的慢性炎症，多因急性扁桃体炎反复发作或隐窝引流不畅引起，表现为咽部不适、异物感、干燥、痒感、刺激性咳嗽、口臭，扁桃体肥大，可引起全身并发症，是耳鼻喉常见病。",30],["疾病编码","J35.0",30],["原首字母","manxingbiantaotiyan",60]]},{"id":"orders-c51a6c5cdfcb70c9cd0f","key":"v1-c9ccc21dfe2a3058|orders-c51a6c5cdfcb70c9cd0f","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"声带息肉","category":"耳鼻喉","raw":{"name":"声带息肉","category":"耳鼻喉","summary":"发生于声带固有层浅层的良性增生性病变，是喉部常见的良性病变，多因用声不当、用声过度引起，表现为声音嘶哑、发音疲劳，严重者可致呼吸困难，手术切除效果好。","symptoms":["声音嘶哑：主要症状，程度与息肉大小、部位有关，息肉小者仅声音变粗、发声疲劳，息肉大者声音嘶哑明显，甚至失声","发音疲劳：说话多时声音嘶哑加重，休息后减轻，不能持久讲话","音调改变：音调降低、单调，缺乏变化","喉部不适：咽部异物感、干燥、痒感，常作清嗓动作","咳嗽：刺激性咳嗽，无痰或少量白痰","呼吸困难：巨大息肉可堵塞声门，引起吸气性呼吸困难、喉喘鸣，严重者可致窒息（罕见）","声带息肉多为单侧，也可双侧，好发于声带前中1/3交界处","间接喉镜或电子喉镜检查：声带边缘（多为前中1/3交界处）可见表面光滑、半透明、灰白色或淡红色的新生物，呈息肉状，可有蒂或广基，随呼吸上下活动，声带闭合不全（息肉遮挡声门）","可伴慢性喉炎、声带小结、咽炎","职业因素：教师、歌手、销售、主持人、播音员等用嗓职业者多见","并发症：一般无严重并发症，巨大息肉可致呼吸困难和窒息；息肉切除后如不注意用嗓可复发"],"diagnosis":["典型症状（声音嘶哑、发音疲劳，病程较长，有用声不当或用声过度史）+喉镜检查见声带息肉","间接喉镜检查（初步观察声带情况，但受咽反射和视野限制）","电子喉镜或纤维喉镜检查（金标准，清晰观察声带息肉的大小、部位、形态、基底、声带活动和闭合情况，可拍照和录像，是诊断和术前必查）","嗓音声学分析（客观评估声音嘶哑程度，基频、抖动度、 shimmer等参数异常）","喉动态镜检查（观察声带黏膜波，息肉处黏膜波减弱或消失，与早期喉癌鉴别）","喉部CT或MRI（怀疑息肉巨大、累及声门下或排除喉部肿瘤时）","病理检查（手术切除后送病理，确诊并排除喉乳头状瘤、喉癌等）","排除声带小结（双侧对称性小突起，位于前中1/3交界处，质硬）、喉乳头状瘤（表面粗糙不平，菜花状，易复发，有恶变倾向，HPV感染）、喉癌（中老年男性，吸烟史，声带新生物表面溃烂、质硬、易出血，声带活动受限，病理可确诊）、声带囊肿（声带内半球形隆起，表面光滑，穿刺可抽出液体）、喉结核（低热、盗汗、咽痛，溃疡呈虫蚀状，肺部结核灶）、癔症性失声（突发失声，咳嗽有声，声带活动正常，与情绪有关）","分型：有蒂型（息肉有蒂，随呼吸活动，对声带闭合影响相对小）、广基型（息肉基底宽，对声带闭合影响大，声音嘶哑明显）、巨大型（息肉大，堵塞声门，可致呼吸困难）","部位：多位于声带前中1/3交界处（发声时声带振动最大处），也可位于声带突或其他部位"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般无需静脉输液；声带息肉以声带休息、雾化吸入（布地奈德混悬液 1mg + 0.9%NS 2ml 雾化吸入 bid）为主","方案2（围手术期）：","用法：术前一般无需静脉抗生素，术后3-5天静脉或口服抗生素预防感染","方案3：","用法：术后一般无需静脉激素，可雾化吸入激素减轻水肿","方案4（合并急性喉炎或喉水肿）：","用法：0.9%NS 100ml + 地塞米松5-10mg ivgtt qd（短期，减轻喉水肿）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案5（合并感染）：","用法：0.9%NS 100ml + 抗生素 ivgtt qd","方案6（补液支持）：","用法：0.9%NS 500ml 静滴 qd；5%GS 500ml 静滴 qd；10%氯化钾 10ml 加入上述液体静滴（维持水电解质平衡）（一般术后即可进温凉流质，不需长期补液）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（小息肉或不宜手术者）：","用法：声带休息（最重要，减少说话，避免大声喊叫，让声带休息，部分小息肉可缩小或消失）、雾化吸入（生理盐水+布地奈德1-2mg，每日1-2次，减轻声带水肿和炎症）、中成药（金嗓散结丸、黄氏响声丸、清音丸、喉症丸，辨证使用）、维生素（维生素B2 10mg tid、维生素C 0.2g tid，促进黏膜修复）","药物2（急性发作或合并急性喉炎）：","用法：抗生素（有细菌感染证据时，头孢克肟0.2g bid、阿莫西林0.5g tid，疗程5-7天）、糖皮质激素（泼尼松10mg tid或地塞米松0.75mg tid，短期3-5天，减轻声带水肿，注意禁忌证）、雾化吸入激素、止咳药（刺激性咳嗽时右美沙芬15mg tid）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","药物3（术后用药）：","用法：抗生素3-5天预防感染、糖皮质激素（口服或雾化，减轻声带水肿）、雾化吸入（生理盐水+布地奈德，每日1-2次，术后1-2周）、中成药（金嗓散结丸、黄氏响声丸，促进恢复）、维生素","药物4（中医中药）：","用法：辨证施治——肺经蕴热型（清热利咽，黄芩汤加减）、肺脾气虚型（补益肺脾，补中益气汤加减）、痰瘀互结型（化痰散结，会厌逐瘀汤加减）；中成药可选用金嗓散结丸、黄氏响声丸、清音丸等","药物5（嗓音训练）：","用法：术后或保守治疗者进行发声训练（纠正不良发声习惯，学习正确发声方法，避免用声过度和用声不当，是防止复发的关键）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["保守治疗（适用于小息肉、声带水肿明显、不宜手术或不愿手术者）：声带休息（最重要，绝对禁声1-2周，之后相对禁声，避免大声喊叫和长时间说话，部分小息肉可缩小或消失）、雾化吸入（激素+生理盐水，减轻水肿炎症）、药物治疗（中成药、维生素）、病因治疗（治疗慢性喉炎、鼻炎鼻窦炎、胃食管反流）、嗓音训练（纠正不良发声习惯）；保守治疗2-4周无效者应手术治疗","手术治疗（主要治疗方法，声带息肉切除术）：手术指征——声带息肉经保守治疗2-4周无效；息肉较大，声音嘶哑明显；广基息肉；息肉影响呼吸；患者对发音质量要求高（歌手、教师、主持人）；手术方式——间接喉镜下息肉切除术（简单，局麻，门诊可做，但视野和操作受限，现已少用）、纤维喉镜或电子喉镜下息肉切除术（局麻，门诊可做，视野清晰，微创，适用于小的有蒂息肉）、支撑喉镜下显微镜下声带息肉切除术（全麻，显微镜下精细操作，切除准确，创伤小，恢复好，是目前主流术式，适用于各种息肉，尤其是广基息肉和巨大息肉）、等离子或激光息肉切除术（微创，出血少，恢复快）；术前准备（完善喉镜检查、凝血、传染病等，术前禁食禁水，术前控制急性炎症）；术后处理（术后声带休息2周（绝对禁声1周，相对禁声1周）、抗生素3-5天预防感染、雾化吸入激素1-2周、中成药促进恢复、术后2周开始嗓音训练、术后1个月内避免大声喊叫和长时间说话、定期复查喉镜观察声带愈合和有无复发）","病因治疗：治疗慢性喉炎、鼻炎鼻窦炎（鼻涕后流刺激声带）、胃食管反流（反酸刺激声带，抑酸治疗）、过敏；戒烟酒；避免辛辣刺激食物；改善工作环境（避免粉尘、烟雾）","嗓音训练：术后或保守治疗者进行专业嗓音训练，学习正确发声方法（腹式呼吸、声带放松、适当音量和音调），避免用声过度和用声不当（大声喊叫、长时间说话、清嗓动作），是防止复发的关键","预防：避免用声过度和用声不当（大声喊叫、长时间说话、耳语说话）；感冒时避免用声（急性喉炎时声带休息）；戒烟酒；避免辛辣刺激食物；避免在粉尘、烟雾环境中长时间说话；积极治疗鼻炎鼻窦炎、胃食管反流；用嗓职业者注意嗓音保护（发声训练、适当休息、多饮水）；出现声音嘶哑及时就医，避免长期不治疗导致息肉增大","随访：术后定期复查喉镜（术后1周、2周、1月、3月），观察声带愈合、有无残留和复发；保守治疗者定期复查（观察息肉大小变化，无效者及时手术）；嗓音训练后评估发声质量；声带息肉术后复发率约5-10%，多因用声不当未纠正，规范嗓音训练可显著降低复发率"],"management":["术前护理：完善术前检查（电子喉镜、凝血、传染病、心电图、胸片，必要时喉部CT）；术前1周避免用声过度，让声带休息；术前3天用含漱液清洁口腔；术前控制急性炎症（急性喉炎需炎症消退后手术）；术前禁食禁水（全麻术前8小时禁食、4小时禁水）；解释手术目的、过程和术后注意事项（术后需禁声、嗓音训练），消除焦虑；术前戒烟酒","术后护理：术后全麻清醒后去枕平卧6小时，头偏向一侧（防止呕吐物误吸）；术后密切观察呼吸情况（有无呼吸困难、喉喘鸣，声带水肿或出血可致喉梗阻）；术后观察有无咯血（少量血丝属正常，大量鲜血提示出血）；术后6小时可进温凉流质饮食（避免热食和硬食，防止声带血管扩张和损伤）；术后1-2天进流质，3-5天进半流质，1周后进软食，2周恢复正常饮食；术后绝对禁声1周（不说话，包括耳语，耳语也会使声带活动，影响愈合），相对禁声1周（尽量少说话，避免大声）；术后2周开始逐渐恢复用声，从少到多，从低音到正常音量；术后1个月内避免大声喊叫、长时间说话、唱歌；术后雾化吸入（生理盐水+布地奈德，每日1-2次，术后1-2周，减轻声带水肿）；术后避免用力咳嗽、清嗓（可改为饮水或吞咽）；术后避免剧烈运动（术后1周内）；术后保持室内适宜湿度，避免干燥","用药护理：按医嘱使用抗生素（术后3-5天预防感染）、糖皮质激素（口服或雾化，减轻声带水肿）、雾化吸入（每日1-2次）、中成药（金嗓散结丸、黄氏响声丸，促进恢复）、维生素；观察药物疗效和副作用（抗生素胃肠道反应、激素副作用）","病情观察：观察声音嘶哑变化（术后声音嘶哑可能暂时加重（声带水肿），之后逐渐改善，一般术后1-3个月恢复最佳）；观察呼吸情况（有无呼吸困难、喉喘鸣，提示喉水肿或出血，需及时处理）；观察有无咯血、发热；术后定期复查喉镜（观察声带愈合、有无残留、粘连、复发）；出现呼吸困难、大量咯血、高热、声音嘶哑加重及时就医","饮食：清淡易消化饮食，多饮水（保持咽喉湿润，促进声带恢复）；多吃新鲜蔬果（富含维生素，促进黏膜修复）；避免辛辣刺激、过冷过热、油炸、烧烤食物；戒烟酒（烟酒刺激声带，加重水肿，影响愈合）；术后饮食按温凉流质→半流质→软食→正常饮食循序渐进；避免咖啡、浓茶、巧克力（反流时）；保持大便通畅","休息与活动：术后保证充足睡眠，避免熬夜；术后1周内避免剧烈运动、重体力劳动；术后2周内避免大声喊叫、长时间说话；术后1个月内避免唱歌、演讲；用嗓职业者术后2-3个月可逐渐恢复工作（需嗓音训练指导）；避免长时间处于粉尘、烟雾、刺激性气体环境；避免在嘈杂环境中大声说话（不自觉提高音量损伤声带）","个人卫生：勤洗手，预防上呼吸道感染（感冒时急性喉炎可影响声带愈合）；保持口腔清洁（早晚刷牙，饭后漱口）；避免用力咳嗽、清嗓；避免频繁做清嗓动作（可改为饮水或吞咽）；感冒时尽量少说话，让声带休息","环境管理：保持室内通风、清洁、适宜温湿度（湿度50-60%，避免干燥）；避免接触粉尘、烟雾、刺激性气体；戒烟（包括二手烟）；厨房使用抽油烟机；干燥季节使用加湿器；用嗓时保持环境安静（避免在嘈杂环境中大声说话）","心理护理：安慰患者，解释声带息肉是良性病变，手术效果好，消除焦虑和恐癌心理；术后需禁声和嗓音训练，患者可能不适应，给予解释和鼓励；用嗓职业者（歌手、教师）对发音质量要求高，术后恢复需要时间，给予心理支持，告知术后1-3个月恢复最佳，不可急于求成；复发患者给予心理支持，告知复发后可再次手术或保守治疗，关键是纠正用声习惯","健康教育：讲解声带息肉的病因（用声不当、用声过度最常见，其次为慢性喉炎、鼻炎鼻窦炎、胃食管反流、吸烟）、症状和危害（巨大息肉可致呼吸困难）；强调声带休息的重要性（术后绝对禁声1周，相对禁声1周，包括耳语也不可以）；指导正确发声方法（腹式呼吸、声带放松、适当音量和音调，避免大声喊叫、长时间说话、清嗓动作）；告知术后嗓音训练是防止复发的关键，建议在专业言语治疗师指导下进行；术后1个月内避免大声喊叫、唱歌、长时间说话；用嗓职业者术后2-3个月可逐渐恢复工作；戒烟酒，避免辛辣刺激食物；积极治疗鼻炎鼻窦炎、胃食管反流；出现声音嘶哑持续>2周不缓解及时就医（排除喉癌）；术后定期复查喉镜（1周、2周、1月、3月）；声带息肉术后复发率约5-10%，规范嗓音训练可显著降低复发率","家庭护理：家属协助患者术后饮食准备（温凉流质、软食）；术后督促患者禁声（避免患者不自觉说话，可用写字板或手机交流）；观察患者呼吸和出血情况；陪同定期复查；保持室内清洁、通风、适宜温湿度；避免在家中吸烟；鼓励患者进行嗓音训练"],"notes":["声带息肉是发生于声带固有层浅层的良性增生性病变，是喉部最常见的良性病变之一，多见于用嗓职业者（教师、歌手、销售、主持人、播音员）和用声不当者，男性略多于女性，好发于声带前中1/3交界处（发声时声带振动最大、摩擦最多处）","病因：用声不当或用声过度（最主要，大声喊叫、长时间说话、耳语说话、在嘈杂环境中大声说话、发声方法不正确）、慢性喉炎（长期炎症刺激）、鼻炎鼻窦炎（鼻涕后流刺激声带）、胃食管反流（胃酸反流刺激声带）、过敏、吸烟、饮酒、空气污染（粉尘、烟雾）、内分泌紊乱（甲状腺功能减退）、急性喉炎反复发作","发病机制：各种因素致声带黏膜损伤→血管扩张、通透性增加→组织水肿→纤维组织增生→玻璃样变性→息肉形成；息肉表面为鳞状上皮，间质为水肿的纤维结缔组织，可有血管增生和炎症细胞浸润","临床表现：声音嘶哑（主要症状，程度与息肉大小、部位、基底有关）、发音疲劳（说话多时加重，休息后减轻）、音调改变（音调降低、单调）、喉部不适（异物感、干燥、痒感）、刺激性咳嗽、巨大息肉可致呼吸困难和喉喘鸣（罕见）；声带息肉多为单侧，也可双侧","喉镜检查：间接喉镜或电子喉镜下见声带边缘（多为前中1/3交界处）表面光滑、半透明、灰白色或淡红色的息肉样新生物，可有蒂（随呼吸活动）或广基，声带闭合不全（息肉遮挡声门）；电子喉镜是诊断金标准，可清晰观察息肉大小、部位、形态、基底、声带活动和闭合情况，可拍照录像","与声带小结鉴别：声带小结多为双侧对称性，位于声带前中1/3交界处，呈小的结节状突起，质较硬，多因用声不当引起，保守治疗（声带休息、嗓音训练）效果好；声带息肉多为单侧，呈息肉状，可有蒂或广基，质软，保守治疗效果有限，多需手术；两者可同时存在","与喉癌鉴别：喉癌多见于中老年男性，有长期吸烟史，表现为进行性声音嘶哑、痰中带血、咽痛、吞咽困难、颈部淋巴结肿大，喉镜见声带新生物表面溃烂、质硬、易出血、声带活动受限或固定，病理可确诊；声带息肉表面光滑、质软、不易出血、声带活动正常；40岁以上、声音嘶哑持续>2周、有吸烟史者，必须详细喉镜检查，必要时病理活检排除喉癌","治疗原则：保守治疗（声带休息+雾化吸入+药物+嗓音训练）适用于小息肉、水肿明显、不宜手术者，2-4周无效者手术；手术治疗（声带息肉切除术）是主要治疗方法，支撑喉镜下显微镜下切除术是目前主流术式，微创、准确、恢复好；术后嗓音训练是防止复发的关键","手术方式：间接喉镜下切除术（简单，局麻，门诊，但视野操作受限，现已少用）、纤维/电子喉镜下切除术（局麻，门诊，视野清晰，微创，适用于小的有蒂息肉）、支撑喉镜下显微镜下切除术（全麻，显微镜下精细操作，切除准确，创伤小，恢复好，是目前主流术式，适用于各种息肉，尤其是广基息肉和巨大息肉）、等离子/激光切除术（微创，出血少，恢复快）","术后声带休息：术后绝对禁声1周（不说话，包括耳语，耳语也会使声带内收活动，影响愈合），相对禁声1周（尽量少说话，避免大声）；术后2周开始逐渐恢复用声，从少到多，从低音到正常音量；术后1个月内避免大声喊叫、长时间说话、唱歌；用嗓职业者术后2-3个月可逐渐恢复工作（需嗓音训练指导）；过早用声或用声不当可致声带愈合不良、息肉残留或复发","术后嗓音训练：是防止复发的关键，建议在专业言语治疗师指导下进行，学习正确发声方法（腹式呼吸、声带放松、适当音量和音调、共鸣腔运用），纠正不良发声习惯（大声喊叫、长时间说话、清嗓动作、耳语说话、在嘈杂环境中大声说话），用嗓职业者术后必须进行嗓音训练才能恢复工作和防止复发","预后：声带息肉是良性病变，手术效果好，术后声音嘶哑多可明显改善或恢复正常，术后1-3个月恢复最佳；术后复发率约5-10%，多因用声不当未纠正、过早用声、息肉残留，规范嗓音训练和术后护理可显著降低复发率；巨大息肉长期不治疗可致声带永久性损伤和呼吸困难；恶变罕见，但40岁以上、声音嘶哑持续>2周者需排除喉癌","预防：避免用声过度和用声不当（大声喊叫、长时间说话、耳语说话）；感冒时避免用声（急性喉炎时声带休息，不强行说话）；戒烟酒；避免辛辣刺激食物；避免在粉尘、烟雾、嘈杂环境中长时间说话；积极治疗鼻炎鼻窦炎、胃食管反流；用嗓职业者注意嗓音保护（发声训练、适当休息、多饮水、避免清嗓）；出现声音嘶哑及时就医，持续>2周不缓解者必须喉镜检查排除喉癌；术后规范嗓音训练防止复发","我国现状：声带息肉是耳鼻喉常见病和多发病，支撑喉镜下显微镜下声带息肉切除术已普及，微创、疗效好；但很多患者术后不注意嗓音保护和训练，复发率较高；用嗓职业者对嗓音保护认知不足，需加强健康教育，推广嗓音训练和科学用声；声音嘶哑持续>2周者需警惕喉癌，必须详细喉镜检查"],"emergency":["出现呼吸困难、喉喘鸣、吸气性三凹征（巨大息肉堵塞声门或术后喉水肿，立即就医，保持呼吸道通畅，必要时气管切开）","出现术后大量咯血、鲜血从口中涌出（术后出血，立即就医压迫止血）","出现声音嘶哑进行性加重、痰中带血、咽痛、吞咽困难、颈部淋巴结肿大（排除喉癌，尽快喉镜检查和病理活检）","出现高热、咽痛剧烈、吞咽困难（急性喉炎或扁桃体炎，及时就医）","出现过敏性休克（药物或食物过敏，呼吸困难、血压下降、意识障碍，立即急诊抢救）","术后出现声带粘连、声音嘶哑不恢复（及时就医喉镜检查和处理）","儿童出现声音嘶哑伴呼吸困难、犬吠样咳嗽（急性喉炎或喉乳头状瘤，立即就医）","出现失声、咳嗽有声、与情绪有关（癔症性失声，需排除器质性病变后心理治疗）","用嗓职业者术后急于恢复用声导致声音嘶哑加重（指导声带休息和嗓音训练，避免过早用声）"],"pinyin":"shengdaixirou","icd10":"J38.1","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态、面容","耳部：耳廓（畸形/红肿/皮疹/瘘管）、外耳道（耵聍/异物/分泌物/红肿/狭窄/闭锁）、鼓膜（标志/充血/内陷/穿孔/钙化/液平/肉芽）、乳突（红肿/压痛）、听力（耳语/音叉试验：Rinne试验/Weber试验/Schwabach试验）、前庭功能（自发性眼震/位置试验）","鼻部：外鼻（畸形/红肿）、鼻前庭（红肿/疖肿/结痂）、鼻腔（鼻中隔偏曲/糜烂/出血/穿孔、下鼻甲肿大/息肉样变、中鼻甲息肉样变/气化、鼻道分泌物（黏脓/血性/水样）、息肉/新生物）、鼻窦（压痛：额窦/上颌窦/筛窦）、后鼻孔检查","咽喉部：口咽（黏膜充血/肿胀/溃疡、扁桃体大小（Ⅰ-Ⅳ度）/充血/隐窝脓栓/结石、咽后壁淋巴滤泡增生/脓性分泌物、悬雍垂水肿/偏斜、软腭运动）、喉咽（会厌充血/水肿/囊肿、杓状会厌襞、梨状窝新生物/积液）、喉部（间接喉镜/电子喉镜：声带充血/息肉/小结/麻痹/新生物、室带肥厚、声门闭合情况）","颈部：淋巴结肿大（部位/大小/质地/活动度/压痛）、甲状腺、包块、瘘管","其他：发音（声嘶/失声）、吞咽（困难/呛咳）、呼吸（喘鸣/呼吸困难）"],"lab_tests":["电子喉镜（纤维喉镜）检查：首选，明确息肉大小、位置、基底及双侧声带情况，必要时加做窄带成像（NBI）观察微血管形态","喉动态镜（频闪喉镜）检查：评估声带黏膜波、振动对称性及闭合情况，判断声门闭合不全程度","嗓音功能评估（喉功能分析）：术前术后对比，检测基频、微扰（Jitter/Shimmer）、谐噪比及最长发声时间（MPT）","颈部薄层CT/喉部MRI：息肉较大、广基或怀疑黏膜下病变、喉室病变时排除深部侵犯及鉴别肿瘤","血常规、凝血功能、传染病筛查及心电图：术前常规完善","24小时咽喉反流监测或电子胃镜：伴反酸烧心、频繁清嗓史者排查喉咽反流病因"],"nursing":["术后绝对禁声1周（可书面或手势交流），避免咳嗽、用力清嗓及屏气用力动作，防创面出血","密切观察呼吸情况：注意有无喉水肿、吸气性喉鸣、三凹征，床旁备气管切开包及吸引装置；全麻苏醒期去枕平卧或半卧位、头偏向一侧","麻醉消退前严格禁食水，防止呛咳误吸；术后6小时起先试温凉水，无呛咳再进流食","布地奈德混悬液雾化吸入每日2次，减轻喉黏膜水肿及炎性渗出","保持口腔清洁，餐后淡盐水或漱口液含漱，减少经口感染及咽喉刺激"],"diet":["术后6小时内禁食水，6小时后进温凉流质（米汤、藕粉、蛋羹），次日过渡至软食，避免过热过烫","忌辛辣刺激（辣椒、芥末、咖喱）、过酸过甜及油炸坚硬食物，避免咖啡、浓茶、碳酸饮料","严格戒烟戒酒，减少对声带黏膜的化学刺激","每日多饮温水（少量多次），保持喉部湿润，促进声带黏膜修复","伴喉咽反流者避免睡前3小时进食及甜食、高脂食物，少食多餐，床头适当抬高"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":403},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"d0b486e4e337c24b54e9c7b943be193104a710c4d3d30c57704e0c7db188940f","pinyin":"shengdaixirou","initials":"sdxr","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","声音嘶哑：主要症状，程度与息肉大小、部位有关，息肉小者仅声音变粗、发声疲劳，息肉大者声音嘶哑明显，甚至失声\\n发音疲劳：说话多时声音嘶哑加重，休息后减轻，不能持久讲话\\n音调改变：音调降低、单调，缺乏变化\\n喉部不适：咽部异物感、干燥、痒感，常作清嗓动作\\n咳嗽：刺激性咳嗽，无痰或少量白痰\\n呼吸困难：巨大息肉可堵塞声门，引起吸气性呼吸困难、喉喘鸣，严重者可致窒息（罕见）\\n声带息肉多为单侧，也可双侧，好发于声带前中1/3交界处\\n间接喉镜或电子喉镜检查：声带边缘（多为前中1/3交界处）可见表面光滑、半透明、灰白色或淡红色的新生物，呈息肉状，可有蒂或广基，随呼吸上下活动，声带闭合不全（息肉遮挡声门）\\n可伴慢性喉炎、声带小结、咽炎\\n职业因素：教师、歌手、销售、主持人、播音员等用嗓职业者多见\\n并发症：一般无严重并发症，巨大息肉可致呼吸困难和窒息；息肉切除后如不注意用嗓可复发",60],["摘要","发生于声带固有层浅层的良性增生性病变，是喉部常见的良性病变，多因用声不当、用声过度引起，表现为声音嘶哑、发音疲劳，严重者可致呼吸困难，手术切除效果好。",30],["疾病编码","J38.1",30],["原首字母","shengdaixirou",60]]},{"id":"orders-aba6df3991f8217b4d58","key":"v1-c9ccc21dfe2a3058|orders-aba6df3991f8217b4d58","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"声带小结","category":"耳鼻喉","raw":{"name":"声带小结","category":"耳鼻喉","summary":"又称歌唱者小结、教师小结，是双侧声带前中1/3交界处对称性的结节状隆起，多因用声不当或用声过度引起，表现为声音嘶哑、发音疲劳，是喉部常见的良性病变，保守治疗效果好。","symptoms":["声音嘶哑：主要症状，早期为发声易倦、间歇性声嘶，发高音时明显，逐渐发展为持续性声嘶","发音疲劳：说话多时声音嘶哑加重，不能持久讲话，休息后减轻","音调改变：音调变粗、变低，缺乏变化，发高音困难","喉部不适：咽部异物感、干燥、痒感，常作清嗓动作","咳嗽：刺激性咳嗽，无痰或少量白痰","声带小结多为双侧对称性，位于声带前中1/3交界处","职业因素：教师、歌手、销售、主持人、播音员、儿童（爱喊叫）多见","间接喉镜或电子喉镜检查：双侧声带前中1/3交界处可见对称性小的结节状隆起，表面光滑，质较硬，声带闭合不全（小结遮挡声门，可有缝隙）","可伴慢性喉炎、咽炎","并发症：一般无严重并发症，长期不治疗可发展为声带息肉或声带永久性损伤"],"diagnosis":["典型症状（声音嘶哑、发音疲劳，有用声不当或用声过度史）+喉镜检查见双侧声带前中1/3交界处对称性小结","间接喉镜检查（初步观察）","电子喉镜或纤维喉镜检查（金标准，清晰观察小结大小、部位、形态、声带活动和闭合情况，可拍照录像）","嗓音声学分析（客观评估声音嘶哑程度）","喉动态镜检查（观察声带黏膜波）","排除声带息肉（多为单侧，息肉状，可有蒂或广基，质软）、喉乳头状瘤（表面粗糙不平，菜花状，易复发，HPV感染）、喉癌（中老年男性，吸烟史，声带新生物表面溃烂、质硬、易出血，声带活动受限，病理可确诊）、声带囊肿（声带内半球形隆起，穿刺可抽出液体）、癔症性失声（突发失声，咳嗽有声，声带活动正常，与情绪有关）","分型：早期（水肿型，小结柔软，呈水肿状，保守治疗效果好）、晚期（纤维化型，小结硬实，呈结节状，保守治疗效果差，需手术）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般无需静脉输液；声带小结以声带休息、雾化吸入（布地奈德混悬液 1mg + 0.9%NS 2ml 雾化吸入 bid）为主","方案2（合并急性喉炎）：","用法：0.9%NS 100ml + 地塞米松5-10mg ivgtt qd（短期，减轻喉水肿）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案3（围手术期）：","用法：术前一般无需静脉抗生素，术后3-5天静脉或口服抗生素预防感染","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（保守治疗（首选））：","用法：声带休息（最重要，减少说话，避免大声喊叫，让声带休息，部分小结可缩小或消失）、雾化吸入（生理盐水+布地奈德1-2mg，每日1-2次，减轻声带水肿和炎症）、中成药（金嗓散结丸、黄氏响声丸、清音丸、喉症丸，辨证使用）、维生素（维生素B2 10mg tid、维生素C 0.2g tid，促进黏膜修复）","药物2（急性发作或合并急性喉炎）：","用法：抗生素（有细菌感染证据时，头孢克肟0.2g bid、阿莫西林0.5g tid，疗程5-7天）、糖皮质激素（泼尼松10mg tid，短期3-5天，减轻声带水肿）、雾化吸入激素、止咳药〔调 CrCl<30 减量；青霉素过敏禁用〕","药物3（术后用药）：","用法：抗生素3-5天预防感染、糖皮质激素（口服或雾化）、雾化吸入、中成药、维生素","药物4（中医中药）：","用法：辨证施治——肺经蕴热型（清热利咽，黄芩汤加减）、肺脾气虚型（补益肺脾，补中益气汤加减）、痰瘀互结型（化痰散结，会厌逐瘀汤加减）；中成药可选用金嗓散结丸、黄氏响声丸、清音丸等","药物5（嗓音训练）：","用法：最重要的治疗方法，纠正不良发声习惯，学习正确发声方法，是治疗和防止复发的关键","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["保守治疗（首选，适用于大多数声带小结，尤其是早期水肿型）：声带休息（绝对禁声1-2周，之后相对禁声，避免大声喊叫和长时间说话，部分小结可缩小或消失）、雾化吸入（激素+生理盐水，减轻水肿炎症）、药物治疗（中成药、维生素）、病因治疗（治疗慢性喉炎、鼻炎鼻窦炎、胃食管反流）、嗓音训练（纠正不良发声习惯，学习正确发声方法，是治疗和防止复发的关键，建议在专业言语治疗师指导下进行）；保守治疗2-3个月无效者应手术治疗","手术治疗（适用于保守治疗2-3个月无效、小结较大、声音嘶哑明显、广基小结、患者对发音质量要求高）：手术方式——间接喉镜下小结切除术（简单，局麻，门诊）、纤维/电子喉镜下小结切除术（局麻，门诊，视野清晰，微创）、支撑喉镜下显微镜下小结切除术（全麻，显微镜下精细操作，切除准确，创伤小，恢复好，是目前主流术式）；术前准备（完善喉镜检查、凝血、传染病等，术前禁食禁水）；术后处理（术后声带休息2周、抗生素3-5天、雾化吸入1-2周、术后2周开始嗓音训练、定期复查）","病因治疗：治疗慢性喉炎、鼻炎鼻窦炎、胃食管反流、过敏；戒烟酒；避免辛辣刺激食物；改善工作环境","嗓音训练：是治疗声带小结最重要的方法，也是防止复发的关键，学习正确发声方法（腹式呼吸、声带放松、适当音量和音调），避免用声过度和用声不当（大声喊叫、长时间说话、清嗓动作、耳语说话）","预防：避免用声过度和用声不当；感冒时避免用声；戒烟酒；避免辛辣刺激食物；避免在粉尘、烟雾、嘈杂环境中长时间说话；积极治疗鼻炎鼻窦炎、胃食管反流；用嗓职业者注意嗓音保护（发声训练、适当休息、多饮水）；儿童避免大声喊叫；出现声音嘶哑及时就医","随访：保守治疗者定期复查喉镜（观察小结大小变化，2-3个月无效者手术）；术后定期复查喉镜（1周、2周、1月、3月，观察声带愈合和有无复发）；嗓音训练后评估发声质量；声带小结保守治疗有效率约70-80%，术后复发率约5-10%，规范嗓音训练可显著降低复发率"],"management":["保守治疗护理：督促患者声带休息（绝对禁声1-2周，包括耳语也不可以，可用写字板或手机交流）；指导正确雾化吸入（每日1-2次，深呼吸使药物到达声带）；按医嘱使用中成药和维生素；指导患者避免清嗓动作（可改为饮水或吞咽）；观察声音嘶哑变化；鼓励患者进行嗓音训练","术前护理：完善术前检查（电子喉镜、凝血、传染病、心电图）；术前1周避免用声过度；术前3天用含漱液清洁口腔；术前控制急性炎症；术前禁食禁水；解释手术目的、过程和术后注意事项，消除焦虑","术后护理：术后全麻清醒后去枕平卧6小时，头偏向一侧；术后密切观察呼吸情况（有无呼吸困难、喉喘鸣）；术后观察有无咯血；术后6小时可进温凉流质饮食；术后1-2天进流质，3-5天进半流质，1周后进软食；术后绝对禁声1周，相对禁声1周；术后2周开始逐渐恢复用声；术后1个月内避免大声喊叫、长时间说话、唱歌；术后雾化吸入（每日1-2次，1-2周）；术后避免用力咳嗽、清嗓；术后避免剧烈运动","用药护理：按医嘱使用抗生素（术后3-5天）、糖皮质激素（口服或雾化）、雾化吸入、中成药、维生素；观察药物疗效和副作用","病情观察：观察声音嘶哑变化（术后可能暂时加重，之后逐渐改善）；观察呼吸情况（有无呼吸困难）；观察有无咯血、发热；术后定期复查喉镜；出现呼吸困难、大量咯血、高热、声音嘶哑加重及时就医","饮食：清淡易消化饮食，多饮水；多吃新鲜蔬果；避免辛辣刺激、过冷过热、油炸食物；戒烟酒；术后饮食按温凉流质→半流质→软食循序渐进；保持大便通畅","休息与活动：术后保证充足睡眠；术后1周内避免剧烈运动；术后2周内避免大声喊叫；术后1个月内避免唱歌、演讲；用嗓职业者术后2-3个月可逐渐恢复工作；避免长时间处于粉尘、烟雾环境","个人卫生：勤洗手，预防上呼吸道感染；保持口腔清洁；避免用力咳嗽、清嗓；感冒时尽量少说话","环境管理：保持室内通风、清洁、适宜温湿度；避免接触粉尘、烟雾；戒烟；干燥季节使用加湿器","心理护理：安慰患者，解释声带小结是良性病变，保守治疗效果好，消除焦虑；术后需禁声和嗓音训练，给予解释和鼓励；用嗓职业者给予心理支持，告知术后恢复需要时间，不可急于求成","健康教育：讲解声带小结的病因（用声不当、用声过度最常见）、症状；强调声带休息和嗓音训练是治疗和防止复发的关键；指导正确发声方法（腹式呼吸、声带放松、适当音量和音调）；避免大声喊叫、长时间说话、清嗓动作、耳语说话；术后1个月内避免大声喊叫、唱歌；用嗓职业者术后必须进行嗓音训练才能恢复工作；戒烟酒，避免辛辣刺激食物；积极治疗鼻炎鼻窦炎、胃食管反流；出现声音嘶哑持续>2周不缓解及时就医（排除喉癌）；术后定期复查喉镜；声带小结保守治疗有效率约70-80%，规范嗓音训练可显著提高疗效和防止复发","家庭护理：家属督促患者禁声和嗓音训练；术后饮食准备（温凉流质、软食）；观察患者呼吸和出血情况；陪同定期复查；保持室内清洁、适宜温湿度；避免在家中吸烟"],"notes":["声带小结又称歌唱者小结、教师小结，是双侧声带前中1/3交界处对称性的结节状隆起，是喉部常见的良性病变，多见于用嗓职业者（教师、歌手、销售、主持人）和爱喊叫的儿童，女性多于男性，是慢性喉炎的一种特殊类型","病因：用声不当或用声过度（最主要，大声喊叫、长时间说话、发高音时方法不正确、在嘈杂环境中大声说话、耳语说话）、慢性喉炎（长期炎症刺激）、鼻炎鼻窦炎（鼻涕后流刺激）、胃食管反流（胃酸反流刺激）、过敏、吸烟、饮酒、空气污染、内分泌紊乱","发病机制：用声不当或过度→声带前中1/3交界处（振动最大、摩擦最多处）黏膜损伤→血管扩张、组织水肿→纤维组织增生、玻璃样变性→对称性结节状隆起；早期为水肿型（柔软，可逆），晚期为纤维化型（硬实，不可逆）","临床表现：声音嘶哑（早期为发声易倦、间歇性声嘶，发高音时明显，逐渐发展为持续性声嘶）、发音疲劳、音调改变（音调变粗变低，发高音困难）、喉部不适（异物感、干燥、痒感）、刺激性咳嗽；多为双侧对称性","喉镜检查：双侧声带前中1/3交界处可见对称性小的结节状隆起，表面光滑，质较硬，声带闭合不全（小结间可有缝隙）；电子喉镜是诊断金标准","与声带息肉鉴别：声带小结多为双侧对称性，小的结节状，质硬，保守治疗效果好；声带息肉多为单侧，息肉状，可有蒂或广基，质软，保守治疗效果有限，多需手术；两者可同时存在，均为良性病变","治疗原则：保守治疗为首选（声带休息+雾化吸入+药物+嗓音训练），适用于大多数声带小结，尤其是早期水肿型，有效率约70-80%；保守治疗2-3个月无效者手术治疗（声带小结切除术）；嗓音训练是治疗和防止复发的关键","嗓音训练：是治疗声带小结最重要的方法，也是防止复发的关键，建议在专业言语治疗师指导下进行，学习正确发声方法（腹式呼吸、声带放松、适当音量和音调、共鸣腔运用），纠正不良发声习惯（大声喊叫、长时间说话、清嗓动作、耳语说话、在嘈杂环境中大声说话）；用嗓职业者必须进行嗓音训练才能恢复工作和防止复发","预后：声带小结是良性病变，保守治疗效果好，早期水肿型小结经声带休息和嗓音训练多可缩小或消失；晚期纤维化型小结保守治疗效果差，需手术；手术效果好，术后声音嘶哑多可明显改善；术后复发率约5-10%，多因用声不当未纠正，规范嗓音训练可显著降低复发率；恶变罕见，但40岁以上、声音嘶哑持续>2周者需排除喉癌","预防：避免用声过度和用声不当（大声喊叫、长时间说话、耳语说话）；感冒时避免用声（急性喉炎时声带休息）；戒烟酒；避免辛辣刺激食物；避免在粉尘、烟雾、嘈杂环境中长时间说话；积极治疗鼻炎鼻窦炎、胃食管反流；用嗓职业者注意嗓音保护（发声训练、适当休息、多饮水、避免清嗓）；儿童避免大声喊叫；出现声音嘶哑及时就医，持续>2周不缓解者必须喉镜检查排除喉癌","我国现状：声带小结是耳鼻喉常见病，尤其是教师、歌手等用嗓职业者发病率高；但很多患者不重视嗓音保护和训练，长期不治疗或治疗不规范，导致小结增大或发展为息肉；需加强嗓音保护健康教育，推广专业嗓音训练；声音嘶哑持续>2周者需警惕喉癌，必须详细喉镜检查"],"emergency":["出现呼吸困难、喉喘鸣（罕见，巨大小结或合并急性喉水肿，立即就医）","出现声音嘶哑进行性加重、痰中带血、咽痛、吞咽困难、颈部淋巴结肿大（排除喉癌，尽快喉镜检查和病理活检）","术后出现大量咯血、呼吸困难（术后出血或喉水肿，立即就医）","出现高热、咽痛剧烈、吞咽困难（急性喉炎或扁桃体炎，及时就医）","儿童出现声音嘶哑伴呼吸困难、犬吠样咳嗽（急性喉炎，立即就医）","用嗓职业者出现失声、严重影响工作（及时就医规范治疗和嗓音训练）","出现过敏性休克（药物过敏，立即急诊抢救）","保守治疗2-3个月无效、声音嘶哑加重（及时就医评估手术）","术后出现声带粘连、声音嘶哑不恢复（及时就医喉镜检查和处理）","出现单侧声带麻痹、声音嘶哑伴饮水呛咳（排除喉返神经麻痹，需检查甲状腺、肺部、食管等，及时就医）"],"pinyin":"shengdaixiaojie","icd10":"J38.2","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态、面容","耳部：耳廓（畸形/红肿/皮疹/瘘管）、外耳道（耵聍/异物/分泌物/红肿/狭窄/闭锁）、鼓膜（标志/充血/内陷/穿孔/钙化/液平/肉芽）、乳突（红肿/压痛）、听力（耳语/音叉试验：Rinne试验/Weber试验/Schwabach试验）、前庭功能（自发性眼震/位置试验）","鼻部：外鼻（畸形/红肿）、鼻前庭（红肿/疖肿/结痂）、鼻腔（鼻中隔偏曲/糜烂/出血/穿孔、下鼻甲肿大/息肉样变、中鼻甲息肉样变/气化、鼻道分泌物（黏脓/血性/水样）、息肉/新生物）、鼻窦（压痛：额窦/上颌窦/筛窦）、后鼻孔检查","咽喉部：口咽（黏膜充血/肿胀/溃疡、扁桃体大小（Ⅰ-Ⅳ度）/充血/隐窝脓栓/结石、咽后壁淋巴滤泡增生/脓性分泌物、悬雍垂水肿/偏斜、软腭运动）、喉咽（会厌充血/水肿/囊肿、杓状会厌襞、梨状窝新生物/积液）、喉部（间接喉镜/电子喉镜：声带充血/息肉/小结/麻痹/新生物、室带肥厚、声门闭合情况）","颈部：淋巴结肿大（部位/大小/质地/活动度/压痛）、甲状腺、包块、瘘管","其他：发音（声嘶/失声）、吞咽（困难/呛咳）、呼吸（喘鸣/呼吸困难）"],"lab_tests":["电子喉镜/纤维喉镜检查（首选，明确小结部位、大小、形态及双侧对称性，可同期行窄带成像NBI观察黏膜微血管）","频闪喉镜（动态喉镜）检查：评估声带振动、黏膜波走行及闭合情况，与声带息肉、囊肿、任克水肿鉴别，嗓音显微手术前必查","嗓音功能评估：嗓音障碍指数（VHI）、GRBAS听感知评估、声学分析（基频、jitter、shimmer）、最长发声时间（MPT）","喉咽反流相关检查：反流症状指数（RSI）及反流体征评分（RFS），必要时行24小时咽喉pH监测或胃镜，排查反流诱因","喉肌电图（必要时）：怀疑声带麻痹、肌张力异常或功能性发声障碍时用于鉴别","喉部CT/MRI（必要时）：声带小结一般不需，仅当喉镜示黏膜粗糙不平、疑占位或保守治疗无效时用于除外喉部病变"],"nursing":["声休护理：急性充血期绝对禁声3~5天，此后相对声休；嘱患者用写字板或手势交流，严禁耳语（耳语声带张力更大，损伤更重）","发声训练指导：指导腹式呼吸、平稳起音、避免清嗓（以温水含漱代替清嗓）及用力咳嗽，训练间断性说话、控制语速音量","体位与呼吸道护理：取头颈放松位，避免长时间低头伏案致颈喉肌紧张；保持呼吸道通畅，观察有无呼吸困难及突发声音嘶哑加重","口腔护理：早晚及餐后温盐水含漱，保持口腔清洁湿润，减少上呼吸道感染诱发喉炎反复","病情观察：术后观察有无声带创面出血、咳血、误吸及声带水肿；监测声音恢复情况，嘱按期复诊复查喉镜"],"diet":["忌口：严格戒烟酒，避免辛辣、油炸、过冷过热及粗糙坚硬食物；停饮浓茶、咖啡等刺激性饮品（致声带干燥、充血加重）","推荐饮水：少量多次饮用温开水，每日1500~2000ml，保持声带黏膜湿润；可辅以蜂蜜温水润喉","质地要求：急性充血期及嗓音显微术后1~2周进温凉流质或半流质（米粥、蛋羹、烂面条），避免过硬食物刺激创面","睡前管理：睡前2~3小时避免进食及酸性、产气食物（如柑橘、巧克力），减少夜间喉咽反流刺激","营养支持：多食富含维生素A、C、B族的新鲜蔬果及优质蛋白（鱼、蛋、瘦肉），促进声带黏膜修复，预防复发"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":404},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"48ffb574c89db27985d3c626e82d1c0dc8c0a1e9229d8b939816b12e0fd4d83e","pinyin":"shengdaixiaojie","initials":"sdxj","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","声音嘶哑：主要症状，早期为发声易倦、间歇性声嘶，发高音时明显，逐渐发展为持续性声嘶\\n发音疲劳：说话多时声音嘶哑加重，不能持久讲话，休息后减轻\\n音调改变：音调变粗、变低，缺乏变化，发高音困难\\n喉部不适：咽部异物感、干燥、痒感，常作清嗓动作\\n咳嗽：刺激性咳嗽，无痰或少量白痰\\n声带小结多为双侧对称性，位于声带前中1/3交界处\\n职业因素：教师、歌手、销售、主持人、播音员、儿童（爱喊叫）多见\\n间接喉镜或电子喉镜检查：双侧声带前中1/3交界处可见对称性小的结节状隆起，表面光滑，质较硬，声带闭合不全（小结遮挡声门，可有缝隙）\\n可伴慢性喉炎、咽炎\\n并发症：一般无严重并发症，长期不治疗可发展为声带息肉或声带永久性损伤",60],["摘要","又称歌唱者小结、教师小结，是双侧声带前中1/3交界处对称性的结节状隆起，多因用声不当或用声过度引起，表现为声音嘶哑、发音疲劳，是喉部常见的良性病变，保守治疗效果好。",30],["疾病编码","J38.2",30],["原首字母","shengdaixiaojie",60]]},{"id":"orders-217bd0ed0ef1c8172ffc","key":"v1-c9ccc21dfe2a3058|orders-217bd0ed0ef1c8172ffc","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"慢性喉炎","category":"耳鼻喉","raw":{"name":"慢性喉炎","category":"耳鼻喉","summary":"喉部黏膜的慢性非特异性炎症，多因用声过度、用声不当、急性喉炎反复发作、邻近器官感染引起，表现为声音嘶哑、喉部不适、干燥、痒感、刺激性咳嗽，是耳鼻喉常见病，分为单纯性、肥厚性、萎缩性。","symptoms":["声音嘶哑：主要症状，程度不一，可为间歇性或持续性，用嗓后加重，休息后减轻，声音变粗、变低、缺乏变化","喉部不适：喉部异物感、干燥、灼热、痒感、微痛","分泌物增多：喉部有少量黏痰，常作清嗓动作以清除分泌物，清嗓后暂时舒服，之后又有分泌物","刺激性咳嗽：咽痒或喉部不适引起阵发性咳嗽，无痰或少量白痰","发音疲劳：说话多时声音嘶哑加重，不能持久讲话","萎缩性喉炎：喉部干燥明显，可有痂皮，咳嗽时可咳出痂皮，声音嘶哑严重，可伴痉挛性咳嗽","喉部检查：慢性单纯性喉炎——喉黏膜弥漫性充血，声带呈粉红色或暗红色，边缘变钝，声带表面有黏稠分泌物附着，声带闭合不全；慢性肥厚性喉炎——喉黏膜增厚，声带肥厚，边缘圆钝，表面粗糙不平，室带肥厚（可遮盖声带），声带闭合不全；萎缩性喉炎——喉黏膜萎缩变薄，干燥发亮，可有黄绿色或黑褐色痂皮附着，声带变薄，声门闭合不全（梭形缝隙）","可伴慢性咽炎、鼻炎鼻窦炎、扁桃体炎、气管支气管炎","职业因素：教师、歌手、销售、主持人等用嗓职业者多见","并发症：一般无严重并发症，长期不治疗可发展为声带小结、声带息肉，萎缩性喉炎可致喉狭窄（罕见）"],"diagnosis":["典型症状（声音嘶哑、喉部不适、干燥、刺激性咳嗽，病程>3个月）+喉镜检查见喉黏膜慢性充血、肥厚或萎缩","详细询问病史（用声情况、急性喉炎发作史、吸烟饮酒史、邻近器官疾病、全身疾病、职业）","间接喉镜检查（初步观察）","电子喉镜或纤维喉镜检查（金标准，清晰观察喉黏膜、声带、室带、会厌、杓状软骨情况，评估充血、肥厚、萎缩、分泌物、声带活动和闭合，可拍照录像）","嗓音声学分析（客观评估声音嘶哑程度）","喉动态镜检查（观察声带黏膜波，与早期喉癌鉴别）","喉部CT或MRI（怀疑肥厚明显、累及声门下或排除肿瘤时）","病理检查（怀疑新生物或排除肿瘤时，活检）","排除急性喉炎（病程短，伴发热、咽痛，黏膜急性充血）、声带小结（双侧对称性小结）、声带息肉（单侧息肉状新生物）、喉乳头状瘤（菜花状新生物）、喉癌（中老年男性，吸烟史，声带新生物表面溃烂、质硬、易出血、声带活动受限，病理可确诊）、喉结核（低热、盗汗、咽痛，溃疡呈虫蚀状）、喉返神经麻痹（声带活动受限或固定，声音嘶哑，饮水呛咳，需检查甲状腺、肺部、食管）、癔症性失声（突发失声，咳嗽有声，声带活动正常，与情绪有关）","分型：慢性单纯性喉炎（喉黏膜弥漫性充血，声带边缘变钝，有分泌物，可逆，预后好）、慢性肥厚性喉炎（喉黏膜和声带肥厚，表面粗糙，室带肥厚，不可逆，治疗困难）、萎缩性喉炎（喉黏膜萎缩变薄，干燥，有痂皮，罕见，治疗困难，多由萎缩性鼻炎蔓延或放疗后引起）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","","方案1：","  用法：一般无需静脉输液；慢性喉炎以声带休息、雾化吸入（布地奈德混悬液 1mg + 0.9%NS 2ml 雾化吸入 bid）为主","","方案2（急性发作或合并急性喉炎）：","  用法：0.9%NS 100ml + 地塞米松5-10mg ivgtt qd（短期，减轻喉水肿）、抗生素 ivgtt（有细菌感染时）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案3（萎缩性喉炎）：","  用法：0.9%NS 250ml + 维生素C 2g ivgtt qd（辅助，促进黏膜修复）","","方案4（围手术期；合并声带息肉或小结手术时）：","  用法：术前一般无需静脉抗生素，术后3-5天静脉或口服抗生素预防感染","","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（慢性单纯性喉炎）：","用法：声带休息（最重要，减少说话，避免大声喊叫）、雾化吸入（生理盐水+布地奈德1-2mg，每日1-2次，减轻喉黏膜炎症和水肿）、含漱液（复方硼砂溶液、生理盐水，每日3-4次，清洁咽部）、含片（西地碘含片、溶菌酶含片，每日3-4次）、中成药（黄氏响声丸、金嗓开音丸、清音丸、喉症丸，辨证使用）、维生素（维生素A 2.5万U qd、维生素B2 10mg tid、维生素C 0.2g tid、维生素E 0.1g qd，促进黏膜修复）","药物2（慢性肥厚性喉炎）：","用法：除上述药物外，可雾化吸入激素+糜蛋白酶（减轻肥厚和分泌物），药物治疗效果有限，以嗓音训练和病因为主，严重者可考虑激光或射频治疗（消除肥厚组织，注意不可过度治疗）","药物3（萎缩性喉炎）：","用法：喉部涂抹2%碘甘油（每日1次，促进腺体分泌，改善干燥）、口服维生素A/B2/C/E、小剂量碘剂（碘化钾0.1-0.3g tid，促进分泌，注意过敏和甲状腺疾病）、生理盐水雾化吸入（湿润喉部，每日2-3次）、蒸汽吸入（湿润喉部，软化痂皮）、鼓励咳嗽排出痂皮（避免强行咳出致出血）","药物4（急性发作）：","用法：抗生素（有细菌感染证据时，头孢克肟0.2g bid、阿莫西林0.5g tid，疗程5-7天）、糖皮质激素（泼尼松10mg tid，短期3-5天，减轻喉水肿）、雾化吸入激素、止咳药（刺激性咳嗽时右美沙芬15mg tid）〔调 CrCl<30 减量；青霉素过敏禁用〕","药物5（病因治疗）：","用法：治疗鼻炎鼻窦炎（鼻用激素+鼻腔冲洗+抗生素，减少鼻涕后流刺激喉部）、慢性扁桃体炎（反复发作者扁桃体切除）、气管支气管炎（抗生素+止咳化痰）、胃食管反流（抑酸+促动力+生活方式调整）、过敏（抗组胺药+避免过敏原）","药物6（中医中药）：","用法：辨证施治——肺阴虚型（养阴清肺，养阴清肺汤加减）、肾阴虚型（滋补肾阴，六味地黄丸、知柏地黄丸加减）、肺脾气虚型（补益肺脾，补中益气汤、参苓白术散加减）、痰瘀互结型（化痰散结，会厌逐瘀汤加减）、肺经蕴热型（清热利咽，黄芩汤加减）；中成药可选用黄氏响声丸、金嗓开音丸、清音丸等","药物7（嗓音训练）：","用法：纠正不良发声习惯，学习正确发声方法，是治疗和防止复发的关键","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["病因治疗（关键）：治疗急性喉炎（及时彻底，防止迁延为慢性）、治疗邻近器官感染（鼻炎鼻窦炎、慢性扁桃体炎、气管支气管炎）、治疗胃食管反流、过敏；避免用声过度和用声不当；戒烟酒；避免辛辣刺激食物；改善工作环境（避免粉尘、烟雾、刺激性气体）；治疗全身慢性疾病（贫血、糖尿病、甲状腺疾病）","局部治疗：声带休息（最重要，减少说话，避免大声喊叫，让喉部休息）、雾化吸入（激素+生理盐水，每日1-2次，减轻炎症水肿）、含漱液和含片、喉部涂抹（碘甘油，萎缩性喉炎）、蒸汽吸入（湿润喉部，萎缩性喉炎）、物理治疗（超短波、药物离子导入，慢性肥厚性喉炎）","药物治疗：根据分型选择药物（见口服药物），中成药辨证使用，维生素促进黏膜修复","手术治疗：慢性肥厚性喉炎声带肥厚明显、药物治疗无效者，可考虑激光、射频、等离子消融治疗（消除肥厚组织，注意不可过度治疗，以免致声带瘢痕和声音嘶哑加重）；合并声带息肉或小结者行相应手术；萎缩性喉炎一般不手术","嗓音训练：是治疗慢性喉炎和防止复发的关键，学习正确发声方法（腹式呼吸、声带放松、适当音量和音调），避免用声过度和用声不当（大声喊叫、长时间说话、清嗓动作、耳语说话），建议在专业言语治疗师指导下进行","预防：积极治疗急性喉炎（及时彻底，防止迁延）；避免用声过度和用声不当；感冒时避免用声；戒烟酒；避免辛辣刺激食物；避免在粉尘、烟雾、刺激性气体环境中长时间说话；积极治疗鼻炎鼻窦炎、胃食管反流、慢性扁桃体炎；用嗓职业者注意嗓音保护（发声训练、适当休息、多饮水、避免清嗓）；出现声音嘶哑及时就医，持续>2周不缓解者必须喉镜检查排除喉癌","随访：治疗后定期复查喉镜（评估疗效，调整方案）；慢性喉炎易复发，需长期管理和避免诱发因素；40岁以上、声音嘶哑持续>2周、有吸烟史者，需详细喉镜检查，必要时病理活检排除喉癌；萎缩性喉炎长期不愈需排除喉部肿瘤"],"management":["声带休息：督促患者减少说话，避免大声喊叫、长时间说话、耳语说话（耳语也会使声带活动，影响恢复）；急性发作时绝对禁声1-2周；慢性期相对禁声，避免用嗓过度；可用写字板或手机交流；避免清嗓动作（可改为饮水或吞咽）","雾化吸入护理：指导正确雾化吸入（每日1-2次，深呼吸使药物到达喉部，雾化后30分钟内避免进食和饮水）；雾化器定期清洁消毒；观察雾化效果","用药护理：按医嘱使用中成药、维生素、雾化吸入药物；急性发作时按医嘱使用抗生素和激素（短期，不可长期使用）；观察药物疗效和副作用（激素副作用、抗生素胃肠道反应）","病情观察：观察声音嘶哑变化（程度、间歇性或持续性、与用嗓关系）；观察喉部不适（干燥、异物感、痒感）变化；观察分泌物和咳嗽情况；观察有无报警症状（声音嘶哑进行性加重、痰中带血、咽痛、吞咽困难、颈部肿块、呼吸困难），一旦出现立即就医（排除喉癌）；治疗后复查喉镜评估疗效；出现报警症状及时就医","饮食：清淡易消化饮食，多饮水（每日1500-2000ml，保持喉部湿润）；多吃新鲜蔬果（富含维生素，促进黏膜修复）；避免辛辣刺激、过冷过热、油炸、烧烤食物；戒烟酒（烟酒刺激喉黏膜，加重炎症）；避免咖啡、浓茶、巧克力（反流时）；萎缩性喉炎患者多饮水，保持喉部湿润；保持大便通畅","休息与活动：保证充足睡眠，避免熬夜和过度劳累；急性发作时卧床休息，少说话；适当体育锻炼，增强体质；避免长时间处于粉尘、烟雾、刺激性气体环境；用嗓职业者注意用嗓休息（每说话1小时休息10-15分钟）；避免在嘈杂环境中大声说话；寒冷季节外出戴口罩（避免冷空气刺激喉部）","个人卫生：勤洗手，预防上呼吸道感染（感冒时急性喉炎可加重慢性喉炎）；保持口腔清洁（早晚刷牙，饭后漱口）；避免用力咳嗽、清嗓；感冒时尽量少说话，让喉部休息","环境管理：保持室内通风、清洁、适宜温湿度（湿度50-60%，避免干燥）；避免接触粉尘、烟雾、刺激性气体；戒烟（包括二手烟）；厨房使用抽油烟机；干燥季节使用加湿器；用嗓时保持环境安静","心理护理：安慰患者，解释慢性喉炎是常见病，良性病变，可治疗和控制，但易复发，消除焦虑和恐癌心理；声音嘶哑影响工作和交流者给予关心和心理支持；需嗓音训练者给予鼓励，告知坚持训练的重要性；40岁以上、声音嘶哑持续不缓解者，需详细检查排除肿瘤，避免患者过度焦虑","健康教育：讲解慢性喉炎的病因（用声不当、用声过度最常见，其次为急性喉炎反复发作、邻近器官感染、胃食管反流、吸烟、空气污染）、分型（单纯性、肥厚性、萎缩性）和症状；强调病因治疗和声带休息的重要性；指导正确发声方法（腹式呼吸、声带放松、适当音量和音调），避免大声喊叫、长时间说话、清嗓动作、耳语说话；用嗓职业者注意嗓音保护（发声训练、适当休息、多饮水、避免清嗓），每说话1小时休息10-15分钟；戒烟酒，避免辛辣刺激食物；积极治疗鼻炎鼻窦炎、胃食管反流、慢性扁桃体炎；感冒时避免用声；出现声音嘶哑持续>2周不缓解及时就医（排除喉癌），40岁以上、有吸烟史者更需重视；慢性喉炎易复发，需长期管理和避免诱发因素；萎缩性喉炎患者需长期湿润喉部，避免干燥；术后或嗓音训练后定期复查喉镜","家庭护理：家属督促患者声带休息和嗓音训练；保持室内清洁、通风、适宜温湿度；避免在家中吸烟；饮食准备清淡、富含维生素食物；观察患者声音嘶哑变化，出现报警症状（进行性声嘶、痰中带血、颈部肿块、呼吸困难）及时就医；陪同定期复查；用嗓职业者家属给予理解和支持，避免让患者大声说话"],"notes":["慢性喉炎是喉部黏膜的慢性非特异性炎症，是耳鼻喉常见病，多见于用嗓职业者和急性喉炎反复发作患者，病程超过3个月，分为慢性单纯性喉炎、慢性肥厚性喉炎、萎缩性喉炎三型","病因：用声过度或用声不当（最主要，大声喊叫、长时间说话、耳语说话、发声方法不正确）、急性喉炎反复发作或治疗不彻底（迁延为慢性）、邻近器官感染（慢性鼻炎鼻窦炎鼻涕后流刺激、慢性扁桃体炎、气管支气管炎）、胃食管反流（胃酸反流刺激喉部，是慢性喉炎的重要原因之一，很多患者无明显反酸）、过敏、吸烟、饮酒、空气污染（粉尘、烟雾、刺激性气体）、全身因素（贫血、糖尿病、甲状腺功能减退、免疫功能低下、维生素缺乏）、长期张口呼吸（鼻塞致）","发病机制：各种因素长期刺激喉黏膜→黏膜慢性充血→血管扩张→淋巴细胞浸润→间质水肿→纤维组织增生→黏膜肥厚或萎缩→腺体分泌异常→声音嘶哑、喉部不适、分泌物增多","分型：慢性单纯性喉炎（最常见，喉黏膜弥漫性充血，声带呈粉红色或暗红色，边缘变钝，表面有黏稠分泌物，声带闭合不全，可逆，预后好）、慢性肥厚性喉炎（喉黏膜和声带肥厚，边缘圆钝，表面粗糙不平，室带肥厚可遮盖声带，声带闭合不全，不可逆，治疗困难，多由单纯性发展而来）、萎缩性喉炎（罕见，喉黏膜萎缩变薄，干燥发亮，可有黄绿色或黑褐色痂皮，声带变薄，声门闭合不全呈梭形缝隙，多由萎缩性鼻炎蔓延或放疗后引起，治疗困难）","临床表现：声音嘶哑（主要症状，间歇性或持续性，用嗓后加重，休息后减轻，声音变粗变低）、喉部不适（异物感、干燥、灼热、痒感、微痛）、分泌物增多（喉部黏痰，常作清嗓动作）、刺激性咳嗽、发音疲劳；萎缩性喉炎干燥明显，可有痂皮和痉挛性咳嗽","喉镜检查：电子喉镜是诊断金标准，可清晰观察喉黏膜、声带、室带、会厌、杓状软骨情况，评估充血、肥厚、萎缩、分泌物、声带活动和闭合，可拍照录像；慢性单纯性喉炎见黏膜弥漫性充血、声带边缘变钝、有分泌物；慢性肥厚性喉炎见黏膜和声带肥厚、表面粗糙、室带肥厚；萎缩性喉炎见黏膜萎缩变薄、干燥、有痂皮","与喉癌鉴别：喉癌多见于中老年男性，有长期吸烟史，表现为进行性声音嘶哑、痰中带血、咽痛、吞咽困难、颈部淋巴结肿大，喉镜见声带新生物表面溃烂、质硬、易出血、声带活动受限或固定，病理可确诊；慢性喉炎声音嘶哑多为间歇性，与用嗓有关，无痰中带血和颈部肿块，声带活动正常；40岁以上、声音嘶哑持续>2周、有吸烟史者，必须详细喉镜检查，必要时病理活检排除喉癌","治疗原则：病因治疗是关键（治疗急性喉炎、邻近器官感染、胃食管反流，避免用声不当和吸烟），配合声带休息、雾化吸入、药物治疗、嗓音训练；慢性单纯性喉炎预后好，慢性肥厚性和萎缩性喉炎治疗困难，以控制症状和防止加重为主","嗓音训练：是治疗慢性喉炎和防止复发的关键，学习正确发声方法（腹式呼吸、声带放松、适当音量和音调、共鸣腔运用），纠正不良发声习惯（大声喊叫、长时间说话、清嗓动作、耳语说话、在嘈杂环境中大声说话），建议在专业言语治疗师指导下进行；用嗓职业者必须进行嗓音训练才能恢复工作和防止复发","预后：慢性单纯性喉炎预后好，去除病因和规范治疗后可痊愈或明显改善；慢性肥厚性喉炎治疗困难，声音嘶哑可持续，以控制症状为主；萎缩性喉炎治疗困难，黏膜萎缩难以恢复，以湿润喉部和控制症状为主；慢性喉炎一般不癌变，但长期不愈需排除喉癌；易复发，需长期管理和避免诱发因素","预防：积极治疗急性喉炎（及时彻底，防止迁延）；避免用声过度和用声不当（大声喊叫、长时间说话、耳语说话）；感冒时避免用声（急性喉炎时声带休息）；戒烟酒；避免辛辣刺激食物；避免在粉尘、烟雾、刺激性气体环境中长时间说话；积极治疗鼻炎鼻窦炎、胃食管反流、慢性扁桃体炎；用嗓职业者注意嗓音保护（发声训练、适当休息、多饮水、避免清嗓），每说话1小时休息10-15分钟；出现声音嘶哑及时就医，持续>2周不缓解者必须喉镜检查排除喉癌","我国现状：慢性喉炎是耳鼻喉常见病，尤其是教师、歌手等用嗓职业者发病率高；但很多患者不重视，长期不治疗或自行用药，导致病情迁延或发展为声带小结、息肉；胃食管反流性喉炎认识不足，很多患者按普通喉炎治疗效果差；需加强健康教育，推广病因治疗和专业嗓音训练；声音嘶哑持续>2周者需警惕喉癌，必须详细喉镜检查"],"emergency":["出现呼吸困难、喉喘鸣、吸气性三凹征（急性喉水肿或喉梗阻，立即就医，保持呼吸道通畅，必要时气管切开）","出现声音嘶哑进行性加重、痰中带血、咽痛、吞咽困难、颈部淋巴结肿大（排除喉癌，尽快喉镜检查和病理活检）","出现高热、咽痛剧烈、吞咽困难、张口受限（急性喉炎或扁桃体周围脓肿，及时就医）","术后出现大量咯血、呼吸困难（术后出血或喉水肿，立即就医）","出现过敏性休克（药物过敏，立即急诊抢救）","萎缩性喉炎出现痂皮堵塞气道、呼吸困难（及时就医取出痂皮）","儿童出现声音嘶哑伴犬吠样咳嗽、呼吸困难（急性喉炎，立即就医）","用嗓职业者出现失声、严重影响工作（及时就医规范治疗和嗓音训练）","出现单侧声带麻痹、声音嘶哑伴饮水呛咳（喉返神经麻痹，需检查甲状腺、肺部、食管等，及时就医）","慢性喉炎患者声音嘶哑突然加重、伴咯血（排除肿瘤或急性出血，及时就医）"],"pinyin":"manxinghouyan","icd10":"J37.0","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态、面容","耳部：耳廓（畸形/红肿/皮疹/瘘管）、外耳道（耵聍/异物/分泌物/红肿/狭窄/闭锁）、鼓膜（标志/充血/内陷/穿孔/钙化/液平/肉芽）、乳突（红肿/压痛）、听力（耳语/音叉试验：Rinne试验/Weber试验/Schwabach试验）、前庭功能（自发性眼震/位置试验）","鼻部：外鼻（畸形/红肿）、鼻前庭（红肿/疖肿/结痂）、鼻腔（鼻中隔偏曲/糜烂/出血/穿孔、下鼻甲肿大/息肉样变、中鼻甲息肉样变/气化、鼻道分泌物（黏脓/血性/水样）、息肉/新生物）、鼻窦（压痛：额窦/上颌窦/筛窦）、后鼻孔检查","咽喉部：口咽（黏膜充血/肿胀/溃疡、扁桃体大小（Ⅰ-Ⅳ度）/充血/隐窝脓栓/结石、咽后壁淋巴滤泡增生/脓性分泌物、悬雍垂水肿/偏斜、软腭运动）、喉咽（会厌充血/水肿/囊肿、杓状会厌襞、梨状窝新生物/积液）、喉部（间接喉镜/电子喉镜：声带充血/息肉/小结/麻痹/新生物、室带肥厚、声门闭合情况）","颈部：淋巴结肿大（部位/大小/质地/活动度/压痛）、甲状腺、包块、瘘管","其他：发音（声嘶/失声）、吞咽（困难/呛咳）、呼吸（喘鸣/呼吸困难）"],"lab_tests":["电子喉镜/纤维喉镜检查（首选，观察声带及喉黏膜充血、肥厚、息肉样变，排除声带小结、息肉及喉部新生物，必要时加窄带成像NBI筛查早期喉癌）","动态喉镜（喉频闪镜）检查（评估声带振动幅度、黏膜波、闭合状况，鉴别声带麻痹及功能性发声障碍）","嗓音功能评估（最长发声时间MPT、声学分析jitter/shimmer、嗓音障碍指数VHI-10，用于评估声嘶程度及疗效随访）","24小时食管pH监测及喉咽反流量表（RFS）评分（声嘶晨起加重、伴反酸烧心或喉异物感者，明确喉咽反流性喉炎诊断）","胸部X线/颈部CT（长期声嘶、痰中带血或声音进行性嘶哑者，排除喉癌及纵隔病变）","喉部分泌物细菌培养+药敏（分泌物脓性、反复急性发作或抗生素疗效不佳时明确病原菌）"],"nursing":["病情观察：监测声嘶程度、有无喉鸣、呼吸困难及痰中带血；声嘶进行性加重或出现吸气性呼吸困难时立即报告医师，床旁备气管切开包","嗓音护理：指导绝对禁声或减少说话，避免耳语及频繁清嗓（清嗓加重声带撞击），嘱腹式呼吸、放慢语速轻声交谈","气道环境护理：保持病室温湿度适宜（相对湿度50%-60%），鼓励少量多次饮水湿润声带，避免烟酒及粉尘、油烟刺激","反流护理：疑喉咽反流者抬高床头15-30cm，睡前3小时禁食禁水，避免过饱及睡前饮用浓茶、咖啡、酒精","术后护理（声带息肉/囊肿切除术后）：术后严格禁声1周，布地奈德+生理盐水雾化吸入每日2次，观察有无咯血、声嘶加重及呼吸困难"],"diet":["忌辛辣刺激及过烫过硬食物（辣椒、花椒、油炸、坚果类），戒烟酒，避免刺激声带黏膜加重充血水肿","反流明显者饮食清淡，少量多餐，睡前3小时禁食，忌甜食、高脂及酸性食物（柑橘、番茄、巧克力、咖啡）","推荐温凉流质或半流质饮食（粥、蛋羹、藕粉、烂面条），术后早期以温凉流质为主，防止过热烫伤声带创面","每日饮水1500-2000ml，可饮罗汉果、胖大海、麦冬泡水润喉，避免碳酸饮料及过冷饮品","增加优质蛋白及维生素摄入（瘦肉、鱼、蛋、豆制品及新鲜蔬果，富含维生素A、B族），促进喉黏膜修复"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":405},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"f75ad54b94bf641360595ea016dd430a98165591330bd64eb4ec92f23a63a839","pinyin":"manxinghouyan","initials":"mxhy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","声音嘶哑：主要症状，程度不一，可为间歇性或持续性，用嗓后加重，休息后减轻，声音变粗、变低、缺乏变化\\n喉部不适：喉部异物感、干燥、灼热、痒感、微痛\\n分泌物增多：喉部有少量黏痰，常作清嗓动作以清除分泌物，清嗓后暂时舒服，之后又有分泌物\\n刺激性咳嗽：咽痒或喉部不适引起阵发性咳嗽，无痰或少量白痰\\n发音疲劳：说话多时声音嘶哑加重，不能持久讲话\\n萎缩性喉炎：喉部干燥明显，可有痂皮，咳嗽时可咳出痂皮，声音嘶哑严重，可伴痉挛性咳嗽\\n喉部检查：慢性单纯性喉炎——喉黏膜弥漫性充血，声带呈粉红色或暗红色，边缘变钝，声带表面有黏稠分泌物附着，声带闭合不全；慢性肥厚性喉炎——喉黏膜增厚，声带肥厚，边缘圆钝，表面粗糙不平，室带肥厚（可遮盖声带），声带闭合不全；萎缩性喉炎——喉黏膜萎缩变薄，干燥发亮，可有黄绿色或黑褐色痂皮附着，声带变薄，声门闭合不全（梭形缝隙）\\n可伴慢性咽炎、鼻炎鼻窦炎、扁桃体炎、气管支气管炎\\n职业因素：教师、歌手、销售、主持人等用嗓职业者多见\\n并发症：一般无严重并发症，长期不治疗可发展为声带小结、声带息肉，萎缩性喉炎可致喉狭窄（罕见）",60],["摘要","喉部黏膜的慢性非特异性炎症，多因用声过度、用声不当、急性喉炎反复发作、邻近器官感染引起，表现为声音嘶哑、喉部不适、干燥、痒感、刺激性咳嗽，是耳鼻喉常见病，分为单纯性、肥厚性、萎缩性。",30],["疾病编码","J37.0",30],["原首字母","manxinghouyan",60]]},{"id":"orders-4e8d328bd80bb3cb8c21","key":"v1-c9ccc21dfe2a3058|orders-4e8d328bd80bb3cb8c21","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"腺样体肥大","category":"耳鼻喉","raw":{"name":"腺样体肥大","category":"耳鼻喉","summary":"腺样体因炎症反复刺激而发生病理性增生肥大，多见于儿童，常与慢性扁桃体炎合并存在，表现为鼻塞、打鼾、张口呼吸、睡眠呼吸暂停，可影响儿童生长发育和面容。","symptoms":["鼻部症状：鼻塞（主要症状，持续性）、流涕（黏液性或脓性）、闭塞性鼻音、嗅觉减退","耳部症状：堵塞咽鼓管咽口，引起分泌性中耳炎，出现耳鸣、耳闷、听力下降","咽喉部症状：分泌物下流刺激咽喉，引起咽部不适、异物感、咳嗽、多痰","全身症状：慢性中毒及反射性神经症状——营养发育不良、反应迟钝、注意力不集中、夜惊、磨牙、遗尿、夜啼、食欲差","睡眠症状：睡眠时打鼾（主要症状）、张口呼吸、睡眠不安、多汗、睡眠呼吸暂停，严重者可憋醒","腺样体面容：长期张口呼吸影响面骨发育，出现上颌骨变长、腭骨高拱、牙列不齐、上切牙突出、唇厚、缺乏表情","鼻镜检查：鼻咽顶后壁可见分叶状淋巴组织增生，如剥去皮的橘子瓣，堵塞后鼻孔，可分为Ⅳ度","可伴慢性鼻炎鼻窦炎、慢性扁桃体炎、分泌性中耳炎","并发症：分泌性中耳炎、化脓性中耳炎、慢性鼻炎鼻窦炎、咽炎、支气管炎、阻塞性睡眠呼吸暂停低通气综合征、腺样体面容、生长发育迟缓、胸廓畸形、肺心病"],"diagnosis":["典型症状（儿童鼻塞、打鼾、张口呼吸、睡眠呼吸暂停）+鼻咽部检查见腺样体肥大","详细询问病史（睡眠情况、听力、注意力、生长发育、反复上呼吸道感染史）","前鼻镜检查（鼻黏膜充血，下鼻甲肥大，收敛鼻黏膜后有时可见鼻咽部红色块状隆起）","鼻内镜检查（金标准，可直接观察腺样体大小、堵塞后鼻孔程度、表面形态）","鼻咽部X线侧位片（测量腺样体厚度与鼻咽腔宽度比值A/N，A/N≤0.60正常，0.61-0.70中度肥大，≥0.71病理性肥大）","鼻咽部CT或MRI（明确腺样体大小、范围，排除鼻咽部肿瘤，评估鼻窦炎和中耳情况）","听力检查（纯音测听或声导抗，评估有无分泌性中耳炎和听力损失）","睡眠监测（多导睡眠监测PSG，怀疑OSAHS时，评估AHI、最低血氧饱和度）","排除鼻咽部肿瘤（鼻咽癌、鼻咽纤维血管瘤、脊索瘤）、后鼻孔闭锁、鼻腔异物、扁桃体肥大","分度：按堵塞后鼻孔程度分Ⅰ-Ⅳ度；按A/N比值分正常、中度肥大、病理性肥大"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般无需静脉输液；腺样体肥大以鼻用糖皮质激素喷鼻（如糠酸莫米松鼻喷雾剂 每侧2喷 喷鼻 qd）为主","方案2（合并急性感染）：","用法：0.9%NS 100ml + 抗生素 ivgtt qd（根据病原选择）","方案3（围手术期）：","用法：术前一般无需静脉抗生素，术后3-5天静脉或口服抗生素预防感染","方案4（术后出血较多）：","用法：止血药静脉输注，必要时输血","方案5（合并OSAHS严重缺氧）：","用法：术前术后吸氧，必要时无创通气","方案6（补液支持）：","用法：0.9%NS 500ml 静滴 qd；5%GS 500ml 静滴 qd；10%氯化钾 10ml 加入上述液体静滴（维持水电解质平衡）","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（保守治疗）：","用法：鼻用糖皮质激素（布地奈德鼻喷雾剂64μg qd、糠酸莫米松鼻喷雾剂100μg qd，减轻腺样体炎症和水肿，连续使用1-3个月）、鼻腔冲洗（生理盐水或高渗盐水，每日1-2次）、白三烯受体拮抗剂（孟鲁司特钠按年龄给药（2-5岁4mg qn、6-14岁5mg qn、≥15岁10mg qn），合并过敏性鼻炎或OSAHS时）、抗组胺药（合并过敏性鼻炎时氯雷他定、西替利嗪）、抗生素（合并急性感染或鼻窦炎时阿莫西林克拉维酸钾、头孢克肟，疗程7-14天）、促排剂（桉柠蒎、标准桃金娘油，合并鼻窦炎或分泌性中耳炎时）","药物2（术前准备）：","用法：术前1-2周鼻用激素+鼻腔冲洗；术前3天口服抗生素；术前完善检查；术前禁食禁水","药物3（术后用药）：","用法：抗生素3-5天预防感染、止痛药、止血药、鼻用激素（术后1-2周开始）、鼻腔冲洗（术后1周开始）、白三烯受体拮抗剂（合并OSAHS或过敏时）","药物4（中医中药）：","用法：辨证施治——肺脾气虚型（补益肺脾，补中益气汤加减）、肾虚型（温补肾阳，金匮肾气丸加减）、痰瘀互结型（化痰散结，会厌逐瘀汤加减）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["保守治疗（适用于轻度肥大、无明显症状或不宜手术者）：鼻用糖皮质激素（连续1-3个月）+鼻腔冲洗+白三烯受体拮抗剂+治疗合并症；观察3-6个月，部分患儿腺样体可缩小；保守治疗无效者应手术","手术治疗（腺样体切除术，主要治疗方法）：手术指征——腺样体肥大堵塞后鼻孔>50%引起明显鼻塞打鼾；引起OSAHS（AHI>5或最低血氧<90%）；引起分泌性中耳炎反复发作听力下降；引起慢性鼻炎鼻窦炎反复发作；已形成腺样体面容；影响生长发育；保守治疗3-6个月无效；手术方式——传统腺样体刮除术（盲刮，现已少用）、鼻内镜下腺样体切除术（目前主流，直视下切除，准确残留少损伤小）、鼻内镜下等离子腺样体消融术（微创，出血少，疼痛轻，恢复快，目前最常用）；同期手术——合并扁桃体肥大反复发炎或引起OSAHS者同期扁桃体切除；合并分泌性中耳炎者同期鼓膜切开置管；术前准备（完善检查、控制急性炎症、术前禁食禁水）；术后处理（全麻清醒后去枕平卧头偏向一侧、观察出血和呼吸、术后6小时进冷流质、术后1-2天流质、3-5天半流质、1周软食、2周正常饮食、抗生素3-5天、术后1周开始鼻腔冲洗和鼻用激素、术后1个月内避免剧烈运动、定期复查）","并发症治疗：分泌性中耳炎（鼓膜置管+治疗腺样体）、OSAHS（手术切除腺样体+扁桃体，术后必要时CPAP）、腺样体面容（早期手术可部分恢复，严重者需口腔正畸）、生长发育迟缓（手术后多可追赶生长）","预防：积极治疗急性鼻炎鼻窦炎、急性咽炎、扁桃体炎；增强体质，预防上呼吸道感染；避免接触过敏原；积极治疗过敏性鼻炎；儿童定期体检，发现鼻塞打鼾及时就医","随访：保守治疗者定期复查（观察腺样体大小变化，3-6个月无效者手术）；术后定期复查鼻内镜（术后1周、2周、1月、3月，观察术腔愈合、有无残留、粘连）；术后评估睡眠、听力、生长发育改善情况"],"management":["术前护理：完善术前检查（鼻内镜、鼻咽X线或CT、凝血、传染病、心电图、胸片、睡眠监测、听力检查）；术前1-2周鼻用激素+鼻腔冲洗；术前3天口服抗生素；术前控制急性炎症；术前禁食禁水（全麻术前8小时禁食、4小时禁水）；解释手术目的、过程和术后注意事项，消除家长和患儿焦虑","术后护理：全麻清醒后去枕平卧6小时，头偏向一侧（防止呕吐物误吸）；术后密切观察呼吸情况（有无呼吸困难、喉喘鸣、血氧下降）；术后观察出血情况（唾液中带血丝属正常，大量鲜血或频繁吞咽提示出血）；术后6小时可进冷流质饮食（牛奶、豆浆、冷米汤，避免热食和硬食）；术后1-2天流质，3-5天半流质，1周软食，2周正常饮食；术后避免用力咳嗽、打喷嚏；术后1周内避免剧烈运动、跑跳；术后1个月内避免大声喊叫；术后1周开始鼻腔冲洗和鼻用激素；术后保持室内适宜湿度；术后注意口腔清洁（餐后漱口）","用药护理：按医嘱使用鼻用激素（每日1-2次，连续1-3个月）、鼻腔冲洗（每日1-2次）、白三烯受体拮抗剂（每晚睡前）、抗生素（术后3-5天）、止痛药；观察药物疗效和副作用","病情观察：观察鼻塞、打鼾、张口呼吸变化（术后可能因术腔水肿暂时加重，1-2周后逐渐改善）；观察睡眠情况（打鼾、呼吸暂停是否改善）；观察听力变化（有无耳闷、耳鸣）；观察生长发育（身高体重增长、注意力、学习成绩）；观察有无并发症征象（耳痛、听力下降、发热、鼻出血）；术后观察出血、呼吸、体温；出现大量出血、呼吸困难、高热、耳痛听力下降及时就医","饮食：清淡易消化饮食，多饮水；多吃新鲜蔬果；避免辛辣刺激、过冷过热、油炸、硬食；术后饮食按冷流质→半流质→软食→正常饮食循序渐进；避免过饱；保持大便通畅","休息与活动：保证充足睡眠；术后1周内避免剧烈运动、跑跳、哭闹；术后1个月内避免大声喊叫、唱歌；术后2周可恢复轻度活动和上学（避免体育课）；术后1个月可恢复正常活动；避免长时间处于粉尘、烟雾环境；寒冷季节外出戴口罩","个人卫生：勤洗手，预防上呼吸道感染；保持口腔清洁；术后1周内避免挖鼻、用力擤鼻（一侧一侧擤）；避免频繁做清嗓动作","环境管理：保持室内通风、清洁、适宜温湿度（湿度50-60%）；避免接触粉尘、烟雾、刺激性气体；戒烟（包括二手烟）；过敏者避免接触过敏原；使用空气净化器；干燥季节使用加湿器","心理护理：安慰患儿和家长，解释腺样体肥大是儿童常见病，手术效果好，消除焦虑；儿童对手术和医院环境恐惧，给予安抚和鼓励，争取配合；术后不适（咽痛、鼻塞）给予解释和安抚；告知家长术后打鼾可能暂时加重（术腔水肿），1-2周后逐渐改善，不要过于担心；告知腺样体面容早期手术可部分恢复，严重者需口腔正畸","健康教育：讲解腺样体肥大的病因、症状和危害（影响听力、生长发育、面容、学习）；强调手术指征和手术效果；指导术前准备（禁食禁水、控制炎症）；指导术后护理（饮食、休息、避免剧烈运动、观察出血和呼吸）；指导鼻用激素和鼻腔冲洗的正确使用方法；告知术后打鼾可能暂时加重，1-2周后逐渐改善；术后1个月内避免大声喊叫和剧烈运动；积极治疗过敏性鼻炎和鼻窦炎；增强体质，预防上呼吸道感染；儿童定期体检，发现鼻塞打鼾及时就医；术后定期复查鼻内镜；腺样体切除后免疫功能影响小，术后其他淋巴组织可代偿","家庭护理：家长协助患儿术后饮食准备（冷流质、软食）；观察患儿术后出血（频繁吞咽提示出血）和呼吸情况；督促患儿避免剧烈运动和大声喊叫；协助患儿鼻腔冲洗和用药；陪同定期复查；保持室内清洁、适宜温湿度；观察患儿睡眠、听力、生长发育改善情况；过敏患儿避免接触过敏原"],"notes":["腺样体又称咽扁桃体、增殖体，位于鼻咽顶后壁，是咽淋巴环的组成部分，出生后即存在，6-7岁时最大，10岁后逐渐萎缩，成人基本消失；腺样体因炎症反复刺激而发生病理性增生肥大，称为腺样体肥大，多见于3-10岁儿童，常与慢性扁桃体炎合并存在","病因：急性鼻炎鼻窦炎反复发作（最主要）、慢性鼻炎鼻窦炎（分泌物长期刺激）、慢性扁桃体炎、咽炎、变态反应（过敏性鼻炎）、胃食管反流、空气污染、遗传因素、全身因素（营养不良、免疫力低下、内分泌紊乱）","发病机制：反复炎症刺激→腺样体淋巴组织增生→腺样体肥大→堵塞后鼻孔→鼻塞、张口呼吸、打鼾；堵塞咽鼓管咽口→分泌性中耳炎；分泌物下流→咽炎、支气管炎；长期缺氧和睡眠结构紊乱→生长发育迟缓、注意力不集中；长期张口呼吸→腺样体面容","腺样体面容：长期张口呼吸影响面骨发育，是腺样体肥大的特征性表现，早期手术可部分恢复，严重者需口腔正畸治疗；一旦形成完全恢复困难，强调早期诊断早期治疗","检查：鼻内镜检查（金标准）；鼻咽部X线侧位片（常用无创检查，测量A/N比值）；鼻咽CT/MRI（明确范围，排除肿瘤）；睡眠监测（评估OSAHS）；听力检查（评估分泌性中耳炎）","A/N比值：鼻咽部X线侧位片上，腺样体厚度（A）与鼻咽腔宽度（N）的比值；A/N≤0.60正常，0.61-0.70中度肥大，≥0.71病理性肥大，≥0.80显著肥大","阻塞性睡眠呼吸暂停低通气综合征（OSAHS）：腺样体肥大是儿童OSAHS最常见的原因，表现为睡眠打鼾、张口呼吸、呼吸暂停、睡眠不安、多汗、遗尿、白天嗜睡、注意力不集中、学习成绩下降、生长发育迟缓；多导睡眠监测（PSG）是诊断金标准，AHI>5或最低血氧<90%可诊断；腺样体切除术是主要治疗方法，有效率80-90%","手术指征：腺样体肥大堵塞后鼻孔>50%引起明显症状；引起OSAHS；引起分泌性中耳炎反复发作听力下降；引起慢性鼻炎鼻窦炎反复发作；已形成腺样体面容；影响生长发育；保守治疗3-6个月无效；年龄不是绝对禁忌，2岁以下严重OSAHS也可手术","手术方式：传统腺样体刮除术（盲刮，易残留和损伤，现已少用）；鼻内镜下腺样体切除术（目前主流，直视下切除，准确残留少损伤小）；鼻内镜下等离子腺样体消融术（微创，低温等离子，出血少，疼痛轻，恢复快，目前最常用）；动力系统腺样体切除术（吸切钻，切除快，出血相对多）","术后出血：是腺样体切除术最常见的并发症，分为原发性出血（术后24小时内）和继发性出血（术后5-10天，白膜脱落时）；少量出血可压迫止血、冷敷；大量出血需手术止血，必要时输血；术后密切观察，频繁吞咽提示血液后流，需及时处理","术后饮食：术后6小时可进冷流质（避免热食致血管扩张出血）；术后1-2天流质；3-5天半流质；1周软食；2周正常饮食；避免辛辣刺激、硬食、油炸食物；鼓励进食和饮水，促进伤口愈合和防止脱水","预后：腺样体切除术效果好，术后鼻塞、打鼾、OSAHS多可明显改善或消失，有效率80-90%；分泌性中耳炎多可好转，听力恢复取决于病程；生长发育术后多可追赶生长；腺样体面容早期手术可部分恢复，严重者需口腔正畸；术后复发率低（<5%），多因残留或过敏体质；腺样体切除后免疫功能影响小，其他淋巴组织可代偿","预防：积极治疗急性鼻炎鼻窦炎（及时彻底，防止反复刺激腺样体）；增强体质，预防上呼吸道感染；积极治疗过敏性鼻炎（避免接触过敏原，规范用药）；避免胃食管反流；改善生活环境（避免粉尘、烟雾）；儿童定期体检，发现鼻塞打鼾及时就医；早期诊断早期治疗，防止腺样体面容和生长发育迟缓","我国现状：腺样体肥大是儿童常见病，是儿童OSAHS最常见的原因，但很多家长不重视，认为孩子打鼾是睡得香，导致就诊时已出现腺样体面容和生长发育迟缓；鼻内镜和等离子微创手术已普及，手术安全有效；需加强儿童健康教育和体检，推广睡眠监测，早期诊断早期治疗"],"emergency":["出现术后鼻腔大量鲜血涌出或频繁吞咽（术后出血，立即就医压迫止血，必要时输血和手术止血）","出现呼吸困难、喉喘鸣、血氧下降、发绀（术后喉水肿或出血堵塞气道，立即就医保持呼吸道通畅，必要时气管插管或切开）","出现高热、寒战、咽痛剧烈、吞咽困难（急性感染或扁桃体周围脓肿，及时就医）","出现耳痛、听力骤降、耳鸣加重（急性中耳炎或分泌性中耳炎加重，及时就医）","出现睡眠呼吸暂停严重、憋醒、口唇发绀（严重OSAHS缺氧，及时就医评估手术）","出现生长发育明显迟缓、身高体重不增、智力发育落后（长期缺氧影响，及时就医评估手术）","出现腺样体面容进行性加重（牙列不齐、上切牙突出、唇厚，及时就医手术，避免面容进一步加重）","术后出现伤口感染、发热、术腔疼痛加重（及时就医抗生素治疗）","儿童出现夜间突然憋醒、哭闹、呼吸困难（OSAHS急性加重，立即就医）","出现鼻出血量大、不易止住（可能损伤鼻咽部血管，立即就医）"],"pinyin":"xianyangtifeida","icd10":"J35.2","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态、面容","耳部：耳廓（畸形/红肿/皮疹/瘘管）、外耳道（耵聍/异物/分泌物/红肿/狭窄/闭锁）、鼓膜（标志/充血/内陷/穿孔/钙化/液平/肉芽）、乳突（红肿/压痛）、听力（耳语/音叉试验：Rinne试验/Weber试验/Schwabach试验）、前庭功能（自发性眼震/位置试验）","鼻部：外鼻（畸形/红肿）、鼻前庭（红肿/疖肿/结痂）、鼻腔（鼻中隔偏曲/糜烂/出血/穿孔、下鼻甲肿大/息肉样变、中鼻甲息肉样变/气化、鼻道分泌物（黏脓/血性/水样）、息肉/新生物）、鼻窦（压痛：额窦/上颌窦/筛窦）、后鼻孔检查","咽喉部：口咽（黏膜充血/肿胀/溃疡、扁桃体大小（Ⅰ-Ⅳ度）/充血/隐窝脓栓/结石、咽后壁淋巴滤泡增生/脓性分泌物、悬雍垂水肿/偏斜、软腭运动）、喉咽（会厌充血/水肿/囊肿、杓状会厌襞、梨状窝新生物/积液）、喉部（间接喉镜/电子喉镜：声带充血/息肉/小结/麻痹/新生物、室带肥厚、声门闭合情况）","颈部：淋巴结肿大（部位/大小/质地/活动度/压痛）、甲状腺、包块、瘘管","其他：发音（声嘶/失声）、吞咽（困难/呛咳）、呼吸（喘鸣/呼吸困难）"],"lab_tests":["电子鼻咽镜（鼻内镜）检查：直视下观察腺样体大小、形态及后鼻孔阻塞程度，为首选检查，术前及复查时均应完成","鼻咽侧位X线片：测量腺样体厚度与鼻咽腔宽度比值（A/N比值）量化肥大程度，用于手术指征评估","耳内镜+声导抗+纯音听阈测定：排查分泌性中耳炎，鼓室图呈B型或C型提示中耳积液，有耳闷、听力下降者必查","睡眠监测（多导睡眠监测或便携式睡眠呼吸监测）：有打鼾、张口呼吸、睡眠呼吸暂停或日间嗜睡者，评估OSA严重程度以决定手术时机","视力、屈光检查及眼压测定：长期张口呼吸低氧及OSA患儿常规筛查屈光状态，评估青光眼风险并排除视力问题","过敏原检测（皮肤点刺或血清特异性IgE）：合并变应性鼻炎者明确过敏原，指导药物及规避治疗"],"nursing":["病情观察：观察鼻塞、张口呼吸、打鼾及夜间呼吸暂停情况，监测血氧饱和度，记录有无憋醒、睡眠中断","术后出血观察：腺样体切除术后观察口鼻腔有无活动性出血，频繁吞咽动作提示渗血，嘱勿用力擤鼻、咳嗽及打喷嚏","体位管理：术后取半卧位或侧卧位、头偏向一侧，利于口内分泌物引流，防止误吸，保持呼吸道通畅","防误吸：麻醉苏醒后及进食前确认吞咽反射恢复，先少量试饮温凉水，无呛咳后再逐步进食","口腔护理：术后当日以生理盐水或漱口水轻轻漱口，观察软腭及悬雍垂水肿情况，保持口腔清洁"],"diet":["术后当日进温凉流质（米汤、牛奶、藕粉），术后1-2天过渡为半流质（粥、烂面条、蒸蛋羹）","术后2周内禁食过热、过硬、粗糙及辛辣刺激性食物（坚果、饼干、油炸食品、带骨带刺食物），防止创面出血","推荐高蛋白、富含维生素食物（鱼泥、肉末、蛋类、果蔬泥），促进创面愈合","保证每日适量饮水，温凉水少量多次，保持咽部湿润","合并变应性鼻炎者，回避明确过敏的食物，以清淡饮食为主，减少鼻咽部刺激"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":406},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"afe154d829394578234ebff1a54f1a825dc6d8b1e23657085e8641dbf92ec019","pinyin":"xianyangtifeida","initials":"xytfd","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","鼻部症状：鼻塞（主要症状，持续性）、流涕（黏液性或脓性）、闭塞性鼻音、嗅觉减退\\n耳部症状：堵塞咽鼓管咽口，引起分泌性中耳炎，出现耳鸣、耳闷、听力下降\\n咽喉部症状：分泌物下流刺激咽喉，引起咽部不适、异物感、咳嗽、多痰\\n全身症状：慢性中毒及反射性神经症状——营养发育不良、反应迟钝、注意力不集中、夜惊、磨牙、遗尿、夜啼、食欲差\\n睡眠症状：睡眠时打鼾（主要症状）、张口呼吸、睡眠不安、多汗、睡眠呼吸暂停，严重者可憋醒\\n腺样体面容：长期张口呼吸影响面骨发育，出现上颌骨变长、腭骨高拱、牙列不齐、上切牙突出、唇厚、缺乏表情\\n鼻镜检查：鼻咽顶后壁可见分叶状淋巴组织增生，如剥去皮的橘子瓣，堵塞后鼻孔，可分为Ⅳ度\\n可伴慢性鼻炎鼻窦炎、慢性扁桃体炎、分泌性中耳炎\\n并发症：分泌性中耳炎、化脓性中耳炎、慢性鼻炎鼻窦炎、咽炎、支气管炎、阻塞性睡眠呼吸暂停低通气综合征、腺样体面容、生长发育迟缓、胸廓畸形、肺心病",60],["摘要","腺样体因炎症反复刺激而发生病理性增生肥大，多见于儿童，常与慢性扁桃体炎合并存在，表现为鼻塞、打鼾、张口呼吸、睡眠呼吸暂停，可影响儿童生长发育和面容。",30],["疾病编码","J35.2",30],["原首字母","xianyangtifeida",60]]},{"id":"orders-368df56f413d41196808","key":"v1-c9ccc21dfe2a3058|orders-368df56f413d41196808","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"咽异感症","category":"耳鼻喉","raw":{"name":"咽异感症","category":"耳鼻喉","summary":"又称梅核气、咽神经官能症，是指除疼痛以外的多种咽部异常感觉或幻觉，如异物感、梗阻感、烧灼感、痒感、黏痰附着感等，检查无明显器质性病变，多与精神因素、局部疾病、全身疾病有关，多见于中年女性。","symptoms":["咽部异物感：最常见，咽内有异物感、梗阻感、痰黏感，咯之不出、咽之不下，不影响进食，空咽时明显，进食时减轻或消失","咽部烧灼感：咽部灼热、发热感","咽部痒感：咽部发痒，引起刺激性咳嗽","咽部黏痰附着感：总觉得咽部有痰，想清嗓，清嗓后暂时舒服，之后又有","咽部压迫感：咽部发紧、压迫感","其他：咽部干燥感、蚁行感、狭窄感、球塞感","症状与情绪有关：心情舒畅、注意力转移时减轻或消失；情绪低落、焦虑、紧张、生气时加重；注意力集中在咽部时加重","一般无疼痛，或仅有轻微隐痛","不影响进食和吞咽（与食管肿瘤、咽部肿瘤鉴别，肿瘤多有进行性吞咽困难）","可伴焦虑、抑郁、失眠、多疑、恐癌等精神症状","可伴慢性咽炎、鼻炎鼻窦炎、胃食管反流、甲状腺疾病等","咽部检查：一般无明显异常，或仅有轻度慢性咽炎表现（咽黏膜轻度充血、少量淋巴滤泡增生），无新生物、无溃疡、无扁桃体明显肿大","电子喉镜检查：咽部、喉部、下咽部无明显器质性病变，可有轻度慢性咽炎或喉咽反流表现（杓间区充血、声带水肿、肉芽肿）"],"diagnosis":["典型症状（咽部异物感等异常感觉，空咽明显进食减轻，与情绪有关，病程>3个月）+检查无明显器质性病变","详细询问病史（症状特点、诱发因素、与情绪和进食关系、伴随症状、精神心理状态、既往疾病、用药史），是诊断的关键","咽部检查（间接喉镜、电子喉镜，详细检查咽部、喉部、下咽部，排除肿瘤、溃疡、异物、扁桃体疾病、咽炎），电子喉镜是必查，排除器质性病变","鼻内镜检查（排除鼻炎鼻窦炎、鼻息肉、腺样体肥大，鼻涕后流刺激咽部）","胃镜或24小时食管pH监测（怀疑胃食管反流性咽炎时，很多咽异感症与喉咽反流有关）","甲状腺检查（触诊、甲状腺B超、甲状腺功能，排除甲状腺疾病）","颈部检查（触诊颈部淋巴结、甲状腺、包块，排除颈部肿瘤）","血常规、生化（排除贫血、糖尿病、肝肾疾病等全身因素）","心理评估（焦虑抑郁量表，评估精神心理状态）","排除器质性疾病：咽部肿瘤（扁桃体癌、咽癌、喉癌、下咽癌，多为单侧、进行性、伴疼痛或痰中带血、吞咽困难）、食管肿瘤（进行性吞咽困难、胸骨后疼痛、体重下降）、咽部异物（有异物史，刺痛，吞咽时加重）、慢性咽炎（咽部检查有明显充血、淋巴滤泡增生）、扁桃体疾病（扁桃体肥大、结石、隐窝炎）、喉咽反流（反酸、烧心、声音嘶哑、晨起咳嗽，喉镜见杓间区充血）、甲状腺疾病（甲状腺肿大、结节、功能异常）、颈椎病（颈部疼痛、上肢麻木、头晕，与颈部活动有关）、贫血（面色苍白、乏力、头晕）、糖尿病（口干、多饮多尿）、更年期综合征（潮热、盗汗、情绪波动）、精神心理疾病（焦虑症、抑郁症、恐癌症、癔症）","分型：器质性咽异感症（由局部或全身疾病引起）、功能性咽异感症（无明显器质性病变，与精神心理因素有关，即咽神经官能症、梅核气）；两者可同时存在"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般无需静脉输液；咽异感症以病因排查及对症处理为主，必要时口服谷维素 20mg 口服 tid","方案2（合并急性咽炎或感染）：","用法：0.9%NS 100ml + 抗生素 ivgtt qd（根据病原选择）","方案3（严重焦虑抑郁或癔症发作）：","用法：精神科会诊，按精神科方案治疗","方案4：","用法：合并其他全身疾病按相应方案治疗","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（病因治疗（关键））：","用法：治疗慢性咽炎（含漱液、含片、中成药）、喉咽反流（抑酸药+促动力药+生活方式调整）、鼻炎鼻窦炎（鼻用激素+鼻腔冲洗+抗生素）、甲状腺疾病（相应治疗，甲亢用甲巯咪唑，甲减用左甲状腺素，结节定期随访或手术）、贫血（补铁、维生素B12、叶酸）、糖尿病（控制血糖）、更年期综合征（激素替代或中药调理）","药物2（对症治疗）：","用法：谷维素10-20mg tid（调节植物神经功能）、维生素B1 10mg tid、维生素B6 10mg tid、维生素B12 500μg qd（营养神经）、镇静剂（地西泮2.5mg tid或阿普唑仑0.4mg qn，焦虑明显时短期使用，注意成瘾性）、抗焦虑抑郁药（氟哌噻吨美利曲辛1片 bid、舍曲林50mg qd、帕罗西汀20mg qd、氟西汀20mg qd，需精神科评估，起效慢，需长期使用，不可自行停药）、中成药（金嗓利咽丸、逍遥丸、柴胡疏肝散、半夏厚朴汤、加味逍遥丸，辨证使用，疏肝理气、化痰散结）","药物3（局部治疗）：","用法：含漱液（复方硼砂溶液、生理盐水，每日3-4次）、含片（西地碘含片、溶菌酶含片，每日3-4次）、雾化吸入（生理盐水+布地奈德，每日1-2次，减轻咽部炎症）、局部封闭（0.5%普鲁卡因穴位封闭，廉泉、人迎等穴位，适用于功能性咽异感症）","药物4（中医中药）：","用法：梅核气（中医病名，相当于功能性咽异感症），辨证施治——痰气交阻型（半夏厚朴汤加减，行气散结、降逆化痰，是梅核气经典方）、肝郁气滞型（柴胡疏肝散加减，疏肝理气）、肝郁化火型（丹栀逍遥散加减，疏肝清热）、心脾两虚型（归脾汤加减，健脾养心）、阴虚火旺型（知柏地黄丸加减，滋阴降火）；中成药可选用金嗓利咽丸、逍遥丸、加味逍遥丸、柴胡疏肝丸等","药物5（心理治疗）：","用法：心理咨询、认知行为治疗、暗示治疗、催眠治疗，适用于功能性咽异感症，帮助患者认识疾病性质，消除恐癌心理，缓解焦虑抑郁","药物6（暗示治疗）：","用法：对于有明显暗示性的患者，可在详细检查排除器质性病变后，给予耐心解释和安慰，配合药物暗示（如谷维素、维生素，告知是特效药），部分患者可明显缓解","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["病因治疗（最关键）：详细检查寻找病因，针对病因治疗——慢性咽炎（药物+生活方式）、喉咽反流（抑酸+促动力+生活方式调整，很多咽异感症与喉咽反流有关，抑酸治疗8-12周可明显改善）、鼻炎鼻窦炎（鼻用激素+鼻腔冲洗）、扁桃体疾病（反复发炎或结石者扁桃体切除）、甲状腺疾病（相应治疗）、颈椎病（骨科治疗）、贫血（补充造血原料）、糖尿病（控制血糖）、更年期综合征（激素替代或中药）；病因治疗有效，症状可明显改善或消失","心理治疗（重要）：对于功能性咽异感症或伴明显焦虑抑郁者，心理治疗是重要组成部分——心理咨询（倾听、解释、安慰，帮助患者认识疾病，消除恐癌心理）、认知行为治疗（改变不良认知和行为模式）、暗示治疗（利用暗示性，配合药物或物理治疗）、催眠治疗（适用于暗示性强者）、放松训练（深呼吸、冥想、渐进性肌肉放松）；心理治疗可显著改善症状，减少药物依赖","药物治疗：病因治疗药物+对症治疗（谷维素、维生素、镇静剂、抗焦虑抑郁药）+中成药+局部治疗；抗焦虑抑郁药需在精神科指导下使用，起效慢（2-4周），需长期使用（6-12个月），不可自行停药（防止戒断反应和复发）","物理治疗：雾化吸入、局部封闭、穴位按摩、针灸（廉泉、人迎、天突、合谷、太冲等穴位）、超短波、药物离子导入，可作为辅助治疗","生活方式调整：保持心情舒畅，避免精神紧张、焦虑、生气；规律作息，避免熬夜；适当体育锻炼（慢跑、游泳、太极拳、瑜伽），增强体质，转移注意力；清淡饮食，避免辛辣刺激、过冷过热、油炸食物，戒烟酒，避免咖啡浓茶（反流时）；多饮水，保持咽部湿润；避免过度用嗓和清嗓动作；改善工作环境（避免粉尘、烟雾、刺激性气体）；培养兴趣爱好，转移注意力（不要总关注咽部感觉）","预防：积极治疗咽部及邻近器官疾病（慢性咽炎、鼻炎鼻窦炎、扁桃体炎、胃食管反流）；保持心情舒畅，避免精神紧张和焦虑；规律作息，避免熬夜；适当体育锻炼，增强体质；清淡饮食，戒烟酒；改善工作环境；出现咽部异物感及时就医，详细检查排除器质性病变，不要自行诊断为梅核气而延误肿瘤等疾病的诊治","随访：定期复查（评估疗效，调整治疗方案）；功能性咽异感症易复发，需长期管理和心理疏导；对于症状持续不缓解或加重、出现报警症状（进行性吞咽困难、疼痛、痰中带血、颈部肿块、体重下降）者，必须重新详细检查排除肿瘤等器质性病变"],"management":["心理护理（最重要）：安慰患者，耐心倾听患者诉说，给予充分理解和同情；详细解释疾病性质（咽异感症是良性病变，不是癌症，与精神因素、局部疾病有关），消除患者恐癌心理和焦虑；告知患者检查结果（电子喉镜等检查无异常），让患者放心；鼓励患者保持心情舒畅，避免精神紧张、焦虑、生气；指导患者转移注意力（培养兴趣爱好、参加社交活动、体育锻炼），不要总关注咽部感觉；对于明显焦虑抑郁者，建议精神科会诊和心理治疗；家属给予理解和支持，不要指责患者装病或想太多","用药护理：按医嘱使用谷维素、维生素、中成药、抗焦虑抑郁药；抗焦虑抑郁药需在精神科指导下使用，告知患者起效慢（2-4周），需长期使用（6-12个月），不可自行停药或减量（防止戒断反应和复发），注意药物副作用（嗜睡、头晕、胃肠道反应、性功能影响等）；镇静剂短期使用，注意成瘾性；观察药物疗效和副作用","病情观察：观察咽部异物感等症状变化（与情绪、饮食、作息关系）；观察有无报警症状（进行性吞咽困难、咽痛、痰中带血、颈部肿块、体重下降、声音嘶哑），一旦出现立即就医（排除咽部肿瘤、食管肿瘤等器质性病变）；观察精神心理状态（焦虑、抑郁、睡眠情况）；治疗后评估疗效；出现报警症状及时就医","饮食：清淡易消化饮食，多饮水（每日1500-2000ml，保持咽部湿润）；多吃新鲜蔬果（富含维生素，促进黏膜修复）；避免辛辣刺激、过冷过热、油炸、烧烤食物；戒烟酒（烟酒刺激咽部黏膜，加重症状）；避免咖啡、浓茶、巧克力（反流时）；避免过饱（七八分饱，防止反流）；睡前3小时不进食（反流时）；规律进餐，细嚼慢咽；保持大便通畅","休息与活动：保证充足睡眠，避免熬夜和过度劳累；适当体育锻炼（慢跑、游泳、太极拳、瑜伽、散步），增强体质，转移注意力，缓解焦虑；避免长时间处于粉尘、烟雾、刺激性气体环境；避免过度用嗓和清嗓动作（清嗓可刺激咽部，加重异物感，可改为饮水或吞咽）；培养兴趣爱好（看书、听音乐、养花、社交活动），转移注意力","个人卫生：勤洗手，预防上呼吸道感染；保持口腔清洁（早晚刷牙，饭后漱口）；避免用手挖鼻；避免频繁做清嗓动作","环境管理：保持室内通风、清洁、适宜温湿度（湿度50-60%，避免干燥）；避免接触粉尘、烟雾、刺激性气体；戒烟（包括二手烟）；厨房使用抽油烟机；干燥季节使用加湿器；避免在嘈杂环境中大声说话","心理调适：指导患者学会自我心理调节——保持乐观心态，避免精神紧张、焦虑、生气；遇到不愉快的事情学会倾诉和释放；培养兴趣爱好，丰富生活，转移注意力；学习放松技巧（深呼吸、冥想、渐进性肌肉放松）；规律作息，适当运动；必要时寻求心理咨询师帮助；家属给予理解和支持，营造温馨的家庭环境","健康教育：讲解咽异感症的病因（精神因素、局部疾病如慢性咽炎/喉咽反流/鼻炎鼻窦炎、全身疾病如甲状腺疾病/贫血/糖尿病/更年期、颈椎病等）、症状特点（空咽明显进食减轻、与情绪有关、无疼痛）和诊断（必须详细检查排除器质性病变，尤其是肿瘤）；强调详细检查的重要性（电子喉镜、胃镜、甲状腺B超等），不要自行诊断为梅核气而延误肿瘤诊治；告知患者咽异感症是良性病变，不是癌症，消除恐癌心理；指导病因治疗（治疗慢性咽炎、喉咽反流、鼻炎鼻窦炎、甲状腺疾病等）；指导心理调节方法（保持心情舒畅、转移注意力、放松训练）；指导生活方式调整（规律作息、适当运动、清淡饮食、戒烟酒）；告知抗焦虑抑郁药的使用注意事项（起效慢、需长期使用、不可自行停药）；出现报警症状（进行性吞咽困难、疼痛、痰中带血、颈部肿块、体重下降、声音嘶哑）及时就医；咽异感症易复发，需长期管理和心理疏导；定期复查","家庭护理：家属给予患者充分理解和支持，不要指责患者装病或想太多；帮助患者保持心情舒畅，营造温馨的家庭环境；鼓励患者参加社交活动和体育锻炼，转移注意力；观察患者症状变化和精神心理状态，出现报警症状及时陪同就医；督促患者按时服药和定期复查；协助患者培养兴趣爱好，丰富生活"],"notes":["咽异感症又称梅核气、咽神经官能症、癔球症、咽部异物感，是指除疼痛以外的多种咽部异常感觉或幻觉，如异物感、梗阻感、烧灼感、痒感、黏痰附着感、球塞感等，检查无明显器质性病变，是耳鼻喉门诊常见病，多见于中年女性（男女比例约1:3），病程长，易反复","病因：局部因素（慢性咽炎、慢性扁桃体炎、扁桃体结石、鼻炎鼻窦炎鼻涕后流、喉咽反流、咽部异物残留、喉部疾病、口腔疾病）、全身因素（甲状腺疾病如甲状腺肿大/结节/甲亢/甲减、贫血、糖尿病、更年期综合征、肝肾疾病、风湿病、植物神经功能紊乱）、精神因素（焦虑、抑郁、疑病、恐癌、神经衰弱、癔症、精神分裂症，是功能性咽异感症的主要原因）、环境因素（粉尘、烟雾、刺激性气体、干燥）、医源性因素（医生解释不当或检查不仔细，加重患者疑虑）","发病机制：尚未完全明确，可能与咽部感觉神经敏感性增高、咽部肌肉痉挛、植物神经功能紊乱、精神心理因素导致的躯体化症状有关；局部疾病可引起咽部感觉异常，精神因素可加重感觉异常，两者常同时存在，互为因果","梅核气：中医病名，出自《金匮要略》，描述咽中似有梅核阻塞，咯之不出、咽之不下，时发时止，与情绪有关，相当于功能性咽异感症；中医认为多因情志不畅、肝气郁结、痰气交阻于咽喉所致，治疗以疏肝理气、化痰散结为主，半夏厚朴汤是经典方剂","临床表现：咽部异物感（最常见，空咽明显进食减轻，不影响进食）、烧灼感、痒感、黏痰附着感、压迫感、干燥感、蚁行感；症状与情绪密切相关（心情好时减轻，焦虑紧张时加重）；一般无疼痛；可伴焦虑、抑郁、失眠、恐癌；检查无明显器质性病变或仅有轻度慢性咽炎","诊断要点：典型症状+详细检查排除器质性病变；必须进行电子喉镜检查（排除咽部、喉部、下咽部肿瘤）；必要时胃镜（排除食管肿瘤和反流）、甲状腺B超和功能（排除甲状腺疾病）、颈部检查；详细询问病史和精神心理状态；不可轻易诊断为功能性咽异感症，必须排除器质性病变，尤其是肿瘤","与咽部肿瘤鉴别：咽部肿瘤（扁桃体癌、咽癌、喉癌、下咽癌）多表现为单侧咽部异物感、进行性加重、伴咽痛（吞咽时加重）、痰中带血、声音嘶哑、吞咽困难、颈部淋巴结肿大、体重下降；咽异感症多为双侧或位置不固定、时轻时重、与情绪有关、无疼痛和痰中带血、不影响进食、无颈部肿块和体重下降；40岁以上、单侧、进行性、伴报警症状者必须详细检查排除肿瘤","与食管肿瘤鉴别：食管肿瘤（食管癌）表现为进行性吞咽困难（先是干饭，后半流质，最后水也难以下咽）、胸骨后疼痛、食物反流、体重下降、呕血黑便；咽异感症不影响进食，甚至进食时减轻，无进行性吞咽困难和体重下降；有吞咽困难或报警症状者必须胃镜检查排除食管癌","喉咽反流（LPR）：是咽异感症的重要原因之一，约占30-50%，很多患者无明显反酸烧心，仅表现为咽部异物感、声音嘶哑、慢性咳嗽、晨起清嗓、咽部球塞感；喉镜可见杓间区充血水肿、声带肉芽肿、喉咽黏膜红斑；治疗需抑酸（PPI 8-12周）+促动力+生活方式调整，单纯按咽炎治疗效果差","治疗原则：病因治疗是关键（寻找并治疗局部和全身病因），心理治疗是重要组成部分（尤其是功能性咽异感症），配合药物（谷维素、维生素、中成药、抗焦虑抑郁药）、物理治疗、生活方式调整；综合治疗效果好，单一治疗效果差","抗焦虑抑郁药使用：对于伴明显焦虑抑郁的患者，可在精神科指导下使用SSRI类（舍曲林、帕罗西汀、氟西汀、西酞普兰）或SNRI类（文拉法辛、度洛西汀），或氟哌噻吨美利曲辛；起效慢（2-4周），需长期使用（6-12个月），不可自行停药（防止戒断反应和复发）；注意副作用（恶心、头痛、失眠、嗜睡、性功能影响等），多数副作用1-2周后耐受；苯二氮䓬类（地西泮、阿普唑仑）短期使用可快速缓解焦虑，但有成瘾性，不宜长期使用","预后：咽异感症预后良好，病因明确者针对病因治疗后症状多可明显改善或消失；功能性咽异感症经心理治疗和药物综合治疗后多数可缓解，但易复发（与精神因素有关）；长期不愈者可能影响生活质量和精神心理健康；关键是详细检查排除器质性病变，尤其是肿瘤，避免误诊","预防：积极治疗咽部及邻近器官疾病（慢性咽炎、鼻炎鼻窦炎、扁桃体炎、胃食管反流）；保持心情舒畅，避免精神紧张和焦虑；规律作息，避免熬夜；适当体育锻炼，增强体质；清淡饮食，戒烟酒；改善工作环境（避免粉尘、烟雾）；出现咽部异物感及时就医，详细检查排除器质性病变，不要自行诊断为梅核气而延误诊治；避免医源性刺激（医生解释要恰当，避免加重患者疑虑）","我国现状：咽异感症是耳鼻喉门诊常见病，尤其是中年女性多见，但很多患者被简单诊断为慢性咽炎或梅核气，未详细检查排除肿瘤和喉咽反流等病因，治疗效果差；需加强详细检查（电子喉镜、胃镜、甲状腺B超）和病因治疗，重视喉咽反流和精神心理因素的诊治；同时需警惕咽部和食管肿瘤，避免误诊延误治疗"],"emergency":["出现进行性吞咽困难、进食受阻、胸骨后疼痛（排除食管癌、食管狭窄，尽快胃镜检查）","出现单侧咽部异物感进行性加重、咽痛、痰中带血、声音嘶哑、颈部肿块、体重下降（排除咽部肿瘤、喉癌、下咽癌，尽快电子喉镜和颈部CT检查，必要时病理活检）","出现高热、咽痛剧烈、吞咽困难、张口受限、颈部肿胀（急性扁桃体炎、扁桃体周围脓肿、咽旁脓肿，及时就医抗生素+切开引流）","出现呼吸困难、喉喘鸣、声音嘶哑（急性喉水肿或喉梗阻，立即就医保持呼吸道通畅）","出现大量呕血、黑便、头晕乏力（上消化道大出血，立即就医）","出现甲状腺肿大迅速、声音嘶哑、呼吸困难、吞咽困难（排除甲状腺癌或甲状腺出血，尽快甲状腺B超和功能检查）","出现严重焦虑抑郁发作、自杀念头（精神科急诊，立即干预）","出现异物感突然加重、伴呼吸困难、面部肿胀（过敏反应或血管神经性水肿，立即就医）","出现更年期严重情绪波动、自杀倾向（精神科和妇科协同治疗）","药物治疗过程中出现严重副作用（如抗抑郁药引起5-羟色胺综合征、严重过敏），立即停药就医"],"pinyin":"yanyiganzheng","icd10":"R09.8","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态、面容","耳部：耳廓（畸形/红肿/皮疹/瘘管）、外耳道（耵聍/异物/分泌物/红肿/狭窄/闭锁）、鼓膜（标志/充血/内陷/穿孔/钙化/液平/肉芽）、乳突（红肿/压痛）、听力（耳语/音叉试验：Rinne试验/Weber试验/Schwabach试验）、前庭功能（自发性眼震/位置试验）","鼻部：外鼻（畸形/红肿）、鼻前庭（红肿/疖肿/结痂）、鼻腔（鼻中隔偏曲/糜烂/出血/穿孔、下鼻甲肿大/息肉样变、中鼻甲息肉样变/气化、鼻道分泌物（黏脓/血性/水样）、息肉/新生物）、鼻窦（压痛：额窦/上颌窦/筛窦）、后鼻孔检查","咽喉部：口咽（黏膜充血/肿胀/溃疡、扁桃体大小（Ⅰ-Ⅳ度）/充血/隐窝脓栓/结石、咽后壁淋巴滤泡增生/脓性分泌物、悬雍垂水肿/偏斜、软腭运动）、喉咽（会厌充血/水肿/囊肿、杓状会厌襞、梨状窝新生物/积液）、喉部（间接喉镜/电子喉镜：声带充血/息肉/小结/麻痹/新生物、室带肥厚、声门闭合情况）","颈部：淋巴结肿大（部位/大小/质地/活动度/压痛）、甲状腺、包块、瘘管","其他：发音（声嘶/失声）、吞咽（困难/呛咳）、呼吸（喘鸣/呼吸困难）"],"lab_tests":["电子喉镜（首选）：重点观察会厌谷、梨状窝、环后区及声门下，排除下咽癌、喉癌等器质性病变","24小时咽喉-食管pH联合监测：伴反酸、烧心、晨起声嘶疑诊咽喉反流者完善，明确反流性咽异感","胃镜及食管钡餐造影：喉镜阴性但症状持续或伴吞咽困难、消瘦时，排除食管肿瘤、食管裂孔疝","颈部彩色多普勒超声：排除甲状腺肿物、颈部肿大淋巴结压迫所致咽部异物感","颈部CT/MRI：喉镜、胃镜均阴性但症状持续＞3个月或进行性加重时完善","甲状腺功能及血常规：甲状腺肿大者查甲功，伴消瘦、贫血者查血常规，排除代谢性及缺铁性贫血相关咽异感"],"nursing":["病情观察：重点观察有无进行性吞咽困难、声音嘶哑、痰中带血及颈部包块，一旦出现立即报告医生并复查喉镜","心理护理：向患者解释本病多为功能性、预后良好，疏导紧张焦虑情绪，必要时请心理科会诊","体位护理：疑似反流者嘱睡前2～3小时禁食，睡眠时床头抬高15～20cm或肩部垫高，减少夜间反流刺激","口腔护理：饭后及睡前用温盐水或漱口液含漱，保持口腔清洁，减少咽部慢性刺激","用药与疗效观察：遵医嘱规律服用质子泵抑制剂，动态记录异物感缓解情况，8～12周后复评疗效"],"diet":["忌口：忌辛辣、过烫、过硬及油炸食物，戒烟酒，避免浓茶、咖啡及碳酸饮料","进食方式：少食多餐、细嚼慢咽，避免暴饮暴食及进食时谈笑，防止呛咳误吸","反流饮食：睡前2～3小时不进食，晚餐宜清淡低脂，避免高脂、甜食及过饱","推荐食谱：以清淡软食为主，多食新鲜蔬菜、水果及富含B族维生素食物，保证水分摄入","营养支持：伴消瘦、贫血或进食量减少者，给予高蛋白、高维生素半流质饮食，必要时予肠内营养支持"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":407},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"d76da6d4c949d29c12c093c4a5757988ba6c9d1b526280482c35e567ac8beccc","pinyin":"yanyiganzheng","initials":"yygz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","咽部异物感：最常见，咽内有异物感、梗阻感、痰黏感，咯之不出、咽之不下，不影响进食，空咽时明显，进食时减轻或消失\\n咽部烧灼感：咽部灼热、发热感\\n咽部痒感：咽部发痒，引起刺激性咳嗽\\n咽部黏痰附着感：总觉得咽部有痰，想清嗓，清嗓后暂时舒服，之后又有\\n咽部压迫感：咽部发紧、压迫感\\n其他：咽部干燥感、蚁行感、狭窄感、球塞感\\n症状与情绪有关：心情舒畅、注意力转移时减轻或消失；情绪低落、焦虑、紧张、生气时加重；注意力集中在咽部时加重\\n一般无疼痛，或仅有轻微隐痛\\n不影响进食和吞咽（与食管肿瘤、咽部肿瘤鉴别，肿瘤多有进行性吞咽困难）\\n可伴焦虑、抑郁、失眠、多疑、恐癌等精神症状\\n可伴慢性咽炎、鼻炎鼻窦炎、胃食管反流、甲状腺疾病等\\n咽部检查：一般无明显异常，或仅有轻度慢性咽炎表现（咽黏膜轻度充血、少量淋巴滤泡增生），无新生物、无溃疡、无扁桃体明显肿大\\n电子喉镜检查：咽部、喉部、下咽部无明显器质性病变，可有轻度慢性咽炎或喉咽反流表现（杓间区充血、声带水肿、肉芽肿）",60],["摘要","又称梅核气、咽神经官能症，是指除疼痛以外的多种咽部异常感觉或幻觉，如异物感、梗阻感、烧灼感、痒感、黏痰附着感等，检查无明显器质性病变，多与精神因素、局部疾病、全身疾病有关，多见于中年女性。",30],["疾病编码","R09.8",30],["原首字母","yanyiganzheng",60]]},{"id":"orders-1392df7f819d56780257","key":"v1-c9ccc21dfe2a3058|orders-1392df7f819d56780257","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"龋病","category":"口腔","raw":{"name":"龋病","category":"口腔","summary":"俗称蛀牙、虫牙，是在以细菌为主的多种因素影响下，牙体硬组织发生慢性进行性破坏的疾病，表现为牙齿颜色改变、缺损、疼痛，是人类最常见的疾病之一，发病率高，分布广。","symptoms":["浅龋：病变局限于牙釉质或牙骨质，一般无自觉症状，检查时可见牙面有白垩色或黑褐色斑点或斑片，表面粗糙，探针检查有粗糙感或能钩住探针尖端","中龋：病变进展到牙本质浅层，患者对冷、热、酸、甜刺激敏感，尤其对冷刺激明显，刺激去除后症状立即消失，无自发痛；检查可见龋洞形成，洞内有软化牙本质和食物残渣","深龋：病变进展到牙本质深层，接近牙髓，患者对冷、热、酸、甜刺激明显疼痛，食物嵌入龋洞时疼痛，刺激去除后症状消失，无自发痛；检查可见较深龋洞，探诊敏感，但无穿髓孔","龋病好发部位：咬合面窝沟（最常见）、邻面（牙齿邻接面）、牙颈部（牙龈缘附近）、根面（老年人牙龈退缩后牙根暴露）","龋病好发牙齿：下颌第一磨牙（最常见）、下颌第二磨牙、上颌第一磨牙、上颌第二磨牙、前磨牙、乳牙（乳磨牙最常见）","并发症：牙髓炎（龋病进展到牙髓，引起牙髓炎症，出现自发痛、夜间痛）、根尖周炎（牙髓坏死，感染扩散到根尖周组织，出现咬合痛、牙龈肿胀、瘘管）、牙体缺损（龋坏严重，牙冠大部分缺损，形成残冠、残根）、牙齿丧失（严重龋坏无法保留，需拔除）、颌面部间隙感染（根尖周炎扩散，引起面部肿胀、疼痛、发热）、全身感染（严重感染可引起败血症，罕见但严重）","儿童龋病：乳牙龋病进展快，范围广，可影响恒牙发育和萌出，引起牙列不齐、咬合紊乱，影响咀嚼和营养吸收，儿童龋病需及时治疗","老年人根面龋：牙龈退缩，牙根暴露，根面牙骨质龋坏，进展快，可引起牙本质过敏、牙髓炎，老年人根面龋需及时治疗"],"diagnosis":["典型症状（牙齿颜色改变、缺损、对冷热酸甜刺激敏感）+口腔检查","口腔检查：视诊（观察牙面颜色改变、龋洞形成、缺损）、探诊（用探针检查龋洞深度、软化牙本质、有无穿髓孔、探痛）、叩诊（轻叩牙齿，有无叩痛，排除根尖周炎）、冷热诊（用冷刺激或热刺激检查牙髓反应，判断牙髓状态）","X线检查（根尖片、咬翼片，可发现邻面龋、隐匿龋、评估龋坏深度、是否接近牙髓、根尖周情况，是诊断邻面龋和隐匿龋的重要手段）","牙髓活力测试（冷测、热测、电活力测试，判断牙髓状态，正常牙髓、可复性牙髓炎、不可复性牙髓炎、牙髓坏死）","龋病分类：按病变深度分浅龋（牙釉质或牙骨质）、中龋（牙本质浅层）、深龋（牙本质深层）；按病变进展速度分急性龋（进展快，多见于儿童和青少年，龋坏组织颜色浅、质地软、湿润）、慢性龋（进展慢，多见于成人，龋坏组织颜色深、质地硬、干燥）、静止龋（龋病进展到一定阶段停止，龋坏组织变硬、颜色深）；按病变部位分窝沟龋、平滑面龋、根面龋；按治疗史分原发龋、继发龋（充填物周围或下方再次龋坏）","排除：牙本质过敏（牙本质暴露，对冷热酸甜敏感，无龋洞）、牙髓炎（有自发痛、夜间痛，刺激去除后疼痛持续）、根尖周炎（咬合痛、牙龈肿胀、瘘管、叩痛）、牙外伤（有外伤史，牙体缺损或松动）、氟斑牙（牙齿表面白垩色或黄褐色斑块，有高氟地区生活史，牙面光滑无缺损）、四环素牙（牙齿黄褐色改变，有四环素类药物服用史，牙面光滑）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般无需静脉输液；龋病以充填治疗（去腐后树脂充填）为主","方案2（合并急性根尖周炎或颌面部间隙感染）：","用法：0.9%NS 100ml + 抗生素 ivgtt qd（根据病原选择，阿莫西林克拉维酸钾、头孢呋辛、甲硝唑联合），根据病情调整〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","方案3（严重感染伴全身症状）：","用法：大剂量抗生素静脉给药，必要时住院治疗","方案4（拔牙术后感染）：","用法：0.9%NS 100ml + 头孢呋辛 1.5g 静滴 q12h；甲硝唑 0.5g 静滴 q8h（甲硝唑用0.5%甲硝唑注射液直接静滴）","方案5（补液支持）：","用法：高热、不能进食时静脉补液","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（浅龋、中龋、深龋（无牙髓症状））：","用法：一般无需口服药物，以充填治疗为主；对冷热敏感明显者可使用脱敏牙膏或含氟涂料","药物2（合并牙髓炎或根尖周炎急性期）：","用法：抗生素（阿莫西林0.5g tid、阿莫西林克拉维酸钾0.625g tid、头孢克肟0.2g bid、甲硝唑0.4g tid（厌氧菌感染），疗程5-7天）、止痛药（布洛芬0.2g tid或对乙酰氨基酚0.5g tid，疼痛明显时）、含漱液（复方氯己定含漱液，每日2次，保持口腔清洁）","药物3（充填治疗后）：","用法：一般无需用药，如有轻微不适可观察，疼痛明显及时复诊","药物4（拔牙术后）：","用法：抗生素（阿莫西林0.5g tid或头孢克肟0.2g bid，预防感染，3-5天）、止痛药（布洛芬0.2g prn）、含漱液（术后24小时后使用，复方氯己定含漱液，每日2次）〔调 CrCl<30 减量；青霉素过敏禁用〕","药物5（预防用药）：","用法：高龋风险患者可使用含氟牙膏、含氟漱口水、窝沟封闭、涂氟等预防措施","药物6（中医中药）：","用法：辨证使用，胃火炽盛型（清胃散加减）、肾阴亏虚型（六味地黄丸加减）、风热外侵型（银翘散加减）","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["充填治疗（主要治疗方法）：去除龋坏组织，制备洞形，消毒，用充填材料充填，恢复牙齿形态和功能；充填材料包括——银汞合金（坚固耐用，但颜色不美观，现已少用）、复合树脂（颜色美观，与牙体粘接，目前最常用，适用于前牙和后牙）、玻璃离子（含氟，可防龋，适用于乳牙、根面龋、楔状缺损，但强度较低）、嵌体（间接修复，用瓷或金属制作，精确、美观、耐用，适用于大面积龋坏）","浅龋：可采用药物治疗（涂氟、硝酸银）或预防性树脂充填，定期观察","中龋：去除龋坏组织，垫底（保护牙髓），复合树脂或玻璃离子充填","深龋：去除龋坏组织，判断牙髓状态，可复性牙髓炎先安抚治疗（氧化锌丁香油粘固粉暂封，观察1-2周，无症状后永久充填），不可复性牙髓炎需根管治疗；深龋接近牙髓时可采用间接盖髓术（氢氧化钙制剂覆盖近髓处，促进修复性牙本质形成），然后垫底充填","根管治疗：龋病进展到牙髓炎或根尖周炎时，需进行根管治疗（去除感染牙髓，根管预备、消毒、充填），然后冠修复（全冠或桩核冠，保护牙齿，防止劈裂）","牙体缺损修复：龋坏严重，牙冠大部分缺损，根管治疗后行桩核冠修复；无法保留的残冠残根需拔除，然后义齿修复（种植牙、固定桥、活动义齿）","乳牙龋病治疗：及时充填治疗，防止进展到牙髓炎和根尖周炎，避免影响恒牙发育和萌出；乳牙牙髓炎可行根管治疗或牙髓切断术；接近替换期的乳牙可拔除","窝沟封闭：预防窝沟龋的有效方法，对新萌出的恒磨牙（6岁左右第一恒磨牙，12岁左右第二恒磨牙）进行窝沟封闭，用树脂封闭窝沟，防止细菌和食物残渣进入","涂氟：定期涂氟（每3-6个月），用氟化物涂料涂于牙面，增强牙釉质抗龋能力，促进早期龋再矿化","预防：保持口腔卫生（早晚刷牙，使用含氟牙膏，采用巴氏刷牙法，每次刷牙2-3分钟；饭后漱口；使用牙线清洁牙缝）；控制糖摄入（减少甜食、含糖饮料频率，睡前不吃甜食）；定期口腔检查（每6-12个月检查一次，早期发现早期治疗）；窝沟封闭和涂氟（儿童和青少年）；使用含氟牙膏和含氟漱口水；戒烟限酒；治疗口干症（唾液减少可增加龋病风险）","随访：充填治疗后定期复查（观察充填体情况、有无继发龋、牙髓状态）；根管治疗后定期复查（观察根尖周愈合情况）；高龋风险患者每3-6个月复查一次"],"management":["口腔卫生指导：指导患者正确刷牙方法（巴氏刷牙法，刷毛与牙面呈45度角，小幅度水平颤动，每次刷牙2-3分钟，早晚各一次）；使用含氟牙膏；饭后漱口；使用牙线或牙缝刷清洁牙齿邻面（每天至少一次）；定期更换牙刷（每3个月更换一次）；儿童需家长协助刷牙（6岁以下儿童）","饮食指导：控制糖摄入频率（减少甜食、含糖饮料、零食的频率，尤其睡前不吃甜食）；减少精制碳水化合物（糖果、蛋糕、饼干、含糖饮料）；多食富含纤维的食物（蔬菜、水果、粗粮，可清洁牙面）；多食含氟食物（茶叶、海产品）；多饮水（保持口腔湿润，唾液有防龋作用）；避免酸性食物和饮料（碳酸饮料、果汁，可腐蚀牙釉质）","用药护理：按医嘱使用抗生素（合并感染时，足量足疗程，不可自行停药）、止痛药（疼痛明显时）、含漱液（每日2次，饭后使用，含漱1分钟后吐出，30分钟内不进食不饮水）；观察药物疗效和副作用（抗生素胃肠道反应、过敏，止痛药胃肠道反应）；含氟漱口水不可吞咽，儿童需在成人监督下使用","病情观察：观察牙齿疼痛变化（有无自发痛、夜间痛、咬合痛，提示牙髓炎或根尖周炎）；观察牙龈情况（有无肿胀、瘘管、出血）；观察充填体情况（有无脱落、松动、继发龋）；观察面部有无肿胀（提示间隙感染）；出现自发痛、夜间痛、咬合痛、牙龈肿胀、面部肿胀、发热及时就医","充填治疗后护理：充填治疗后2小时内避免进食（充填材料未完全固化），24小时内避免用患侧咀嚼硬物；复合树脂充填后避免食用深色食物和饮料（咖啡、茶、酱油，防止着色）；如有轻微咬合不适可观察，如咬合过高或疼痛明显及时复诊调磨；如出现自发痛、夜间痛及时复诊（可能牙髓受刺激，需根管治疗）；定期复查（观察充填体和有无继发龋）","根管治疗后护理：根管治疗期间避免用患侧咀嚼硬物（防止牙齿劈裂）；按医嘱按时复诊（根管治疗一般需2-3次完成）；治疗后如有轻微咬合痛属正常（根管充填反应），如疼痛剧烈、肿胀及时复诊；根管治疗后牙齿变脆，建议行全冠修复（保护牙齿，防止劈裂），尤其是后牙和大面积缺损牙；定期复查（观察根尖周愈合情况）","拔牙术后护理：拔牙后咬紧棉球30-60分钟止血；24小时内不漱口、不刷牙、不吸吮伤口、不用舌头舔伤口、不用患侧咀嚼；24小时后可轻柔刷牙和漱口（复方氯己定含漱液）；术后2小时可进温凉软食，避免过热、过硬、辛辣刺激食物；术后1-2天唾液中带血丝属正常，如大量出血及时复诊；术后3-5天可有轻微疼痛和肿胀，可冷敷（术后24小时内）和热敷（48小时后）；按医嘱使用抗生素和止痛药；术后1周拆线（如缝合）；术后3个月可考虑义齿修复（种植牙、固定桥、活动义齿）","儿童龋病护理：家长协助儿童刷牙（6岁以下儿童，使用儿童含氟牙膏，用量为米粒大小（3岁以下）或豌豆大小（3-6岁））；控制儿童糖摄入（减少糖果、含糖饮料、零食频率）；定期带儿童口腔检查（每3-6个月）；新萌出恒磨牙及时窝沟封闭；定期涂氟（每3-6个月）；发现儿童龋病及时治疗（乳牙龋病也需治疗，避免影响恒牙）；儿童治疗时需安抚，避免恐惧","老年人根面龋护理：老年人牙龈退缩，牙根暴露，需特别注意根面清洁；使用软毛牙刷，避免用力横刷（防止楔状缺损和牙龈损伤）；使用牙线或牙缝刷清洁牙根面；使用含氟牙膏和含氟漱口水（增强根面抗龋能力）；口干症患者多饮水，使用人工唾液，治疗口干症；定期口腔检查（每3-6个月），发现根面龋及时治疗","心理护理：安慰患者，解释龋病是常见病，可治疗，消除焦虑；牙科治疗恐惧患者给予解释和安抚，必要时使用镇静或无痛治疗；儿童患者给予鼓励和安抚，争取配合；告知患者定期口腔检查和早期治疗的重要性（早期龋治疗简单、费用低、痛苦小，晚期治疗复杂、费用高、痛苦大）","健康教育：讲解龋病的病因（细菌、食物、宿主、时间四联因素）、症状和危害（牙髓炎、根尖周炎、牙齿丧失、间隙感染）；强调口腔卫生的重要性（正确刷牙、使用牙线、含氟牙膏）；指导控制糖摄入（减少甜食频率，睡前不吃甜食）；告知定期口腔检查的重要性（每6-12个月，早期发现早期治疗）；指导窝沟封闭和涂氟的适应证（儿童和青少年新萌出恒磨牙）；告知充填治疗后注意事项和复诊要求；根管治疗后建议全冠修复；戒烟限酒；治疗口干症；出现牙痛、牙龈肿胀、面部肿胀及时就医","家庭护理：家属协助儿童和老年人刷牙；监督儿童糖摄入；定期带家人口腔检查；发现家人牙痛、牙龈肿胀及时就医；家庭共用牙膏但不共用牙刷（防止交叉感染）；保持卫生间牙刷清洁干燥，定期更换牙刷","有创操作/拔牙前评估：询问抗凝/抗血小板药（按血栓风险决定停药与桥接）、双膦酸盐/地舒单抗（颌骨坏死风险）、心内膜炎高危者按指南预防性抗菌药"],"notes":["龋病俗称蛀牙、虫牙，是在以细菌为主的多种因素影响下，牙体硬组织发生慢性进行性破坏的疾病，是人类最常见的疾病之一，被世界卫生组织列为全球三大非传染性疾病之一（心血管病、癌症、龋病），发病率高，分布广，各年龄组均可发病，儿童和青少年发病率最高","病因：四联因素理论——细菌（主要是变形链球菌，其次为乳酸杆菌、放线菌，细菌在牙面形成牙菌斑，代谢碳水化合物产酸，酸使牙体硬组织脱矿）、食物（碳水化合物，尤其是蔗糖，是细菌代谢底物，产酸致龋；糖的致龋力与摄入频率、摄入量、物理性状有关，粘性大的食物致龋力强）、宿主（牙齿的抗龋力，包括牙釉质矿化程度、牙齿形态结构（窝沟深易患龋）、唾液的质和量（唾液有缓冲、清洁、抗菌、再矿化作用，唾液减少致龋力增加）、全身健康状况）、时间（龋病的发生需要一定时间，从牙菌斑形成到脱矿、龋洞形成需要数月至数年）","发病机制：牙菌斑形成→细菌代谢碳水化合物产酸→牙釉质脱矿（钙离子、磷酸根离子析出）→牙体硬组织破坏→龋洞形成；早期龋（白垩斑）可通过氟化物促进再矿化而逆转，形成龋洞后则需充填治疗","好发部位：咬合面窝沟（最常见，窝沟深，易滞留细菌和食物残渣，不易清洁）、邻面（牙齿邻接面，牙线不易清洁，多见于中老年人牙龈退缩后）、牙颈部（牙龈缘附近，牙釉质薄，易发生楔状缺损和龋坏）、根面（老年人牙龈退缩后牙根暴露，牙骨质易龋坏，进展快）","好发牙齿：下颌第一磨牙（最常见，萌出早，窝沟深，咬合面大）、下颌第二磨牙、上颌第一磨牙、上颌第二磨牙、前磨牙、乳牙（乳磨牙最常见，乳牙牙釉质薄，矿化程度低，儿童糖摄入多，口腔卫生差，龋病进展快）","临床表现：浅龋（无症状，牙面白垩色或黑褐色斑点）、中龋（冷热酸甜敏感，刺激去除后症状消失，龋洞形成）、深龋（冷热酸甜刺激痛明显，食物嵌入痛，无自发痛，龋洞深）；龋病进展到牙髓炎时出现自发痛、夜间痛、刺激去除后疼痛持续；进展到根尖周炎时出现咬合痛、牙龈肿胀、瘘管","诊断：口腔检查（视诊、探诊、叩诊、冷热诊）+X线检查（咬翼片、根尖片，发现邻面龋和隐匿龋，评估龋坏深度）；牙髓活力测试判断牙髓状态","治疗原则：早期龋（白垩斑）可通过氟化物促进再矿化，定期观察；形成龋洞后需充填治疗（去除龋坏组织，充填修复）；深龋接近牙髓时先安抚或间接盖髓，无症状后永久充填；进展到牙髓炎或根尖周炎时需根管治疗，然后冠修复；严重龋坏无法保留者拔除，然后义齿修复","充填材料选择：复合树脂（颜色美观，与牙体粘接，适用范围广，目前最常用，前牙后牙均可）、玻璃离子（含氟，可防龋，适用于乳牙、根面龋、楔状缺损、非咬合面龋，但强度和美观性较差）、银汞合金（坚固耐用，成本低，但颜色不美观，汞污染，现已少用）、嵌体（间接修复，瓷或金合金，精确、美观、耐用，适用于大面积龋坏和邻面龋，但费用高、需两次就诊）","根管治疗：是治疗牙髓炎和根尖周炎的首选方法，包括根管预备（去除感染牙髓，扩大成形根管）、根管消毒（根管内封药，杀灭残留细菌）、根管充填（用牙胶尖和封闭剂严密充填根管，防止再感染）三个步骤；一般需2-3次完成；根管治疗后牙齿变脆，建议行全冠修复，尤其是后牙和大面积缺损牙，防止牙齿劈裂","窝沟封闭：是预防窝沟龋的有效方法，用树脂材料封闭牙齿咬合面的窝沟点隙，阻止细菌和食物残渣进入窝沟，从而预防龋病；适应证：新萌出的恒磨牙（6岁左右第一恒磨牙，12岁左右第二恒磨牙）、窝沟深的牙齿、高龋风险儿童；封闭后需定期复查，如封闭剂脱落及时重新封闭","涂氟：用氟化物涂料（氟化钠、氟化亚锡、氟保护漆）涂于牙面，增强牙釉质抗龋能力，促进早期龋再矿化；适用于儿童和青少年、高龋风险患者、早期龋（白垩斑）；一般每3-6个月涂氟一次","预防：保持口腔卫生（正确刷牙、使用牙线、含氟牙膏）是预防龋病的关键；控制糖摄入（减少甜食频率，睡前不吃甜食）；定期口腔检查（每6-12个月，早期发现早期治疗）；窝沟封闭和涂氟（儿童和青少年）；使用含氟牙膏和含氟漱口水；戒烟限酒；治疗口干症；多饮水，保持口腔湿润","预后：早期龋（白垩斑）通过氟化物和口腔卫生改善可逆转；形成龋洞后充填治疗效果好，可恢复牙齿形态和功能；龋病进展到牙髓炎或根尖周炎时，根管治疗后冠修复可保留牙齿；严重龋坏无法保留者需拔除，然后义齿修复；龋病是可预防可治疗的疾病，关键是早期发现早期治疗和长期预防","我国现状：我国龋病患病率高，尤其是儿童和青少年，5岁儿童乳牙龋患率约70%，12岁儿童恒牙龋患率约35%，成年人龋患率约50%，老年人根面龋患病率高；但我国居民口腔健康意识薄弱，就诊率低，很多患者龋病进展到牙髓炎或根尖周炎才就诊，治疗复杂、费用高、痛苦大；需加强口腔健康教育，推广正确刷牙、使用牙线、含氟牙膏、窝沟封闭、涂氟、定期口腔检查，提高龋病防治水平"],"emergency":["出现自发痛、夜间痛、疼痛剧烈、刺激去除后疼痛持续（急性牙髓炎，及时就医根管治疗或开髓引流止痛）","出现咬合痛、牙龈肿胀、瘘管、面部肿胀、发热（急性根尖周炎或颌面部间隙感染，及时就医抗生素+根管治疗或切开引流）","出现面部明显肿胀、张口受限、吞咽困难、呼吸困难、高热（严重颌面部间隙感染，可能危及生命，立即急诊，大剂量抗生素+切开引流+支持治疗）","出现牙齿外伤后牙体缺损、松动、脱落（牙外伤，及时就医，脱落牙应保存在生理盐水或牛奶中，30分钟内再植成功率高）","充填治疗后出现剧烈自发痛、夜间痛（牙髓受刺激或急性牙髓炎，及时复诊根管治疗）","根管治疗期间出现面部肿胀、发热（急性根尖周炎或间隙感染，及时复诊抗生素+根管引流）","拔牙术后出现大量出血、出血不止（拔牙后出血，及时复诊压迫止血或缝合）","拔牙术后3-4天出现剧烈疼痛、口臭、拔牙创空虚（干槽症，及时复诊清创换药）","儿童龋病出现面部肿胀、发热、精神差（严重感染，及时就医）","老年人根面龋出现牙齿折断、松动、疼痛（及时就医评估能否保留）"],"pinyin":"qubing","icd10":"K02.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态、面容","口腔检查：张口度（正常3指/受限）、张口型、口腔黏膜（溃疡/糜烂/白斑/红斑/肿物/色素沉着）、牙龈（红肿/出血/萎缩/溢脓/瘘管）、牙齿（龋坏/缺损/缺失/松动/叩痛/冷热敏感/咬合痛，记录牙位）、牙周（牙周袋深度/附着丧失/牙龈退缩/牙石）、咬合（牙列/覆合覆盖/错合畸形）、舌（大小/形态/颜色/舌苔/乳头/溃疡/肿物/运动）、腭（硬腭/软腭/悬雍垂/充血/溃疡/肿物）、口底（肿物/涎石）、唾液腺（腮腺/下颌下腺/舌下腺：大小/压痛/导管口分泌物）","颌面部：面部对称/肿胀/畸形/瘢痕、颞下颌关节（弹响/压痛/开口度/开口型）、颌骨（压痛/膨隆/异常动度）、淋巴结（颈部/颌下/颏下肿大）","其他：口干/口臭、吞咽/发音功能"],"lab_tests":["口腔专科检查（视诊、探诊、叩诊、冷热诊及牙髓电活力测试）：评估龋坏深度、范围及牙髓状态，初诊即查","根尖片（X线牙片，平行投照）：显示邻面龋、龋坏深度及与髓腔关系、充填体边缘继发龋，治疗前及术后复查各一次","咬合翼片：用于后牙邻面早期龋及继发龋检测，青少年龋病普查及高危人群定期筛查时拍摄","全景片（曲面断层片）：多发龋、广泛龋损或需同时评估全口牙列及邻牙状况时，全口整体评估","锥形束CT（CBCT）：深龋近髓、疑牙髓或根尖周病变需三维评估时，明确龋坏与髓腔、根管关系","龋活性检测（DIAGNOdent激光龋齿检测仪、菌斑指数）：儿童及龋病高危人群风险评估，辅助制定预防方案"],"nursing":["病情观察：治疗后观察有无持续性疼痛、咬合痛或自发痛，警惕牙髓炎及充填体过高，发现异常及时报告医师调改","口腔护理：每日早晚刷牙、饭后漱口，使用含氟牙膏，配合牙线或牙间隙刷清洁邻面，保持口腔清洁预防继发龋","术后护理：充填术后24小时内避免患侧咀嚼硬物，告知树脂充填体色泽变化属正常现象，观察充填体有无脱落、缺损","防感染护理：深龋行间接盖髓或安抚治疗后按医嘱用药，观察有无面部肿胀、发热等感染征象，嘱勿用患侧咀嚼过冷过热食物","健康宣教：讲解龋病病因及防治知识，指导每6～12个月定期口腔检查，高危人群适当缩短复查间隔"],"diet":["忌口：限制高糖食物及含糖饮料，避免黏性甜食（奶糖、软糕）长时间粘附牙面，睡前及两餐之间禁食甜食","软食流质：治疗当日进食温凉软食，避免过烫、过硬及辛辣刺激食物，咀嚼时偏向健侧","口腔卫生：进食后及时漱口或刷牙，使用含氟牙膏，配合牙线清洁牙间隙，保持窝沟及充填体边缘清洁","营养支持：均衡饮食，适当增加富含钙、磷及维生素D的食物（奶制品、豆制品、绿叶蔬菜），促进牙体再矿化","特殊指导：儿童及老年患者避免啃咬硬物、注意细嚼慢咽；按医嘱完成涂氟或窝沟封闭，并维持相应饮食间隔（涂氟后30分钟内不进食、不饮水）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":408},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"615168b70069817540991946b2dcd5f60ce73c6535cd8591b694d68b10c149a5","pinyin":"qubing","initials":"qb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","浅龋：病变局限于牙釉质或牙骨质，一般无自觉症状，检查时可见牙面有白垩色或黑褐色斑点或斑片，表面粗糙，探针检查有粗糙感或能钩住探针尖端\\n中龋：病变进展到牙本质浅层，患者对冷、热、酸、甜刺激敏感，尤其对冷刺激明显，刺激去除后症状立即消失，无自发痛；检查可见龋洞形成，洞内有软化牙本质和食物残渣\\n深龋：病变进展到牙本质深层，接近牙髓，患者对冷、热、酸、甜刺激明显疼痛，食物嵌入龋洞时疼痛，刺激去除后症状消失，无自发痛；检查可见较深龋洞，探诊敏感，但无穿髓孔\\n龋病好发部位：咬合面窝沟（最常见）、邻面（牙齿邻接面）、牙颈部（牙龈缘附近）、根面（老年人牙龈退缩后牙根暴露）\\n龋病好发牙齿：下颌第一磨牙（最常见）、下颌第二磨牙、上颌第一磨牙、上颌第二磨牙、前磨牙、乳牙（乳磨牙最常见）\\n并发症：牙髓炎（龋病进展到牙髓，引起牙髓炎症，出现自发痛、夜间痛）、根尖周炎（牙髓坏死，感染扩散到根尖周组织，出现咬合痛、牙龈肿胀、瘘管）、牙体缺损（龋坏严重，牙冠大部分缺损，形成残冠、残根）、牙齿丧失（严重龋坏无法保留，需拔除）、颌面部间隙感染（根尖周炎扩散，引起面部肿胀、疼痛、发热）、全身感染（严重感染可引起败血症，罕见但严重）\\n儿童龋病：乳牙龋病进展快，范围广，可影响恒牙发育和萌出，引起牙列不齐、咬合紊乱，影响咀嚼和营养吸收，儿童龋病需及时治疗\\n老年人根面龋：牙龈退缩，牙根暴露，根面牙骨质龋坏，进展快，可引起牙本质过敏、牙髓炎，老年人根面龋需及时治疗",60],["摘要","俗称蛀牙、虫牙，是在以细菌为主的多种因素影响下，牙体硬组织发生慢性进行性破坏的疾病，表现为牙齿颜色改变、缺损、疼痛，是人类最常见的疾病之一，发病率高，分布广。",30],["疾病编码","K02.9",30],["原首字母","qubing",60]]},{"id":"orders-add7819f4fc9bdd9e95b","key":"v1-c9ccc21dfe2a3058|orders-add7819f4fc9bdd9e95b","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"牙髓炎","category":"口腔","raw":{"name":"牙髓炎","category":"口腔","summary":"牙髓组织的炎症性疾病，多由龋病发展而来，也可由牙外伤、牙体手术、牙周病逆行感染引起，分为可复性牙髓炎和不可复性牙髓炎，表现为牙齿疼痛，急性牙髓炎疼痛剧烈，是口腔科急症之一。","symptoms":["可复性牙髓炎：牙齿对冷、热刺激敏感，尤其对冷刺激明显，刺激去除后疼痛立即消失，无自发痛；检查可见深龋或深的牙体缺损，探诊敏感，无穿髓孔，叩诊阴性，牙髓活力测试敏感","急性牙髓炎（不可复性）：剧烈疼痛，特点为——自发痛（无任何刺激时突然发生疼痛）、阵发性痛（疼痛持续一段时间后缓解，然后再次发作，早期疼痛持续时间短、间隔时间长，晚期疼痛持续时间长、间隔时间短，甚至持续性疼痛）、夜间痛（夜间疼痛加重，平卧时疼痛明显，常因疼痛从睡眠中惊醒）、温度刺激加剧疼痛（冷、热刺激可诱发或加重疼痛，早期冷刺激痛明显，晚期热刺激痛明显、冷刺激可缓解疼痛（化脓性牙髓炎））、疼痛不能定位（疼痛可放射至同侧头面部、耳部、颞部，患者常不能明确指出患牙，只能指出疼痛侧）、晚期可出现咬合痛（炎症波及根尖周组织）","慢性牙髓炎（不可复性）：一般无剧烈自发痛，可有轻微自发痛或隐痛、钝痛，长期冷热刺激痛，刺激去除后疼痛持续一段时间，可有咬合不适或轻微咬合痛；检查可见深龋或牙体缺损，洞内可有息肉（慢性增生性牙髓炎，多见于青少年，牙髓息肉从穿髓孔长出，呈红色、质软、易出血），探诊敏感，可有穿髓孔，叩诊可有轻度不适，牙髓活力测试迟钝或敏感","逆行性牙髓炎：由牙周病引起，细菌经牙周袋从根尖孔或侧支根管逆行感染牙髓；表现为牙周病症状（牙龈红肿、牙周袋、牙齿松动、咬合痛）+牙髓炎症状（自发痛、冷热刺激痛、夜间痛）；检查可见深牙周袋，牙齿松动，X线可见牙槽骨吸收","牙髓坏死：牙髓炎发展到晚期，牙髓组织坏死；一般无自觉症状，或有牙冠变色（暗黄色或灰色，无光泽）；检查可见牙体缺损，探诊无反应（穿髓孔处无探痛），牙髓活力测试无反应，叩诊可阴性或轻度不适；X线可见根尖周可无明显异常或有根尖周阴影","并发症：根尖周炎（牙髓炎发展到晚期，牙髓坏死，感染扩散到根尖周组织，出现咬合痛、牙龈肿胀、瘘管）、根尖周脓肿（急性根尖周炎发展，形成脓肿，出现剧烈咬合痛、牙龈肿胀、面部肿胀、发热）、颌面部间隙感染（根尖周脓肿扩散，引起面部肿胀、张口受限、吞咽困难、高热，严重者可危及生命）、牙体缺损（龋坏严重，牙冠大部分缺损）、牙齿丧失（严重龋坏和根尖周病变无法保留，需拔除）","好发牙齿：下颌第一磨牙（最常见，龋病好发牙，牙髓炎也最常见）、下颌第二磨牙、上颌第一磨牙、上颌第二磨牙、前磨牙","诱因：龋病（最常见，深龋发展到牙髓）、牙外伤（牙齿撞击、折断，暴露牙髓）、牙体手术（备洞时意外穿髓、充填材料刺激）、楔状缺损（深的楔状缺损接近牙髓）、磨损（牙齿过度磨损，牙本质暴露，接近牙髓）、牙周病（逆行性牙髓炎）、温度刺激（突然的冷热刺激，尤其是深龋时）"],"diagnosis":["典型症状（牙齿疼痛，急性牙髓炎有自发痛、夜间痛、温度刺激痛、疼痛不能定位）+口腔检查+X线检查","详细询问病史：疼痛性质（自发痛/激发痛、阵发性/持续性、锐痛/钝痛）、疼痛时间（白天/夜间、持续时间、间隔时间）、诱发因素（冷热刺激、咬合、自发）、疼痛部位（能否定位、放射部位）、疼痛程度（轻度/中度/重度，是否影响睡眠和进食）、既往史（龋病、牙外伤、牙体治疗、牙周病）","口腔检查：视诊（观察牙体有无龋洞、缺损、变色、充填物）、探诊（用探针检查龋洞深度、有无穿髓孔、探痛程度，可复性牙髓炎探诊敏感无穿髓孔，不可复性牙髓炎可有穿髓孔、探痛剧烈）、叩诊（轻叩牙齿，有无叩痛，牙髓炎早期叩诊阴性，晚期波及根尖周时叩痛阳性）、冷热诊（用冷刺激（冰棒、冷水）或热刺激（热牙胶、热水）检查牙髓反应，可复性牙髓炎刺激痛、去除后立即消失，急性牙髓炎刺激痛加剧、去除后疼痛持续，牙髓坏死无反应）、牙周检查（牙周袋深度、牙龈情况、牙齿松动度，排除逆行性牙髓炎）","X线检查（根尖片、咬翼片，可发现龋坏深度、是否接近牙髓或穿髓、根尖周情况、牙槽骨吸收情况，是诊断和治疗的重要依据）","牙髓活力测试（冷测、热测、电活力测试，判断牙髓状态，可复性牙髓炎敏感、不可复性牙髓炎敏感或迟钝、牙髓坏死无反应）","分类诊断：可复性牙髓炎（无自发痛，冷热刺激痛、去除后立即消失，无穿髓孔，叩诊阴性）、急性牙髓炎（自发痛、夜间痛、温度刺激痛、疼痛不能定位，可有穿髓孔，探痛剧烈）、慢性牙髓炎（轻微自发痛或隐痛，长期冷热刺激痛、去除后持续，可有穿髓孔或牙髓息肉，叩诊轻度不适）、逆行性牙髓炎（有牙周病，深牙周袋，牙齿松动，牙髓炎症状）、牙髓坏死（无自觉症状，牙冠变色，牙髓活力无反应）","排除：三叉神经痛（电击样疼痛，有扳机点，夜间不痛，温度刺激不诱发，无牙体疾病）、龈乳头炎（牙龈乳头红肿疼痛，持续性胀痛，温度刺激敏感但无自发痛，可定位，检查可见龈乳头红肿、有食物嵌塞）、急性上颌窦炎（面部胀痛、头痛、鼻塞、流脓涕，多颗上颌后牙疼痛，温度刺激不诱发，检查可见上颌窦区压痛，无牙体疾病）、干槽症（拔牙后3-4天出现剧烈疼痛，拔牙创空虚，有臭味，有拔牙史）、牙本质过敏（冷热酸甜敏感，无自发痛，无龋洞，牙本质暴露）、根尖周炎（咬合痛为主，可有牙龈肿胀、瘘管，叩痛明显，牙髓活力多无反应）"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般无需静脉输液；牙髓炎以根管治疗为主，疼痛明显时口服布洛芬 0.3g 口服（必要时）","方案2：","用法：急性牙髓炎一般无需静脉抗生素，以根管治疗或开髓引流止痛为主","方案3（合并急性根尖周脓肿或颌面部间隙感染）：","用法：0.9%NS 100ml + 抗生素 ivgtt qd（阿莫西林克拉维酸钾1.2g q8h、头孢呋辛1.5g q8h、头孢曲松2g qd，联合甲硝唑0.5g q8h抗厌氧菌），根据病情和药敏调整〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","方案4：","用法：严重感染伴全身症状（高热、寒战、面部肿胀明显、张口受限、吞咽困难）：大剂量广谱抗生素静脉给药，必要时住院治疗，切开引流，支持治疗","方案5（拔牙术后感染）：","用法：0.9%NS 100ml + 头孢呋辛 1.5g 静滴 q12h；甲硝唑 0.5g 静滴 q8h（甲硝唑用0.5%甲硝唑注射液直接静滴）","方案6（补液支持）：","用法：高热、不能进食、脱水时静脉补液，维持水电解质平衡","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（可复性牙髓炎）：","用法：一般无需口服药物，以安抚治疗或间接盖髓后充填为主；疼痛明显时可短期使用止痛药（布洛芬0.2g prn或对乙酰氨基酚0.5g prn）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物2（急性牙髓炎）：","用法：止痛药（布洛芬0.2g tid或对乙酰氨基酚0.5g tid，疼痛剧烈时可短期使用，缓解疼痛）、抗生素（一般无需抗生素，如合并根尖周炎或全身症状时使用，阿莫西林0.5g tid、阿莫西林克拉维酸钾0.625g tid、头孢克肟0.2g bid、甲硝唑0.4g tid（厌氧菌感染），疗程5-7天）、含漱液（复方氯己定含漱液，每日2次，保持口腔清洁）；注意：止痛药和抗生素只能暂时缓解症状，不能根治，必须进行根管治疗","药物3（慢性牙髓炎）：","用法：一般无需口服药物，以根管治疗为主；如有急性发作或疼痛明显，可使用止痛药和抗生素（同急性牙髓炎）","药物4（逆行性牙髓炎）：","用法：抗生素（阿莫西林+甲硝唑，或头孢类+甲硝唑，控制牙周和牙髓感染）、止痛药、含漱液；同时进行牙周治疗（洁治、刮治、牙周袋内上药）和根管治疗〔调 CrCl<30 减量；青霉素过敏禁用〕","药物5（牙髓坏死）：","用法：一般无需口服药物，以根管治疗为主；如合并根尖周炎，可使用抗生素和止痛药","药物6（根管治疗期间）：","用法：按医嘱使用抗生素（如根管感染较重或有根尖周病变时）、止痛药（治疗后如有轻微疼痛可使用）、含漱液（保持口腔清洁）","药物7（拔牙术后）：","用法：抗生素（阿莫西林0.5g tid或头孢克肟0.2g bid，预防感染，3-5天）、止痛药（布洛芬0.2g prn）、含漱液（术后24小时后使用，复方氯己定含漱液，每日2次）〔调 CrCl<30 减量；青霉素过敏禁用〕","药物8（中医中药）：","用法：辨证使用，胃火炽盛型（清胃散加减，清胃泻火）、风热外侵型（银翘散加减，疏风清热）、阴虚火旺型（知柏地黄丸加减，滋阴降火）、气血亏虚型（八珍汤加减，补益气血）；中成药可选用牛黄解毒片、黄连上清丸、知柏地黄丸等","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["可复性牙髓炎：去除龋坏组织，安抚治疗（氧化锌丁香油粘固粉暂封，观察1-2周，无症状后永久充填）或间接盖髓术（氢氧化钙制剂覆盖近髓处，促进修复性牙本质形成，然后垫底充填）；如发展为不可复性牙髓炎，需根管治疗","急性牙髓炎：急诊处理——开髓引流（局麻下打开髓腔，释放压力，引流脓液，可迅速缓解疼痛，是急性牙髓炎最有效的止痛方法）；如无法立即根管治疗，可开髓后封失活剂（多聚甲醛失活剂，使牙髓失活，1-2周后复诊根管治疗）；根管治疗（急性炎症缓解后进行，去除感染牙髓，根管预备、消毒、充填，是根治牙髓炎的方法）；止痛药（布洛芬 0.3-0.4g 口服 q6-8h 或对乙酰氨基酚 0.5g 口服 q6h）和抗生素（阿莫西林 0.5g 口服 tid+甲硝唑 0.4g 口服 tid，疗程5-7天）辅助（缓解症状，不能根治）；根管治疗后建议全冠修复（保护牙齿，防止劈裂）","慢性牙髓炎：根管治疗（首选，去除感染牙髓，根管预备、消毒、充填）；根管治疗后全冠修复（保护牙齿）；如牙冠大面积缺损，根管治疗后行桩核冠修复；无法保留的严重龋坏牙需拔除，然后义齿修复","逆行性牙髓炎：根管治疗（去除感染牙髓）+牙周治疗（洁治、刮治、根面平整、牙周袋内上药如甲硝唑凝胶，必要时牙周手术）；如牙周病变严重、牙齿松动明显、预后差，可考虑拔除","牙髓坏死：根管治疗（去除坏死牙髓，根管预备、消毒、充填）；根管治疗后全冠修复；如合并根尖周病变，根管治疗后定期复查观察根尖周愈合情况","根管治疗步骤：第一步（开髓、拔髓、根管预备、根管消毒封药如氢氧化钙糊剂，如有急性炎症先开髓引流）；第二步（根管充填，用牙胶尖和封闭剂严密充填根管）；一般需2-3次完成，每次间隔1-2周；根管治疗后建议全冠修复（尤其是后牙和大面积缺损牙，防止牙齿劈裂）","盖髓术：直接盖髓术（适用于意外穿髓、穿髓孔小、牙髓无明显炎症的年轻恒牙，用氢氧化钙制剂直接覆盖穿髓孔，促进修复性牙本质形成，然后充填）；间接盖髓术（适用于深龋接近牙髓、可复性牙髓炎，用氢氧化钙制剂覆盖近髓处，促进修复性牙本质形成，然后垫底充填）","牙髓切断术：适用于年轻恒牙牙髓炎局限于冠髓、根髓正常者，切除冠髓，保留根髓，用氢氧化钙制剂覆盖根管口，促进牙本质桥形成，然后充填；如根髓也有炎症，需根管治疗","拔牙：严重龋坏无法保留的残冠残根、牙周病变严重牙齿松动明显、根管治疗无效或预后差的牙齿，需拔除，然后义齿修复（种植牙、固定桥、活动义齿）；拔牙用阿替卡因或利多卡因局麻，术后疼痛明显者布洛芬 0.3-0.4g 口服 q6-8h","急性根尖周脓肿：开髓引流（根管内引流）+切开引流（脓肿形成后，牙龈处切开排脓）+抗生素（阿莫西林 0.5g 口服 tid+甲硝唑 0.4g 口服 tid，或头孢类如头孢氨苄 0.5g 口服 tid+甲硝唑）+止痛药（布洛芬 0.3-0.4g 口服 q6-8h）；急性炎症缓解后根管治疗","颌面部间隙感染：大剂量抗生素静脉给药（广谱如头孢曲松 2g 静滴 qd+抗厌氧菌甲硝唑 0.5g 静滴 q8h）+切开引流（脓肿形成后及时切开）+支持治疗（补液、营养支持、退热）+必要时住院治疗；感染控制后处理病灶牙（根管治疗或拔除）","预防：保持口腔卫生（正确刷牙、使用牙线、含氟牙膏）；控制糖摄入（减少甜食频率，睡前不吃甜食）；定期口腔检查（每6-12个月，早期发现龋病，早期治疗，防止发展到牙髓炎）；及时治疗龋病（深龋及时充填，避免发展到牙髓炎）；避免牙外伤（运动时戴护齿器，避免咬硬物）；牙体手术时注意保护牙髓（备洞时避免意外穿髓，深龋垫底保护牙髓）；治疗牙周病（防止逆行性牙髓炎）","随访：根管治疗后定期复查（术后3个月、6个月、1年复查，拍摄X线观察根尖周愈合情况）；充填治疗后定期复查（观察充填体和有无继发龋）；根管治疗后如出现疼痛、肿胀及时复诊；高龋风险患者每3-6个月口腔检查"],"management":["疼痛护理：急性牙髓炎疼痛剧烈，给予心理安慰，解释疼痛原因和治疗方法，消除焦虑；指导患者避免冷热刺激（避免冷热食物和饮料，用温水漱口）；避免用患侧咀嚼；按医嘱使用止痛药（布洛芬或对乙酰氨基酚），观察止痛效果；如疼痛剧烈、止痛药无效，及时复诊开髓引流止痛","口腔卫生指导：指导患者正确刷牙方法（巴氏刷牙法，每次2-3分钟，早晚各一次）；使用含氟牙膏；饭后漱口；使用牙线或牙缝刷清洁牙齿邻面；根管治疗期间患牙可轻柔刷牙，避免用力刷治疗部位；定期更换牙刷（每3个月）","饮食指导：急性牙髓炎期间避免冷热刺激、辛辣刺激、过硬食物，用健侧咀嚼，进温凉软食；根管治疗期间避免用患侧咀嚼硬物（防止牙齿劈裂和暂封物脱落）；根管治疗后全冠修复前避免用患侧咀嚼硬物；控制糖摄入（减少甜食、含糖饮料频率，睡前不吃甜食）；多饮水，保持口腔湿润","用药护理：按医嘱使用止痛药（疼痛明显时，不可长期大量使用，注意胃肠道副作用）、抗生素（合并感染时，足量足疗程，不可自行停药，注意过敏反应）、含漱液（每日2次，饭后使用，含漱1分钟后吐出，30分钟内不进食不饮水）；观察药物疗效和副作用；告知患者止痛药和抗生素只能暂时缓解症状，不能根治牙髓炎，必须进行根管治疗","根管治疗期间护理：按医嘱按时复诊（根管治疗一般需2-3次，每次间隔1-2周，不可延误复诊，以免封药时间过长或感染加重）；治疗后如有轻微疼痛、肿胀属正常反应（根管预备刺激、封药反应），一般1-3天缓解，如疼痛剧烈、肿胀明显、发热及时复诊；暂封物脱落及时复诊（避免食物残渣进入根管引起感染）；治疗期间避免用患侧咀嚼硬物；保持口腔卫生","根管治疗后护理：根管治疗后牙齿变脆（失去牙髓营养供应），建议行全冠修复（尤其是后牙和大面积缺损牙，保护牙齿，防止劈裂）；全冠修复前避免用患侧咀嚼硬物；根管治疗后定期复查（3个月、6个月、1年，拍摄X线观察根尖周愈合情况）；如出现疼痛、肿胀、瘘管及时复诊（可能根管治疗失败，需重新治疗或根尖手术）","拔牙术后护理：拔牙后咬紧棉球30-60分钟止血；24小时内不漱口、不刷牙、不吸吮伤口、不用舌头舔伤口、不用患侧咀嚼；24小时后可轻柔刷牙和漱口（复方氯己定含漱液）；术后2小时可进温凉软食，避免过热、过硬、辛辣刺激食物；术后1-2天唾液中带血丝属正常，如大量出血及时复诊；术后3-5天可有轻微疼痛和肿胀，可冷敷（术后24小时内）和热敷（48小时后）；按医嘱使用抗生素和止痛药；术后1周拆线（如缝合）；术后3个月可考虑义齿修复","急性根尖周脓肿护理：观察疼痛、肿胀、体温变化；如面部肿胀明显、张口受限、吞咽困难、高热，提示严重间隙感染，立即就医；按医嘱使用抗生素和止痛药；脓肿切开后保持引流通畅，按医嘱换药；进温凉流质或半流质饮食，多饮水；注意休息，避免劳累","儿童牙髓炎护理：儿童乳牙牙髓炎进展快，需及时治疗（避免影响恒牙发育和萌出）；儿童治疗时需安抚，争取配合，必要时使用镇静或全麻下治疗；乳牙牙髓炎可行根管治疗或牙髓切断术（保留根髓，促进牙根继续发育）；接近替换期的乳牙可拔除；家长协助儿童口腔卫生（6岁以下儿童家长协助刷牙）；控制儿童糖摄入；定期带儿童口腔检查（每3-6个月）","老年人牙髓炎护理：老年人多有根面龋和牙周病，牙髓炎可为龋源性或逆行性；老年人常合并全身疾病（高血压、糖尿病、心脏病），治疗前需评估全身情况和用药情况（如抗凝药、双膦酸盐）；根管治疗是首选，如全身情况差不能耐受根管治疗，可考虑拔除；老年人根管钙化、狭窄多见，治疗难度大，需有经验医生操作；定期口腔检查，及时治疗根面龋和牙周病","心理护理：安慰患者，解释牙髓炎的病因、症状和治疗方法，消除焦虑和恐惧；牙科治疗恐惧患者给予解释和安抚，必要时使用镇静或无痛治疗；急性牙髓炎疼痛剧烈患者给予心理支持，告知开髓引流可迅速止痛，鼓励及时治疗；告知患者根管治疗的必要性和过程，争取患者配合；告知患者止痛药和抗生素不能根治，必须根管治疗，避免延误治疗","健康教育：讲解牙髓炎的病因（龋病最常见，其次牙外伤、牙体手术、牙周病）、症状（急性牙髓炎自发痛、夜间痛、温度刺激痛、疼痛不能定位）和危害（根尖周炎、间隙感染、牙齿丧失）；强调及时治疗龋病的重要性（深龋及时充填，避免发展到牙髓炎）；告知急性牙髓炎是口腔科急症，疼痛剧烈，应及时就医开髓引流止痛，不要自行服用止痛药拖延；讲解根管治疗的必要性、过程和术后注意事项（根管治疗后建议全冠修复）；指导口腔卫生（正确刷牙、使用牙线、含氟牙膏）；指导控制糖摄入；告知定期口腔检查的重要性（每6-12个月，早期发现早期治疗）；出现牙痛、牙龈肿胀、面部肿胀、发热及时就医；根管治疗后定期复查；戒烟限酒","家庭护理：家属协助儿童和老年人刷牙；监督儿童糖摄入；发现家人牙痛、面部肿胀、发热及时陪同就医；急性牙髓炎疼痛剧烈时安抚患者，协助及时就诊；根管治疗期间提醒患者按时复诊；家庭共用牙膏但不共用牙刷；保持卫生间牙刷清洁干燥，定期更换牙刷"],"notes":["牙髓炎是牙髓组织的炎症性疾病，多由龋病发展而来，也可由牙外伤、牙体手术、牙周病逆行感染引起，是口腔科常见病和急症之一，急性牙髓炎疼痛剧烈，严重影响患者生活质量","牙髓组织：位于牙齿内部的牙髓腔内，包含神经、血管、淋巴管和结缔组织，主要功能是形成牙本质、营养牙体组织、感觉和防御；牙髓被坚硬的牙本质壁包围，牙髓腔是一个密闭的空间，炎症时牙髓组织水肿、压力升高，压迫神经引起剧烈疼痛，且牙髓缺乏侧支循环，炎症不易恢复，容易发展为坏死","病因：龋病（最常见，深龋时细菌及其毒素通过牙本质小管进入牙髓，引起炎症，穿髓后直接感染牙髓）、牙外伤（牙齿撞击、折断，暴露牙髓，细菌感染）、牙体手术（备洞时意外穿髓、充填材料刺激、切割产热过多）、楔状缺损和磨损（深的楔状缺损或过度磨损接近牙髓，细菌通过牙本质小管感染牙髓）、牙周病（深牙周袋，细菌经根尖孔或侧支根管逆行感染牙髓，引起逆行性牙髓炎）、温度刺激（突然的冷热刺激，尤其是深龋时，可诱发牙髓炎）、化学刺激（充填材料、酸蚀剂、消毒剂刺激牙髓）","分类：可复性牙髓炎（牙髓充血，炎症较轻，去除刺激后牙髓可恢复正常，无自发痛，冷热刺激痛、去除后立即消失）、不可复性牙髓炎（牙髓炎症较重，不可恢复，需根管治疗，包括急性牙髓炎、慢性牙髓炎、逆行性牙髓炎）、牙髓坏死（牙髓炎发展到晚期，牙髓组织坏死，无自觉症状，牙冠变色）","急性牙髓炎疼痛特点：自发痛（无刺激时突然疼痛）、阵发性痛（疼痛持续一段时间缓解，然后再次发作）、夜间痛（夜间平卧时疼痛加重，常痛醒）、温度刺激加剧疼痛（冷热刺激诱发或加重，早期冷痛明显，晚期化脓性牙髓炎热痛明显、冷可缓解）、疼痛不能定位（疼痛放射至同侧头面部，患者不能明确指出患牙，只能指出疼痛侧，这是急性牙髓炎的重要特征，也是与根尖周炎和龈乳头炎的鉴别要点）","发病机制：牙髓感染→炎症反应→血管扩张、通透性增加→牙髓组织水肿→牙髓腔内压力升高→压迫神经末梢→剧烈疼痛；压力持续升高→静脉回流受阻→动脉供血障碍→牙髓缺血、缺氧→牙髓坏死；牙髓坏死后压力降低，疼痛可暂时缓解，但感染扩散到根尖周组织引起根尖周炎","诊断要点：典型症状（急性牙髓炎自发痛、夜间痛、温度刺激痛、疼痛不能定位）+口腔检查（深龋或牙体缺损、穿髓孔、探痛剧烈、冷热诊刺激痛加剧、去除后持续）+X线检查（龋坏深度、根尖周情况）；注意与三叉神经痛、龈乳头炎、急性上颌窦炎、根尖周炎鉴别","治疗原则：可复性牙髓炎——安抚治疗或间接盖髓后充填，保存活髓；不可复性牙髓炎——根管治疗（去除感染牙髓，保存牙齿），是根治方法；急性牙髓炎——首先开髓引流止痛（最有效的止痛方法），然后根管治疗；牙髓坏死——根管治疗；逆行性牙髓炎——根管治疗+牙周治疗；无法保留的牙齿拔除；根管治疗后建议全冠修复","开髓引流：是急性牙髓炎最有效的止痛方法，局麻下用牙钻打开髓腔，释放牙髓腔内压力，引流脓液，疼痛可迅速缓解；如无法立即进行完善根管治疗，可开髓后封失活剂（多聚甲醛失活剂，使牙髓失活，1-2周后复诊根管治疗），或封消毒药物（樟脑酚、甲醛甲酚，注意甲醛甲酚刺激性强，现已少用）","根管治疗：是治疗牙髓炎和根尖周炎的首选和根治方法，包括根管预备（用根管锉去除感染牙髓和感染的牙本质壁，扩大成形根管）、根管消毒（根管内封消毒药物，杀灭残留细菌，常用氢氧化钙糊剂）、根管充填（用牙胶尖和封闭剂严密充填根管，防止再感染）三个步骤；一般需2-3次完成，每次间隔1-2周；根管治疗成功率约85-95%；根管治疗后牙齿变脆，建议行全冠修复，尤其是后牙和大面积缺损牙，防止牙齿劈裂","盖髓术和牙髓切断术：是保存活髓的治疗方法，适用于年轻恒牙和牙髓炎症较轻者；直接盖髓术适用于意外穿髓、穿髓孔小、牙髓无明显炎症；间接盖髓术适用于深龋接近牙髓、可复性牙髓炎；牙髓切断术适用于年轻恒牙冠髓炎、根髓正常；如活髓保存失败，需改行根管治疗","预后：可复性牙髓炎经安抚或盖髓治疗后牙髓可恢复，预后好；急性牙髓炎和慢性牙髓炎经根管治疗后可保留牙齿，预后好，但根管治疗后牙齿变脆，需全冠修复；牙髓坏死合并根尖周炎经根管治疗后根尖周病变多可愈合；严重龋坏和根尖周病变无法保留者需拔除；牙髓炎如不及时治疗，可发展为根尖周炎、根尖周脓肿、颌面部间隙感染，严重者可危及生命；关键是早期诊断早期治疗","预防：保持口腔卫生（正确刷牙、使用牙线、含氟牙膏）是预防龋病和牙髓炎的关键；控制糖摄入（减少甜食频率，睡前不吃甜食）；定期口腔检查（每6-12个月，早期发现龋病，早期充填治疗，防止发展到牙髓炎）；及时治疗深龋（深龋及时充填或安抚治疗，避免穿髓和牙髓炎）；避免牙外伤（运动时戴护齿器，避免咬硬物）；牙体手术时注意保护牙髓（备洞时冷却、避免意外穿髓，深龋垫底保护牙髓）；治疗牙周病（防止逆行性牙髓炎）；出现牙痛及时就医，不要自行服用止痛药拖延","我国现状：我国牙髓炎患病率高，主要由龋病发展而来，但很多患者对牙髓炎认识不足，牙痛时自行服用止痛药拖延，导致发展为根尖周炎、间隙感染，治疗复杂、费用高、痛苦大；根管治疗技术已普及，但基层医疗机构根管治疗质量参差不齐；需加强口腔健康教育，推广定期口腔检查和早期治疗，提高根管治疗质量"],"emergency":["出现剧烈自发痛、夜间痛、疼痛不能忍受、止痛药无效（急性牙髓炎急性发作，及时就医开髓引流止痛）","出现面部明显肿胀、张口受限、吞咽困难、呼吸困难、高热、寒战（严重颌面部间隙感染，可能危及生命，立即急诊，大剂量抗生素+切开引流+支持治疗）","出现牙龈肿胀、瘘管、咬合痛剧烈、发热（急性根尖周脓肿，及时就医开髓引流+切开引流+抗生素）","出现牙齿外伤后牙体缺损、暴露牙髓、剧烈疼痛（牙外伤露髓，及时就医，根据情况行盖髓术、牙髓切断术或根管治疗）","充填治疗后出现剧烈自发痛、夜间痛（急性牙髓炎，可能充填前牙髓已有炎症或充填材料刺激，及时复诊根管治疗）","根管治疗期间出现面部肿胀、发热、疼痛剧烈（急性根尖周炎或间隙感染，及时复诊抗生素+根管引流+切开引流）","根管治疗后出现牙齿劈裂、咬合痛、牙齿松动（牙齿劈裂，及时就医，根据劈裂程度行全冠修复或拔除）","拔牙术后出现大量出血、出血不止（拔牙后出血，及时复诊压迫止血或缝合）","拔牙术后3-4天出现剧烈疼痛、口臭、拔牙创空虚（干槽症，及时复诊清创换药）","儿童出现面部肿胀、发热、精神差、哭闹不安（严重感染，及时就医）","老年人牙髓炎合并全身疾病（高血压、糖尿病、心脏病）出现牙痛、肿胀（及时就医，评估全身情况后治疗，避免自行用药）"],"pinyin":"yasuiyan","icd10":"K04.0","physical_exam":["生命体征：体温、脉搏、呼吸、血压","一般情况：神志、精神状态、面容","口腔检查：张口度（正常3指/受限）、张口型、口腔黏膜（溃疡/糜烂/白斑/红斑/肿物/色素沉着）、牙龈（红肿/出血/萎缩/溢脓/瘘管）、牙齿（龋坏/缺损/缺失/松动/叩痛/冷热敏感/咬合痛，记录牙位）、牙周（牙周袋深度/附着丧失/牙龈退缩/牙石）、咬合（牙列/覆合覆盖/错合畸形）、舌（大小/形态/颜色/舌苔/乳头/溃疡/肿物/运动）、腭（硬腭/软腭/悬雍垂/充血/溃疡/肿物）、口底（肿物/涎石）、唾液腺（腮腺/下颌下腺/舌下腺：大小/压痛/导管口分泌物）","颌面部：面部对称/肿胀/畸形/瘢痕、颞下颌关节（弹响/压痛/开口度/开口型）、颌骨（压痛/膨隆/异常动度）、淋巴结（颈部/颌下/颏下肿大）","其他：口干/口臭、吞咽/发音功能"],"lab_tests":["口腔专科检查（视诊、探诊、叩诊、冷热诊、电活力测试）：首选基础检查，探及深龋穿髓点、冷热刺激激发痛且疼痛持续、叩痛阳性支持诊断","根尖片（X线牙片）：明确龋坏深度与髓腔关系、有无穿髓、根尖周及牙槽骨情况，诊断及治疗前必查","咬合翼片或曲面断层片（全景片）：邻面龋、多发龋或全口牙列评估时加拍","CBCT（锥形束CT）：常规影像难以评估复杂根管形态、髓腔钙化、根折或根尖周病变范围，及根管再治疗前建议拍摄","血常规、凝血功能及传染病筛查（乙肝、丙肝、HIV等）：行开髓减压、牙髓摘除等有创操作前完善"],"nursing":["病情观察：评估疼痛性质（自发性痛、夜间痛、冷热刺激痛加重）、有无放射痛及面部肿胀、发热，观察叩痛与患牙松动度，记录镇痛效果","疼痛护理：急性牙髓炎开髓减压后复评疼痛缓解情况，遵医嘱给予镇痛药；指导患侧勿咀嚼，避免过冷过热刺激","口腔护理：保持口腔清洁，术后24小时内勿用力漱口、避免刺激术区；软毛牙刷轻刷，遵医嘱用氯己定漱口液或生理盐水含漱，每日2-3次","感染防控与随访：观察有无面部肿胀、发热等感染征象，必要时遵医嘱应用抗生素；嘱按时复诊完成根管治疗全程，暂封物脱落或疼痛加重及时就诊"],"diet":["治疗当日及疼痛明显期给予温凉软食或流质（粥、烂面条、蛋羹、藕粉），避免过热、过冷、过甜刺激","忌辛辣、过酸、过硬及黏性食物（坚果、骨头、年糕等），避免患侧咀嚼，防止暂封物脱落","增加优质蛋白及维生素摄入（瘦肉、鱼、蛋、新鲜果蔬泥），必要时口服营养补充剂，增强抵抗力","每次进食后用温水或淡盐水含漱，保持口腔清洁，预防继发感染"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":409},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"66da9d686f01a0bdbb34f4c9160708e5542af13c64e2f95e4b70b3e61e7a9fef","pinyin":"yasuiyan","initials":"ysy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","可复性牙髓炎：牙齿对冷、热刺激敏感，尤其对冷刺激明显，刺激去除后疼痛立即消失，无自发痛；检查可见深龋或深的牙体缺损，探诊敏感，无穿髓孔，叩诊阴性，牙髓活力测试敏感\\n急性牙髓炎（不可复性）：剧烈疼痛，特点为——自发痛（无任何刺激时突然发生疼痛）、阵发性痛（疼痛持续一段时间后缓解，然后再次发作，早期疼痛持续时间短、间隔时间长，晚期疼痛持续时间长、间隔时间短，甚至持续性疼痛）、夜间痛（夜间疼痛加重，平卧时疼痛明显，常因疼痛从睡眠中惊醒）、温度刺激加剧疼痛（冷、热刺激可诱发或加重疼痛，早期冷刺激痛明显，晚期热刺激痛明显、冷刺激可缓解疼痛（化脓性牙髓炎））、疼痛不能定位（疼痛可放射至同侧头面部、耳部、颞部，患者常不能明确指出患牙，只能指出疼痛侧）、晚期可出现咬合痛（炎症波及根尖周组织）\\n慢性牙髓炎（不可复性）：一般无剧烈自发痛，可有轻微自发痛或隐痛、钝痛，长期冷热刺激痛，刺激去除后疼痛持续一段时间，可有咬合不适或轻微咬合痛；检查可见深龋或牙体缺损，洞内可有息肉（慢性增生性牙髓炎，多见于青少年，牙髓息肉从穿髓孔长出，呈红色、质软、易出血），探诊敏感，可有穿髓孔，叩诊可有轻度不适，牙髓活力测试迟钝或敏感\\n逆行性牙髓炎：由牙周病引起，细菌经牙周袋从根尖孔或侧支根管逆行感染牙髓；表现为牙周病症状（牙龈红肿、牙周袋、牙齿松动、咬合痛）+牙髓炎症状（自发痛、冷热刺激痛、夜间痛）；检查可见深牙周袋，牙齿松动，X线可见牙槽骨吸收\\n牙髓坏死：牙髓炎发展到晚期，牙髓组织坏死；一般无自觉症状，或有牙冠变色（暗黄色或灰色，无光泽）；检查可见牙体缺损，探诊无反应（穿髓孔处无探痛），牙髓活力测试无反应，叩诊可阴性或轻度不适；X线可见根尖周可无明显异常或有根尖周阴影\\n并发症：根尖周炎（牙髓炎发展到晚期，牙髓坏死，感染扩散到根尖周组织，出现咬合痛、牙龈肿胀、瘘管）、根尖周脓肿（急性根尖周炎发展，形成脓肿，出现剧烈咬合痛、牙龈肿胀、面部肿胀、发热）、颌面部间隙感染（根尖周脓肿扩散，引起面部肿胀、张口受限、吞咽困难、高热，严重者可危及生命）、牙体缺损（龋坏严重，牙冠大部分缺损）、牙齿丧失（严重龋坏和根尖周病变无法保留，需拔除）\\n好发牙齿：下颌第一磨牙（最常见，龋病好发牙，牙髓炎也最常见）、下颌第二磨牙、上颌第一磨牙、上颌第二磨牙、前磨牙\\n诱因：龋病（最常见，深龋发展到牙髓）、牙外伤（牙齿撞击、折断，暴露牙髓）、牙体手术（备洞时意外穿髓、充填材料刺激）、楔状缺损（深的楔状缺损接近牙髓）、磨损（牙齿过度磨损，牙本质暴露，接近牙髓）、牙周病（逆行性牙髓炎）、温度刺激（突然的冷热刺激，尤其是深龋时）",60],["摘要","牙髓组织的炎症性疾病，多由龋病发展而来，也可由牙外伤、牙体手术、牙周病逆行感染引起，分为可复性牙髓炎和不可复性牙髓炎，表现为牙齿疼痛，急性牙髓炎疼痛剧烈，是口腔科急症之一。",30],["疾病编码","K04.0",30],["原首字母","yasuiyan",60]]},{"id":"orders-cf3b51c95449378fe6e9","key":"v1-c9ccc21dfe2a3058|orders-cf3b51c95449378fe6e9","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"脂溢性皮炎","category":"皮肤科","raw":{"name":"脂溢性皮炎","category":"皮肤科","summary":"又称脂溢性湿疹，是发生在头面、胸背等皮脂溢出部位的一种慢性丘疹鳞屑性炎症性皮肤病，表现为红斑、油腻性鳞屑或痂皮，伴不同程度瘙痒，成年人和新生儿多见，易反复发作。","symptoms":["好发部位：头皮、眉弓、鼻唇沟、鼻翼、耳后、胸背部、腋窝、腹股沟等皮脂溢出部位，多对称分布","头皮损害：轻型表现为糠状脱屑（头皮屑增多），伴轻度瘙痒；重型表现为油腻性鳞屑性红斑，基底潮红，可有渗出、厚痂，伴明显瘙痒，严重时整个头皮被油腻性厚痂覆盖，可有异味，头发可稀疏脱落（脂溢性脱发）","面部损害：眉弓、鼻唇沟、鼻翼、眉间可见黄红色斑片，覆以油腻性鳞屑或痂皮，伴瘙痒，可伴睑缘炎（眼睑缘潮红、脱屑、睫毛脱落）","耳部损害：耳后、外耳道可见红斑、油腻性鳞屑、皲裂、结痂，伴瘙痒，外耳道可被痂皮堵塞影响听力","躯干损害：胸背部可见圆形或椭圆形黄红色斑片，覆以油腻性鳞屑，可融合成片，中心可自愈，形成环形或多环形损害","皱褶部位损害：腋窝、腹股沟、乳房下可见红斑、糜烂、渗出，类似间擦疹，易继发念珠菌感染","新生儿脂溢性皮炎：出生后2-10周发病，好发于头皮（乳痂，油腻性灰黄色厚痂）、眉弓、鼻唇沟、耳后，表现为油腻性鳞屑性红斑，一般无明显瘙痒，多在3-4周内自行消退，少数可持续数月","瘙痒：程度不一，轻者轻度瘙痒，重者明显瘙痒，影响睡眠","病程：慢性经过，反复发作，冬季加重，夏季减轻；精神紧张、熬夜、辛辣刺激饮食、饮酒、皮脂分泌旺盛可诱发或加重","并发症：脂溢性脱发（头皮脂溢性皮炎长期不愈，毛囊受损，头发稀疏脱落）、睑缘炎、外耳道炎、继发细菌感染（毛囊炎、疖肿）、继发念珠菌感染（皱褶部位）、红皮病（严重泛发性脂溢性皮炎，全身皮肤潮红脱屑）","好发人群：成年人（20-40岁，男性略多）、新生儿、皮脂分泌旺盛者、油性皮肤者、精神紧张熬夜者、肥胖者、HIV感染者（脂溢性皮炎发生率高，病情重，可作为艾滋病的皮肤表现）"],"diagnosis":["典型临床表现（皮脂溢出部位的红斑、油腻性鳞屑或痂皮，伴瘙痒，慢性反复发作）+好发部位+好发人群","详细询问病史：发病时间、部位、症状（瘙痒、脱屑、渗出）、诱发因素（熬夜、精神紧张、饮食、饮酒）、既往治疗史、全身疾病史（HIV、帕金森、癫痫、抑郁症）、用药史（锂剂、雄激素、糖皮质激素可诱发或加重）","皮肤检查：视诊（观察皮损部位、形态、颜色、鳞屑特点、分布）、触诊（皮损质地、有无浸润）、头皮检查（头发密度、毛囊情况、鳞屑性质）","皮肤镜检查（观察皮损微细结构，辅助诊断和鉴别）","真菌检查（鳞屑真菌镜检和培养，排除头癣、体癣，脂溢性皮炎可查到马拉色菌，但马拉色菌是皮肤正常寄生菌，不能仅凭真菌检查诊断）","伍德灯检查（辅助鉴别白癜风、花斑癣等）","皮肤活检（病理检查，用于诊断不明确、怀疑其他疾病如银屑病、红斑狼疮、皮肤T细胞淋巴瘤时，病理表现为表皮角化不全、棘层肥厚、海绵水肿、真皮浅层血管周围淋巴细胞和组织细胞浸润，可见马拉色菌孢子）","排除：银屑病（头皮银屑病鳞屑厚、呈银白色，束状发，超出发际，身体其他部位有银屑病皮损，Auspitz征阳性）、头癣（儿童多见，鳞屑斑、断发、脱发，真菌检查阳性，有传染性）、体癣（环形红斑，边缘隆起有丘疹水疱，中央消退，真菌检查阳性）、玫瑰糠疹（椭圆形红斑，长轴与皮纹一致，先有母斑，好发于躯干和四肢近端，一般不累及头皮，有自限性）、湿疹（多形性皮损，红斑、丘疹、水疱、渗出、结痂，边界不清，瘙痒剧烈，无油腻性鳞屑，分布不局限于皮脂溢出部位）、接触性皮炎（有接触史，皮损边界清楚，形态与接触物一致，去除接触物后好转）、红斑狼疮（面部蝶形红斑，光敏感，口腔溃疡，关节痛，全身症状，抗核抗体阳性）、酒渣鼻（面中部红斑、毛细血管扩张、丘疹脓疱，无油腻性鳞屑，好发于中年人，无头皮损害）、脂溢性脱发（以头发稀疏脱落为主，可伴轻度脂溢性皮炎）、特应性皮炎（个人或家族过敏史，皮肤干燥，屈侧为主，剧烈瘙痒，嗜酸性粒细胞升高，总IgE升高）","分型：按部位分头皮型、面部型、躯干型、皱褶型；按严重程度分轻型（头皮屑增多，轻度红斑瘙痒）、中型（油腻性鳞屑性红斑，明显瘙痒）、重型（泛发，渗出厚痂，红皮病）；按年龄分成人型和新生儿型"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！","方案1：","用法：一般无需静脉输液；头皮/面部皮损：酮康唑洗剂 2% 外用 每周2次；氢化可的松乳膏 1% 外用 bid；瘙痒明显：氯雷他定 10mg 口服 qd","方案2（严重泛发性脂溢性皮炎或红皮病）：","用法：0.9%NS 250ml + 维生素C 2g ivgtt qd（辅助，促进恢复）、0.9%NS 100ml + 甘草酸苷40-60mg ivgtt qd（抗炎，严重病例）、0.9%NS 100ml + 抗生素 ivgtt qd（继发严重细菌感染时，根据病原选择）","方案3（继发严重感染伴全身症状）：","用法：大剂量抗生素静脉给药，必要时住院治疗","方案4（HIV相关脂溢性皮炎）：","用法：抗反转录病毒治疗（ART），同时局部治疗","方案5（补液支持）：","用法：发热、不能进食、脱水时静脉补液","📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。"],"oral_medication":["⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！","药物1（抗组胺药（瘙痒明显时））：","用法：氯雷他定10mg qd、西替利嗪10mg qd、依巴斯汀10mg qd、非索非那定60mg bid，缓解瘙痒，睡前服用可改善睡眠〔调 肝功能/肾功能不全减量；妊娠哺乳慎用〕","药物2（B族维生素）：","用法：维生素B2 10mg tid、维生素B6 10mg tid、复合维生素B 2片 tid，调节皮脂分泌，辅助治疗","药物3（锌制剂）：","用法：葡萄糖酸锌0.1g tid、甘草锌0.25g tid，辅助治疗，调节免疫和皮脂分泌","药物4（抗真菌药（严重或泛发性，马拉色菌相关））：","用法：伊曲康唑0.1g qd×1-2周（餐后服用，注意肝功能）、酮康唑0.2g qd×1-2周（注意肝功能和药物相互作用，现已少用）、氟康唑0.15g qw×2-4周","药物5（抗生素（继发细菌感染或严重炎症））：","用法：四环素类（多西环素0.1g bid、米诺环素0.1g bid，抗炎抗菌，疗程4-8周）、大环内酯类（红霉素0.25g qid、罗红霉素0.15g bid）、头孢类（头孢克肟0.2g bid，继发严重感染时）〔调 肾功能不全减量；青霉素过敏慎用〕","药物6（糖皮质激素）：","用法：糖皮质激素（严重泛发性或红皮病，短期使用）：泼尼松10-20mg qd（晨起顿服，短期3-7天，逐渐减量，注意禁忌证和副作用，不可长期使用）〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物7（异维A酸（严重顽固病例，皮脂分泌旺盛））：","用法：异维A酸10mg bid或0.5mg/kg/d，疗程12-16周，注意致畸（育龄期女性避孕）、口干、唇炎、肝功能异常、血脂升高、情绪变化，需在医生指导下使用","药物8（利尿）：","用法：抗雄激素药（女性患者，皮脂分泌旺盛，月经不调）：螺内酯20-40mg tid、达英-35（口服避孕药，月经第1天开始，每月21天，停7天），需在妇科或皮肤科医生指导下使用，注意禁忌证〔调 ★ eGFR<30 禁用；高钾血症禁用〕","药物9：","用法：免疫抑制剂（严重顽固病例，其他治疗无效）：甲氨蝶呤、环孢素，需在医生指导下使用，监测副作用","药物10（中医中药）：","用法：辨证施治——风热血燥型（消风散加减，祛风清热、养血润燥）、肠胃湿热型（参苓白术散合茵陈蒿汤加减，清热利湿）、血虚风燥型（当归饮子加减，养血润燥、祛风止痒）；中成药可选用当归苦参丸、湿毒清胶囊、皮肤病血毒丸、润燥止痒胶囊等","药物11（新生儿脂溢性皮炎）：","用法：一般无需口服药物，以局部护理和外用药为主，严重时短期外用弱效激素","📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。"],"treatment":["一般治疗：生活规律，睡眠充足，避免熬夜和精神紧张；调节饮食，限制多脂、多糖、辛辣刺激食物，忌饮酒，多吃新鲜蔬果，保持大便通畅；避免过度清洁和摩擦皮肤，使用温和的清洁产品；头皮脂溢性皮炎避免频繁洗头（每周2-3次即可），避免用指甲抓挠头皮；避免使用刺激性强的洗发水和化妆品；保持皮肤清洁湿润","外用药物治疗（主要治疗方法）：","——抗真菌药（针对马拉色菌，一线用药）：酮康唑洗剂（2%，每周2-3次洗头，停留5分钟后冲洗，可用于头皮和身体，是治疗头皮脂溢性皮炎的一线药物）、酮康唑乳膏（2%，每日1-2次，用于面部和躯干）、二硫化硒洗剂（2.5%，每周2次洗头，停留5-10分钟后冲洗，注意头发褪色和干燥）、吡硫翁锌洗剂（每周2-3次洗头）、环吡酮胺乳膏（每日2次）、联苯苄唑乳膏（每日1次）、特比萘芬乳膏（每日1-2次）、克霉唑乳膏（每日2次）、咪康唑乳膏（每日2次）","——糖皮质激素（抗炎止痒，中重度炎症短期使用）：弱效激素（氢化可的松乳膏0.5-1%、地奈德乳膏0.05%，用于面部和皱褶部位，短期使用，不超过1-2周）、中效激素（糠酸莫米松乳膏0.1%、丁酸氢化可的松乳膏0.1%，用于躯干和头皮，短期使用）、强效激素（卤米松乳膏、氯倍他索乳膏，一般不用于脂溢性皮炎，尤其不用于面部和皱褶部位，避免副作用）；激素软膏可与抗真菌药联合使用（如复方酮康唑乳膏，含酮康唑和丙酸氯倍他索，短期使用，注意激素副作用）","——钙调神经磷酸酶抑制剂（非激素抗炎药，用于面部和皱褶部位，可长期使用，替代激素）：他克莫司软膏0.03%（儿童和面部）或0.1%（成人），每日2次；吡美莫司乳膏1%，每日2次；用于激素不耐受或需要长期维持治疗者，注意局部刺激（灼热感、刺痛，一般1-2周耐受）","——角质剥脱剂（去除鳞屑，头皮厚痂）：水杨酸制剂（2-5%水杨酸软膏或洗剂，溶解角质，去除鳞屑）、煤焦油洗剂（1-5%，抗炎、角质剥脱，用于头皮，注意气味和染色，孕妇禁用）、硫磺洗剂（5-10%，抑菌、角质剥脱，用于头皮和面部，注意干燥刺激）、尿素乳膏（10-20%，软化角质，保湿）","——抗菌药（继发细菌感染）：莫匹罗星软膏（每日2-3次）、夫西地酸乳膏（每日2次）、红霉素软膏（每日2次）、新霉素软膏","——抗念珠菌药（皱褶部位继发念珠菌感染）：制霉菌素软膏、克霉唑乳膏、咪康唑乳膏、联苯苄唑乳膏","——保湿剂（皮肤干燥、屏障修复）：凡士林、尿素乳膏、神经酰胺乳膏、维生素E乳膏，每日多次，修复皮肤屏障","头皮脂溢性皮炎治疗：酮康唑洗剂或二硫化硒洗剂洗头（每周2-3次），配合外用激素溶液或搽剂（哈西奈德溶液、地塞米松搽剂，短期使用），厚痂先用植物油或水杨酸软膏软化后再清洗，避免强行剥除；严重时口服抗真菌药（伊曲康唑 200mg 口服 qd，疗程1-2周）或异维A酸（10mg 口服 qd-bid，育龄女性严格避孕）","面部脂溢性皮炎治疗：外用抗真菌乳膏（酮康唑乳膏2% 每日1-2次、联苯苄唑乳膏 每日1次）+钙调神经磷酸酶抑制剂（他克莫司软膏0.03% 每日2次、吡美莫司乳膏1% 每日2次），短期使用弱效激素（地奈德乳膏0.05%、氢化可的松乳膏0.5-1%，每日1-2次，不超过1-2周），避免使用强效激素和长期使用激素；注意面部皮肤屏障修复，使用温和保湿剂","躯干脂溢性皮炎治疗：外用抗真菌乳膏（酮康唑乳膏2% 每日1-2次）+中效激素软膏（糠酸莫米松乳膏0.1% 每日1次），范围广时使用抗真菌洗剂洗澡（酮康唑洗剂），严重时口服抗真菌药（伊曲康唑 200mg 口服 qd，疗程1-2周）","皱褶部位脂溢性皮炎治疗：保持干燥通风，外用抗真菌乳膏（酮康唑乳膏2% 每日1-2次）+弱效激素（氢化可的松乳膏0.5-1% 每日1-2次），继发念珠菌感染时用抗念珠菌药（制霉菌素软膏 每日2次、克霉唑乳膏 每日2次），避免使用强效激素和封包","新生儿脂溢性皮炎治疗：一般可自行消退，以护理为主——头皮乳痂用植物油或婴儿油软化后用婴儿shampoo轻柔清洗，不要强行剥除；面部和身体用温水清洗，涂抹温和保湿剂；严重时短期外用弱效激素（氢化可的松乳膏0.5-1%，每日1-2次，不超过1周）或抗真菌乳膏（酮康唑乳膏2%，每日1次，短期使用）","物理治疗：窄谱UVB照射（严重泛发性病例，每周2-3次，抗炎调节免疫）、光动力治疗（严重病例）、红蓝光照射（抗炎、促进修复）","并发症治疗：脂溢性脱发（治疗脂溢性皮炎+米诺地尔酊 1ml 涂患处 bid+非那雄胺 1mg 口服 qd（男性），必要时毛发移植）、睑缘炎（热敷+清洁睑缘+抗生素眼膏如红霉素眼膏+激素眼膏，眼科协同）、外耳道炎（清洁外耳道+抗真菌或抗生素滴耳液如氧氟沙星滴耳液 每次3-5滴 tid，耳鼻喉科协同）、继发感染（抗生素如莫匹罗星软膏 每日2-3次）、红皮病（住院治疗，系统用激素如泼尼松 30-40mg 口服 qd+抗组胺如氯雷他定 10mg 口服 qd+保湿+支持治疗）","预防：生活规律，避免熬夜和精神紧张；清淡饮食，限制多脂多糖辛辣食物，忌饮酒；注意皮肤清洁卫生，使用温和清洁产品，避免过度清洁和摩擦；头皮脂溢性皮炎定期用抗真菌洗剂洗头（每周1-2次维持）；避免使用刺激性强的化妆品和洗发水；保持心情舒畅；积极治疗相关疾病（HIV、帕金森、癫痫等）","随访：定期复查（每1-3个月），评估疗效，调整治疗方案；脂溢性皮炎易复发，需长期维持治疗（每周1-2次抗真菌洗剂洗头预防复发）；长期使用激素者注意观察副作用（皮肤萎缩、毛细血管扩张、色素沉着、激素依赖性皮炎）；口服抗真菌药和异维A酸者定期复查肝功能、血脂；HIV相关脂溢性皮炎需同时抗反转录病毒治疗"],"management":["皮肤护理：使用温和、无刺激的清洁产品（pH接近皮肤弱酸性），避免使用碱性强的肥皂和刺激性强的洗发水；水温适中（37℃左右），避免热水烫洗（加重皮肤屏障损伤和瘙痒）；避免过度清洁（每日洗脸不超过2次，洗头每周2-3次），避免用力搓擦和搔抓；清洁后及时涂抹保湿剂（修复皮肤屏障）；头皮厚痂先用植物油或水杨酸软膏软化后再清洗，不要强行剥除（避免出血和感染）","头皮护理：选择温和的洗发水，避免使用含酒精、香精、强去脂成分的洗发水；使用抗真菌洗剂（酮康唑、二硫化硒）时，先用温水湿润头发，将洗剂涂抹于头皮，轻轻按摩，停留5-10分钟后冲洗干净，每周2-3次；避免频繁洗头（过度清洁刺激皮脂腺分泌更多油脂），也不要长期不洗头（油脂和鳞屑堆积加重炎症）；避免用指甲抓挠头皮（可用指腹轻柔按摩）；头发不要扎得过紧；避免使用发胶、发蜡等刺激性美发产品","面部护理：使用温和的洁面产品，每日洗脸不超过2次；避免使用含酒精、香精、磨砂颗粒的护肤品和化妆品；清洁后及时涂抹温和的保湿剂（选择清爽、不油腻、无致痘成分的保湿霜）；避免使用油性护肤品和粉底（堵塞毛孔，加重皮脂溢出）；注意防晒（紫外线可加重炎症和色素沉着，选择温和的物理防晒或遮阳伞）；避免频繁去角质和使用美容仪器（刺激皮肤）；不要用手挤压皮损（避免感染和瘢痕）","饮食护理：清淡饮食，多吃新鲜蔬菜水果（富含维生素B族、维生素C、锌，如粗粮、瘦肉、蛋类、豆制品、绿叶蔬菜、水果）；限制多脂食物（肥肉、油炸食品、奶油、黄油、坚果）、多糖食物（糖果、甜点、含糖饮料）、辛辣刺激食物（辣椒、花椒、生姜、大蒜）；忌饮酒（酒精刺激皮脂分泌，加重炎症）；避免饮用浓茶、咖啡（可能加重瘙痒和精神紧张）；保持大便通畅（便秘可加重皮脂溢出）；肥胖者适当控制体重","作息与情绪：生活规律，保证充足睡眠（每日7-8小时），避免熬夜（熬夜导致内分泌紊乱，皮脂分泌增加，免疫力下降）；避免精神紧张、焦虑、抑郁（精神因素诱发或加重脂溢性皮炎）；保持心情舒畅，学会放松（听音乐、运动、冥想）；适当体育锻炼（增强体质，调节免疫，促进新陈代谢，但运动后及时清洁皮肤）；避免过度劳累","用药护理：按医嘱使用外用药（抗真菌药、激素、钙调神经磷酸酶抑制剂），注意用药方法和疗程；激素软膏不可长期大面积使用（尤其是面部和皱褶部位），避免突然停药（反跳），逐渐减量；钙调神经磷酸酶抑制剂初期可能有局部刺激（灼热、刺痛），一般1-2周耐受，可先小面积试用；口服抗组胺药可能有嗜睡副作用，避免驾驶和高空作业；口服抗真菌药（伊曲康唑、酮康唑）注意肝功能，定期复查，避免与其他药物相互作用；异维A酸注意致畸（育龄期女性避孕，停药后至少3个月避孕）、口干唇炎、肝功能血脂异常、情绪变化，需在医生指导下使用，定期复查；观察药物疗效和副作用，出现严重副作用及时复诊","病情观察：观察皮损变化（部位、范围、红斑、鳞屑、渗出、结痂）、瘙痒程度、睡眠影响；观察有无继发感染（毛囊炎、疖肿，表现为红肿疼痛、脓疱、发热）；观察有无红皮病征象（全身皮肤潮红、肿胀、脱屑、发热、淋巴结肿大）；观察头发变化（有无稀疏脱落）；观察眼部和耳部症状（睑缘炎、外耳道炎）；治疗后评估疗效，调整方案；出现皮损加重、继发感染、红皮病、发热及时就医","心理护理：安慰患者，解释脂溢性皮炎是常见病、慢性疾病，可治疗控制，但易复发，消除焦虑；面部皮损影响美观者可能有心理压力，给予心理支持，告知规范治疗可控制；瘙痒影响睡眠者给予关心，指导缓解瘙痒的方法（冷敷、轻拍、避免搔抓，按医嘱用抗组胺药）；鼓励患者保持良好生活习惯和心态，积极配合治疗；避免因反复发作而失去信心，告知维持治疗可减少复发","健康教育：讲解脂溢性皮炎的病因（皮脂分泌旺盛、马拉色菌感染、免疫炎症反应、遗传、精神因素、饮食、熬夜等）、症状（红斑、油腻性鳞屑、瘙痒）和好发部位（头皮、面部、胸背等皮脂溢出部位）；强调生活调理的重要性（规律作息、清淡饮食、避免熬夜精神紧张）；指导正确皮肤护理（温和清洁、保湿、避免过度清洁和搔抓）；指导外用药使用方法和注意事项（激素不可长期面部使用，抗真菌洗剂停留5-10分钟）；告知脂溢性皮炎易复发，需长期维持治疗（每周1-2次抗真菌洗剂洗头预防复发）；告知不要自行长期使用强效激素（可致皮肤萎缩、激素依赖性皮炎）；出现皮损加重、继发感染、红皮病、发热及时就医；HIV感染者脂溢性皮炎发生率高且重，需同时抗反转录病毒治疗；新生儿脂溢性皮炎多可自行消退，以护理为主，不要过度治疗；戒烟限酒；定期复查","家庭护理：家属协助患者保持规律作息和清淡饮食；提醒患者按时用药和定期复查；观察患者皮损变化和情绪变化；瘙痒影响睡眠时给予关心和协助；家庭共用毛巾、枕巾、帽子可能传播马拉色菌（虽然不是传染病，但建议个人专用）；患者枕巾、毛巾、帽子定期清洗消毒（热水烫洗或阳光暴晒）；新生儿脂溢性皮炎家属协助护理（软化乳痂、温和清洗、保湿）"],"notes":["脂溢性皮炎又称脂溢性湿疹，是发生在头面、胸背等皮脂溢出部位的一种慢性丘疹鳞屑性炎症性皮肤病，是皮肤科常见病，成年人患病率约2-5%，男性略多于女性，新生儿也可发病，多在出生后2-10周发病，3-4周内自行消退","病因：尚未完全明确，与多种因素有关——皮脂分泌旺盛（基础，皮脂腺分泌功能亢进，皮脂排出过多，在皮肤上堆积，为马拉色菌提供营养）、马拉色菌感染（重要因素，马拉色菌是皮肤正常寄生菌，在皮脂溢出部位大量繁殖，其代谢产物（游离脂肪酸）刺激皮肤，引起炎症反应，抗真菌治疗有效支持这一学说）、免疫炎症反应（个体对马拉色菌及其代谢产物的免疫反应异常，T细胞免疫异常，HIV感染者脂溢性皮炎发生率高且重）、遗传因素（家族倾向，皮脂分泌旺盛体质遗传）、精神因素（精神紧张、焦虑、熬夜、过度劳累，诱发或加重）、饮食因素（多脂、多糖、辛辣刺激饮食、饮酒，刺激皮脂分泌）、维生素B族缺乏、其他疾病（HIV感染、帕金森病、癫痫、抑郁症、脑卒中、面神经麻痹，脂溢性皮炎发生率增加）、药物（锂剂、雄激素、糖皮质激素、干扰素，可诱发或加重）","发病机制：皮脂分泌旺盛→马拉色菌大量繁殖→马拉色菌代谢产物（脂肪酶分解皮脂产生游离脂肪酸）刺激皮肤→皮肤屏障功能受损→免疫炎症反应（淋巴细胞、组织细胞浸润，细胞因子释放）→红斑、鳞屑、瘙痒等炎症表现；精神因素、饮食、熬夜等通过神经内分泌调节影响皮脂分泌和免疫功能，诱发或加重","好发部位：头皮（最常见）、眉弓、眉间、鼻唇沟、鼻翼、耳后、外耳道、胸背部（胸骨前、肩胛间）、腋窝、腹股沟、乳房下、脐窝等皮脂溢出部位，多对称分布","临床表现：轻型仅表现为头皮屑增多（糠状脱屑），伴轻度瘙痒；重型表现为油腻性鳞屑性红斑，基底潮红，可有渗出、厚痂，伴明显瘙痒；头皮严重时整个头皮被油腻性厚痂覆盖，可有异味，头发稀疏脱落；新生儿表现为头皮乳痂（油腻性灰黄色厚痂）和面部油腻性红斑，一般无明显瘙痒，多可自行消退","病程：慢性经过，反复发作，冬季加重（干燥、皮脂分泌相对旺盛），夏季减轻（出汗多、清洗多）；精神紧张、熬夜、辛辣饮食、饮酒可诱发或加重","诊断要点：皮脂溢出部位的红斑、油腻性鳞屑或痂皮，伴瘙痒，慢性反复发作，好发于成年人和新生儿，一般诊断不难；不典型病例需真菌检查、皮肤活检排除其他疾病","与银屑病鉴别：头皮银屑病鳞屑厚、呈银白色，超出发际，头发呈束状（束状发），身体其他部位有银屑病皮损（边界清楚的红色斑块，上覆银白色鳞屑，Auspitz征阳性），一般无油腻性鳞屑，真菌检查阴性；脂溢性皮炎鳞屑油腻、黄红色，不超出发际，无束状发，好发于皮脂溢出部位","与头癣鉴别：头癣多见于儿童，有鳞屑斑、断发、脱发、脓疱，真菌检查阳性（发内或发外孢子、菌丝），有传染性，需抗真菌治疗；脂溢性皮炎多见于成年人，无断发，真菌检查可查到马拉色菌（正常寄生菌）","与玫瑰糠疹鉴别：玫瑰糠疹好发于躯干和四肢近端，先有母斑（椭圆形红斑，上覆细薄鳞屑），后有子斑，椭圆形红斑长轴与皮纹一致，一般不累及头皮，有自限性（6-8周），无油腻性鳞屑；脂溢性皮炎好发于皮脂溢出部位，累及头皮，油腻性鳞屑，慢性反复发作","与湿疹鉴别：湿疹皮损多形性（红斑、丘疹、水疱、渗出、结痂、苔藓化），边界不清，瘙痒剧烈，分布不局限于皮脂溢出部位，无油腻性鳞屑，个人或家族过敏史；脂溢性皮炎皮损单一（红斑+油腻性鳞屑），好发于皮脂溢出部位，有油腻性鳞屑","与酒渣鼻（玫瑰痤疮）鉴别：酒渣鼻好发于面中部（鼻、两颊、眉间、颏部），表现为红斑、毛细血管扩张、丘疹脓疱，晚期鼻赘，无油腻性鳞屑，一般不累及头皮，好发于中年人，女性多见但男性鼻赘重；脂溢性皮炎好发于皮脂溢出部位包括头皮，有油腻性鳞屑","治疗原则：一般治疗（生活调理、皮肤护理）+外用药物（抗真菌药为主，配合激素、钙调神经磷酸酶抑制剂、角质剥脱剂）+口服药物（严重病例，抗组胺、B族维生素、抗真菌、抗生素、异维A酸等）；脂溢性皮炎易复发，需长期维持治疗（每周1-2次抗真菌洗剂洗头）","外用抗真菌药：是治疗脂溢性皮炎的一线用药，针对马拉色菌，酮康唑洗剂（2%）是治疗头皮脂溢性皮炎的金标准，每周2-3次，停留5-10分钟；酮康唑乳膏用于面部和躯干；二硫化硒洗剂、吡硫翁锌洗剂也可用于头皮；抗真菌药与激素联合使用（复方制剂）可提高疗效，但注意激素副作用","外用激素：用于中重度炎症，短期使用，面部和皱褶部位用弱效激素（地奈德、氢化可的松），躯干和头皮用中效激素（糠酸莫米松、丁酸氢化可的松），避免长期使用（不超过2-4周）和大面积使用，避免突然停药（逐渐减量），避免使用强效激素（卤米松、氯倍他索），尤其是面部","钙调神经磷酸酶抑制剂：他克莫司、吡美莫司，非激素抗炎药，用于面部和皱褶部位，可长期使用，替代激素，注意初期局部刺激，适合需要长期维持治疗和激素不耐受者","口服抗真菌药：用于严重或泛发性病例，伊曲康唑0.1g qd×1-2周，注意肝功能和药物相互作用；酮康唑因肝毒性现已少用；氟康唑也可使用","异维A酸：用于严重顽固病例，皮脂分泌旺盛，0.5mg/kg/d，疗程12-16周，注意致畸、口干唇炎、肝功能血脂异常、情绪变化，育龄期女性避孕，需在医生指导下使用，定期复查","预后：脂溢性皮炎是慢性疾病，易反复发作，但经规范治疗和生活调理可控制症状，不影响全身健康；新生儿脂溢性皮炎多可自行消退；严重泛发性病例可发展为红皮病，需积极治疗；HIV相关脂溢性皮炎病情重，需同时抗反转录病毒治疗；长期不愈的头皮脂溢性皮炎可致脂溢性脱发；关键是规范治疗和长期维持，减少复发","预防：生活规律，避免熬夜和精神紧张；清淡饮食，限制多脂多糖辛辣食物，忌饮酒；注意皮肤清洁卫生，使用温和清洁产品，避免过度清洁和摩擦；头皮脂溢性皮炎定期用抗真菌洗剂洗头（每周1-2次维持）；避免使用刺激性强的化妆品和洗发水；保持心情舒畅；积极治疗相关疾病（HIV、帕金森、癫痫等）；避免使用可诱发脂溢性皮炎的药物（锂剂、雄激素等），如必须使用需注意皮肤变化","我国现状：脂溢性皮炎是皮肤科常见病，患病率高，但很多患者不重视，自行使用激素类药膏（如皮炎平、肤轻松），长期使用导致激素依赖性皮炎、皮肤萎缩等副作用；需加强健康教育，推广规范治疗（抗真菌药为主，激素短期使用，长期维持），避免滥用激素"],"emergency":["出现全身皮肤潮红、肿胀、脱屑、发热、淋巴结肿大（红皮病，严重泛发性脂溢性皮炎，需住院治疗）","出现皮损处红肿疼痛、脓疱、发热、寒战（继发严重细菌感染，蜂窝织炎、败血症，及时就医抗生素治疗）","出现头皮脓肿、脱发、疼痛剧烈（严重毛囊炎、疖肿、脓肿，及时就医切开引流+抗生素）","出现眼睑红肿、疼痛、视力下降、分泌物增多（睑缘炎加重或继发感染，眼科协同治疗）","出现外耳道红肿疼痛、流脓、听力下降（外耳道炎或中耳炎，耳鼻喉科协同治疗）","口服抗真菌药或异维A酸后出现恶心、呕吐、黄疸、腹痛、乏力（肝功能损害，及时就医停药并检查肝功能）","异维A酸治疗期间患者出现严重抑郁、自杀念头（精神副作用，立即停药并精神科就诊）","孕妇使用异维A酸或维A酸类药物（致畸，立即停药并产科咨询）","外用激素后出现皮肤萎缩、毛细血管扩张、痤疮、多毛（激素副作用，及时复诊调整用药，不可突然停药）","新生儿脂溢性皮炎出现皮损加重、糜烂、渗出、发热、精神差（继发感染或其他疾病，及时就医）","HIV感染者出现严重泛发性脂溢性皮炎、红皮病（提示免疫功能严重低下，及时感染科就诊，评估抗反转录病毒治疗）","出现严重瘙痒影响睡眠、焦虑抑郁（及时就医调整治疗，必要时精神科协同）"],"pinyin":"zhiyixingpiyan","icd10":"L21.9","physical_exam":["生命体征：体温（感染性皮肤病发热）、脉搏、呼吸、血压","一般情况：神志、精神状态、面容","皮肤检查（重点）：皮损部位（按皮区分布）、分布（局限性/全身性/对称性/单侧/带状）、排列（散在/密集/群集/环状/线状）、形态（原发疹：斑疹/丘疹/斑块/风团/结节/水疱/大疱/脓疱/囊肿；继发疹：糜烂/溃疡/鳞屑/结痂/抓痕/皲裂/苔藓样变/萎缩/瘢痕）、颜色（红/紫/褐/黑/白/黄）、大小（用cm描述或实物比喻）、数目、边界（清楚/模糊）、表面（光滑/粗糙/乳头状/蜡样光泽）、基底（浸润/红晕）、内容物（水疱液清/浊/血性）","皮肤触诊：温度、湿度、浸润深度、压痛、有无波动感、淋巴结肿大","黏膜检查：口腔、眼结膜、鼻、外阴、肛周（黏膜受累情况）","毛发：脱发类型（斑秃/全秃/普秃/脂溢性脱发）、毛发异常（多毛/变色/变脆）","甲：甲面（凹凸/纵嵴/横沟/点凹）、甲色（白甲/黄甲/黑甲/甲下出血）、甲分离、甲下角化、甲周红肿","淋巴结：局部/全身淋巴结肿大（压痛/质地）","其他：全身系统检查（排除内脏受累）"],"lab_tests":["皮损专科检查：Wood灯下观察皮损形态、边界及油腻性鳞屑特征，评估头皮、面中部、胸背等好发部位受累范围","真菌镜检：取头皮或面颊部鳞屑行10%氢氧化钾涂片镜检，排除马拉色菌毛囊炎及头癣，必要时加做真菌培养","皮肤病理活检：皮损不典型、常规治疗效果差或需与银屑病、红斑狼疮鉴别时行组织病理检查","免疫学检查：抗核抗体、补体C3/C4等，顽固性泛发者排除系统性红斑狼疮等免疫相关疾病","血液检查：血常规、空腹血糖、血脂，评估伴发的代谢异常；重症反复发作者建议查HIV抗体排除免疫缺陷","过敏原检测：疑与护肤品、洗发水相关或伴接触性皮炎表现时行斑贴试验"],"nursing":["头皮皮疹护理：遵医嘱用2%酮康唑洗剂或2.5%二硫化硒洗剂洗头，每周2-3次，泡沫停留5分钟后再冲洗，洗发后及时擦干","皮肤清洁：用37℃左右温水轻柔清洗面部及患处，避免热水烫洗、搔抓和碱性肥皂、刺激性化妆品刺激","止痒防抓：剪短指甲，瘙痒明显时局部冷敷或遵医嘱口服抗组胺药，夜间可戴棉质手套防抓伤","用药观察：外涂糖皮质激素乳膏时观察有无皮肤萎缩、毛细血管扩张，遵医嘱间歇、短程使用，避免长期连续涂抹","防感染：皮损破损渗液处保持清洁干燥，渗液较多时予3%硼酸溶液冷湿敷后再涂药，防止继发细菌感染"],"diet":["忌口：避免辛辣刺激、油炸高脂及高糖甜食（如火锅、烧烤、油炸食品、巧克力、奶油蛋糕、含糖饮料）","控制饮酒及咖啡、浓茶等刺激性饮料，戒烟","发物管理：急性发作期适当限制海鲜、牛羊肉等发物，观察皮疹变化，个体化调整","推荐多食富含B族维生素及锌的食物：全谷物、瘦肉、豆类、蛋类、坚果","多食新鲜蔬菜水果，保持规律进餐和大便通畅，避免暴饮暴食"],"topical_medication":["酮康唑洗剂 涂患处（头皮）bid；丁酸氢化可的松乳膏 涂患处 bid；他克莫司软膏 涂患处 bid"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":410},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"fe221dc20b793bf0995c7247f16df4e353236a1c6e36664f9a3bd20bc7662462","pinyin":"zhiyixingpiyan","initials":"zyxpy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","好发部位：头皮、眉弓、鼻唇沟、鼻翼、耳后、胸背部、腋窝、腹股沟等皮脂溢出部位，多对称分布\\n头皮损害：轻型表现为糠状脱屑（头皮屑增多），伴轻度瘙痒；重型表现为油腻性鳞屑性红斑，基底潮红，可有渗出、厚痂，伴明显瘙痒，严重时整个头皮被油腻性厚痂覆盖，可有异味，头发可稀疏脱落（脂溢性脱发）\\n面部损害：眉弓、鼻唇沟、鼻翼、眉间可见黄红色斑片，覆以油腻性鳞屑或痂皮，伴瘙痒，可伴睑缘炎（眼睑缘潮红、脱屑、睫毛脱落）\\n耳部损害：耳后、外耳道可见红斑、油腻性鳞屑、皲裂、结痂，伴瘙痒，外耳道可被痂皮堵塞影响听力\\n躯干损害：胸背部可见圆形或椭圆形黄红色斑片，覆以油腻性鳞屑，可融合成片，中心可自愈，形成环形或多环形损害\\n皱褶部位损害：腋窝、腹股沟、乳房下可见红斑、糜烂、渗出，类似间擦疹，易继发念珠菌感染\\n新生儿脂溢性皮炎：出生后2-10周发病，好发于头皮（乳痂，油腻性灰黄色厚痂）、眉弓、鼻唇沟、耳后，表现为油腻性鳞屑性红斑，一般无明显瘙痒，多在3-4周内自行消退，少数可持续数月\\n瘙痒：程度不一，轻者轻度瘙痒，重者明显瘙痒，影响睡眠\\n病程：慢性经过，反复发作，冬季加重，夏季减轻；精神紧张、熬夜、辛辣刺激饮食、饮酒、皮脂分泌旺盛可诱发或加重\\n并发症：脂溢性脱发（头皮脂溢性皮炎长期不愈，毛囊受损，头发稀疏脱落）、睑缘炎、外耳道炎、继发细菌感染（毛囊炎、疖肿）、继发念珠菌感染（皱褶部位）、红皮病（严重泛发性脂溢性皮炎，全身皮肤潮红脱屑）\\n好发人群：成年人（20-40岁，男性略多）、新生儿、皮脂分泌旺盛者、油性皮肤者、精神紧张熬夜者、肥胖者、HIV感染者（脂溢性皮炎发生率高，病情重，可作为艾滋病的皮肤表现）",60],["摘要","又称脂溢性湿疹，是发生在头面、胸背等皮脂溢出部位的一种慢性丘疹鳞屑性炎症性皮肤病，表现为红斑、油腻性鳞屑或痂皮，伴不同程度瘙痒，成年人和新生儿多见，易反复发作。",30],["疾病编码","L21.9",30],["原首字母","zhiyixingpiyan",60]]}]);